DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='011709c9-8910-51e0-a9de-c94c2374544c' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p056", "note": "原文：初，帝在籓镇，用法严，将校有战没者，所部兵悉斩之，谓之跋队斩。士卒失主将者，多亡逸不敢归。帝乃命凡军士皆文其面以记军号。军士或思乡里逃去，关津辄执之送所属，无不死者，其乡里亦不敢容。由是亡者皆聚山泽为盗，大为州县之患。壬寅，诏赦其罪，自今虽文面亦听还乡里。盗减什七八。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第56段", "note": "原文：初，帝在籓镇，用法严，将校有战没者，所部兵悉斩之，谓之跋队斩。士卒失主将者，多亡逸不敢归。帝乃命凡军士皆文其面以记军号。军士或思乡里逃去，关津辄执之送所属，无不死者，其乡里亦不敢容。由是亡者皆聚山泽为盗，大为州县之患。壬寅，诏赦其罪，自今虽文面亦听还乡里。盗减什七八。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 011709c9-8910-51e0-a9de-c94c2374544c'; END IF; END $$;
