DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='0438ec8a-bd50-5cd3-ad3b-9d27a507ec25' AND (to_jsonb(t) @> '{"note": "原文：新五代史 \n23/1627 \n \n \n梁本纪第二  \n \n开平元年春正月壬寅，天子使御\n史大夫薛贻矩来劳军。宰相张文蔚率\n百官来劝进。夏四月壬戌，更名晃。\n甲子，皇帝即位。戊辰，大赦  ，改\n元，国号梁。封唐主为济阴王。升汴\n州为开封府，建为东都，以唐东都为\n西都。废京兆府为雍州。赐东都酺一\n日。契丹阿保机使袍笏梅老来。  \n五月丁丑朔，以唐相张文蔚杨涉；核对说明：本项目核读电子文本；文字层不是原刻影印，未作纸本校勘。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：新五代史 \n23/1627 \n \n \n梁本纪第二  \n \n开平元年春正月壬寅，天子使御\n史大夫薛贻矩来劳军。宰相张文蔚率\n百官来劝进。夏四月壬戌，更名晃。\n甲子，皇帝即位。戊辰，大赦  ，改\n元，国号梁。封唐主为济阴王。升汴\n州为开封府，建为东都，以唐东都为\n西都。废京兆府为雍州。赐东都酺一\n日。契丹阿保机使袍笏梅老来。  \n五月丁丑朔，以唐相张文蔚杨涉；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 0438ec8a-bd50-5cd3-ad3b-9d27a507ec25'; END IF; END $$;
UPDATE public.fact_claim SET note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"note": "原文：新五代史 \n23/1627 \n \n \n梁本纪第二  \n \n开平元年春正月壬寅，天子使御\n史大夫薛贻矩来劳军。宰相张文蔚率\n百官来劝进。夏四月壬戌，更名晃。\n甲子，皇帝即位。戊辰，大赦  ，改\n元，国号梁。封唐主为济阴王。升汴\n州为开封府，建为东都，以唐东都为\n西都。废京兆府为雍州。赐东都酺一\n日。契丹阿保机使袍笏梅老来。  \n五月丁丑朔，以唐相张文蔚杨涉；核对说明："}'::jsonb) v WHERE fact_claim.id='0438ec8a-bd50-5cd3-ad3b-9d27a507ec25';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='0442bfbe-0dd0-54e3-915b-2dfc43399ead' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p011", "note": "原文：甲辰，唐昭宣帝降御札禅位于梁。以摄中书令张文蔚为册礼使，礼部尚书苏循副之；摄侍中杨涉为押传国宝使，翰林学士张策副之；御史大夫薛贻矩为押金宝使，尚书左丞赵光逢副之；帅百官备法驾诣大梁。杨涉子直史馆凝式言于涉曰：“大人为唐宰相，而国家至此，不可谓之无过。况手持天子玺绶与人，虽保富贵，奈千载何！盍辞之！”涉大骇曰：“汝灭吾族！”神色为之不宁者数日。策，敦煌人。光逢，隐之子也。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第11段", "note": "原文：甲辰，唐昭宣帝降御札禅位于梁。以摄中书令张文蔚为册礼使，礼部尚书苏循副之；摄侍中杨涉为押传国宝使，翰林学士张策副之；御史大夫薛贻矩为押金宝使，尚书左丞赵光逢副之；帅百官备法驾诣大梁。杨涉子直史馆凝式言于涉曰：“大人为唐宰相，而国家至此，不可谓之无过。况手持天子玺绶与人，虽保富贵，奈千载何！盍辞之！”涉大骇曰：“汝灭吾族！”神色为之不宁者数日。策，敦煌人。光逢，隐之子也。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 0442bfbe-0dd0-54e3-915b-2dfc43399ead'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第11段", "note": "原文：甲辰，唐昭宣帝降御札禅位于梁。以摄中书令张文蔚为册礼使，礼部尚书苏循副之；摄侍中杨涉为押传国宝使，翰林学士张策副之；御史大夫薛贻矩为押金宝使，尚书左丞赵光逢副之；帅百官备法驾诣大梁。杨涉子直史馆凝式言于涉曰：“大人为唐宰相，而国家至此，不可谓之无过。况手持天子玺绶与人，虽保富贵，奈千载何！盍辞之！”涉大骇曰：“汝灭吾族！”神色为之不宁者数日。策，敦煌人。光逢，隐之子也。；核对说明："}'::jsonb) v WHERE fact_claim.id='0442bfbe-0dd0-54e3-915b-2dfc43399ead';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='046296c1-a80a-5db9-aaa7-33be9e6b5b32' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p019", "claim_text": "《资治通鉴》907年条所记人物。在“敬翔主持崇政院，枢密院职事并入”中为受命者。本批仅整理相关史事，生卒与完整履历待补。", "note": "原文：以宣武掌书记、太府卿敬翔知崇政院事，以备顾问，参谋议，于禁中承上旨，宣于宰相而行之。宰相非进对时有所奏请及已受旨应复请者，皆具记事因崇政院以闻，得旨则复宣于宰相。翔为人沉深，有智略，在幕府三十馀年，军谋、民政，帝一以委之。翔尽心勤劳，昼夜不寐，自言惟马上乃得休息，帝性暴戾难近，人莫能测，惟翔能识其意趣。或有所不可，翔未尝显言，但微示持疑；帝意已悟，多为之改易。禅代之际，翔谋居多。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第19段", "claim_text": "据《资治通鉴》，907年在“敬翔主持崇政院，枢密院职事并入”中为受命者。", "note": "原文：以宣武掌书记、太府卿敬翔知崇政院事，以备顾问，参谋议，于禁中承上旨，宣于宰相而行之。宰相非进对时有所奏请及已受旨应复请者，皆具记事因崇政院以闻，得旨则复宣于宰相。翔为人沉深，有智略，在幕府三十馀年，军谋、民政，帝一以委之。翔尽心勤劳，昼夜不寐，自言惟马上乃得休息，帝性暴戾难近，人莫能测，惟翔能识其意趣。或有所不可，翔未尝显言，但微示持疑；帝意已悟，多为之改易。禅代之际，翔谋居多。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 046296c1-a80a-5db9-aaa7-33be9e6b5b32'; END IF; END $$;
