DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='048ca31a-0d5a-5c71-a747-db4a6e8a7f0d' AND (to_jsonb(t) @> '{"note": "原文：六月，庚寅朔，賀德倫帥將吏請晉王入府城慰勞。既入，德倫上印節，請王兼領天雄軍，王固辭，曰：「比聞汴寇侵逼貴道，故親董師徒，遠來相救。又聞城中新罹塗炭，故暫入存撫。明公不垂鑒信，乃以印節見推，誠非素懷。」德倫再拜曰：「今寇敵密邇，軍城新有大變，人心未安。德倫腹心紀綱為張彥所殺殆盡，形孤勢弱，安能統眾！一旦生事，恐負大恩。」王乃受之。德倫帥將吏拜賀，王承製以德倫為大同節度使，遣之官。德倫至晉陽，張承業留之。；核对说明：已对照所保存电子文本；尚待人工复核，不视为纸本校勘结论。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：六月，庚寅朔，賀德倫帥將吏請晉王入府城慰勞。既入，德倫上印節，請王兼領天雄軍，王固辭，曰：「比聞汴寇侵逼貴道，故親董師徒，遠來相救。又聞城中新罹塗炭，故暫入存撫。明公不垂鑒信，乃以印節見推，誠非素懷。」德倫再拜曰：「今寇敵密邇，軍城新有大變，人心未安。德倫腹心紀綱為張彥所殺殆盡，形孤勢弱，安能統眾！一旦生事，恐負大恩。」王乃受之。德倫帥將吏拜賀，王承製以德倫為大同節度使，遣之官。德倫至晉陽，張承業留之。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 048ca31a-0d5a-5c71-a747-db4a6e8a7f0d'; END IF; END $$;
