DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='097f3e40-ac88-5f60-8a3b-6097cc3e0dd9' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p035", "note": "原文：礼部尚书苏循及其子起居郎楷自谓有功于梁，当不次擢用；循朝夕望为相，帝薄其为人，敬翔及殿中监李振亦鄙之。翔言于帝曰：“苏循，唐之鸱枭，卖国求利，不可以立于惟新之朝。”戊戍，诏循及刑部尚书张祎等十五人并勒致仕，楷斥归田里。循父子乃之河中依硃友谦。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第35段", "note": "原文：礼部尚书苏循及其子起居郎楷自谓有功于梁，当不次擢用；循朝夕望为相，帝薄其为人，敬翔及殿中监李振亦鄙之。翔言于帝曰：“苏循，唐之鸱枭，卖国求利，不可以立于惟新之朝。”戊戍，诏循及刑部尚书张祎等十五人并勒致仕，楷斥归田里。循父子乃之河中依硃友谦。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 097f3e40-ac88-5f60-8a3b-6097cc3e0dd9'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第35段", "note": "原文：礼部尚书苏循及其子起居郎楷自谓有功于梁，当不次擢用；循朝夕望为相，帝薄其为人，敬翔及殿中监李振亦鄙之。翔言于帝曰：“苏循，唐之鸱枭，卖国求利，不可以立于惟新之朝。”戊戍，诏循及刑部尚书张祎等十五人并勒致仕，楷斥归田里。循父子乃之河中依硃友谦。；核对说明："}'::jsonb) v WHERE fact_claim.id='097f3e40-ac88-5f60-8a3b-6097cc3e0dd9';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='09832cfb-e114-5b0f-863b-3500b4e5c7b5' AND (to_jsonb(t) @> '{"note": "原文：旧五代史 \n80/1667 \n甚厚。宿州刺史王儒进白兔一，濮州\n刺史图嘉禾瑞麦以进。广州进奇宝名\n药，品类甚多。河南尹张全义进开平\n元年已前羡余钱十万贯、绸六千匹、\n绵三十万两，仍请每年上供定额每岁\n贡绢三万匹，以为常式。荆南高季昌\n进瑞橘数十颗，质状百味，倍胜常\n贡。且橘当冬熟，今方仲夏，时人咸\n异其事，因称为瑞。   \n六月，幸乾元院，宴召宰臣、学\n士及诸道入贡陪臣。己亥，帝御崇元\n殿，内出追尊四庙上谥号玉册宝共八\n副，宰臣文武百官仪仗鼓吹导引至太\n庙行事。癸卯，司天监奏：“日辰内\n有‘戊’字，请改为‘武’。”从\n旧五代史 \n81/1667 \n之。癸亥，诏以前朝官僚，谴逐南\n荒，积年未经昭雪，其间有怀抱材器\n为时所嫉者，深负冤抑。仍令录其名\n姓，尽复官资，兼告谕诸道令津致赴\n阙。如已亡殁，并许归葬，以明恩\n荡。以西都徽安门北路逼近大内宫\n垣，兼非民便，令移自榆林直趋端门\n之南。改耀州报恩禅院为兴国寺。马\n殷奏破淮寇；静海军节度使曲裕卒。  \n七月丙申，以静海军行营司马权\n知留后曲颢起复为安南都护，充节度\n使。《五代会要》：七月，敕云：\n“建国迁都，俾新其制，况山河之\n险，表里为防。今二京俱在关东以\n内，仍以潼关隶陕州，复置河潼军；核对说明：本项目核读电子文本；文字层不是原刻影印，未作纸本校勘。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：旧五代史 \n80/1667 \n甚厚。宿州刺史王儒进白兔一，濮州\n刺史图嘉禾瑞麦以进。广州进奇宝名\n药，品类甚多。河南尹张全义进开平\n元年已前羡余钱十万贯、绸六千匹、\n绵三十万两，仍请每年上供定额每岁\n贡绢三万匹，以为常式。荆南高季昌\n进瑞橘数十颗，质状百味，倍胜常\n贡。且橘当冬熟，今方仲夏，时人咸\n异其事，因称为瑞。   \n六月，幸乾元院，宴召宰臣、学\n士及诸道入贡陪臣。己亥，帝御崇元\n殿，内出追尊四庙上谥号玉册宝共八\n副，宰臣文武百官仪仗鼓吹导引至太\n庙行事。癸卯，司天监奏：“日辰内\n有‘戊’字，请改为‘武’。”从\n旧五代史 \n81/1667 \n之。癸亥，诏以前朝官僚，谴逐南\n荒，积年未经昭雪，其间有怀抱材器\n为时所嫉者，深负冤抑。仍令录其名\n姓，尽复官资，兼告谕诸道令津致赴\n阙。如已亡殁，并许归葬，以明恩\n荡。以西都徽安门北路逼近大内宫\n垣，兼非民便，令移自榆林直趋端门\n之南。改耀州报恩禅院为兴国寺。马\n殷奏破淮寇；静海军节度使曲裕卒。  \n七月丙申，以静海军行营司马权\n知留后曲颢起复为安南都护，充节度\n使。《五代会要》：七月，敕云：\n“建国迁都，俾新其制，况山河之\n险，表里为防。今二京俱在关东以\n内，仍以潼关隶陕州，复置河潼军；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 09832cfb-e114-5b0f-863b-3500b4e5c7b5'; END IF; END $$;
