DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='09a1d3ea-3cc3-565b-a634-79647121f09f' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p010", "note": "原文：镇海、镇东节度使吴王钱镠遣其子传镣、传瓘讨卢佶于温州。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第10段", "note": "原文：镇海、镇东节度使吴王钱镠遣其子传镣、传瓘讨卢佶于温州。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 09a1d3ea-3cc3-565b-a634-79647121f09f'; END IF; END $$;
