DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='0b6a1d9d-7de5-595b-a3d3-3bb4ee8599a8' AND (to_jsonb(t) @> '{"note": "原文：駙馬都尉趙巖，犨之子，太祖之婿也；左龍虎統軍、侍衛親軍都指揮使袁象先，太祖之甥也。巖奉使至大梁，均王友貞密與之謀誅友珪，巖曰：「此事成敗，在招討楊令公耳，得其一言諭禁軍，吾事立辦。」均王乃遣腹心馬慎交之魏州說楊師厚曰：「郢王篡弒，人望屬在大梁，公若因而成之，此不世之功也。」且許事成之日賜犒軍錢五十萬緡。師厚與將佐謀之，曰：「方郢王弒逆，吾不能即討；今君臣之分已定，無故改圖，可乎？」或曰：「郢王親弒君父，賊也，均王舉兵復仇，義也。奉義討賊，何君臣之有！彼若一朝破賊，公將何以自處乎？」師厚驚曰：「吾幾誤計。」乃遣其將王舜賢至洛陽，陰與袁象先謀，遣招討馬步都虞候譙人朱漢賓將兵屯滑州為外應。趙巖歸洛陽，亦與象先密定計。；核对说明：已对照所保存电子文本；尚待人工复核，不视为纸本校勘结论。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：駙馬都尉趙巖，犨之子，太祖之婿也；左龍虎統軍、侍衛親軍都指揮使袁象先，太祖之甥也。巖奉使至大梁，均王友貞密與之謀誅友珪，巖曰：「此事成敗，在招討楊令公耳，得其一言諭禁軍，吾事立辦。」均王乃遣腹心馬慎交之魏州說楊師厚曰：「郢王篡弒，人望屬在大梁，公若因而成之，此不世之功也。」且許事成之日賜犒軍錢五十萬緡。師厚與將佐謀之，曰：「方郢王弒逆，吾不能即討；今君臣之分已定，無故改圖，可乎？」或曰：「郢王親弒君父，賊也，均王舉兵復仇，義也。奉義討賊，何君臣之有！彼若一朝破賊，公將何以自處乎？」師厚驚曰：「吾幾誤計。」乃遣其將王舜賢至洛陽，陰與袁象先謀，遣招討馬步都虞候譙人朱漢賓將兵屯滑州為外應。趙巖歸洛陽，亦與象先密定計。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 0b6a1d9d-7de5-595b-a3d3-3bb4ee8599a8'; END IF; END $$;
