DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='0cf8461b-1b17-5f69-a9f5-3b7adada2bdd' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p031", "claim_text": "《资治通鉴》907年条所记人物。在“后梁封朱全昱及诸子为王”中为受封者。本批仅整理相关史事，生卒与完整履历待补。", "note": "原文：乙酉，立皇兄全昱为广王，子友文为博王，友珪为郢王，友璋为福王，友贞为均王，友雍为贺王，友徽为建王。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第31段", "claim_text": "据《资治通鉴》，907年在“后梁封朱全昱及诸子为王”中为受封者。", "note": "原文：乙酉，立皇兄全昱为广王，子友文为博王，友珪为郢王，友璋为福王，友贞为均王，友雍为贺王，友徽为建王。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 0cf8461b-1b17-5f69-a9f5-3b7adada2bdd'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,claim_text=v.claim_text,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第31段", "claim_text": "据《资治通鉴》，907年在“后梁封朱全昱及诸子为王”中为受封者。", "note": "原文：乙酉，立皇兄全昱为广王，子友文为博王，友珪为郢王，友璋为福王，友贞为均王，友雍为贺王，友徽为建王。；核对说明："}'::jsonb) v WHERE fact_claim.id='0cf8461b-1b17-5f69-a9f5-3b7adada2bdd';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='0d191b04-1265-5786-a013-f7ce183dbe16' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p000", "note": "原文：开平元年丁卯，公元九零七年；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·年次题记", "note": "原文：开平元年丁卯，公元九零七年；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 0d191b04-1265-5786-a013-f7ce183dbe16'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·年次题记", "note": "原文：开平元年丁卯，公元九零七年；核对说明："}'::jsonb) v WHERE fact_claim.id='0d191b04-1265-5786-a013-f7ce183dbe16';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='0e1f4e97-d502-5265-970c-788b3d2e278d' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p056", "note": "原文：初，帝在籓镇，用法严，将校有战没者，所部兵悉斩之，谓之跋队斩。士卒失主将者，多亡逸不敢归。帝乃命凡军士皆文其面以记军号。军士或思乡里逃去，关津辄执之送所属，无不死者，其乡里亦不敢容。由是亡者皆聚山泽为盗，大为州县之患。壬寅，诏赦其罪，自今虽文面亦听还乡里。盗减什七八。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第56段", "note": "原文：初，帝在籓镇，用法严，将校有战没者，所部兵悉斩之，谓之跋队斩。士卒失主将者，多亡逸不敢归。帝乃命凡军士皆文其面以记军号。军士或思乡里逃去，关津辄执之送所属，无不死者，其乡里亦不敢容。由是亡者皆聚山泽为盗，大为州县之患。壬寅，诏赦其罪，自今虽文面亦听还乡里。盗减什七八。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 0e1f4e97-d502-5265-970c-788b3d2e278d'; END IF; END $$;
