DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='0e64aa4a-8ad4-5b15-8886-d1ff45dfa762' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p047", "note": "原文：辛亥，以吴越王镠兼淮南节度使，楚王殷兼武昌节度使，各充本道招讨制置使。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第47段", "note": "原文：辛亥，以吴越王镠兼淮南节度使，楚王殷兼武昌节度使，各充本道招讨制置使。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 0e64aa4a-8ad4-5b15-8886-d1ff45dfa762'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第47段", "note": "原文：辛亥，以吴越王镠兼淮南节度使，楚王殷兼武昌节度使，各充本道招讨制置使。；核对说明："}'::jsonb) v WHERE fact_claim.id='0e64aa4a-8ad4-5b15-8886-d1ff45dfa762';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='0efcc6a2-2882-5bb2-8684-cea5eb96ca1c' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p051", "note": "原文：蜀王会将佐议称帝，皆曰：“大王虽忠于唐，唐已亡矣，此所谓‘天与不取’者也。”冯涓独献议，请，以蜀王称制，曰：“朝兴则未爽称臣，贼在则不同为恶。”王不从，涓杜门不出。王用安抚副使、掌书记韦庄之谋，帅吏民哭三日；己亥，即皇帝位，国号大蜀。辛丑，以前东川节度使兼侍中王宗佶为中书令，韦庄为左散骑常侍、判中书门下事，阆州防御使唐道袭为内枢密使。庄，见素之孙也。蜀主虽目不知书，好与书生谈论，粗晓其理。是时唐衣冠之族多避乱在蜀，蜀主礼而用之，使修举故事，故其典章文物有唐之遗风。蜀主长子校书郎宗仁幼以疾废，立其次子秘书少监宗懿为遂王。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第51段", "note": "原文：蜀王会将佐议称帝，皆曰：“大王虽忠于唐，唐已亡矣，此所谓‘天与不取’者也。”冯涓独献议，请，以蜀王称制，曰：“朝兴则未爽称臣，贼在则不同为恶。”王不从，涓杜门不出。王用安抚副使、掌书记韦庄之谋，帅吏民哭三日；己亥，即皇帝位，国号大蜀。辛丑，以前东川节度使兼侍中王宗佶为中书令，韦庄为左散骑常侍、判中书门下事，阆州防御使唐道袭为内枢密使。庄，见素之孙也。蜀主虽目不知书，好与书生谈论，粗晓其理。是时唐衣冠之族多避乱在蜀，蜀主礼而用之，使修举故事，故其典章文物有唐之遗风。蜀主长子校书郎宗仁幼以疾废，立其次子秘书少监宗懿为遂王。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 0efcc6a2-2882-5bb2-8684-cea5eb96ca1c'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第51段", "note": "原文：蜀王会将佐议称帝，皆曰：“大王虽忠于唐，唐已亡矣，此所谓‘天与不取’者也。”冯涓独献议，请，以蜀王称制，曰：“朝兴则未爽称臣，贼在则不同为恶。”王不从，涓杜门不出。王用安抚副使、掌书记韦庄之谋，帅吏民哭三日；己亥，即皇帝位，国号大蜀。辛丑，以前东川节度使兼侍中王宗佶为中书令，韦庄为左散骑常侍、判中书门下事，阆州防御使唐道袭为内枢密使。庄，见素之孙也。蜀主虽目不知书，好与书生谈论，粗晓其理。是时唐衣冠之族多避乱在蜀，蜀主礼而用之，使修举故事，故其典章文物有唐之遗风。蜀主长子校书郎宗仁幼以疾废，立其次子秘书少监宗懿为遂王。；核对说明："}'::jsonb) v WHERE fact_claim.id='0efcc6a2-2882-5bb2-8684-cea5eb96ca1c';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='0f2a3a4c-9d07-54c5-85a1-ca234b01d790' AND (to_jsonb(t) @> '{"note": "原文：旧五代史 \n83/1667 \n树，并图形以献。是月，隰州奏，大\n宁县至固镇上下二百里，今月八日，\n黄河清，至十月如故。   \n九月辛丑，西京大内放出两宫内\n人及前朝宫人，任其所适。敕以近年\n文武官诸道奉使，皆于所在分外停\n住，逾年涉岁，未闻归阙。非惟劳费\n州郡，抑且侮慢国经。臣节既亏，宪\n章安在。自今后两浙、福建、广州、\n安南、邕、容等道使到发许住一月；\n湖南、洪、鄂、黔、桂许住二十日；\n荆、襄、同、雍、镇、定、青、沧许\n住十日；其余侧近不过三五日。凡往\n来道路，据远近里数，日行两驿。如\n遇疾患及江河阻隔，委所在长吏具事\n旧五代史 \n84/1667 \n由奏闻。如或有违，当行朝典，命御\n史点检纠察，以亻敬慢官。魏博罗绍\n威二男廷望、廷矩，年在幼稚，皆有\n材器，帝以其籓屏勋臣之胄，宜受非\n次之用，皆擢为郎。恩命既行之后，\n二子亦就班列。绍威乃上章，以齿幼\n未任公事，乞免主印、宿直。从之。\n封镇东军神祠为崇福侯。浙西奏，道\n门威仪郑章、道士夏隐言，焚修精\n志，妙达希夷，推诸辈流实有道业。\n郑章宜赐号贞一大师，仍名元章，隐\n言赐紫衣。《五代会要》：九月，置\n左右天兴、左右广胜军，仍以亲王为\n军使。   \n十月，帝以用军，未暇西幸，文；核对说明：本项目核读电子文本；文字层不是原刻影印，未作纸本校勘。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：旧五代史 \n83/1667 \n树，并图形以献。是月，隰州奏，大\n宁县至固镇上下二百里，今月八日，\n黄河清，至十月如故。   \n九月辛丑，西京大内放出两宫内\n人及前朝宫人，任其所适。敕以近年\n文武官诸道奉使，皆于所在分外停\n住，逾年涉岁，未闻归阙。非惟劳费\n州郡，抑且侮慢国经。臣节既亏，宪\n章安在。自今后两浙、福建、广州、\n安南、邕、容等道使到发许住一月；\n湖南、洪、鄂、黔、桂许住二十日；\n荆、襄、同、雍、镇、定、青、沧许\n住十日；其余侧近不过三五日。凡往\n来道路，据远近里数，日行两驿。如\n遇疾患及江河阻隔，委所在长吏具事\n旧五代史 \n84/1667 \n由奏闻。如或有违，当行朝典，命御\n史点检纠察，以亻敬慢官。魏博罗绍\n威二男廷望、廷矩，年在幼稚，皆有\n材器，帝以其籓屏勋臣之胄，宜受非\n次之用，皆擢为郎。恩命既行之后，\n二子亦就班列。绍威乃上章，以齿幼\n未任公事，乞免主印、宿直。从之。\n封镇东军神祠为崇福侯。浙西奏，道\n门威仪郑章、道士夏隐言，焚修精\n志，妙达希夷，推诸辈流实有道业。\n郑章宜赐号贞一大师，仍名元章，隐\n言赐紫衣。《五代会要》：九月，置\n左右天兴、左右广胜军，仍以亲王为\n军使。   \n十月，帝以用军，未暇西幸，文；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 0f2a3a4c-9d07-54c5-85a1-ca234b01d790'; END IF; END $$;
