DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='1027bb5c-d118-5189-93d3-4c0e7757a315' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p027", "claim_text": "《资治通鉴》907年条所记人物。在“后梁加授王镕、罗绍威、王处直官衔”中为受授者。本批仅整理相关史事，生卒与完整履历待补。", "note": "原文：加武顺军节度使赵王王镕宁太师，天雄节度使鄴王罗绍威守太傅，义武节度使王处直兼侍中。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第27段", "claim_text": "据《资治通鉴》，907年在“后梁加授王镕、罗绍威、王处直官衔”中为受授者。", "note": "原文：加武顺军节度使赵王王镕宁太师，天雄节度使鄴王罗绍威守太傅，义武节度使王处直兼侍中。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 1027bb5c-d118-5189-93d3-4c0e7757a315'; END IF; END $$;
