DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='113781d7-6264-5923-9058-6378c3eb6eb7' AND (to_jsonb(t) @> '{"note": "原文：六月，庚寅朔，賀德倫帥將吏請晉王入府城慰勞。既入，德倫上印節，請王兼領天雄軍，王固辭，曰：「比聞汴寇侵逼貴道，故親董師徒，遠來相救。又聞城中新罹塗炭，故暫入存撫。明公不垂鑒信，乃以印節見推，誠非素懷。」德倫再拜曰：「今寇敵密邇，軍城新有大變，人心未安。德倫腹心紀綱為張彥所殺殆盡，形孤勢弱，安能統眾！一旦生事，恐負大恩。」王乃受之。德倫帥將吏拜賀，王承製以德倫為大同節度使，遣之官。德倫至晉陽，張承業留之。；核对说明：已对照所保存电子文本；尚待人工复核，不视为纸本校勘结论。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：六月，庚寅朔，賀德倫帥將吏請晉王入府城慰勞。既入，德倫上印節，請王兼領天雄軍，王固辭，曰：「比聞汴寇侵逼貴道，故親董師徒，遠來相救。又聞城中新罹塗炭，故暫入存撫。明公不垂鑒信，乃以印節見推，誠非素懷。」德倫再拜曰：「今寇敵密邇，軍城新有大變，人心未安。德倫腹心紀綱為張彥所殺殆盡，形孤勢弱，安能統眾！一旦生事，恐負大恩。」王乃受之。德倫帥將吏拜賀，王承製以德倫為大同節度使，遣之官。德倫至晉陽，張承業留之。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 113781d7-6264-5923-9058-6378c3eb6eb7'; END IF; END $$;
UPDATE public.fact_claim SET note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"note": "原文：六月，庚寅朔，賀德倫帥將吏請晉王入府城慰勞。既入，德倫上印節，請王兼領天雄軍，王固辭，曰：「比聞汴寇侵逼貴道，故親董師徒，遠來相救。又聞城中新罹塗炭，故暫入存撫。明公不垂鑒信，乃以印節見推，誠非素懷。」德倫再拜曰：「今寇敵密邇，軍城新有大變，人心未安。德倫腹心紀綱為張彥所殺殆盡，形孤勢弱，安能統眾！一旦生事，恐負大恩。」王乃受之。德倫帥將吏拜賀，王承製以德倫為大同節度使，遣之官。德倫至晉陽，張承業留之。；核对说明："}'::jsonb) v WHERE fact_claim.id='113781d7-6264-5923-9058-6378c3eb6eb7';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='1179c255-1bdc-5d9e-87a1-6be67dc9c8c9' AND (to_jsonb(t) @> '{"note": "原文：旧五代史 \n82/1667 \n使，命虢州刺史兼领之。”其月，敕\n改虎牢关为军，仍置虎牢关军使。己\n亥，追尊皇妣为皇太后。   \n八月，以潞州军前屯师旅，壁垒\n未收，乃别议戎帅，于是以亳州刺史\n李思安充潞州行营都统。敕：“朝廷\n之仪，封册为重，用报勋烈，以隆恩\n荣，固合亲临，式光典礼。旧章久\n缺，自我复行。今后每封册大臣，宜\n令有司备临轩之礼。”《五代会\n要》：八月，敕云：“诸道所有军事\n申奏，令直至右银台门，委客省使画\n时引进，寻常公事依前四方馆收\n接。”甲子平明前，老人星见于南\n极。壬申，密州进嘉禾，又有合欢榆；核对说明：本项目核读电子文本；文字层不是原刻影印，未作纸本校勘。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：旧五代史 \n82/1667 \n使，命虢州刺史兼领之。”其月，敕\n改虎牢关为军，仍置虎牢关军使。己\n亥，追尊皇妣为皇太后。   \n八月，以潞州军前屯师旅，壁垒\n未收，乃别议戎帅，于是以亳州刺史\n李思安充潞州行营都统。敕：“朝廷\n之仪，封册为重，用报勋烈，以隆恩\n荣，固合亲临，式光典礼。旧章久\n缺，自我复行。今后每封册大臣，宜\n令有司备临轩之礼。”《五代会\n要》：八月，敕云：“诸道所有军事\n申奏，令直至右银台门，委客省使画\n时引进，寻常公事依前四方馆收\n接。”甲子平明前，老人星见于南\n极。壬申，密州进嘉禾，又有合欢榆；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 1179c255-1bdc-5d9e-87a1-6be67dc9c8c9'; END IF; END $$;
UPDATE public.fact_claim SET note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"note": "原文：旧五代史 \n82/1667 \n使，命虢州刺史兼领之。”其月，敕\n改虎牢关为军，仍置虎牢关军使。己\n亥，追尊皇妣为皇太后。   \n八月，以潞州军前屯师旅，壁垒\n未收，乃别议戎帅，于是以亳州刺史\n李思安充潞州行营都统。敕：“朝廷\n之仪，封册为重，用报勋烈，以隆恩\n荣，固合亲临，式光典礼。旧章久\n缺，自我复行。今后每封册大臣，宜\n令有司备临轩之礼。”《五代会\n要》：八月，敕云：“诸道所有军事\n申奏，令直至右银台门，委客省使画\n时引进，寻常公事依前四方馆收\n接。”甲子平明前，老人星见于南\n极。壬申，密州进嘉禾，又有合欢榆；核对说明："}'::jsonb) v WHERE fact_claim.id='1179c255-1bdc-5d9e-87a1-6be67dc9c8c9';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='11872121-a76d-51d0-ac0e-29da6b63d534' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p037", "claim_text": "《资治通鉴》907年条所记人物。在“楚军击败刘存等淮南水军，攻取岳州”中为淮南将领。本批仅整理相关史事，生卒与完整履历待补。", "note": "原文：弘农王以鄂岳观察使刘存为西南面都招讨使，岳州刺史陈知新为岳州团练使，庐州观察使刘威为应援使，别将许玄应为监军，将水军三万以击楚。楚王马殷甚惧，静江军使杨定真贺曰：“我军胜矣！”殷问其故，定真曰：“夫战惧则胜，骄则败。今淮南兵直趋吾城，是骄而轻敌也；而王有惧色，吾是以知其必胜也。”殷命在城都指挥使秦彦晖将水军三万浮江而下，水军副指挥使黄璠帅战舰三百屯浏阳口。六月，存等遇大雨，引兵还至越堤北，彦晖追之。存数战不利，乃遗殷书诈降。彦晖使谓殷曰：“此必诈也，勿受！”存与彦晖夹水而阵，存遥呼曰：“杀降不祥，公独不为子孙计耶！”彦晖曰：“贼入吾境而不击，奚顾子孙！”鼓噪而进。存等走，黄璠自浏阳引兵绝江，与彦晖合击，大破之，执存及知新，裨将死者百馀人，士卒死者以万数，获战舰八百艘。威以馀众遁归，彦晖遂拔岳州。殷释存、知新之缚，慰谕之。二人皆骂曰：“丈夫以死报主，肯事贼乎！”遂斩之。许玄应，弘农王之腹心也，常预政事，张颢、徐温因其败，收斩之。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第37段", "claim_text": "据《资治通鉴》，907年在“楚军击败刘存等淮南水军，攻取岳州”中为淮南将领。", "note": "原文：弘农王以鄂岳观察使刘存为西南面都招讨使，岳州刺史陈知新为岳州团练使，庐州观察使刘威为应援使，别将许玄应为监军，将水军三万以击楚。楚王马殷甚惧，静江军使杨定真贺曰：“我军胜矣！”殷问其故，定真曰：“夫战惧则胜，骄则败。今淮南兵直趋吾城，是骄而轻敌也；而王有惧色，吾是以知其必胜也。”殷命在城都指挥使秦彦晖将水军三万浮江而下，水军副指挥使黄璠帅战舰三百屯浏阳口。六月，存等遇大雨，引兵还至越堤北，彦晖追之。存数战不利，乃遗殷书诈降。彦晖使谓殷曰：“此必诈也，勿受！”存与彦晖夹水而阵，存遥呼曰：“杀降不祥，公独不为子孙计耶！”彦晖曰：“贼入吾境而不击，奚顾子孙！”鼓噪而进。存等走，黄璠自浏阳引兵绝江，与彦晖合击，大破之，执存及知新，裨将死者百馀人，士卒死者以万数，获战舰八百艘。威以馀众遁归，彦晖遂拔岳州。殷释存、知新之缚，慰谕之。二人皆骂曰：“丈夫以死报主，肯事贼乎！”遂斩之。许玄应，弘农王之腹心也，常预政事，张颢、徐温因其败，收斩之。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 11872121-a76d-51d0-ac0e-29da6b63d534'; END IF; END $$;
