DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='12a89fcc-7a99-5675-b211-14dcec77b0f4' AND (to_jsonb(t) @> '{"note": "原文：新五代史 \n24/1627 \n为门下侍郎，御史大夫薛贻矩为中书\n侍郎；同中书门下平章事。戊寅，渤\n海、契丹遣使者来。乙酉，封兄全昱\n为广王，子友文博王，友珪郢王，友\n璋福王，友贞均王，友徽建王，侄友\n谅衡王，友能惠王，友诲邵王。甲\n午，改枢密院为崇政院，太府卿敬翔\n为使。是月，潞州行营都指挥使李思\n安及晋人战，败绩。六月甲寅，平卢\n军节度使韩建守司徒，同中书门下平\n章事。秋七月己亥，追尊祖考为皇\n帝，妣为皇后；皇高祖黯谥曰宣元，\n庙号肃祖，祖妣范氏谥曰宣僖；曾祖\n茂琳谥曰光献，庙号敬祖，祖妣杨氏\n谥曰光孝；祖信谥曰昭武，庙号宪；核对说明：本项目核读电子文本；文字层不是原刻影印，未作纸本校勘。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：新五代史 \n24/1627 \n为门下侍郎，御史大夫薛贻矩为中书\n侍郎；同中书门下平章事。戊寅，渤\n海、契丹遣使者来。乙酉，封兄全昱\n为广王，子友文博王，友珪郢王，友\n璋福王，友贞均王，友徽建王，侄友\n谅衡王，友能惠王，友诲邵王。甲\n午，改枢密院为崇政院，太府卿敬翔\n为使。是月，潞州行营都指挥使李思\n安及晋人战，败绩。六月甲寅，平卢\n军节度使韩建守司徒，同中书门下平\n章事。秋七月己亥，追尊祖考为皇\n帝，妣为皇后；皇高祖黯谥曰宣元，\n庙号肃祖，祖妣范氏谥曰宣僖；曾祖\n茂琳谥曰光献，庙号敬祖，祖妣杨氏\n谥曰光孝；祖信谥曰昭武，庙号宪；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 12a89fcc-7a99-5675-b211-14dcec77b0f4'; END IF; END $$;
UPDATE public.fact_claim SET note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"note": "原文：新五代史 \n24/1627 \n为门下侍郎，御史大夫薛贻矩为中书\n侍郎；同中书门下平章事。戊寅，渤\n海、契丹遣使者来。乙酉，封兄全昱\n为广王，子友文博王，友珪郢王，友\n璋福王，友贞均王，友徽建王，侄友\n谅衡王，友能惠王，友诲邵王。甲\n午，改枢密院为崇政院，太府卿敬翔\n为使。是月，潞州行营都指挥使李思\n安及晋人战，败绩。六月甲寅，平卢\n军节度使韩建守司徒，同中书门下平\n章事。秋七月己亥，追尊祖考为皇\n帝，妣为皇后；皇高祖黯谥曰宣元，\n庙号肃祖，祖妣范氏谥曰宣僖；曾祖\n茂琳谥曰光献，庙号敬祖，祖妣杨氏\n谥曰光孝；祖信谥曰昭武，庙号宪；核对说明："}'::jsonb) v WHERE fact_claim.id='12a89fcc-7a99-5675-b211-14dcec77b0f4';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='134839ee-5cc5-51ce-b833-0cc94e273f6e' AND (to_jsonb(t) @> '{"note": "原文：晉兵無復部伍。梁兵四集，勢甚盛。晉王據高丘收散兵，至日中，軍復振。陂中有土山，賀瑰引兵據之。晉王謂將士曰：「今日得此山者勝，吾與汝曹奪之。」即引騎兵先登，李從珂與銀槍大將王建及以步卒繼之，梁兵紛紛而下，遂奪其山。\n日向晡，賀瑰陳於山西，晉兵望之有懼色。諸將以為諸軍未盡集，不若斂兵還營，詰朝復戰。天平節度使、東南面招討使閻寶曰：「王彥章騎兵已入濮陽，山下惟步卒，向晚皆有歸志，我乘高趣下擊之，破之必矣。今王深入敵境，偏師不利，若復引退，必為所乘。諸軍未集者聞梁再克，必不戰自潰。凡決勝料敵，惟觀情勢，情勢已得，斷在不疑。王之成敗，在此一戰；若不決力取勝，縱收餘眾北歸，河朔非王有也。」昭義節度使李嗣昭曰：「賊無營壘，日晚思歸，但以精騎擾之，使不得夕食，俟其引退，追擊可破也。我若斂兵還營，彼歸整眾復來，勝負未可知也。」王建及擐甲橫槊而進曰：「賊大將已遁，王之騎軍一無所失，今擊此疲乏之眾，如拉朽耳。王但登山，觀臣為王破賊。」王愕然曰：「非公等言，吾幾誤計。」嗣昭、建及以騎兵大呼陷陳，諸軍繼之，梁兵大敗。元城令吳瓊、貴鄉令胡裝，各帥白丁萬人，於山下曳柴揚塵，鼓噪以助其勢。梁兵自相騰藉，棄甲山積，死亡者幾三萬人。裝，證之曾孫也。是日，兩軍所喪士卒各三之二，皆不能振。；核对说明：已对照所保存电子文本；尚待人工复核，不视为纸本校勘结论。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：晉兵無復部伍。梁兵四集，勢甚盛。晉王據高丘收散兵，至日中，軍復振。陂中有土山，賀瑰引兵據之。晉王謂將士曰：「今日得此山者勝，吾與汝曹奪之。」即引騎兵先登，李從珂與銀槍大將王建及以步卒繼之，梁兵紛紛而下，遂奪其山。\n日向晡，賀瑰陳於山西，晉兵望之有懼色。諸將以為諸軍未盡集，不若斂兵還營，詰朝復戰。天平節度使、東南面招討使閻寶曰：「王彥章騎兵已入濮陽，山下惟步卒，向晚皆有歸志，我乘高趣下擊之，破之必矣。今王深入敵境，偏師不利，若復引退，必為所乘。諸軍未集者聞梁再克，必不戰自潰。凡決勝料敵，惟觀情勢，情勢已得，斷在不疑。王之成敗，在此一戰；若不決力取勝，縱收餘眾北歸，河朔非王有也。」昭義節度使李嗣昭曰：「賊無營壘，日晚思歸，但以精騎擾之，使不得夕食，俟其引退，追擊可破也。我若斂兵還營，彼歸整眾復來，勝負未可知也。」王建及擐甲橫槊而進曰：「賊大將已遁，王之騎軍一無所失，今擊此疲乏之眾，如拉朽耳。王但登山，觀臣為王破賊。」王愕然曰：「非公等言，吾幾誤計。」嗣昭、建及以騎兵大呼陷陳，諸軍繼之，梁兵大敗。元城令吳瓊、貴鄉令胡裝，各帥白丁萬人，於山下曳柴揚塵，鼓噪以助其勢。梁兵自相騰藉，棄甲山積，死亡者幾三萬人。裝，證之曾孫也。是日，兩軍所喪士卒各三之二，皆不能振。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 134839ee-5cc5-51ce-b833-0cc94e273f6e'; END IF; END $$;
