DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='13f68b79-0d15-5977-9147-7099142dcd6d' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p026", "note": "原文：五月，丁丑朔，以御史大夫薛贻矩为中书侍郎、同平章事。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第26段", "note": "原文：五月，丁丑朔，以御史大夫薛贻矩为中书侍郎、同平章事。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 13f68b79-0d15-5977-9147-7099142dcd6d'; END IF; END $$;
