DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='15f244cc-c621-5e08-b939-6473d8e20e2c' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p030", "claim_text": "《资治通鉴》907年条所记人物。在“高季昌受命为荆南节度使”中为受任者。本批仅整理相关史事，生卒与完整履历待补。", "note": "原文：癸未，以权知荆南留后高季昌为节度使。荆南旧统八州，乾符以来，寇乱相继，诸州皆为邻道所据，独馀江陵。季昌到官，城邑残毁，户口雕耗。季昌安集流散，民皆复业。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第30段", "claim_text": "据《资治通鉴》，907年在“高季昌受命为荆南节度使”中为受任者。", "note": "原文：癸未，以权知荆南留后高季昌为节度使。荆南旧统八州，乾符以来，寇乱相继，诸州皆为邻道所据，独馀江陵。季昌到官，城邑残毁，户口雕耗。季昌安集流散，民皆复业。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 15f244cc-c621-5e08-b939-6473d8e20e2c'; END IF; END $$;
