DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='1788d93b-5da6-5de7-a94e-565cc98e66e4' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p055", "note": "原文：天雄节度使鄴王绍威谓其下曰：“守光以窘急归国，守文孤立无援，沧州可不战服也。”乃遗守文书，谕以祸福。守文亦恐梁乘虚袭其后，戊子，遣使请降，以子延祐为质。帝拊手曰：“绍威折简，胜十万兵！”加守文中书令，抚纳之。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第55段", "note": "原文：天雄节度使鄴王绍威谓其下曰：“守光以窘急归国，守文孤立无援，沧州可不战服也。”乃遗守文书，谕以祸福。守文亦恐梁乘虚袭其后，戊子，遣使请降，以子延祐为质。帝拊手曰：“绍威折简，胜十万兵！”加守文中书令，抚纳之。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 1788d93b-5da6-5de7-a94e-565cc98e66e4'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第55段", "note": "原文：天雄节度使鄴王绍威谓其下曰：“守光以窘急归国，守文孤立无援，沧州可不战服也。”乃遗守文书，谕以祸福。守文亦恐梁乘虚袭其后，戊子，遣使请降，以子延祐为质。帝拊手曰：“绍威折简，胜十万兵！”加守文中书令，抚纳之。；核对说明："}'::jsonb) v WHERE fact_claim.id='1788d93b-5da6-5de7-a94e-565cc98e66e4';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='179d00da-d182-5167-88fe-e73133ab20c5' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p052", "note": "原文：冬，十月，高季昌遣其将倪可福会楚将秦彦晖攻朗州，雷彦恭遣使乞降于淮南，且告急。弘农王遣将泠业将水军屯平江，李饶将步骑屯浏阳以救之，楚王殷遣岳州刺史许德勋将兵拒之。泠业进屯朗口，德勋使善游者五十人，以木枝叶覆其首，持长刀浮江而下，夜犯其营，且举火，业军中惊扰。德以大军进击，大破之，追至鹿角镇，擒业；又破浏阳寨，擒李饶；掠上高、唐年而归。斩业、饶于长沙市。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第52段", "note": "原文：冬，十月，高季昌遣其将倪可福会楚将秦彦晖攻朗州，雷彦恭遣使乞降于淮南，且告急。弘农王遣将泠业将水军屯平江，李饶将步骑屯浏阳以救之，楚王殷遣岳州刺史许德勋将兵拒之。泠业进屯朗口，德勋使善游者五十人，以木枝叶覆其首，持长刀浮江而下，夜犯其营，且举火，业军中惊扰。德以大军进击，大破之，追至鹿角镇，擒业；又破浏阳寨，擒李饶；掠上高、唐年而归。斩业、饶于长沙市。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 179d00da-d182-5167-88fe-e73133ab20c5'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第52段", "note": "原文：冬，十月，高季昌遣其将倪可福会楚将秦彦晖攻朗州，雷彦恭遣使乞降于淮南，且告急。弘农王遣将泠业将水军屯平江，李饶将步骑屯浏阳以救之，楚王殷遣岳州刺史许德勋将兵拒之。泠业进屯朗口，德勋使善游者五十人，以木枝叶覆其首，持长刀浮江而下，夜犯其营，且举火，业军中惊扰。德以大军进击，大破之，追至鹿角镇，擒业；又破浏阳寨，擒李饶；掠上高、唐年而归。斩业、饶于长沙市。；核对说明："}'::jsonb) v WHERE fact_claim.id='179d00da-d182-5167-88fe-e73133ab20c5';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='17bdc810-25bb-5444-b490-680c71e4353f' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p035", "claim_text": "《资治通鉴》907年条所记人物。在“后梁勒令苏循、张祎等致仕”中为接纳者。本批仅整理相关史事，生卒与完整履历待补。", "note": "原文：礼部尚书苏循及其子起居郎楷自谓有功于梁，当不次擢用；循朝夕望为相，帝薄其为人，敬翔及殿中监李振亦鄙之。翔言于帝曰：“苏循，唐之鸱枭，卖国求利，不可以立于惟新之朝。”戊戍，诏循及刑部尚书张祎等十五人并勒致仕，楷斥归田里。循父子乃之河中依硃友谦。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第35段", "claim_text": "据《资治通鉴》，907年在“后梁勒令苏循、张祎等致仕”中为接纳者。", "note": "原文：礼部尚书苏循及其子起居郎楷自谓有功于梁，当不次擢用；循朝夕望为相，帝薄其为人，敬翔及殿中监李振亦鄙之。翔言于帝曰：“苏循，唐之鸱枭，卖国求利，不可以立于惟新之朝。”戊戍，诏循及刑部尚书张祎等十五人并勒致仕，楷斥归田里。循父子乃之河中依硃友谦。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 17bdc810-25bb-5444-b490-680c71e4353f'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,claim_text=v.claim_text,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第35段", "claim_text": "据《资治通鉴》，907年在“后梁勒令苏循、张祎等致仕”中为接纳者。", "note": "原文：礼部尚书苏循及其子起居郎楷自谓有功于梁，当不次擢用；循朝夕望为相，帝薄其为人，敬翔及殿中监李振亦鄙之。翔言于帝曰：“苏循，唐之鸱枭，卖国求利，不可以立于惟新之朝。”戊戍，诏循及刑部尚书张祎等十五人并勒致仕，楷斥归田里。循父子乃之河中依硃友谦。；核对说明："}'::jsonb) v WHERE fact_claim.id='17bdc810-25bb-5444-b490-680c71e4353f';
