UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第44段", "note": "原文：静海节度使曲裕卒，丙申，以其子权知留后颢为节度使。；核对说明："}'::jsonb) v WHERE fact_claim.id='1894e34f-5e03-5e94-b245-8a1219e4cd21';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='18c88aff-d2a9-5606-82ca-56fe74013a32' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p049", "note": "原文：丁已，帝以亳州刺史李思安代怀贞为潞州行营都统，黜怀贞为行营都虞候。思安将河北兵西上，至潞州城下，更筑重城，内以防奔突，外以拒援兵，谓之夹寨。调山东民馈军粮，德威日以轻骑抄之，思安乃自东南山口筑甬道，属于夹寨。德威与诸将互往攻之，排墙填堑，一昼夜间数十发，梁兵疲于奔命。夹寨中出刍牧者，德威辄抄之，于是梁兵闭壁不出。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第49段", "note": "原文：丁已，帝以亳州刺史李思安代怀贞为潞州行营都统，黜怀贞为行营都虞候。思安将河北兵西上，至潞州城下，更筑重城，内以防奔突，外以拒援兵，谓之夹寨。调山东民馈军粮，德威日以轻骑抄之，思安乃自东南山口筑甬道，属于夹寨。德威与诸将互往攻之，排墙填堑，一昼夜间数十发，梁兵疲于奔命。夹寨中出刍牧者，德威辄抄之，于是梁兵闭壁不出。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 18c88aff-d2a9-5606-82ca-56fe74013a32'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第49段", "note": "原文：丁已，帝以亳州刺史李思安代怀贞为潞州行营都统，黜怀贞为行营都虞候。思安将河北兵西上，至潞州城下，更筑重城，内以防奔突，外以拒援兵，谓之夹寨。调山东民馈军粮，德威日以轻骑抄之，思安乃自东南山口筑甬道，属于夹寨。德威与诸将互往攻之，排墙填堑，一昼夜间数十发，梁兵疲于奔命。夹寨中出刍牧者，德威辄抄之，于是梁兵闭壁不出。；核对说明："}'::jsonb) v WHERE fact_claim.id='18c88aff-d2a9-5606-82ca-56fe74013a32';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='18d0aa9b-37f8-57ed-b308-559177dc1e60' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p052", "claim_text": "《资治通鉴》907年条所记人物。在“荆南、楚军攻朗州，许德勋击败淮南援军”中为进攻者。本批仅整理相关史事，生卒与完整履历待补。", "note": "原文：冬，十月，高季昌遣其将倪可福会楚将秦彦晖攻朗州，雷彦恭遣使乞降于淮南，且告急。弘农王遣将泠业将水军屯平江，李饶将步骑屯浏阳以救之，楚王殷遣岳州刺史许德勋将兵拒之。泠业进屯朗口，德勋使善游者五十人，以木枝叶覆其首，持长刀浮江而下，夜犯其营，且举火，业军中惊扰。德以大军进击，大破之，追至鹿角镇，擒业；又破浏阳寨，擒李饶；掠上高、唐年而归。斩业、饶于长沙市。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第52段", "claim_text": "据《资治通鉴》，907年在“荆南、楚军攻朗州，许德勋击败淮南援军”中为进攻者。", "note": "原文：冬，十月，高季昌遣其将倪可福会楚将秦彦晖攻朗州，雷彦恭遣使乞降于淮南，且告急。弘农王遣将泠业将水军屯平江，李饶将步骑屯浏阳以救之，楚王殷遣岳州刺史许德勋将兵拒之。泠业进屯朗口，德勋使善游者五十人，以木枝叶覆其首，持长刀浮江而下，夜犯其营，且举火，业军中惊扰。德以大军进击，大破之，追至鹿角镇，擒业；又破浏阳寨，擒李饶；掠上高、唐年而归。斩业、饶于长沙市。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 18d0aa9b-37f8-57ed-b308-559177dc1e60'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,claim_text=v.claim_text,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第52段", "claim_text": "据《资治通鉴》，907年在“荆南、楚军攻朗州，许德勋击败淮南援军”中为进攻者。", "note": "原文：冬，十月，高季昌遣其将倪可福会楚将秦彦晖攻朗州，雷彦恭遣使乞降于淮南，且告急。弘农王遣将泠业将水军屯平江，李饶将步骑屯浏阳以救之，楚王殷遣岳州刺史许德勋将兵拒之。泠业进屯朗口，德勋使善游者五十人，以木枝叶覆其首，持长刀浮江而下，夜犯其营，且举火，业军中惊扰。德以大军进击，大破之，追至鹿角镇，擒业；又破浏阳寨，擒李饶；掠上高、唐年而归。斩业、饶于长沙市。；核对说明："}'::jsonb) v WHERE fact_claim.id='18d0aa9b-37f8-57ed-b308-559177dc1e60';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='195c2f08-e22c-542b-a506-cc9b3c6edb99' AND (to_jsonb(t) @> '{"note": "原文：甲子，張文蔚、楊涉乘輅自上源驛從冊寶，諸司各備儀衛鹵簿前導，百官從其後，至金祥殿前陳之。王被兗冕，即皇帝位。張文蔚、蘇循奉冊升殿進讀，楊涉、張策、薛貽矩、趙光逢以次奉寶升殿，讀已，降，帥百官舞蹈稱賀。帝遂與文蔚等宴於玄德殿。帝舉酒曰：「朕輔政未久，此皆諸公推戴之力。」文蔚等皆慚懼，俯伏不能對，獨蘇循、薛貽矩及刑部尚書張禕盛稱帝功德宜應天順人。帝復與宗戚飲博於宮中，酒酣，朱全昱忽以投瓊擊盆中迸散，睨帝曰：「朱三，汝本碭山一民也，從黃巢為盜，天子用汝為四鎮節度使，富貴極矣！奈何一旦滅唐家三百年社稷，自稱帝王！行當族滅，奚以博為！」帝不懌而罷。乙丑，命有司告天地、宗廟、社稷。丁卯，遣使宣諭州、鎮。戊辰，大赦，改元，國號大梁。奉唐昭宣帝為濟陰王，皆如前代故事，唐中外舊臣官爵並如故。以汴州為開封府，命曰東都；以故東都為西都；廢故西京，以京兆府為大安府，置佑國軍於大安府，更名魏博曰天雄軍。遷濟陰王於曹州，栫之以棘，使甲士守之。；核对说明：已对照所保存电子文本；尚待人工复核，不视为纸本校勘结论。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：甲子，張文蔚、楊涉乘輅自上源驛從冊寶，諸司各備儀衛鹵簿前導，百官從其後，至金祥殿前陳之。王被兗冕，即皇帝位。張文蔚、蘇循奉冊升殿進讀，楊涉、張策、薛貽矩、趙光逢以次奉寶升殿，讀已，降，帥百官舞蹈稱賀。帝遂與文蔚等宴於玄德殿。帝舉酒曰：「朕輔政未久，此皆諸公推戴之力。」文蔚等皆慚懼，俯伏不能對，獨蘇循、薛貽矩及刑部尚書張禕盛稱帝功德宜應天順人。帝復與宗戚飲博於宮中，酒酣，朱全昱忽以投瓊擊盆中迸散，睨帝曰：「朱三，汝本碭山一民也，從黃巢為盜，天子用汝為四鎮節度使，富貴極矣！奈何一旦滅唐家三百年社稷，自稱帝王！行當族滅，奚以博為！」帝不懌而罷。乙丑，命有司告天地、宗廟、社稷。丁卯，遣使宣諭州、鎮。戊辰，大赦，改元，國號大梁。奉唐昭宣帝為濟陰王，皆如前代故事，唐中外舊臣官爵並如故。以汴州為開封府，命曰東都；以故東都為西都；廢故西京，以京兆府為大安府，置佑國軍於大安府，更名魏博曰天雄軍。遷濟陰王於曹州，栫之以棘，使甲士守之。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 195c2f08-e22c-542b-a506-cc9b3c6edb99'; END IF; END $$;
