DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='212809d5-b3bb-5315-a45e-a082566231c3' AND (to_jsonb(t) @> '{"note": "原文：旧五代史 \n75/1667 \n追谥昭懿皇后；皇考文明王上谥曰文\n穆皇帝，庙号烈祖，第四室，陵号咸\n宁，皇妣晋国太夫人王氏追谥文惠皇\n后。以宣武节度副使皇子友文为开封\n尹，判建昌院事。友文，本康氏子\n也，帝养以为子。   \n是月，制宫殿门及都门名额：正\n殿为崇元殿，东殿为元德殿，内殿为\n金祥殿，万岁堂为万岁殿，门如殿\n名。帝自谓以金德王，又以福建上献\n鹦鹉，诸州相继上白乌、白兔洎白莲\n之合蒂者，以为金行应运之兆，故名\n殿曰金祥。以大内正门为元化门，皇\n墙南门为建国门，滴漏门为启运门，\n下马门为升龙门，元德殿前门为崇明；核对说明：本项目核读电子文本；文字层不是原刻影印，未作纸本校勘。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：旧五代史 \n75/1667 \n追谥昭懿皇后；皇考文明王上谥曰文\n穆皇帝，庙号烈祖，第四室，陵号咸\n宁，皇妣晋国太夫人王氏追谥文惠皇\n后。以宣武节度副使皇子友文为开封\n尹，判建昌院事。友文，本康氏子\n也，帝养以为子。   \n是月，制宫殿门及都门名额：正\n殿为崇元殿，东殿为元德殿，内殿为\n金祥殿，万岁堂为万岁殿，门如殿\n名。帝自谓以金德王，又以福建上献\n鹦鹉，诸州相继上白乌、白兔洎白莲\n之合蒂者，以为金行应运之兆，故名\n殿曰金祥。以大内正门为元化门，皇\n墙南门为建国门，滴漏门为启运门，\n下马门为升龙门，元德殿前门为崇明；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 212809d5-b3bb-5315-a45e-a082566231c3'; END IF; END $$;
