DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='223b85a5-2db7-5dd5-9bc2-8da151beecef' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p013", "claim_text": "《资治通鉴》907年条所记人物。在“王思同、李承约等离开幽州投奔河东”中为归附者。本批仅整理相关史事，生卒与完整履历待补。", "note": "原文：仁恭有爱妾罗氏，其子守光通焉。仁恭杖守光而斥之，不以为子数。李思安引兵入其境，所过焚荡无馀。夏，四月，己酉，直抵幽州城下。仁恭犹在大安山。城中无备，几至不守。守光自外引兵入，登城拒守；又出兵与思安战，思安败退。守光遂自称节度使，命部将李小喜、元行钦将兵攻大安山。仁恭遣兵拒战，为小喜所败。虏仁恭以归，囚于别室。仁恭将佐及左右，凡守光素所恶者皆杀之。银胡录都指挥使王思同帅部兵三千，山后八安巡检使李承约帅部兵二千奔河东，守光弟守奇奔契丹，未几，亦奔河东，河东节度使晋王克用以承约为匡霸指挥使，思同为飞腾指挥使。思同母，仁恭之女也。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第13段", "claim_text": "据《资治通鉴》，907年在“王思同、李承约等离开幽州投奔河东”中为归附者。", "note": "原文：仁恭有爱妾罗氏，其子守光通焉。仁恭杖守光而斥之，不以为子数。李思安引兵入其境，所过焚荡无馀。夏，四月，己酉，直抵幽州城下。仁恭犹在大安山。城中无备，几至不守。守光自外引兵入，登城拒守；又出兵与思安战，思安败退。守光遂自称节度使，命部将李小喜、元行钦将兵攻大安山。仁恭遣兵拒战，为小喜所败。虏仁恭以归，囚于别室。仁恭将佐及左右，凡守光素所恶者皆杀之。银胡录都指挥使王思同帅部兵三千，山后八安巡检使李承约帅部兵二千奔河东，守光弟守奇奔契丹，未几，亦奔河东，河东节度使晋王克用以承约为匡霸指挥使，思同为飞腾指挥使。思同母，仁恭之女也。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 223b85a5-2db7-5dd5-9bc2-8da151beecef'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,claim_text=v.claim_text,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第13段", "claim_text": "据《资治通鉴》，907年在“王思同、李承约等离开幽州投奔河东”中为归附者。", "note": "原文：仁恭有爱妾罗氏，其子守光通焉。仁恭杖守光而斥之，不以为子数。李思安引兵入其境，所过焚荡无馀。夏，四月，己酉，直抵幽州城下。仁恭犹在大安山。城中无备，几至不守。守光自外引兵入，登城拒守；又出兵与思安战，思安败退。守光遂自称节度使，命部将李小喜、元行钦将兵攻大安山。仁恭遣兵拒战，为小喜所败。虏仁恭以归，囚于别室。仁恭将佐及左右，凡守光素所恶者皆杀之。银胡录都指挥使王思同帅部兵三千，山后八安巡检使李承约帅部兵二千奔河东，守光弟守奇奔契丹，未几，亦奔河东，河东节度使晋王克用以承约为匡霸指挥使，思同为飞腾指挥使。思同母，仁恭之女也。；核对说明："}'::jsonb) v WHERE fact_claim.id='223b85a5-2db7-5dd5-9bc2-8da151beecef';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='22b267bb-0809-5b62-ac22-01c59d04ef78' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p052", "note": "原文：冬，十月，高季昌遣其将倪可福会楚将秦彦晖攻朗州，雷彦恭遣使乞降于淮南，且告急。弘农王遣将泠业将水军屯平江，李饶将步骑屯浏阳以救之，楚王殷遣岳州刺史许德勋将兵拒之。泠业进屯朗口，德勋使善游者五十人，以木枝叶覆其首，持长刀浮江而下，夜犯其营，且举火，业军中惊扰。德以大军进击，大破之，追至鹿角镇，擒业；又破浏阳寨，擒李饶；掠上高、唐年而归。斩业、饶于长沙市。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第52段", "note": "原文：冬，十月，高季昌遣其将倪可福会楚将秦彦晖攻朗州，雷彦恭遣使乞降于淮南，且告急。弘农王遣将泠业将水军屯平江，李饶将步骑屯浏阳以救之，楚王殷遣岳州刺史许德勋将兵拒之。泠业进屯朗口，德勋使善游者五十人，以木枝叶覆其首，持长刀浮江而下，夜犯其营，且举火，业军中惊扰。德以大军进击，大破之，追至鹿角镇，擒业；又破浏阳寨，擒李饶；掠上高、唐年而归。斩业、饶于长沙市。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 22b267bb-0809-5b62-ac22-01c59d04ef78'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第52段", "note": "原文：冬，十月，高季昌遣其将倪可福会楚将秦彦晖攻朗州，雷彦恭遣使乞降于淮南，且告急。弘农王遣将泠业将水军屯平江，李饶将步骑屯浏阳以救之，楚王殷遣岳州刺史许德勋将兵拒之。泠业进屯朗口，德勋使善游者五十人，以木枝叶覆其首，持长刀浮江而下，夜犯其营，且举火，业军中惊扰。德以大军进击，大破之，追至鹿角镇，擒业；又破浏阳寨，擒李饶；掠上高、唐年而归。斩业、饶于长沙市。；核对说明："}'::jsonb) v WHERE fact_claim.id='22b267bb-0809-5b62-ac22-01c59d04ef78';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='22e835e0-0089-5b9e-ab14-1cd87d8ec9fa' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p019", "note": "原文：以宣武掌书记、太府卿敬翔知崇政院事，以备顾问，参谋议，于禁中承上旨，宣于宰相而行之。宰相非进对时有所奏请及已受旨应复请者，皆具记事因崇政院以闻，得旨则复宣于宰相。翔为人沉深，有智略，在幕府三十馀年，军谋、民政，帝一以委之。翔尽心勤劳，昼夜不寐，自言惟马上乃得休息，帝性暴戾难近，人莫能测，惟翔能识其意趣。或有所不可，翔未尝显言，但微示持疑；帝意已悟，多为之改易。禅代之际，翔谋居多。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第19段", "note": "原文：以宣武掌书记、太府卿敬翔知崇政院事，以备顾问，参谋议，于禁中承上旨，宣于宰相而行之。宰相非进对时有所奏请及已受旨应复请者，皆具记事因崇政院以闻，得旨则复宣于宰相。翔为人沉深，有智略，在幕府三十馀年，军谋、民政，帝一以委之。翔尽心勤劳，昼夜不寐，自言惟马上乃得休息，帝性暴戾难近，人莫能测，惟翔能识其意趣。或有所不可，翔未尝显言，但微示持疑；帝意已悟，多为之改易。禅代之际，翔谋居多。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 22e835e0-0089-5b9e-ab14-1cd87d8ec9fa'; END IF; END $$;
