DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='2482f087-824d-5811-8ced-8b520bbb77a0' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p028", "note": "原文：契丹遣其臣袍笏梅老来通好，帝遣太府少卿高颀报之。初，契丹有八部，部各有大人，相与约，推一人为王，建旗鼓以号令诸部，每三年则以次相代。咸通末，有习尔者为王，土宇始大。其后钦德为王，乘中原多故，时入盗边。及阿保机为王，尤雄勇，五姓奚及七姓室韦、达靼咸役属之。阿保机姓邪律氏，恃其强，不肯受代。久之，阿保机击黄头室韦还，七部劫之于境上，求如约。阿保机不得已，传旗鼓，且曰：“我为王九年，得汉人多，请帅种落居古汉城，与汉人守之，别自为一部。”七部许之。汉城者，故后魏滑盐县也。地宜五谷，有盐池之利。其后阿保机稍以兵击灭七部，复并为一国。又北侵室韦、女真，西取突阙故地，击奚，灭之，复立奚王而使契丹监其兵，东北诸夷皆畏服之。是岁，阿保机帅众三十万寇云州，晋王与之连和，面会东城，约为兄弟，延之帐中，纵酒，握手尽欢，约以今冬共击梁。或劝晋王：“因其来，可擒也，”王曰：“仇敌未灭而失信夷狄，自亡之道也。”阿保机留旬日乃去，晋王赠以金缯数万。阿保机留马三千匹，杂畜万计以酬之。阿保机既归而背盟，更附于梁，晋王由是而恨之。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第28段", "note": "原文：契丹遣其臣袍笏梅老来通好，帝遣太府少卿高颀报之。初，契丹有八部，部各有大人，相与约，推一人为王，建旗鼓以号令诸部，每三年则以次相代。咸通末，有习尔者为王，土宇始大。其后钦德为王，乘中原多故，时入盗边。及阿保机为王，尤雄勇，五姓奚及七姓室韦、达靼咸役属之。阿保机姓邪律氏，恃其强，不肯受代。久之，阿保机击黄头室韦还，七部劫之于境上，求如约。阿保机不得已，传旗鼓，且曰：“我为王九年，得汉人多，请帅种落居古汉城，与汉人守之，别自为一部。”七部许之。汉城者，故后魏滑盐县也。地宜五谷，有盐池之利。其后阿保机稍以兵击灭七部，复并为一国。又北侵室韦、女真，西取突阙故地，击奚，灭之，复立奚王而使契丹监其兵，东北诸夷皆畏服之。是岁，阿保机帅众三十万寇云州，晋王与之连和，面会东城，约为兄弟，延之帐中，纵酒，握手尽欢，约以今冬共击梁。或劝晋王：“因其来，可擒也，”王曰：“仇敌未灭而失信夷狄，自亡之道也。”阿保机留旬日乃去，晋王赠以金缯数万。阿保机留马三千匹，杂畜万计以酬之。阿保机既归而背盟，更附于梁，晋王由是而恨之。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 2482f087-824d-5811-8ced-8b520bbb77a0'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第28段", "note": "原文：契丹遣其臣袍笏梅老来通好，帝遣太府少卿高颀报之。初，契丹有八部，部各有大人，相与约，推一人为王，建旗鼓以号令诸部，每三年则以次相代。咸通末，有习尔者为王，土宇始大。其后钦德为王，乘中原多故，时入盗边。及阿保机为王，尤雄勇，五姓奚及七姓室韦、达靼咸役属之。阿保机姓邪律氏，恃其强，不肯受代。久之，阿保机击黄头室韦还，七部劫之于境上，求如约。阿保机不得已，传旗鼓，且曰：“我为王九年，得汉人多，请帅种落居古汉城，与汉人守之，别自为一部。”七部许之。汉城者，故后魏滑盐县也。地宜五谷，有盐池之利。其后阿保机稍以兵击灭七部，复并为一国。又北侵室韦、女真，西取突阙故地，击奚，灭之，复立奚王而使契丹监其兵，东北诸夷皆畏服之。是岁，阿保机帅众三十万寇云州，晋王与之连和，面会东城，约为兄弟，延之帐中，纵酒，握手尽欢，约以今冬共击梁。或劝晋王：“因其来，可擒也，”王曰：“仇敌未灭而失信夷狄，自亡之道也。”阿保机留旬日乃去，晋王赠以金缯数万。阿保机留马三千匹，杂畜万计以酬之。阿保机既归而背盟，更附于梁，晋王由是而恨之。；核对说明："}'::jsonb) v WHERE fact_claim.id='2482f087-824d-5811-8ced-8b520bbb77a0';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='2505a513-cc4f-5b64-a389-c0aee29e7595' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p046", "note": "原文：八月，丙午，赐河南尹张全义名宗奭。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第46段", "note": "原文：八月，丙午，赐河南尹张全义名宗奭。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 2505a513-cc4f-5b64-a389-c0aee29e7595'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第46段", "note": "原文：八月，丙午，赐河南尹张全义名宗奭。；核对说明："}'::jsonb) v WHERE fact_claim.id='2505a513-cc4f-5b64-a389-c0aee29e7595';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='254ca02d-88ba-553b-97b3-9b67a9d482b0' AND (to_jsonb(t) @> '{"note": "原文：庚寅旦，袁象先等帥禁兵數千人突入宮中。友珪聞變，與妻張氏及馮廷諤趨北垣樓下，將逾城，自度不免，令廷諤先殺妻，次殺己，廷諤亦自剄。諸軍十餘萬大掠都市，百司逃散，中書侍郎、同平章事杜曉、侍講學士李珽皆為亂兵所殺，門下侍郎、同平章事於兢、宣政使李振被傷。至晡乃定。\n像先、巖繼傳國寶詣大梁迎均王，王曰：「大梁國家創業之地，何必洛陽！」乃即帝位於大梁，復稱乾化三年，追廢友珪為庶人，復博王友文官爵。；核对说明：已对照所保存电子文本；尚待人工复核，不视为纸本校勘结论。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：庚寅旦，袁象先等帥禁兵數千人突入宮中。友珪聞變，與妻張氏及馮廷諤趨北垣樓下，將逾城，自度不免，令廷諤先殺妻，次殺己，廷諤亦自剄。諸軍十餘萬大掠都市，百司逃散，中書侍郎、同平章事杜曉、侍講學士李珽皆為亂兵所殺，門下侍郎、同平章事於兢、宣政使李振被傷。至晡乃定。\n像先、巖繼傳國寶詣大梁迎均王，王曰：「大梁國家創業之地，何必洛陽！」乃即帝位於大梁，復稱乾化三年，追廢友珪為庶人，復博王友文官爵。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 254ca02d-88ba-553b-97b3-9b67a9d482b0'; END IF; END $$;
