DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='29baa0d4-fabe-5b4a-96db-4da93b3127fe' AND (to_jsonb(t) @> '{"note": "原文：新五代史 \n25/1627 \n祖，祖妣刘氏谥曰昭懿；考诚谥曰文\n穆，庙号烈祖，妣王氏谥曰文惠。八\n月丁卯，同州虸蚄虫生。隰州黄河\n清。九月，括马。冬十月己未，讲武\n于繁台。十一月壬寅，赦亡命背军髡\n黥刑徒。  \n二年春正月丁酉，渤海遣使者\n来。己亥，卜郊于西都。弑济阴王。\n二月辛未，契丹阿保机遣使者来。三\n月壬申朔，如西都。丙子，如怀州。\n丁丑，如泽州。戊寅，封鸿胪卿李崧\n介国公，为二王后。壬午，匡国军节\n度使刘知俊为潞州行营招讨使。癸\n巳，改卜郊。张文蔚薨。夏四月癸\n卯，杨涉罢，吏部侍郎于兢为中书侍；核对说明：本项目核读电子文本；文字层不是原刻影印，未作纸本校勘。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：新五代史 \n25/1627 \n祖，祖妣刘氏谥曰昭懿；考诚谥曰文\n穆，庙号烈祖，妣王氏谥曰文惠。八\n月丁卯，同州虸蚄虫生。隰州黄河\n清。九月，括马。冬十月己未，讲武\n于繁台。十一月壬寅，赦亡命背军髡\n黥刑徒。  \n二年春正月丁酉，渤海遣使者\n来。己亥，卜郊于西都。弑济阴王。\n二月辛未，契丹阿保机遣使者来。三\n月壬申朔，如西都。丙子，如怀州。\n丁丑，如泽州。戊寅，封鸿胪卿李崧\n介国公，为二王后。壬午，匡国军节\n度使刘知俊为潞州行营招讨使。癸\n巳，改卜郊。张文蔚薨。夏四月癸\n卯，杨涉罢，吏部侍郎于兢为中书侍；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 29baa0d4-fabe-5b4a-96db-4da93b3127fe'; END IF; END $$;
