DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='2a6a6468-fd9a-580b-a78d-8499358f39b4' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p036", "note": "原文：卢约以处州降吴越。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第36段", "note": "原文：卢约以处州降吴越。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 2a6a6468-fd9a-580b-a78d-8499358f39b4'; END IF; END $$;
