DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='2e855ef9-d7d0-5a93-bd9a-3931e31478ee' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p011", "note": "原文：甲辰，唐昭宣帝降御札禅位于梁。以摄中书令张文蔚为册礼使，礼部尚书苏循副之；摄侍中杨涉为押传国宝使，翰林学士张策副之；御史大夫薛贻矩为押金宝使，尚书左丞赵光逢副之；帅百官备法驾诣大梁。杨涉子直史馆凝式言于涉曰：“大人为唐宰相，而国家至此，不可谓之无过。况手持天子玺绶与人，虽保富贵，奈千载何！盍辞之！”涉大骇曰：“汝灭吾族！”神色为之不宁者数日。策，敦煌人。光逢，隐之子也。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第11段", "note": "原文：甲辰，唐昭宣帝降御札禅位于梁。以摄中书令张文蔚为册礼使，礼部尚书苏循副之；摄侍中杨涉为押传国宝使，翰林学士张策副之；御史大夫薛贻矩为押金宝使，尚书左丞赵光逢副之；帅百官备法驾诣大梁。杨涉子直史馆凝式言于涉曰：“大人为唐宰相，而国家至此，不可谓之无过。况手持天子玺绶与人，虽保富贵，奈千载何！盍辞之！”涉大骇曰：“汝灭吾族！”神色为之不宁者数日。策，敦煌人。光逢，隐之子也。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 2e855ef9-d7d0-5a93-bd9a-3931e31478ee'; END IF; END $$;
