DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='2f29634a-7924-5f58-b2a4-b70d0b06a0ad' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p019", "note": "原文：以宣武掌书记、太府卿敬翔知崇政院事，以备顾问，参谋议，于禁中承上旨，宣于宰相而行之。宰相非进对时有所奏请及已受旨应复请者，皆具记事因崇政院以闻，得旨则复宣于宰相。翔为人沉深，有智略，在幕府三十馀年，军谋、民政，帝一以委之。翔尽心勤劳，昼夜不寐，自言惟马上乃得休息，帝性暴戾难近，人莫能测，惟翔能识其意趣。或有所不可，翔未尝显言，但微示持疑；帝意已悟，多为之改易。禅代之际，翔谋居多。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第19段", "note": "原文：以宣武掌书记、太府卿敬翔知崇政院事，以备顾问，参谋议，于禁中承上旨，宣于宰相而行之。宰相非进对时有所奏请及已受旨应复请者，皆具记事因崇政院以闻，得旨则复宣于宰相。翔为人沉深，有智略，在幕府三十馀年，军谋、民政，帝一以委之。翔尽心勤劳，昼夜不寐，自言惟马上乃得休息，帝性暴戾难近，人莫能测，惟翔能识其意趣。或有所不可，翔未尝显言，但微示持疑；帝意已悟，多为之改易。禅代之际，翔谋居多。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 2f29634a-7924-5f58-b2a4-b70d0b06a0ad'; END IF; END $$;
