DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='324f6ad4-1add-5a2d-a2ae-86f66264738e' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p022", "note": "原文：乙亥，下制削夺李克用官爵。是时，惟河东、凤翔、淮南称“天祐”，西川称“天复”年号。馀皆禀梁正朔，称臣奉贡。蜀王与弘农王移檄诸道，云欲与岐王、晋王会兵兴复唐室，卒无应者。蜀王乃谋称帝，下教谕统内吏民；又遗晋王书云：“请各帝一方，俟硃温既平，乃访唐宗室立之，退归籓服。”晋王复书不许，曰：“誓于此生靡敢失节。”；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第22段", "note": "原文：乙亥，下制削夺李克用官爵。是时，惟河东、凤翔、淮南称“天祐”，西川称“天复”年号。馀皆禀梁正朔，称臣奉贡。蜀王与弘农王移檄诸道，云欲与岐王、晋王会兵兴复唐室，卒无应者。蜀王乃谋称帝，下教谕统内吏民；又遗晋王书云：“请各帝一方，俟硃温既平，乃访唐宗室立之，退归籓服。”晋王复书不许，曰：“誓于此生靡敢失节。”；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 324f6ad4-1add-5a2d-a2ae-86f66264738e'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第22段", "note": "原文：乙亥，下制削夺李克用官爵。是时，惟河东、凤翔、淮南称“天祐”，西川称“天复”年号。馀皆禀梁正朔，称臣奉贡。蜀王与弘农王移檄诸道，云欲与岐王、晋王会兵兴复唐室，卒无应者。蜀王乃谋称帝，下教谕统内吏民；又遗晋王书云：“请各帝一方，俟硃温既平，乃访唐宗室立之，退归籓服。”晋王复书不许，曰：“誓于此生靡敢失节。”；核对说明："}'::jsonb) v WHERE fact_claim.id='324f6ad4-1add-5a2d-a2ae-86f66264738e';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='32b3c7a0-c9d7-5004-8202-f4073bcec382' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p013", "note": "原文：仁恭有爱妾罗氏，其子守光通焉。仁恭杖守光而斥之，不以为子数。李思安引兵入其境，所过焚荡无馀。夏，四月，己酉，直抵幽州城下。仁恭犹在大安山。城中无备，几至不守。守光自外引兵入，登城拒守；又出兵与思安战，思安败退。守光遂自称节度使，命部将李小喜、元行钦将兵攻大安山。仁恭遣兵拒战，为小喜所败。虏仁恭以归，囚于别室。仁恭将佐及左右，凡守光素所恶者皆杀之。银胡录都指挥使王思同帅部兵三千，山后八安巡检使李承约帅部兵二千奔河东，守光弟守奇奔契丹，未几，亦奔河东，河东节度使晋王克用以承约为匡霸指挥使，思同为飞腾指挥使。思同母，仁恭之女也。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第13段", "note": "原文：仁恭有爱妾罗氏，其子守光通焉。仁恭杖守光而斥之，不以为子数。李思安引兵入其境，所过焚荡无馀。夏，四月，己酉，直抵幽州城下。仁恭犹在大安山。城中无备，几至不守。守光自外引兵入，登城拒守；又出兵与思安战，思安败退。守光遂自称节度使，命部将李小喜、元行钦将兵攻大安山。仁恭遣兵拒战，为小喜所败。虏仁恭以归，囚于别室。仁恭将佐及左右，凡守光素所恶者皆杀之。银胡录都指挥使王思同帅部兵三千，山后八安巡检使李承约帅部兵二千奔河东，守光弟守奇奔契丹，未几，亦奔河东，河东节度使晋王克用以承约为匡霸指挥使，思同为飞腾指挥使。思同母，仁恭之女也。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 32b3c7a0-c9d7-5004-8202-f4073bcec382'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第13段", "note": "原文：仁恭有爱妾罗氏，其子守光通焉。仁恭杖守光而斥之，不以为子数。李思安引兵入其境，所过焚荡无馀。夏，四月，己酉，直抵幽州城下。仁恭犹在大安山。城中无备，几至不守。守光自外引兵入，登城拒守；又出兵与思安战，思安败退。守光遂自称节度使，命部将李小喜、元行钦将兵攻大安山。仁恭遣兵拒战，为小喜所败。虏仁恭以归，囚于别室。仁恭将佐及左右，凡守光素所恶者皆杀之。银胡录都指挥使王思同帅部兵三千，山后八安巡检使李承约帅部兵二千奔河东，守光弟守奇奔契丹，未几，亦奔河东，河东节度使晋王克用以承约为匡霸指挥使，思同为飞腾指挥使。思同母，仁恭之女也。；核对说明："}'::jsonb) v WHERE fact_claim.id='32b3c7a0-c9d7-5004-8202-f4073bcec382';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='3316ee88-5b94-5feb-a84b-502964d60632' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p009", "note": "原文：庚寅，唐昭宣帝诏薛贻矩再诣大梁谕禅位之意，又诏礼部尚书苏循赍百官诣大梁。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第9段", "note": "原文：庚寅，唐昭宣帝诏薛贻矩再诣大梁谕禅位之意，又诏礼部尚书苏循赍百官诣大梁。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 3316ee88-5b94-5feb-a84b-502964d60632'; END IF; END $$;
