DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='3428d0cf-2787-5905-aff4-711505c1761b' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p022", "note": "原文：乙亥，下制削夺李克用官爵。是时，惟河东、凤翔、淮南称“天祐”，西川称“天复”年号。馀皆禀梁正朔，称臣奉贡。蜀王与弘农王移檄诸道，云欲与岐王、晋王会兵兴复唐室，卒无应者。蜀王乃谋称帝，下教谕统内吏民；又遗晋王书云：“请各帝一方，俟硃温既平，乃访唐宗室立之，退归籓服。”晋王复书不许，曰：“誓于此生靡敢失节。”；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第22段", "note": "原文：乙亥，下制削夺李克用官爵。是时，惟河东、凤翔、淮南称“天祐”，西川称“天复”年号。馀皆禀梁正朔，称臣奉贡。蜀王与弘农王移檄诸道，云欲与岐王、晋王会兵兴复唐室，卒无应者。蜀王乃谋称帝，下教谕统内吏民；又遗晋王书云：“请各帝一方，俟硃温既平，乃访唐宗室立之，退归籓服。”晋王复书不许，曰：“誓于此生靡敢失节。”；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 3428d0cf-2787-5905-aff4-711505c1761b'; END IF; END $$;
