DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='3676e8c1-9d60-5073-bfc9-f1adb72d31ab' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p033", "note": "原文：壬辰，命保平节度使康怀贞将兵八万会魏博兵攻潞州。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第33段", "note": "原文：壬辰，命保平节度使康怀贞将兵八万会魏博兵攻潞州。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 3676e8c1-9d60-5073-bfc9-f1adb72d31ab'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第33段", "note": "原文：壬辰，命保平节度使康怀贞将兵八万会魏博兵攻潞州。；核对说明："}'::jsonb) v WHERE fact_claim.id='3676e8c1-9d60-5073-bfc9-f1adb72d31ab';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='369a81b6-9063-5710-818c-e55cd1d81a99' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p028", "note": "原文：契丹遣其臣袍笏梅老来通好，帝遣太府少卿高颀报之。初，契丹有八部，部各有大人，相与约，推一人为王，建旗鼓以号令诸部，每三年则以次相代。咸通末，有习尔者为王，土宇始大。其后钦德为王，乘中原多故，时入盗边。及阿保机为王，尤雄勇，五姓奚及七姓室韦、达靼咸役属之。阿保机姓邪律氏，恃其强，不肯受代。久之，阿保机击黄头室韦还，七部劫之于境上，求如约。阿保机不得已，传旗鼓，且曰：“我为王九年，得汉人多，请帅种落居古汉城，与汉人守之，别自为一部。”七部许之。汉城者，故后魏滑盐县也。地宜五谷，有盐池之利。其后阿保机稍以兵击灭七部，复并为一国。又北侵室韦、女真，西取突阙故地，击奚，灭之，复立奚王而使契丹监其兵，东北诸夷皆畏服之。是岁，阿保机帅众三十万寇云州，晋王与之连和，面会东城，约为兄弟，延之帐中，纵酒，握手尽欢，约以今冬共击梁。或劝晋王：“因其来，可擒也，”王曰：“仇敌未灭而失信夷狄，自亡之道也。”阿保机留旬日乃去，晋王赠以金缯数万。阿保机留马三千匹，杂畜万计以酬之。阿保机既归而背盟，更附于梁，晋王由是而恨之。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第28段", "note": "原文：契丹遣其臣袍笏梅老来通好，帝遣太府少卿高颀报之。初，契丹有八部，部各有大人，相与约，推一人为王，建旗鼓以号令诸部，每三年则以次相代。咸通末，有习尔者为王，土宇始大。其后钦德为王，乘中原多故，时入盗边。及阿保机为王，尤雄勇，五姓奚及七姓室韦、达靼咸役属之。阿保机姓邪律氏，恃其强，不肯受代。久之，阿保机击黄头室韦还，七部劫之于境上，求如约。阿保机不得已，传旗鼓，且曰：“我为王九年，得汉人多，请帅种落居古汉城，与汉人守之，别自为一部。”七部许之。汉城者，故后魏滑盐县也。地宜五谷，有盐池之利。其后阿保机稍以兵击灭七部，复并为一国。又北侵室韦、女真，西取突阙故地，击奚，灭之，复立奚王而使契丹监其兵，东北诸夷皆畏服之。是岁，阿保机帅众三十万寇云州，晋王与之连和，面会东城，约为兄弟，延之帐中，纵酒，握手尽欢，约以今冬共击梁。或劝晋王：“因其来，可擒也，”王曰：“仇敌未灭而失信夷狄，自亡之道也。”阿保机留旬日乃去，晋王赠以金缯数万。阿保机留马三千匹，杂畜万计以酬之。阿保机既归而背盟，更附于梁，晋王由是而恨之。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 369a81b6-9063-5710-818c-e55cd1d81a99'; END IF; END $$;
