DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='36e5d905-094a-527b-8f48-c4d300b371bf' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p039", "note": "原文：康怀贞至潞州，晋昭义节度使李嗣昭、副使李嗣弼闭城拒守。怀贞昼夜攻之，半月不克，乃筑垒穿蚰蜓堑而守之，内外断绝。晋王以蕃、汉都指挥使周德威为行营都指挥使，帅马军都指挥使李嗣本、马步都虞候李存璋、先锋指挥使史建瑭、铁林都指挥使安元信、横冲指挥使李嗣源、骑将安金全救潞州。嗣弼，克修之子；嗣本，本姓张；建瑭，敬思之子；金全，代北人也。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第39段", "note": "原文：康怀贞至潞州，晋昭义节度使李嗣昭、副使李嗣弼闭城拒守。怀贞昼夜攻之，半月不克，乃筑垒穿蚰蜓堑而守之，内外断绝。晋王以蕃、汉都指挥使周德威为行营都指挥使，帅马军都指挥使李嗣本、马步都虞候李存璋、先锋指挥使史建瑭、铁林都指挥使安元信、横冲指挥使李嗣源、骑将安金全救潞州。嗣弼，克修之子；嗣本，本姓张；建瑭，敬思之子；金全，代北人也。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 36e5d905-094a-527b-8f48-c4d300b371bf'; END IF; END $$;
