DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='37146598-9cfc-582d-a2b7-476cbdbf01c8' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p052", "note": "原文：冬，十月，高季昌遣其将倪可福会楚将秦彦晖攻朗州，雷彦恭遣使乞降于淮南，且告急。弘农王遣将泠业将水军屯平江，李饶将步骑屯浏阳以救之，楚王殷遣岳州刺史许德勋将兵拒之。泠业进屯朗口，德勋使善游者五十人，以木枝叶覆其首，持长刀浮江而下，夜犯其营，且举火，业军中惊扰。德以大军进击，大破之，追至鹿角镇，擒业；又破浏阳寨，擒李饶；掠上高、唐年而归。斩业、饶于长沙市。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第52段", "note": "原文：冬，十月，高季昌遣其将倪可福会楚将秦彦晖攻朗州，雷彦恭遣使乞降于淮南，且告急。弘农王遣将泠业将水军屯平江，李饶将步骑屯浏阳以救之，楚王殷遣岳州刺史许德勋将兵拒之。泠业进屯朗口，德勋使善游者五十人，以木枝叶覆其首，持长刀浮江而下，夜犯其营，且举火，业军中惊扰。德以大军进击，大破之，追至鹿角镇，擒业；又破浏阳寨，擒李饶；掠上高、唐年而归。斩业、饶于长沙市。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 37146598-9cfc-582d-a2b7-476cbdbf01c8'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第52段", "note": "原文：冬，十月，高季昌遣其将倪可福会楚将秦彦晖攻朗州，雷彦恭遣使乞降于淮南，且告急。弘农王遣将泠业将水军屯平江，李饶将步骑屯浏阳以救之，楚王殷遣岳州刺史许德勋将兵拒之。泠业进屯朗口，德勋使善游者五十人，以木枝叶覆其首，持长刀浮江而下，夜犯其营，且举火，业军中惊扰。德以大军进击，大破之，追至鹿角镇，擒业；又破浏阳寨，擒李饶；掠上高、唐年而归。斩业、饶于长沙市。；核对说明："}'::jsonb) v WHERE fact_claim.id='37146598-9cfc-582d-a2b7-476cbdbf01c8';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='37467bb4-db06-525a-9d6f-941efe181011' AND (to_jsonb(t) @> '{"note": "原文：旧五代史 \n74/1667 \n张祎盛称帝功德，宜应天顺人。宋州\n刺史王皋进两岐麦，陈州袁象先进白\n兔一，付史馆编录，兼示百官。诏在\n京司及诸军州县印一例铸换，其篆文\n则各如旧。辛未，武安军节度使马殷\n进封楚王。以太府卿敬翔知崇政院，\n翔与帷幄之谋，故首擢焉。追尊四代\n庙号：高祖妫州府君上谥曰宣元皇\n帝，庙号肃祖，太庙第一室，陵号兴\n极陵，祖妣高平县君范氏追谥宣僖皇\n后；皇曾祖宣惠王上谥曰光献皇帝，\n庙号敬祖，第二室，陵号永安，祖妣\n秦国夫人杨氏追谥光孝皇后；皇祖武\n元王上谥曰昭武皇帝，庙号宪祖，第\n三室，陵号光天，祖妣吴国夫人刘氏；核对说明：本项目核读电子文本；文字层不是原刻影印，未作纸本校勘。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：旧五代史 \n74/1667 \n张祎盛称帝功德，宜应天顺人。宋州\n刺史王皋进两岐麦，陈州袁象先进白\n兔一，付史馆编录，兼示百官。诏在\n京司及诸军州县印一例铸换，其篆文\n则各如旧。辛未，武安军节度使马殷\n进封楚王。以太府卿敬翔知崇政院，\n翔与帷幄之谋，故首擢焉。追尊四代\n庙号：高祖妫州府君上谥曰宣元皇\n帝，庙号肃祖，太庙第一室，陵号兴\n极陵，祖妣高平县君范氏追谥宣僖皇\n后；皇曾祖宣惠王上谥曰光献皇帝，\n庙号敬祖，第二室，陵号永安，祖妣\n秦国夫人杨氏追谥光孝皇后；皇祖武\n元王上谥曰昭武皇帝，庙号宪祖，第\n三室，陵号光天，祖妣吴国夫人刘氏；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 37467bb4-db06-525a-9d6f-941efe181011'; END IF; END $$;
UPDATE public.fact_claim SET note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"note": "原文：旧五代史 \n74/1667 \n张祎盛称帝功德，宜应天顺人。宋州\n刺史王皋进两岐麦，陈州袁象先进白\n兔一，付史馆编录，兼示百官。诏在\n京司及诸军州县印一例铸换，其篆文\n则各如旧。辛未，武安军节度使马殷\n进封楚王。以太府卿敬翔知崇政院，\n翔与帷幄之谋，故首擢焉。追尊四代\n庙号：高祖妫州府君上谥曰宣元皇\n帝，庙号肃祖，太庙第一室，陵号兴\n极陵，祖妣高平县君范氏追谥宣僖皇\n后；皇曾祖宣惠王上谥曰光献皇帝，\n庙号敬祖，第二室，陵号永安，祖妣\n秦国夫人杨氏追谥光孝皇后；皇祖武\n元王上谥曰昭武皇帝，庙号宪祖，第\n三室，陵号光天，祖妣吴国夫人刘氏；核对说明："}'::jsonb) v WHERE fact_claim.id='37467bb4-db06-525a-9d6f-941efe181011';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='3774e952-caa9-5d4f-b115-bdf6f49d7ca3' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p005", "note": "原文：初，梁王以河北诸镇皆服，唯幽、沧未下，故大举伐之，欲以坚诸镇之心，既而潞州内叛，王烧营而还，威望大沮。恐中外因此离心，欲速受禅以镇之。丁亥，王入馆于魏，有疾，卧府中，魏博节度使罗绍威恐王袭之，入见王曰：“今四方称兵为王患者，皆以翼戴唐室为名，王不如早灭唐以绝人望。”王虽不许而心德之，乃亟归。壬寅，至大梁。甲辰，唐昭宣帝遣御史大夫薛贻矩至大梁劳王，贻矩请以臣礼见，王揖之升阶，贻矩曰：“殿下功德在人，三灵改卜，皇帝方行舜、禹之事，臣安敢违！”乃北面拜舞于庭。王侧身避之。贻矩还，言于帝曰：“元帅有受禅之意矣！”帝乃下诏，以二月禅位于梁，又遣宰相以书谕王；王辞。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第5段", "note": "原文：初，梁王以河北诸镇皆服，唯幽、沧未下，故大举伐之，欲以坚诸镇之心，既而潞州内叛，王烧营而还，威望大沮。恐中外因此离心，欲速受禅以镇之。丁亥，王入馆于魏，有疾，卧府中，魏博节度使罗绍威恐王袭之，入见王曰：“今四方称兵为王患者，皆以翼戴唐室为名，王不如早灭唐以绝人望。”王虽不许而心德之，乃亟归。壬寅，至大梁。甲辰，唐昭宣帝遣御史大夫薛贻矩至大梁劳王，贻矩请以臣礼见，王揖之升阶，贻矩曰：“殿下功德在人，三灵改卜，皇帝方行舜、禹之事，臣安敢违！”乃北面拜舞于庭。王侧身避之。贻矩还，言于帝曰：“元帅有受禅之意矣！”帝乃下诏，以二月禅位于梁，又遣宰相以书谕王；王辞。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 3774e952-caa9-5d4f-b115-bdf6f49d7ca3'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第5段", "note": "原文：初，梁王以河北诸镇皆服，唯幽、沧未下，故大举伐之，欲以坚诸镇之心，既而潞州内叛，王烧营而还，威望大沮。恐中外因此离心，欲速受禅以镇之。丁亥，王入馆于魏，有疾，卧府中，魏博节度使罗绍威恐王袭之，入见王曰：“今四方称兵为王患者，皆以翼戴唐室为名，王不如早灭唐以绝人望。”王虽不许而心德之，乃亟归。壬寅，至大梁。甲辰，唐昭宣帝遣御史大夫薛贻矩至大梁劳王，贻矩请以臣礼见，王揖之升阶，贻矩曰：“殿下功德在人，三灵改卜，皇帝方行舜、禹之事，臣安敢违！”乃北面拜舞于庭。王侧身避之。贻矩还，言于帝曰：“元帅有受禅之意矣！”帝乃下诏，以二月禅位于梁，又遣宰相以书谕王；王辞。；核对说明："}'::jsonb) v WHERE fact_claim.id='3774e952-caa9-5d4f-b115-bdf6f49d7ca3';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='385e03e5-33c9-5fe3-85ec-58bbde2a4ece' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p035", "claim_text": "《资治通鉴》907年条所记人物。在“后梁勒令苏循、张祎等致仕”中为被斥归者。本批仅整理相关史事，生卒与完整履历待补。", "note": "原文：礼部尚书苏循及其子起居郎楷自谓有功于梁，当不次擢用；循朝夕望为相，帝薄其为人，敬翔及殿中监李振亦鄙之。翔言于帝曰：“苏循，唐之鸱枭，卖国求利，不可以立于惟新之朝。”戊戍，诏循及刑部尚书张祎等十五人并勒致仕，楷斥归田里。循父子乃之河中依硃友谦。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第35段", "claim_text": "据《资治通鉴》，907年在“后梁勒令苏循、张祎等致仕”中为被斥归者。", "note": "原文：礼部尚书苏循及其子起居郎楷自谓有功于梁，当不次擢用；循朝夕望为相，帝薄其为人，敬翔及殿中监李振亦鄙之。翔言于帝曰：“苏循，唐之鸱枭，卖国求利，不可以立于惟新之朝。”戊戍，诏循及刑部尚书张祎等十五人并勒致仕，楷斥归田里。循父子乃之河中依硃友谦。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 385e03e5-33c9-5fe3-85ec-58bbde2a4ece'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,claim_text=v.claim_text,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第35段", "claim_text": "据《资治通鉴》，907年在“后梁勒令苏循、张祎等致仕”中为被斥归者。", "note": "原文：礼部尚书苏循及其子起居郎楷自谓有功于梁，当不次擢用；循朝夕望为相，帝薄其为人，敬翔及殿中监李振亦鄙之。翔言于帝曰：“苏循，唐之鸱枭，卖国求利，不可以立于惟新之朝。”戊戍，诏循及刑部尚书张祎等十五人并勒致仕，楷斥归田里。循父子乃之河中依硃友谦。；核对说明："}'::jsonb) v WHERE fact_claim.id='385e03e5-33c9-5fe3-85ec-58bbde2a4ece';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='388c59e0-7c07-5253-ba14-4cd356421b8d' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p021", "note": "原文：初，帝为四镇节度使，凡仓库之籍，置建昌院以领之；至是，以养子宣武节度副使友文为开封尹、判院事，掌凡国之金谷。友文本康氏之子也。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第21段", "note": "原文：初，帝为四镇节度使，凡仓库之籍，置建昌院以领之；至是，以养子宣武节度副使友文为开封尹、判院事，掌凡国之金谷。友文本康氏之子也。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 388c59e0-7c07-5253-ba14-4cd356421b8d'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第21段", "note": "原文：初，帝为四镇节度使，凡仓库之籍，置建昌院以领之；至是，以养子宣武节度副使友文为开封尹、判院事，掌凡国之金谷。友文本康氏之子也。；核对说明："}'::jsonb) v WHERE fact_claim.id='388c59e0-7c07-5253-ba14-4cd356421b8d';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='38baea0a-290d-593a-b676-55055ff44ad0' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p000", "note": "原文：开平元年丁卯，公元九零七年；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·年次题记", "note": "原文：开平元年丁卯，公元九零七年；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 38baea0a-290d-593a-b676-55055ff44ad0'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·年次题记", "note": "原文：开平元年丁卯，公元九零七年；核对说明："}'::jsonb) v WHERE fact_claim.id='38baea0a-290d-593a-b676-55055ff44ad0';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='390e7dd8-aaeb-5113-a086-1d64624fb0e9' AND (to_jsonb(t) @> '{"note": "原文：旧五代史 \n80/1667 \n甚厚。宿州刺史王儒进白兔一，濮州\n刺史图嘉禾瑞麦以进。广州进奇宝名\n药，品类甚多。河南尹张全义进开平\n元年已前羡余钱十万贯、绸六千匹、\n绵三十万两，仍请每年上供定额每岁\n贡绢三万匹，以为常式。荆南高季昌\n进瑞橘数十颗，质状百味，倍胜常\n贡。且橘当冬熟，今方仲夏，时人咸\n异其事，因称为瑞。   \n六月，幸乾元院，宴召宰臣、学\n士及诸道入贡陪臣。己亥，帝御崇元\n殿，内出追尊四庙上谥号玉册宝共八\n副，宰臣文武百官仪仗鼓吹导引至太\n庙行事。癸卯，司天监奏：“日辰内\n有‘戊’字，请改为‘武’。”从\n旧五代史 \n81/1667 \n之。癸亥，诏以前朝官僚，谴逐南\n荒，积年未经昭雪，其间有怀抱材器\n为时所嫉者，深负冤抑。仍令录其名\n姓，尽复官资，兼告谕诸道令津致赴\n阙。如已亡殁，并许归葬，以明恩\n荡。以西都徽安门北路逼近大内宫\n垣，兼非民便，令移自榆林直趋端门\n之南。改耀州报恩禅院为兴国寺。马\n殷奏破淮寇；静海军节度使曲裕卒。  \n七月丙申，以静海军行营司马权\n知留后曲颢起复为安南都护，充节度\n使。《五代会要》：七月，敕云：\n“建国迁都，俾新其制，况山河之\n险，表里为防。今二京俱在关东以\n内，仍以潼关隶陕州，复置河潼军；核对说明：本项目核读电子文本；文字层不是原刻影印，未作纸本校勘。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：旧五代史 \n80/1667 \n甚厚。宿州刺史王儒进白兔一，濮州\n刺史图嘉禾瑞麦以进。广州进奇宝名\n药，品类甚多。河南尹张全义进开平\n元年已前羡余钱十万贯、绸六千匹、\n绵三十万两，仍请每年上供定额每岁\n贡绢三万匹，以为常式。荆南高季昌\n进瑞橘数十颗，质状百味，倍胜常\n贡。且橘当冬熟，今方仲夏，时人咸\n异其事，因称为瑞。   \n六月，幸乾元院，宴召宰臣、学\n士及诸道入贡陪臣。己亥，帝御崇元\n殿，内出追尊四庙上谥号玉册宝共八\n副，宰臣文武百官仪仗鼓吹导引至太\n庙行事。癸卯，司天监奏：“日辰内\n有‘戊’字，请改为‘武’。”从\n旧五代史 \n81/1667 \n之。癸亥，诏以前朝官僚，谴逐南\n荒，积年未经昭雪，其间有怀抱材器\n为时所嫉者，深负冤抑。仍令录其名\n姓，尽复官资，兼告谕诸道令津致赴\n阙。如已亡殁，并许归葬，以明恩\n荡。以西都徽安门北路逼近大内宫\n垣，兼非民便，令移自榆林直趋端门\n之南。改耀州报恩禅院为兴国寺。马\n殷奏破淮寇；静海军节度使曲裕卒。  \n七月丙申，以静海军行营司马权\n知留后曲颢起复为安南都护，充节度\n使。《五代会要》：七月，敕云：\n“建国迁都，俾新其制，况山河之\n险，表里为防。今二京俱在关东以\n内，仍以潼关隶陕州，复置河潼军；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 390e7dd8-aaeb-5113-a086-1d64624fb0e9'; END IF; END $$;
