DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='3b9e4cda-4e57-5da5-8fa8-34f17ce5ee67' AND (to_jsonb(t) @> '{"note": "原文：帝長子郴王友裕早卒。次假子博王友文，帝特愛之，常留守東都，兼建昌宮使。次郢王友珪，其母亳州營倡也，為左右控鶴都指揮使，無寵。次均王友貞，為東都馬步都揮指使。；核对说明：已对照所保存电子文本；尚待人工复核，不视为纸本校勘结论。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：帝長子郴王友裕早卒。次假子博王友文，帝特愛之，常留守東都，兼建昌宮使。次郢王友珪，其母亳州營倡也，為左右控鶴都指揮使，無寵。次均王友貞，為東都馬步都揮指使。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 3b9e4cda-4e57-5da5-8fa8-34f17ce5ee67'; END IF; END $$;
UPDATE public.fact_claim SET note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"note": "原文：帝長子郴王友裕早卒。次假子博王友文，帝特愛之，常留守東都，兼建昌宮使。次郢王友珪，其母亳州營倡也，為左右控鶴都指揮使，無寵。次均王友貞，為東都馬步都揮指使。；核对说明："}'::jsonb) v WHERE fact_claim.id='3b9e4cda-4e57-5da5-8fa8-34f17ce5ee67';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='3c781402-7237-557e-8155-0f2d71a01ceb' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p037", "note": "原文：弘农王以鄂岳观察使刘存为西南面都招讨使，岳州刺史陈知新为岳州团练使，庐州观察使刘威为应援使，别将许玄应为监军，将水军三万以击楚。楚王马殷甚惧，静江军使杨定真贺曰：“我军胜矣！”殷问其故，定真曰：“夫战惧则胜，骄则败。今淮南兵直趋吾城，是骄而轻敌也；而王有惧色，吾是以知其必胜也。”殷命在城都指挥使秦彦晖将水军三万浮江而下，水军副指挥使黄璠帅战舰三百屯浏阳口。六月，存等遇大雨，引兵还至越堤北，彦晖追之。存数战不利，乃遗殷书诈降。彦晖使谓殷曰：“此必诈也，勿受！”存与彦晖夹水而阵，存遥呼曰：“杀降不祥，公独不为子孙计耶！”彦晖曰：“贼入吾境而不击，奚顾子孙！”鼓噪而进。存等走，黄璠自浏阳引兵绝江，与彦晖合击，大破之，执存及知新，裨将死者百馀人，士卒死者以万数，获战舰八百艘。威以馀众遁归，彦晖遂拔岳州。殷释存、知新之缚，慰谕之。二人皆骂曰：“丈夫以死报主，肯事贼乎！”遂斩之。许玄应，弘农王之腹心也，常预政事，张颢、徐温因其败，收斩之。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第37段", "note": "原文：弘农王以鄂岳观察使刘存为西南面都招讨使，岳州刺史陈知新为岳州团练使，庐州观察使刘威为应援使，别将许玄应为监军，将水军三万以击楚。楚王马殷甚惧，静江军使杨定真贺曰：“我军胜矣！”殷问其故，定真曰：“夫战惧则胜，骄则败。今淮南兵直趋吾城，是骄而轻敌也；而王有惧色，吾是以知其必胜也。”殷命在城都指挥使秦彦晖将水军三万浮江而下，水军副指挥使黄璠帅战舰三百屯浏阳口。六月，存等遇大雨，引兵还至越堤北，彦晖追之。存数战不利，乃遗殷书诈降。彦晖使谓殷曰：“此必诈也，勿受！”存与彦晖夹水而阵，存遥呼曰：“杀降不祥，公独不为子孙计耶！”彦晖曰：“贼入吾境而不击，奚顾子孙！”鼓噪而进。存等走，黄璠自浏阳引兵绝江，与彦晖合击，大破之，执存及知新，裨将死者百馀人，士卒死者以万数，获战舰八百艘。威以馀众遁归，彦晖遂拔岳州。殷释存、知新之缚，慰谕之。二人皆骂曰：“丈夫以死报主，肯事贼乎！”遂斩之。许玄应，弘农王之腹心也，常预政事，张颢、徐温因其败，收斩之。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 3c781402-7237-557e-8155-0f2d71a01ceb'; END IF; END $$;
