DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='405d9bb0-44f6-563b-9221-d84de2dcbe2f' AND (to_jsonb(t) @> '{"note": "原文：新五代史 \n24/1627 \n为门下侍郎，御史大夫薛贻矩为中书\n侍郎；同中书门下平章事。戊寅，渤\n海、契丹遣使者来。乙酉，封兄全昱\n为广王，子友文博王，友珪郢王，友\n璋福王，友贞均王，友徽建王，侄友\n谅衡王，友能惠王，友诲邵王。甲\n午，改枢密院为崇政院，太府卿敬翔\n为使。是月，潞州行营都指挥使李思\n安及晋人战，败绩。六月甲寅，平卢\n军节度使韩建守司徒，同中书门下平\n章事。秋七月己亥，追尊祖考为皇\n帝，妣为皇后；皇高祖黯谥曰宣元，\n庙号肃祖，祖妣范氏谥曰宣僖；曾祖\n茂琳谥曰光献，庙号敬祖，祖妣杨氏\n谥曰光孝；祖信谥曰昭武，庙号宪；核对说明：本项目核读电子文本；文字层不是原刻影印，未作纸本校勘。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：新五代史 \n24/1627 \n为门下侍郎，御史大夫薛贻矩为中书\n侍郎；同中书门下平章事。戊寅，渤\n海、契丹遣使者来。乙酉，封兄全昱\n为广王，子友文博王，友珪郢王，友\n璋福王，友贞均王，友徽建王，侄友\n谅衡王，友能惠王，友诲邵王。甲\n午，改枢密院为崇政院，太府卿敬翔\n为使。是月，潞州行营都指挥使李思\n安及晋人战，败绩。六月甲寅，平卢\n军节度使韩建守司徒，同中书门下平\n章事。秋七月己亥，追尊祖考为皇\n帝，妣为皇后；皇高祖黯谥曰宣元，\n庙号肃祖，祖妣范氏谥曰宣僖；曾祖\n茂琳谥曰光献，庙号敬祖，祖妣杨氏\n谥曰光孝；祖信谥曰昭武，庙号宪；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 405d9bb0-44f6-563b-9221-d84de2dcbe2f'; END IF; END $$;
UPDATE public.fact_claim SET note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"note": "原文：新五代史 \n24/1627 \n为门下侍郎，御史大夫薛贻矩为中书\n侍郎；同中书门下平章事。戊寅，渤\n海、契丹遣使者来。乙酉，封兄全昱\n为广王，子友文博王，友珪郢王，友\n璋福王，友贞均王，友徽建王，侄友\n谅衡王，友能惠王，友诲邵王。甲\n午，改枢密院为崇政院，太府卿敬翔\n为使。是月，潞州行营都指挥使李思\n安及晋人战，败绩。六月甲寅，平卢\n军节度使韩建守司徒，同中书门下平\n章事。秋七月己亥，追尊祖考为皇\n帝，妣为皇后；皇高祖黯谥曰宣元，\n庙号肃祖，祖妣范氏谥曰宣僖；曾祖\n茂琳谥曰光献，庙号敬祖，祖妣杨氏\n谥曰光孝；祖信谥曰昭武，庙号宪；核对说明："}'::jsonb) v WHERE fact_claim.id='405d9bb0-44f6-563b-9221-d84de2dcbe2f';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='40e63085-52f9-5c70-bcb4-767a25178fe6' AND (to_jsonb(t) @> '{"note": "原文：旧五代史 \n69/1667 \n更易。先王令典，布在缣缃。寡人本\n名，兼于二字，且异帝王之号，仍兼\n易之难，郡职县官，多须改换。况宗\n庙不迁之业，宪章百世之规，事叶典\n仪，岂惮革易。寡人今改名晃，是以\n天意雅符于明德，日光显契于瑞文，\n昭融万邦，理斯在是。庶顺昊穹之\n意，永臻康济之期。宜令有司分告天\n地宗庙，其旧名，中外章疏不得更有\n回避。”时将受禅，下教以本名二字\n异帝王之称，故改名。己未，赐文武\n百官一百六十人本色衣一副。戊辰，\n即位。制曰：   \n王者受命于天，光宅四海，祗事\n上帝，宠绥下民。革故鼎新，谅历数；核对说明：本项目核读电子文本；文字层不是原刻影印，未作纸本校勘。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：旧五代史 \n69/1667 \n更易。先王令典，布在缣缃。寡人本\n名，兼于二字，且异帝王之号，仍兼\n易之难，郡职县官，多须改换。况宗\n庙不迁之业，宪章百世之规，事叶典\n仪，岂惮革易。寡人今改名晃，是以\n天意雅符于明德，日光显契于瑞文，\n昭融万邦，理斯在是。庶顺昊穹之\n意，永臻康济之期。宜令有司分告天\n地宗庙，其旧名，中外章疏不得更有\n回避。”时将受禅，下教以本名二字\n异帝王之称，故改名。己未，赐文武\n百官一百六十人本色衣一副。戊辰，\n即位。制曰：   \n王者受命于天，光宅四海，祗事\n上帝，宠绥下民。革故鼎新，谅历数；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 40e63085-52f9-5c70-bcb4-767a25178fe6'; END IF; END $$;
UPDATE public.fact_claim SET note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"note": "原文：旧五代史 \n69/1667 \n更易。先王令典，布在缣缃。寡人本\n名，兼于二字，且异帝王之号，仍兼\n易之难，郡职县官，多须改换。况宗\n庙不迁之业，宪章百世之规，事叶典\n仪，岂惮革易。寡人今改名晃，是以\n天意雅符于明德，日光显契于瑞文，\n昭融万邦，理斯在是。庶顺昊穹之\n意，永臻康济之期。宜令有司分告天\n地宗庙，其旧名，中外章疏不得更有\n回避。”时将受禅，下教以本名二字\n异帝王之称，故改名。己未，赐文武\n百官一百六十人本色衣一副。戊辰，\n即位。制曰：   \n王者受命于天，光宅四海，祗事\n上帝，宠绥下民。革故鼎新，谅历数；核对说明："}'::jsonb) v WHERE fact_claim.id='40e63085-52f9-5c70-bcb4-767a25178fe6';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='410ca6fc-203c-5e86-86c6-6ee2399444f2' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p051", "note": "原文：蜀王会将佐议称帝，皆曰：“大王虽忠于唐，唐已亡矣，此所谓‘天与不取’者也。”冯涓独献议，请，以蜀王称制，曰：“朝兴则未爽称臣，贼在则不同为恶。”王不从，涓杜门不出。王用安抚副使、掌书记韦庄之谋，帅吏民哭三日；己亥，即皇帝位，国号大蜀。辛丑，以前东川节度使兼侍中王宗佶为中书令，韦庄为左散骑常侍、判中书门下事，阆州防御使唐道袭为内枢密使。庄，见素之孙也。蜀主虽目不知书，好与书生谈论，粗晓其理。是时唐衣冠之族多避乱在蜀，蜀主礼而用之，使修举故事，故其典章文物有唐之遗风。蜀主长子校书郎宗仁幼以疾废，立其次子秘书少监宗懿为遂王。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第51段", "note": "原文：蜀王会将佐议称帝，皆曰：“大王虽忠于唐，唐已亡矣，此所谓‘天与不取’者也。”冯涓独献议，请，以蜀王称制，曰：“朝兴则未爽称臣，贼在则不同为恶。”王不从，涓杜门不出。王用安抚副使、掌书记韦庄之谋，帅吏民哭三日；己亥，即皇帝位，国号大蜀。辛丑，以前东川节度使兼侍中王宗佶为中书令，韦庄为左散骑常侍、判中书门下事，阆州防御使唐道袭为内枢密使。庄，见素之孙也。蜀主虽目不知书，好与书生谈论，粗晓其理。是时唐衣冠之族多避乱在蜀，蜀主礼而用之，使修举故事，故其典章文物有唐之遗风。蜀主长子校书郎宗仁幼以疾废，立其次子秘书少监宗懿为遂王。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 410ca6fc-203c-5e86-86c6-6ee2399444f2'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第51段", "note": "原文：蜀王会将佐议称帝，皆曰：“大王虽忠于唐，唐已亡矣，此所谓‘天与不取’者也。”冯涓独献议，请，以蜀王称制，曰：“朝兴则未爽称臣，贼在则不同为恶。”王不从，涓杜门不出。王用安抚副使、掌书记韦庄之谋，帅吏民哭三日；己亥，即皇帝位，国号大蜀。辛丑，以前东川节度使兼侍中王宗佶为中书令，韦庄为左散骑常侍、判中书门下事，阆州防御使唐道袭为内枢密使。庄，见素之孙也。蜀主虽目不知书，好与书生谈论，粗晓其理。是时唐衣冠之族多避乱在蜀，蜀主礼而用之，使修举故事，故其典章文物有唐之遗风。蜀主长子校书郎宗仁幼以疾废，立其次子秘书少监宗懿为遂王。；核对说明："}'::jsonb) v WHERE fact_claim.id='410ca6fc-203c-5e86-86c6-6ee2399444f2';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='41a7f0b5-c9e8-5695-8e5d-8a2c7e913015' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p040", "note": "原文：晋兵攻泽州，帝遣左神勇军使范居实将兵救之。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第40段", "note": "原文：晋兵攻泽州，帝遣左神勇军使范居实将兵救之。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 41a7f0b5-c9e8-5695-8e5d-8a2c7e913015'; END IF; END $$;
