DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='42d06032-0d6b-58c3-8535-5fcf4b3c84b8' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p048", "note": "原文：晋周德威壁于高河，康怀贞遣亲骑都头秦武将兵击之，武败。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第48段", "note": "原文：晋周德威壁于高河，康怀贞遣亲骑都头秦武将兵击之，武败。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 42d06032-0d6b-58c3-8535-5fcf4b3c84b8'; END IF; END $$;
