DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='44794f31-94b5-5f5f-a276-a8fb42db479a' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p000", "note": "原文：开平元年丁卯，公元九零七年；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·年次题记", "note": "原文：开平元年丁卯，公元九零七年；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 44794f31-94b5-5f5f-a276-a8fb42db479a'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·年次题记", "note": "原文：开平元年丁卯，公元九零七年；核对说明："}'::jsonb) v WHERE fact_claim.id='44794f31-94b5-5f5f-a276-a8fb42db479a';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='44bc07e3-60f1-5402-a5f4-8735f2c832f1' AND (to_jsonb(t) @> '{"note": "原文：戊寅，友珪易服微行入左龍虎軍。見統軍韓珪，以情告之。勍亦見功臣宿將多以小過被誅，懼不自保，遂相與合謀。勍以牙兵五百人從友珪雜控鶴士入，伏於禁中，中夜斬關入，至寢殿，侍疾者皆散走。帝驚起，問：「反者為誰？」友珪曰：「非他人也！」帝曰：「我固疑此賊，恨不早殺之。汝悖逆如此，天地豈容汝乎！」友珪曰：「老賊萬段！」友珪僕夫馮廷諤刺帝腹，刃出於背。友珪自以敗氈裹之，瘞於寢殿，秘不發喪。遣供奉官丁昭溥馳詣東都，命均王友貞殺友文。\n己卯，矯詔稱：「博王友文謀逆，遣兵突入殿中，賴郢王友珪忠孝，將兵誅之，保全朕躬。然疾因震驚，彌致危殆，宜令友珪權主軍國之務。」韓勍為友珪謀，多出府庫金帛賜諸軍及百官以取悅。\n辛巳，丁昭溥還，聞友文已死，乃發喪，宣遺制，友珪即皇帝位。；核对说明：已对照所保存电子文本；尚待人工复核，不视为纸本校勘结论。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：戊寅，友珪易服微行入左龍虎軍。見統軍韓珪，以情告之。勍亦見功臣宿將多以小過被誅，懼不自保，遂相與合謀。勍以牙兵五百人從友珪雜控鶴士入，伏於禁中，中夜斬關入，至寢殿，侍疾者皆散走。帝驚起，問：「反者為誰？」友珪曰：「非他人也！」帝曰：「我固疑此賊，恨不早殺之。汝悖逆如此，天地豈容汝乎！」友珪曰：「老賊萬段！」友珪僕夫馮廷諤刺帝腹，刃出於背。友珪自以敗氈裹之，瘞於寢殿，秘不發喪。遣供奉官丁昭溥馳詣東都，命均王友貞殺友文。\n己卯，矯詔稱：「博王友文謀逆，遣兵突入殿中，賴郢王友珪忠孝，將兵誅之，保全朕躬。然疾因震驚，彌致危殆，宜令友珪權主軍國之務。」韓勍為友珪謀，多出府庫金帛賜諸軍及百官以取悅。\n辛巳，丁昭溥還，聞友文已死，乃發喪，宣遺制，友珪即皇帝位。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 44bc07e3-60f1-5402-a5f4-8735f2c832f1'; END IF; END $$;
