DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='44c1a2ce-49b5-56bb-baa5-c57e79feddda' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p005", "note": "原文：初，梁王以河北诸镇皆服，唯幽、沧未下，故大举伐之，欲以坚诸镇之心，既而潞州内叛，王烧营而还，威望大沮。恐中外因此离心，欲速受禅以镇之。丁亥，王入馆于魏，有疾，卧府中，魏博节度使罗绍威恐王袭之，入见王曰：“今四方称兵为王患者，皆以翼戴唐室为名，王不如早灭唐以绝人望。”王虽不许而心德之，乃亟归。壬寅，至大梁。甲辰，唐昭宣帝遣御史大夫薛贻矩至大梁劳王，贻矩请以臣礼见，王揖之升阶，贻矩曰：“殿下功德在人，三灵改卜，皇帝方行舜、禹之事，臣安敢违！”乃北面拜舞于庭。王侧身避之。贻矩还，言于帝曰：“元帅有受禅之意矣！”帝乃下诏，以二月禅位于梁，又遣宰相以书谕王；王辞。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第5段", "note": "原文：初，梁王以河北诸镇皆服，唯幽、沧未下，故大举伐之，欲以坚诸镇之心，既而潞州内叛，王烧营而还，威望大沮。恐中外因此离心，欲速受禅以镇之。丁亥，王入馆于魏，有疾，卧府中，魏博节度使罗绍威恐王袭之，入见王曰：“今四方称兵为王患者，皆以翼戴唐室为名，王不如早灭唐以绝人望。”王虽不许而心德之，乃亟归。壬寅，至大梁。甲辰，唐昭宣帝遣御史大夫薛贻矩至大梁劳王，贻矩请以臣礼见，王揖之升阶，贻矩曰：“殿下功德在人，三灵改卜，皇帝方行舜、禹之事，臣安敢违！”乃北面拜舞于庭。王侧身避之。贻矩还，言于帝曰：“元帅有受禅之意矣！”帝乃下诏，以二月禅位于梁，又遣宰相以书谕王；王辞。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 44c1a2ce-49b5-56bb-baa5-c57e79feddda'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第5段", "note": "原文：初，梁王以河北诸镇皆服，唯幽、沧未下，故大举伐之，欲以坚诸镇之心，既而潞州内叛，王烧营而还，威望大沮。恐中外因此离心，欲速受禅以镇之。丁亥，王入馆于魏，有疾，卧府中，魏博节度使罗绍威恐王袭之，入见王曰：“今四方称兵为王患者，皆以翼戴唐室为名，王不如早灭唐以绝人望。”王虽不许而心德之，乃亟归。壬寅，至大梁。甲辰，唐昭宣帝遣御史大夫薛贻矩至大梁劳王，贻矩请以臣礼见，王揖之升阶，贻矩曰：“殿下功德在人，三灵改卜，皇帝方行舜、禹之事，臣安敢违！”乃北面拜舞于庭。王侧身避之。贻矩还，言于帝曰：“元帅有受禅之意矣！”帝乃下诏，以二月禅位于梁，又遣宰相以书谕王；王辞。；核对说明："}'::jsonb) v WHERE fact_claim.id='44c1a2ce-49b5-56bb-baa5-c57e79feddda';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='44db40a4-cb04-51fc-b0e1-28786542c71f' AND (to_jsonb(t) @> '{"claim_text": "本批“蜀王”对应前蜀王建；《新五代史》前蜀世家列其姓名。", "note": "原文：新五代史 \n1344/1627 \n \n  \n前蜀世家第三  \n \n王建，字光图，许州舞阳人也。\n隆眉广颡，状貌伟然。少无赖，以屠\n牛、盗驴、贩私盐为事  ，里人谓之\n“贼王八”。后为忠武军卒，稍迁队\n将。  \n黄巢陷长安，僖宗在蜀，忠武军\n将鹿晏弘以兵八千属杨复光讨贼，巢\n败走，复光以其兵为八都，都将千\n人，建与晏弘皆为一都头。复光死，；核对说明：按PDF文字层提取核对；版式断行保留，未作纸本校勘。"}'::jsonb OR to_jsonb(t) @> '{"claim_text": "“蜀王”指前蜀王建；《新五代史》前蜀世家列其姓名。", "note": "原文：新五代史 \n1344/1627 \n \n  \n前蜀世家第三  \n \n王建，字光图，许州舞阳人也。\n隆眉广颡，状貌伟然。少无赖，以屠\n牛、盗驴、贩私盐为事  ，里人谓之\n“贼王八”。后为忠武军卒，稍迁队\n将。  \n黄巢陷长安，僖宗在蜀，忠武军\n将鹿晏弘以兵八千属杨复光讨贼，巢\n败走，复光以其兵为八都，都将千\n人，建与晏弘皆为一都头。复光死，；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 44db40a4-cb04-51fc-b0e1-28786542c71f'; END IF; END $$;
UPDATE public.fact_claim SET claim_text=v.claim_text,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"claim_text": "“蜀王”指前蜀王建；《新五代史》前蜀世家列其姓名。", "note": "原文：新五代史 \n1344/1627 \n \n  \n前蜀世家第三  \n \n王建，字光图，许州舞阳人也。\n隆眉广颡，状貌伟然。少无赖，以屠\n牛、盗驴、贩私盐为事  ，里人谓之\n“贼王八”。后为忠武军卒，稍迁队\n将。  \n黄巢陷长安，僖宗在蜀，忠武军\n将鹿晏弘以兵八千属杨复光讨贼，巢\n败走，复光以其兵为八都，都将千\n人，建与晏弘皆为一都头。复光死，；核对说明："}'::jsonb) v WHERE fact_claim.id='44db40a4-cb04-51fc-b0e1-28786542c71f';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='45704125-1877-5956-8a79-9df38f9639b0' AND (to_jsonb(t) @> '{"note": "原文：旧五代史 \n81/1667 \n之。癸亥，诏以前朝官僚，谴逐南\n荒，积年未经昭雪，其间有怀抱材器\n为时所嫉者，深负冤抑。仍令录其名\n姓，尽复官资，兼告谕诸道令津致赴\n阙。如已亡殁，并许归葬，以明恩\n荡。以西都徽安门北路逼近大内宫\n垣，兼非民便，令移自榆林直趋端门\n之南。改耀州报恩禅院为兴国寺。马\n殷奏破淮寇；静海军节度使曲裕卒。  \n七月丙申，以静海军行营司马权\n知留后曲颢起复为安南都护，充节度\n使。《五代会要》：七月，敕云：\n“建国迁都，俾新其制，况山河之\n险，表里为防。今二京俱在关东以\n内，仍以潼关隶陕州，复置河潼军；核对说明：本项目核读电子文本；文字层不是原刻影印，未作纸本校勘。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：旧五代史 \n81/1667 \n之。癸亥，诏以前朝官僚，谴逐南\n荒，积年未经昭雪，其间有怀抱材器\n为时所嫉者，深负冤抑。仍令录其名\n姓，尽复官资，兼告谕诸道令津致赴\n阙。如已亡殁，并许归葬，以明恩\n荡。以西都徽安门北路逼近大内宫\n垣，兼非民便，令移自榆林直趋端门\n之南。改耀州报恩禅院为兴国寺。马\n殷奏破淮寇；静海军节度使曲裕卒。  \n七月丙申，以静海军行营司马权\n知留后曲颢起复为安南都护，充节度\n使。《五代会要》：七月，敕云：\n“建国迁都，俾新其制，况山河之\n险，表里为防。今二京俱在关东以\n内，仍以潼关隶陕州，复置河潼军；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 45704125-1877-5956-8a79-9df38f9639b0'; END IF; END $$;
