UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第44段", "note": "原文：静海节度使曲裕卒，丙申，以其子权知留后颢为节度使。；核对说明："}'::jsonb) v WHERE fact_claim.id='4632cb5c-114f-54da-883f-9c5fb3e23b71';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='46b5fe61-25b1-510c-981d-e95d4edb579c' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p011", "note": "原文：甲辰，唐昭宣帝降御札禅位于梁。以摄中书令张文蔚为册礼使，礼部尚书苏循副之；摄侍中杨涉为押传国宝使，翰林学士张策副之；御史大夫薛贻矩为押金宝使，尚书左丞赵光逢副之；帅百官备法驾诣大梁。杨涉子直史馆凝式言于涉曰：“大人为唐宰相，而国家至此，不可谓之无过。况手持天子玺绶与人，虽保富贵，奈千载何！盍辞之！”涉大骇曰：“汝灭吾族！”神色为之不宁者数日。策，敦煌人。光逢，隐之子也。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第11段", "note": "原文：甲辰，唐昭宣帝降御札禅位于梁。以摄中书令张文蔚为册礼使，礼部尚书苏循副之；摄侍中杨涉为押传国宝使，翰林学士张策副之；御史大夫薛贻矩为押金宝使，尚书左丞赵光逢副之；帅百官备法驾诣大梁。杨涉子直史馆凝式言于涉曰：“大人为唐宰相，而国家至此，不可谓之无过。况手持天子玺绶与人，虽保富贵，奈千载何！盍辞之！”涉大骇曰：“汝灭吾族！”神色为之不宁者数日。策，敦煌人。光逢，隐之子也。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 46b5fe61-25b1-510c-981d-e95d4edb579c'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第11段", "note": "原文：甲辰，唐昭宣帝降御札禅位于梁。以摄中书令张文蔚为册礼使，礼部尚书苏循副之；摄侍中杨涉为押传国宝使，翰林学士张策副之；御史大夫薛贻矩为押金宝使，尚书左丞赵光逢副之；帅百官备法驾诣大梁。杨涉子直史馆凝式言于涉曰：“大人为唐宰相，而国家至此，不可谓之无过。况手持天子玺绶与人，虽保富贵，奈千载何！盍辞之！”涉大骇曰：“汝灭吾族！”神色为之不宁者数日。策，敦煌人。光逢，隐之子也。；核对说明："}'::jsonb) v WHERE fact_claim.id='46b5fe61-25b1-510c-981d-e95d4edb579c';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='46ca4d62-81e4-50e5-8204-19f9b6eaa6f9' AND (to_jsonb(t) @> '{"note": "原文：甲子，張文蔚、楊涉乘輅自上源驛從冊寶，諸司各備儀衛鹵簿前導，百官從其後，至金祥殿前陳之。王被兗冕，即皇帝位。張文蔚、蘇循奉冊升殿進讀，楊涉、張策、薛貽矩、趙光逢以次奉寶升殿，讀已，降，帥百官舞蹈稱賀。帝遂與文蔚等宴於玄德殿。帝舉酒曰：「朕輔政未久，此皆諸公推戴之力。」文蔚等皆慚懼，俯伏不能對，獨蘇循、薛貽矩及刑部尚書張禕盛稱帝功德宜應天順人。帝復與宗戚飲博於宮中，酒酣，朱全昱忽以投瓊擊盆中迸散，睨帝曰：「朱三，汝本碭山一民也，從黃巢為盜，天子用汝為四鎮節度使，富貴極矣！奈何一旦滅唐家三百年社稷，自稱帝王！行當族滅，奚以博為！」帝不懌而罷。乙丑，命有司告天地、宗廟、社稷。丁卯，遣使宣諭州、鎮。戊辰，大赦，改元，國號大梁。奉唐昭宣帝為濟陰王，皆如前代故事，唐中外舊臣官爵並如故。以汴州為開封府，命曰東都；以故東都為西都；廢故西京，以京兆府為大安府，置佑國軍於大安府，更名魏博曰天雄軍。遷濟陰王於曹州，栫之以棘，使甲士守之。；核对说明：已对照所保存电子文本；尚待人工复核，不视为纸本校勘结论。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：甲子，張文蔚、楊涉乘輅自上源驛從冊寶，諸司各備儀衛鹵簿前導，百官從其後，至金祥殿前陳之。王被兗冕，即皇帝位。張文蔚、蘇循奉冊升殿進讀，楊涉、張策、薛貽矩、趙光逢以次奉寶升殿，讀已，降，帥百官舞蹈稱賀。帝遂與文蔚等宴於玄德殿。帝舉酒曰：「朕輔政未久，此皆諸公推戴之力。」文蔚等皆慚懼，俯伏不能對，獨蘇循、薛貽矩及刑部尚書張禕盛稱帝功德宜應天順人。帝復與宗戚飲博於宮中，酒酣，朱全昱忽以投瓊擊盆中迸散，睨帝曰：「朱三，汝本碭山一民也，從黃巢為盜，天子用汝為四鎮節度使，富貴極矣！奈何一旦滅唐家三百年社稷，自稱帝王！行當族滅，奚以博為！」帝不懌而罷。乙丑，命有司告天地、宗廟、社稷。丁卯，遣使宣諭州、鎮。戊辰，大赦，改元，國號大梁。奉唐昭宣帝為濟陰王，皆如前代故事，唐中外舊臣官爵並如故。以汴州為開封府，命曰東都；以故東都為西都；廢故西京，以京兆府為大安府，置佑國軍於大安府，更名魏博曰天雄軍。遷濟陰王於曹州，栫之以棘，使甲士守之。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 46ca4d62-81e4-50e5-8204-19f9b6eaa6f9'; END IF; END $$;
