DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='4bd83daa-0077-54f5-96c7-57d3654d7226' AND (to_jsonb(t) @> '{"note": "原文：旧五代史 \n79/1667 \n为乾文院，同和院改为佐鸾院。《五\n代会要》：五月，改御食使为司膳\n使，小马坊使为天骥使。以西都水北\n宅为大昌宫，废雍州太清宫，改西都\n太微宫，亳州太清宫皆为观，诸州紫\n极宫皆为老君庙。泉州僧智宣自西域\n回，进辟支佛骨及梵夹经律。丙申，\n御元德殿，宴犒诸军使刘捍、符道昭\n已下，赐物有差。   \n是月，青州、许州、定州三镇节\n度使请开内宴，各赐方物。以青州节\n度使韩建守司徒、平章事。帝以建有\n文武材，且详于稼穑利害、军旅之\n事、筹度经费，欲尽询焉，恩泽特异\n于时，罕有比者；随拜为上相，赐赉；核对说明：本项目核读电子文本；文字层不是原刻影印，未作纸本校勘。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：旧五代史 \n79/1667 \n为乾文院，同和院改为佐鸾院。《五\n代会要》：五月，改御食使为司膳\n使，小马坊使为天骥使。以西都水北\n宅为大昌宫，废雍州太清宫，改西都\n太微宫，亳州太清宫皆为观，诸州紫\n极宫皆为老君庙。泉州僧智宣自西域\n回，进辟支佛骨及梵夹经律。丙申，\n御元德殿，宴犒诸军使刘捍、符道昭\n已下，赐物有差。   \n是月，青州、许州、定州三镇节\n度使请开内宴，各赐方物。以青州节\n度使韩建守司徒、平章事。帝以建有\n文武材，且详于稼穑利害、军旅之\n事、筹度经费，欲尽询焉，恩泽特异\n于时，罕有比者；随拜为上相，赐赉；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 4bd83daa-0077-54f5-96c7-57d3654d7226'; END IF; END $$;
