DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='4c0bc829-859d-546a-8342-e36a31183fc7' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p016", "note": "原文：壬戌，梁王更名晃。王兄全昱闻王将即帝位，谓王曰：“硃三，尔可作天子乎！”；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第16段", "note": "原文：壬戌，梁王更名晃。王兄全昱闻王将即帝位，谓王曰：“硃三，尔可作天子乎！”；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 4c0bc829-859d-546a-8342-e36a31183fc7'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第16段", "note": "原文：壬戌，梁王更名晃。王兄全昱闻王将即帝位，谓王曰：“硃三，尔可作天子乎！”；核对说明："}'::jsonb) v WHERE fact_claim.id='4c0bc829-859d-546a-8342-e36a31183fc7';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='4c9d7da7-ce22-5291-b10c-e3dcb655c4f2' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p004", "note": "原文：渥居丧，昼夜酣饮作乐，然十围之烛以击球，一烛费钱数万。或单骑出游，从者奔走道路，不知所之。左、右牙指挥使张颢、徐温泣谏，渥怒曰：“汝谓我不才，何不杀我自为之！”二人惧。渥选壮士，号“东院马军”，广署亲信为将吏；所署者恃势骄横，陵蔑勋旧。颢、温潜谋作乱。渥父行密之世，有亲军数千，营于牙城之内，渥迁出于外，以其地为射场，颢、温由是无所惮。渥之镇宣州也，命指挥使硃思勍、范思从、陈璠将亲兵三千；及嗣位，召归广陵。颢、温使三将从秦裴击江西，因戍洪州，诬以谋叛，命别将陈祐往诛之。祐间道兼行，六日至洪州，微服怀短兵径入秦裴帐中，裴大惊，祐告之故，乃召思勍等饮酒，祐数思勍等罪，执而斩之。渥闻三将死，益忌颢、温，欲诛之。丙戍，渥晨视事，颢、温帅牙兵二百，露刃直入庭中，渥曰：“尔思欲杀我邪？”对曰，“非敢然也，欲诛王左右乱政者耳！”因数渥所亲信十馀人之罪，曳下，以铁楇击杀之，谓之“兵谏”。诸将不与之同者，颢、温稍以法诛之，于是军政悉归二人，渥不能制。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第4段", "note": "原文：渥居丧，昼夜酣饮作乐，然十围之烛以击球，一烛费钱数万。或单骑出游，从者奔走道路，不知所之。左、右牙指挥使张颢、徐温泣谏，渥怒曰：“汝谓我不才，何不杀我自为之！”二人惧。渥选壮士，号“东院马军”，广署亲信为将吏；所署者恃势骄横，陵蔑勋旧。颢、温潜谋作乱。渥父行密之世，有亲军数千，营于牙城之内，渥迁出于外，以其地为射场，颢、温由是无所惮。渥之镇宣州也，命指挥使硃思勍、范思从、陈璠将亲兵三千；及嗣位，召归广陵。颢、温使三将从秦裴击江西，因戍洪州，诬以谋叛，命别将陈祐往诛之。祐间道兼行，六日至洪州，微服怀短兵径入秦裴帐中，裴大惊，祐告之故，乃召思勍等饮酒，祐数思勍等罪，执而斩之。渥闻三将死，益忌颢、温，欲诛之。丙戍，渥晨视事，颢、温帅牙兵二百，露刃直入庭中，渥曰：“尔思欲杀我邪？”对曰，“非敢然也，欲诛王左右乱政者耳！”因数渥所亲信十馀人之罪，曳下，以铁楇击杀之，谓之“兵谏”。诸将不与之同者，颢、温稍以法诛之，于是军政悉归二人，渥不能制。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 4c9d7da7-ce22-5291-b10c-e3dcb655c4f2'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第4段", "note": "原文：渥居丧，昼夜酣饮作乐，然十围之烛以击球，一烛费钱数万。或单骑出游，从者奔走道路，不知所之。左、右牙指挥使张颢、徐温泣谏，渥怒曰：“汝谓我不才，何不杀我自为之！”二人惧。渥选壮士，号“东院马军”，广署亲信为将吏；所署者恃势骄横，陵蔑勋旧。颢、温潜谋作乱。渥父行密之世，有亲军数千，营于牙城之内，渥迁出于外，以其地为射场，颢、温由是无所惮。渥之镇宣州也，命指挥使硃思勍、范思从、陈璠将亲兵三千；及嗣位，召归广陵。颢、温使三将从秦裴击江西，因戍洪州，诬以谋叛，命别将陈祐往诛之。祐间道兼行，六日至洪州，微服怀短兵径入秦裴帐中，裴大惊，祐告之故，乃召思勍等饮酒，祐数思勍等罪，执而斩之。渥闻三将死，益忌颢、温，欲诛之。丙戍，渥晨视事，颢、温帅牙兵二百，露刃直入庭中，渥曰：“尔思欲杀我邪？”对曰，“非敢然也，欲诛王左右乱政者耳！”因数渥所亲信十馀人之罪，曳下，以铁楇击杀之，谓之“兵谏”。诸将不与之同者，颢、温稍以法诛之，于是军政悉归二人，渥不能制。；核对说明："}'::jsonb) v WHERE fact_claim.id='4c9d7da7-ce22-5291-b10c-e3dcb655c4f2';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='4d384a20-3de4-5790-b7cf-13dae9d4d726' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p013", "claim_text": "《资治通鉴》907年条所记人物。在“刘守光夺取卢龙军权并囚禁刘仁恭”中为进攻者。本批仅整理相关史事，生卒与完整履历待补。", "note": "原文：仁恭有爱妾罗氏，其子守光通焉。仁恭杖守光而斥之，不以为子数。李思安引兵入其境，所过焚荡无馀。夏，四月，己酉，直抵幽州城下。仁恭犹在大安山。城中无备，几至不守。守光自外引兵入，登城拒守；又出兵与思安战，思安败退。守光遂自称节度使，命部将李小喜、元行钦将兵攻大安山。仁恭遣兵拒战，为小喜所败。虏仁恭以归，囚于别室。仁恭将佐及左右，凡守光素所恶者皆杀之。银胡录都指挥使王思同帅部兵三千，山后八安巡检使李承约帅部兵二千奔河东，守光弟守奇奔契丹，未几，亦奔河东，河东节度使晋王克用以承约为匡霸指挥使，思同为飞腾指挥使。思同母，仁恭之女也。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第13段", "claim_text": "据《资治通鉴》，907年在“刘守光夺取卢龙军权并囚禁刘仁恭”中为进攻者。", "note": "原文：仁恭有爱妾罗氏，其子守光通焉。仁恭杖守光而斥之，不以为子数。李思安引兵入其境，所过焚荡无馀。夏，四月，己酉，直抵幽州城下。仁恭犹在大安山。城中无备，几至不守。守光自外引兵入，登城拒守；又出兵与思安战，思安败退。守光遂自称节度使，命部将李小喜、元行钦将兵攻大安山。仁恭遣兵拒战，为小喜所败。虏仁恭以归，囚于别室。仁恭将佐及左右，凡守光素所恶者皆杀之。银胡录都指挥使王思同帅部兵三千，山后八安巡检使李承约帅部兵二千奔河东，守光弟守奇奔契丹，未几，亦奔河东，河东节度使晋王克用以承约为匡霸指挥使，思同为飞腾指挥使。思同母，仁恭之女也。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 4d384a20-3de4-5790-b7cf-13dae9d4d726'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,claim_text=v.claim_text,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第13段", "claim_text": "据《资治通鉴》，907年在“刘守光夺取卢龙军权并囚禁刘仁恭”中为进攻者。", "note": "原文：仁恭有爱妾罗氏，其子守光通焉。仁恭杖守光而斥之，不以为子数。李思安引兵入其境，所过焚荡无馀。夏，四月，己酉，直抵幽州城下。仁恭犹在大安山。城中无备，几至不守。守光自外引兵入，登城拒守；又出兵与思安战，思安败退。守光遂自称节度使，命部将李小喜、元行钦将兵攻大安山。仁恭遣兵拒战，为小喜所败。虏仁恭以归，囚于别室。仁恭将佐及左右，凡守光素所恶者皆杀之。银胡录都指挥使王思同帅部兵三千，山后八安巡检使李承约帅部兵二千奔河东，守光弟守奇奔契丹，未几，亦奔河东，河东节度使晋王克用以承约为匡霸指挥使，思同为飞腾指挥使。思同母，仁恭之女也。；核对说明："}'::jsonb) v WHERE fact_claim.id='4d384a20-3de4-5790-b7cf-13dae9d4d726';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='4dead970-faaa-5532-b96c-dd9c5f20ef85' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p055", "claim_text": "《资治通鉴》907年条所记人物。在“罗绍威劝刘守文归梁，刘延祐入质”中为入质者。本批仅整理相关史事，生卒与完整履历待补。", "note": "原文：天雄节度使鄴王绍威谓其下曰：“守光以窘急归国，守文孤立无援，沧州可不战服也。”乃遗守文书，谕以祸福。守文亦恐梁乘虚袭其后，戊子，遣使请降，以子延祐为质。帝拊手曰：“绍威折简，胜十万兵！”加守文中书令，抚纳之。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第55段", "claim_text": "据《资治通鉴》，907年在“罗绍威劝刘守文归梁，刘延祐入质”中为入质者。", "note": "原文：天雄节度使鄴王绍威谓其下曰：“守光以窘急归国，守文孤立无援，沧州可不战服也。”乃遗守文书，谕以祸福。守文亦恐梁乘虚袭其后，戊子，遣使请降，以子延祐为质。帝拊手曰：“绍威折简，胜十万兵！”加守文中书令，抚纳之。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 4dead970-faaa-5532-b96c-dd9c5f20ef85'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,claim_text=v.claim_text,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第55段", "claim_text": "据《资治通鉴》，907年在“罗绍威劝刘守文归梁，刘延祐入质”中为入质者。", "note": "原文：天雄节度使鄴王绍威谓其下曰：“守光以窘急归国，守文孤立无援，沧州可不战服也。”乃遗守文书，谕以祸福。守文亦恐梁乘虚袭其后，戊子，遣使请降，以子延祐为质。帝拊手曰：“绍威折简，胜十万兵！”加守文中书令，抚纳之。；核对说明："}'::jsonb) v WHERE fact_claim.id='4dead970-faaa-5532-b96c-dd9c5f20ef85';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='4e763387-4d43-5996-b9d6-25da5792e7a7' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p017", "note": "原文：甲子，张文蔚、杨涉乘辂自上源驿从册宝，诸司各备仪卫卤簿前导，百官从其后，至金祥殿前陈之。王被兗冕，即皇帝位。张文蔚、苏循奉册升殿进读，杨涉、张策、薛贻矩、赵光逢以次奉宝升殿，读已，降，帅百官舞蹈称贺。帝遂与文蔚等宴于玄德殿。帝举酒曰：“朕辅政未久，此皆诸公推戴之力。”文蔚等皆惭惧，俯伏不能对，独苏循、薛贻矩及刑部尚书张祎盛称帝功德宜应天顺人。帝复与宗戚饮博于宫中，酒酣，硃全昱忽以投琼击盆中迸散，睨帝曰：“硃三，汝本砀山一民也，从黄巢为盗，天子用汝为四镇节度使，富贵极矣！奈何一旦灭唐家三百年社稷，自称帝王！行当族灭，奚以博为！”帝不怿而罢。乙丑，命有司告天地、宗庙、社稷。丁卯，遣使宣谕州、镇。戊辰，大赦，改元，国号大梁。奉唐昭宣帝为济阴王，皆如前代故事，唐中外旧臣官爵并如故。以汴州为开封府，命曰东都；以故东都为西都；废故西京，以京兆府为大安府，置佑国军于大安府，更名魏博曰天雄军。迁济阴王于曹州，栫之以棘，使甲士守之。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第17段", "note": "原文：甲子，张文蔚、杨涉乘辂自上源驿从册宝，诸司各备仪卫卤簿前导，百官从其后，至金祥殿前陈之。王被兗冕，即皇帝位。张文蔚、苏循奉册升殿进读，杨涉、张策、薛贻矩、赵光逢以次奉宝升殿，读已，降，帅百官舞蹈称贺。帝遂与文蔚等宴于玄德殿。帝举酒曰：“朕辅政未久，此皆诸公推戴之力。”文蔚等皆惭惧，俯伏不能对，独苏循、薛贻矩及刑部尚书张祎盛称帝功德宜应天顺人。帝复与宗戚饮博于宫中，酒酣，硃全昱忽以投琼击盆中迸散，睨帝曰：“硃三，汝本砀山一民也，从黄巢为盗，天子用汝为四镇节度使，富贵极矣！奈何一旦灭唐家三百年社稷，自称帝王！行当族灭，奚以博为！”帝不怿而罢。乙丑，命有司告天地、宗庙、社稷。丁卯，遣使宣谕州、镇。戊辰，大赦，改元，国号大梁。奉唐昭宣帝为济阴王，皆如前代故事，唐中外旧臣官爵并如故。以汴州为开封府，命曰东都；以故东都为西都；废故西京，以京兆府为大安府，置佑国军于大安府，更名魏博曰天雄军。迁济阴王于曹州，栫之以棘，使甲士守之。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 4e763387-4d43-5996-b9d6-25da5792e7a7'; END IF; END $$;
