DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='4ec59af4-c251-5b84-b138-9ea2d5ffc64c' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p024", "note": "原文：岐王治军甚宽，待士卒简易。有告部将苻昭反者，岐王直诣其家，悉去左右，熟寝经宿而还；由是众心悦服。然御军无纪律。及闻唐亡，以兵羸地蹙，不敢称帝，但开岐王府，置百官，名其所居为宫殿，妻称皇后，将吏上书称笺表，鞭、扇、号令多拟帝者。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第24段", "note": "原文：岐王治军甚宽，待士卒简易。有告部将苻昭反者，岐王直诣其家，悉去左右，熟寝经宿而还；由是众心悦服。然御军无纪律。及闻唐亡，以兵羸地蹙，不敢称帝，但开岐王府，置百官，名其所居为宫殿，妻称皇后，将吏上书称笺表，鞭、扇、号令多拟帝者。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 4ec59af4-c251-5b84-b138-9ea2d5ffc64c'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第24段", "note": "原文：岐王治军甚宽，待士卒简易。有告部将苻昭反者，岐王直诣其家，悉去左右，熟寝经宿而还；由是众心悦服。然御军无纪律。及闻唐亡，以兵羸地蹙，不敢称帝，但开岐王府，置百官，名其所居为宫殿，妻称皇后，将吏上书称笺表，鞭、扇、号令多拟帝者。；核对说明："}'::jsonb) v WHERE fact_claim.id='4ec59af4-c251-5b84-b138-9ea2d5ffc64c';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='50105dc3-adde-5fa3-877f-6d043203b7d1' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p027", "note": "原文：加武顺军节度使赵王王镕宁太师，天雄节度使鄴王罗绍威守太傅，义武节度使王处直兼侍中。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第27段", "note": "原文：加武顺军节度使赵王王镕宁太师，天雄节度使鄴王罗绍威守太傅，义武节度使王处直兼侍中。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 50105dc3-adde-5fa3-877f-6d043203b7d1'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第27段", "note": "原文：加武顺军节度使赵王王镕宁太师，天雄节度使鄴王罗绍威守太傅，义武节度使王处直兼侍中。；核对说明："}'::jsonb) v WHERE fact_claim.id='50105dc3-adde-5fa3-877f-6d043203b7d1';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='50249b52-b8f9-5859-a651-cb339621d63e' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p013", "note": "原文：仁恭有爱妾罗氏，其子守光通焉。仁恭杖守光而斥之，不以为子数。李思安引兵入其境，所过焚荡无馀。夏，四月，己酉，直抵幽州城下。仁恭犹在大安山。城中无备，几至不守。守光自外引兵入，登城拒守；又出兵与思安战，思安败退。守光遂自称节度使，命部将李小喜、元行钦将兵攻大安山。仁恭遣兵拒战，为小喜所败。虏仁恭以归，囚于别室。仁恭将佐及左右，凡守光素所恶者皆杀之。银胡录都指挥使王思同帅部兵三千，山后八安巡检使李承约帅部兵二千奔河东，守光弟守奇奔契丹，未几，亦奔河东，河东节度使晋王克用以承约为匡霸指挥使，思同为飞腾指挥使。思同母，仁恭之女也。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第13段", "note": "原文：仁恭有爱妾罗氏，其子守光通焉。仁恭杖守光而斥之，不以为子数。李思安引兵入其境，所过焚荡无馀。夏，四月，己酉，直抵幽州城下。仁恭犹在大安山。城中无备，几至不守。守光自外引兵入，登城拒守；又出兵与思安战，思安败退。守光遂自称节度使，命部将李小喜、元行钦将兵攻大安山。仁恭遣兵拒战，为小喜所败。虏仁恭以归，囚于别室。仁恭将佐及左右，凡守光素所恶者皆杀之。银胡录都指挥使王思同帅部兵三千，山后八安巡检使李承约帅部兵二千奔河东，守光弟守奇奔契丹，未几，亦奔河东，河东节度使晋王克用以承约为匡霸指挥使，思同为飞腾指挥使。思同母，仁恭之女也。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 50249b52-b8f9-5859-a651-cb339621d63e'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第13段", "note": "原文：仁恭有爱妾罗氏，其子守光通焉。仁恭杖守光而斥之，不以为子数。李思安引兵入其境，所过焚荡无馀。夏，四月，己酉，直抵幽州城下。仁恭犹在大安山。城中无备，几至不守。守光自外引兵入，登城拒守；又出兵与思安战，思安败退。守光遂自称节度使，命部将李小喜、元行钦将兵攻大安山。仁恭遣兵拒战，为小喜所败。虏仁恭以归，囚于别室。仁恭将佐及左右，凡守光素所恶者皆杀之。银胡录都指挥使王思同帅部兵三千，山后八安巡检使李承约帅部兵二千奔河东，守光弟守奇奔契丹，未几，亦奔河东，河东节度使晋王克用以承约为匡霸指挥使，思同为飞腾指挥使。思同母，仁恭之女也。；核对说明："}'::jsonb) v WHERE fact_claim.id='50249b52-b8f9-5859-a651-cb339621d63e';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='50302a68-3caa-5169-b521-13072ec2d5e0' AND (to_jsonb(t) @> '{"note": "原文：甲子，張文蔚、楊涉乘輅自上源驛從冊寶，諸司各備儀衛鹵簿前導，百官從其後，至金祥殿前陳之。王被兗冕，即皇帝位。張文蔚、蘇循奉冊升殿進讀，楊涉、張策、薛貽矩、趙光逢以次奉寶升殿，讀已，降，帥百官舞蹈稱賀。帝遂與文蔚等宴於玄德殿。帝舉酒曰：「朕輔政未久，此皆諸公推戴之力。」文蔚等皆慚懼，俯伏不能對，獨蘇循、薛貽矩及刑部尚書張禕盛稱帝功德宜應天順人。帝復與宗戚飲博於宮中，酒酣，朱全昱忽以投瓊擊盆中迸散，睨帝曰：「朱三，汝本碭山一民也，從黃巢為盜，天子用汝為四鎮節度使，富貴極矣！奈何一旦滅唐家三百年社稷，自稱帝王！行當族滅，奚以博為！」帝不懌而罷。乙丑，命有司告天地、宗廟、社稷。丁卯，遣使宣諭州、鎮。戊辰，大赦，改元，國號大梁。奉唐昭宣帝為濟陰王，皆如前代故事，唐中外舊臣官爵並如故。以汴州為開封府，命曰東都；以故東都為西都；廢故西京，以京兆府為大安府，置佑國軍於大安府，更名魏博曰天雄軍。遷濟陰王於曹州，栫之以棘，使甲士守之。；核对说明：已对照所保存电子文本；尚待人工复核，不视为纸本校勘结论。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：甲子，張文蔚、楊涉乘輅自上源驛從冊寶，諸司各備儀衛鹵簿前導，百官從其後，至金祥殿前陳之。王被兗冕，即皇帝位。張文蔚、蘇循奉冊升殿進讀，楊涉、張策、薛貽矩、趙光逢以次奉寶升殿，讀已，降，帥百官舞蹈稱賀。帝遂與文蔚等宴於玄德殿。帝舉酒曰：「朕輔政未久，此皆諸公推戴之力。」文蔚等皆慚懼，俯伏不能對，獨蘇循、薛貽矩及刑部尚書張禕盛稱帝功德宜應天順人。帝復與宗戚飲博於宮中，酒酣，朱全昱忽以投瓊擊盆中迸散，睨帝曰：「朱三，汝本碭山一民也，從黃巢為盜，天子用汝為四鎮節度使，富貴極矣！奈何一旦滅唐家三百年社稷，自稱帝王！行當族滅，奚以博為！」帝不懌而罷。乙丑，命有司告天地、宗廟、社稷。丁卯，遣使宣諭州、鎮。戊辰，大赦，改元，國號大梁。奉唐昭宣帝為濟陰王，皆如前代故事，唐中外舊臣官爵並如故。以汴州為開封府，命曰東都；以故東都為西都；廢故西京，以京兆府為大安府，置佑國軍於大安府，更名魏博曰天雄軍。遷濟陰王於曹州，栫之以棘，使甲士守之。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 50302a68-3caa-5169-b521-13072ec2d5e0'; END IF; END $$;
