DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='529967d4-bb61-56e8-bae8-4629a2e6a614' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p011", "note": "原文：甲辰，唐昭宣帝降御札禅位于梁。以摄中书令张文蔚为册礼使，礼部尚书苏循副之；摄侍中杨涉为押传国宝使，翰林学士张策副之；御史大夫薛贻矩为押金宝使，尚书左丞赵光逢副之；帅百官备法驾诣大梁。杨涉子直史馆凝式言于涉曰：“大人为唐宰相，而国家至此，不可谓之无过。况手持天子玺绶与人，虽保富贵，奈千载何！盍辞之！”涉大骇曰：“汝灭吾族！”神色为之不宁者数日。策，敦煌人。光逢，隐之子也。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第11段", "note": "原文：甲辰，唐昭宣帝降御札禅位于梁。以摄中书令张文蔚为册礼使，礼部尚书苏循副之；摄侍中杨涉为押传国宝使，翰林学士张策副之；御史大夫薛贻矩为押金宝使，尚书左丞赵光逢副之；帅百官备法驾诣大梁。杨涉子直史馆凝式言于涉曰：“大人为唐宰相，而国家至此，不可谓之无过。况手持天子玺绶与人，虽保富贵，奈千载何！盍辞之！”涉大骇曰：“汝灭吾族！”神色为之不宁者数日。策，敦煌人。光逢，隐之子也。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 529967d4-bb61-56e8-bae8-4629a2e6a614'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第11段", "note": "原文：甲辰，唐昭宣帝降御札禅位于梁。以摄中书令张文蔚为册礼使，礼部尚书苏循副之；摄侍中杨涉为押传国宝使，翰林学士张策副之；御史大夫薛贻矩为押金宝使，尚书左丞赵光逢副之；帅百官备法驾诣大梁。杨涉子直史馆凝式言于涉曰：“大人为唐宰相，而国家至此，不可谓之无过。况手持天子玺绶与人，虽保富贵，奈千载何！盍辞之！”涉大骇曰：“汝灭吾族！”神色为之不宁者数日。策，敦煌人。光逢，隐之子也。；核对说明："}'::jsonb) v WHERE fact_claim.id='529967d4-bb61-56e8-bae8-4629a2e6a614';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='53218a93-a5bd-5edf-bf7d-dad1d042c9b2' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p052", "claim_text": "《资治通鉴》907年条所记人物。在“荆南、楚军攻朗州，许德勋击败淮南援军”中为淮南援将。本批仅整理相关史事，生卒与完整履历待补。", "note": "原文：冬，十月，高季昌遣其将倪可福会楚将秦彦晖攻朗州，雷彦恭遣使乞降于淮南，且告急。弘农王遣将泠业将水军屯平江，李饶将步骑屯浏阳以救之，楚王殷遣岳州刺史许德勋将兵拒之。泠业进屯朗口，德勋使善游者五十人，以木枝叶覆其首，持长刀浮江而下，夜犯其营，且举火，业军中惊扰。德以大军进击，大破之，追至鹿角镇，擒业；又破浏阳寨，擒李饶；掠上高、唐年而归。斩业、饶于长沙市。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第52段", "claim_text": "据《资治通鉴》，907年在“荆南、楚军攻朗州，许德勋击败淮南援军”中为淮南援将。", "note": "原文：冬，十月，高季昌遣其将倪可福会楚将秦彦晖攻朗州，雷彦恭遣使乞降于淮南，且告急。弘农王遣将泠业将水军屯平江，李饶将步骑屯浏阳以救之，楚王殷遣岳州刺史许德勋将兵拒之。泠业进屯朗口，德勋使善游者五十人，以木枝叶覆其首，持长刀浮江而下，夜犯其营，且举火，业军中惊扰。德以大军进击，大破之，追至鹿角镇，擒业；又破浏阳寨，擒李饶；掠上高、唐年而归。斩业、饶于长沙市。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 53218a93-a5bd-5edf-bf7d-dad1d042c9b2'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,claim_text=v.claim_text,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第52段", "claim_text": "据《资治通鉴》，907年在“荆南、楚军攻朗州，许德勋击败淮南援军”中为淮南援将。", "note": "原文：冬，十月，高季昌遣其将倪可福会楚将秦彦晖攻朗州，雷彦恭遣使乞降于淮南，且告急。弘农王遣将泠业将水军屯平江，李饶将步骑屯浏阳以救之，楚王殷遣岳州刺史许德勋将兵拒之。泠业进屯朗口，德勋使善游者五十人，以木枝叶覆其首，持长刀浮江而下，夜犯其营，且举火，业军中惊扰。德以大军进击，大破之，追至鹿角镇，擒业；又破浏阳寨，擒李饶；掠上高、唐年而归。斩业、饶于长沙市。；核对说明："}'::jsonb) v WHERE fact_claim.id='53218a93-a5bd-5edf-bf7d-dad1d042c9b2';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='53aa8cb9-faaf-579f-9ed7-36be16103c75' AND (to_jsonb(t) @> '{"note": "原文：晉王疽發於首，病篤。周德威等退屯亂柳。晉王命其弟內外蕃漢都知兵馬使、振武節度使克寧、監軍張承業、大將李存璋、吳珙、掌書記盧質立其子晉州刺史存勖為嗣，曰：「此子志氣遠大，必能成吾事，爾曹善教導之！」辛卯，晉王謂存勖曰：「嗣昭厄於重圍，吾不及見矣。俟葬畢，汝與德威輩速竭力救之！」又謂克寧等曰：「以亞子累汝！」亞子，存勖小名也。言終而卒。克寧綱紀軍府，中外無敢喧嘩。克寧久總兵柄，有次立之勢，時上黨圍未解，軍中以存勖年少，多竊議者，人情忷忷。存勖懼，以位讓克寧。克寧曰：「汝冢嗣也，且有先王之命，誰敢違之！」將吏欲謁見存勖，存勖方哀哭未出。張承業入謂存勖曰：「大孝在不墜基業，多哭何為！」因扶存勖出，襲位為河東節度使、晉王。；核对说明：已对照所保存电子文本；尚待人工复核，不视为纸本校勘结论。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：晉王疽發於首，病篤。周德威等退屯亂柳。晉王命其弟內外蕃漢都知兵馬使、振武節度使克寧、監軍張承業、大將李存璋、吳珙、掌書記盧質立其子晉州刺史存勖為嗣，曰：「此子志氣遠大，必能成吾事，爾曹善教導之！」辛卯，晉王謂存勖曰：「嗣昭厄於重圍，吾不及見矣。俟葬畢，汝與德威輩速竭力救之！」又謂克寧等曰：「以亞子累汝！」亞子，存勖小名也。言終而卒。克寧綱紀軍府，中外無敢喧嘩。克寧久總兵柄，有次立之勢，時上黨圍未解，軍中以存勖年少，多竊議者，人情忷忷。存勖懼，以位讓克寧。克寧曰：「汝冢嗣也，且有先王之命，誰敢違之！」將吏欲謁見存勖，存勖方哀哭未出。張承業入謂存勖曰：「大孝在不墜基業，多哭何為！」因扶存勖出，襲位為河東節度使、晉王。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 53aa8cb9-faaf-579f-9ed7-36be16103c75'; END IF; END $$;
UPDATE public.fact_claim SET note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"note": "原文：晉王疽發於首，病篤。周德威等退屯亂柳。晉王命其弟內外蕃漢都知兵馬使、振武節度使克寧、監軍張承業、大將李存璋、吳珙、掌書記盧質立其子晉州刺史存勖為嗣，曰：「此子志氣遠大，必能成吾事，爾曹善教導之！」辛卯，晉王謂存勖曰：「嗣昭厄於重圍，吾不及見矣。俟葬畢，汝與德威輩速竭力救之！」又謂克寧等曰：「以亞子累汝！」亞子，存勖小名也。言終而卒。克寧綱紀軍府，中外無敢喧嘩。克寧久總兵柄，有次立之勢，時上黨圍未解，軍中以存勖年少，多竊議者，人情忷忷。存勖懼，以位讓克寧。克寧曰：「汝冢嗣也，且有先王之命，誰敢違之！」將吏欲謁見存勖，存勖方哀哭未出。張承業入謂存勖曰：「大孝在不墜基業，多哭何為！」因扶存勖出，襲位為河東節度使、晉王。；核对说明："}'::jsonb) v WHERE fact_claim.id='53aa8cb9-faaf-579f-9ed7-36be16103c75';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='53ad2e69-3003-54aa-a96d-4cf0f58cd868' AND (to_jsonb(t) @> '{"note": "原文：壬戌，至胡柳陂。癸亥旦，候者言梁兵自後至矣。周德威曰：「賊倍道而來，未有所捨，我營柵已固，守備有餘，既深入敵境，動須萬全，不可輕發。此去大梁至近，梁兵各念其家，內懷憤激，不以方略制之，恐難得志。王宜按兵勿戰，德威請以騎兵擾之，使彼不得休息，至暮營壘未立，樵爨未具，乘其疲乏，可一舉滅也。」王曰：「前在河上恨不見賊，今賊至不擊，尚復何待，公何怯也！」顧李存審曰：「敕輜重先發，吾為爾殿後，破賊而去！」即以親軍先出。德威不得已，引幽州兵從之，謂其子曰：「吾無死所矣。」賀瑰結陳而至，橫亙數十里。王帥銀槍都陷其陳，沖蕩擊斬，往返十餘里。行營左廂馬軍都指揮使、鄭州防禦使王彥章軍先敗，西走趣濮陽。晉輜重在陳西，望見梁旗幟，驚潰，入幽州陳，幽州兵亦擾亂，自相蹈藉；周德威不能制，父子皆戰死。；核对说明：已对照所保存电子文本；尚待人工复核，不视为纸本校勘结论。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：壬戌，至胡柳陂。癸亥旦，候者言梁兵自後至矣。周德威曰：「賊倍道而來，未有所捨，我營柵已固，守備有餘，既深入敵境，動須萬全，不可輕發。此去大梁至近，梁兵各念其家，內懷憤激，不以方略制之，恐難得志。王宜按兵勿戰，德威請以騎兵擾之，使彼不得休息，至暮營壘未立，樵爨未具，乘其疲乏，可一舉滅也。」王曰：「前在河上恨不見賊，今賊至不擊，尚復何待，公何怯也！」顧李存審曰：「敕輜重先發，吾為爾殿後，破賊而去！」即以親軍先出。德威不得已，引幽州兵從之，謂其子曰：「吾無死所矣。」賀瑰結陳而至，橫亙數十里。王帥銀槍都陷其陳，沖蕩擊斬，往返十餘里。行營左廂馬軍都指揮使、鄭州防禦使王彥章軍先敗，西走趣濮陽。晉輜重在陳西，望見梁旗幟，驚潰，入幽州陳，幽州兵亦擾亂，自相蹈藉；周德威不能制，父子皆戰死。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 53ad2e69-3003-54aa-a96d-4cf0f58cd868'; END IF; END $$;
