DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='548e364b-c9bf-5e71-9c84-53da8386098a' AND (to_jsonb(t) @> '{"note": "原文：戊寅，友珪易服微行入左龍虎軍。見統軍韓珪，以情告之。勍亦見功臣宿將多以小過被誅，懼不自保，遂相與合謀。勍以牙兵五百人從友珪雜控鶴士入，伏於禁中，中夜斬關入，至寢殿，侍疾者皆散走。帝驚起，問：「反者為誰？」友珪曰：「非他人也！」帝曰：「我固疑此賊，恨不早殺之。汝悖逆如此，天地豈容汝乎！」友珪曰：「老賊萬段！」友珪僕夫馮廷諤刺帝腹，刃出於背。友珪自以敗氈裹之，瘞於寢殿，秘不發喪。遣供奉官丁昭溥馳詣東都，命均王友貞殺友文。\n己卯，矯詔稱：「博王友文謀逆，遣兵突入殿中，賴郢王友珪忠孝，將兵誅之，保全朕躬。然疾因震驚，彌致危殆，宜令友珪權主軍國之務。」韓勍為友珪謀，多出府庫金帛賜諸軍及百官以取悅。\n辛巳，丁昭溥還，聞友文已死，乃發喪，宣遺制，友珪即皇帝位。；核对说明：已对照所保存电子文本；尚待人工复核，不视为纸本校勘结论。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：戊寅，友珪易服微行入左龍虎軍。見統軍韓珪，以情告之。勍亦見功臣宿將多以小過被誅，懼不自保，遂相與合謀。勍以牙兵五百人從友珪雜控鶴士入，伏於禁中，中夜斬關入，至寢殿，侍疾者皆散走。帝驚起，問：「反者為誰？」友珪曰：「非他人也！」帝曰：「我固疑此賊，恨不早殺之。汝悖逆如此，天地豈容汝乎！」友珪曰：「老賊萬段！」友珪僕夫馮廷諤刺帝腹，刃出於背。友珪自以敗氈裹之，瘞於寢殿，秘不發喪。遣供奉官丁昭溥馳詣東都，命均王友貞殺友文。\n己卯，矯詔稱：「博王友文謀逆，遣兵突入殿中，賴郢王友珪忠孝，將兵誅之，保全朕躬。然疾因震驚，彌致危殆，宜令友珪權主軍國之務。」韓勍為友珪謀，多出府庫金帛賜諸軍及百官以取悅。\n辛巳，丁昭溥還，聞友文已死，乃發喪，宣遺制，友珪即皇帝位。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 548e364b-c9bf-5e71-9c84-53da8386098a'; END IF; END $$;
