DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='55cc38bf-0c0f-507d-94d1-2550b2ca245f' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p016", "claim_text": "《资治通鉴》907年条所记人物。在“朱温在即位前更名晃”中为质问者。本批仅整理相关史事，生卒与完整履历待补。", "note": "原文：壬戌，梁王更名晃。王兄全昱闻王将即帝位，谓王曰：“硃三，尔可作天子乎！”；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第16段", "claim_text": "据《资治通鉴》，907年在“朱温在即位前更名晃”中为质问者。", "note": "原文：壬戌，梁王更名晃。王兄全昱闻王将即帝位，谓王曰：“硃三，尔可作天子乎！”；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 55cc38bf-0c0f-507d-94d1-2550b2ca245f'; END IF; END $$;
