UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·年次题记", "note": "原文：开平元年丁卯，公元九零七年；核对说明："}'::jsonb) v WHERE fact_claim.id='5704d2be-914e-5e8d-90dd-b8d062b9f19c';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='5748663a-d6cf-50a1-b03b-0f8605b2afbd' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p037", "claim_text": "《资治通鉴》907年条所记人物。在“楚军击败刘存等淮南水军，攻取岳州”中为淮南应援使。本批仅整理相关史事，生卒与完整履历待补。", "note": "原文：弘农王以鄂岳观察使刘存为西南面都招讨使，岳州刺史陈知新为岳州团练使，庐州观察使刘威为应援使，别将许玄应为监军，将水军三万以击楚。楚王马殷甚惧，静江军使杨定真贺曰：“我军胜矣！”殷问其故，定真曰：“夫战惧则胜，骄则败。今淮南兵直趋吾城，是骄而轻敌也；而王有惧色，吾是以知其必胜也。”殷命在城都指挥使秦彦晖将水军三万浮江而下，水军副指挥使黄璠帅战舰三百屯浏阳口。六月，存等遇大雨，引兵还至越堤北，彦晖追之。存数战不利，乃遗殷书诈降。彦晖使谓殷曰：“此必诈也，勿受！”存与彦晖夹水而阵，存遥呼曰：“杀降不祥，公独不为子孙计耶！”彦晖曰：“贼入吾境而不击，奚顾子孙！”鼓噪而进。存等走，黄璠自浏阳引兵绝江，与彦晖合击，大破之，执存及知新，裨将死者百馀人，士卒死者以万数，获战舰八百艘。威以馀众遁归，彦晖遂拔岳州。殷释存、知新之缚，慰谕之。二人皆骂曰：“丈夫以死报主，肯事贼乎！”遂斩之。许玄应，弘农王之腹心也，常预政事，张颢、徐温因其败，收斩之。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第37段", "claim_text": "据《资治通鉴》，907年在“楚军击败刘存等淮南水军，攻取岳州”中为淮南应援使。", "note": "原文：弘农王以鄂岳观察使刘存为西南面都招讨使，岳州刺史陈知新为岳州团练使，庐州观察使刘威为应援使，别将许玄应为监军，将水军三万以击楚。楚王马殷甚惧，静江军使杨定真贺曰：“我军胜矣！”殷问其故，定真曰：“夫战惧则胜，骄则败。今淮南兵直趋吾城，是骄而轻敌也；而王有惧色，吾是以知其必胜也。”殷命在城都指挥使秦彦晖将水军三万浮江而下，水军副指挥使黄璠帅战舰三百屯浏阳口。六月，存等遇大雨，引兵还至越堤北，彦晖追之。存数战不利，乃遗殷书诈降。彦晖使谓殷曰：“此必诈也，勿受！”存与彦晖夹水而阵，存遥呼曰：“杀降不祥，公独不为子孙计耶！”彦晖曰：“贼入吾境而不击，奚顾子孙！”鼓噪而进。存等走，黄璠自浏阳引兵绝江，与彦晖合击，大破之，执存及知新，裨将死者百馀人，士卒死者以万数，获战舰八百艘。威以馀众遁归，彦晖遂拔岳州。殷释存、知新之缚，慰谕之。二人皆骂曰：“丈夫以死报主，肯事贼乎！”遂斩之。许玄应，弘农王之腹心也，常预政事，张颢、徐温因其败，收斩之。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 5748663a-d6cf-50a1-b03b-0f8605b2afbd'; END IF; END $$;
