DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='585b0ac6-a392-56b3-8a7b-37265ccaf603' AND (to_jsonb(t) @> '{"note": "原文：庚寅旦，袁象先等帥禁兵數千人突入宮中。友珪聞變，與妻張氏及馮廷諤趨北垣樓下，將逾城，自度不免，令廷諤先殺妻，次殺己，廷諤亦自剄。諸軍十餘萬大掠都市，百司逃散，中書侍郎、同平章事杜曉、侍講學士李珽皆為亂兵所殺，門下侍郎、同平章事於兢、宣政使李振被傷。至晡乃定。\n像先、巖繼傳國寶詣大梁迎均王，王曰：「大梁國家創業之地，何必洛陽！」乃即帝位於大梁，復稱乾化三年，追廢友珪為庶人，復博王友文官爵。；核对说明：已对照所保存电子文本；尚待人工复核，不视为纸本校勘结论。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：庚寅旦，袁象先等帥禁兵數千人突入宮中。友珪聞變，與妻張氏及馮廷諤趨北垣樓下，將逾城，自度不免，令廷諤先殺妻，次殺己，廷諤亦自剄。諸軍十餘萬大掠都市，百司逃散，中書侍郎、同平章事杜曉、侍講學士李珽皆為亂兵所殺，門下侍郎、同平章事於兢、宣政使李振被傷。至晡乃定。\n像先、巖繼傳國寶詣大梁迎均王，王曰：「大梁國家創業之地，何必洛陽！」乃即帝位於大梁，復稱乾化三年，追廢友珪為庶人，復博王友文官爵。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 585b0ac6-a392-56b3-8a7b-37265ccaf603'; END IF; END $$;
UPDATE public.fact_claim SET note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"note": "原文：庚寅旦，袁象先等帥禁兵數千人突入宮中。友珪聞變，與妻張氏及馮廷諤趨北垣樓下，將逾城，自度不免，令廷諤先殺妻，次殺己，廷諤亦自剄。諸軍十餘萬大掠都市，百司逃散，中書侍郎、同平章事杜曉、侍講學士李珽皆為亂兵所殺，門下侍郎、同平章事於兢、宣政使李振被傷。至晡乃定。\n像先、巖繼傳國寶詣大梁迎均王，王曰：「大梁國家創業之地，何必洛陽！」乃即帝位於大梁，復稱乾化三年，追廢友珪為庶人，復博王友文官爵。；核对说明："}'::jsonb) v WHERE fact_claim.id='585b0ac6-a392-56b3-8a7b-37265ccaf603';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='5876d05b-3efd-5981-b69f-a48f19e2bf0a' AND (to_jsonb(t) @> '{"note": "原文：戊寅，或告唐軍已過曹州，塵埃漲天，趙巖謂從者曰：「吾待溫許州厚，必不負我。」遂奔許州。梁主謂皇甫麟曰：「李氏吾世仇，理難降首，不可俟彼刀鋸。吾不能自裁，卿可斷吾首。」麟泣曰：「臣為陛下揮劍死唐軍則可矣，不敢奉此詔。」梁主曰：「卿欲賣我邪？」麟欲自剄，梁主持之曰：「與卿俱死！」麟遂弒梁主，因自殺。梁主為人溫恭儉約，無荒淫之失；但寵信趙、張，使擅威福，疏棄敬、李舊臣，不用其言，以至於亡。\n己卯旦，李嗣源軍至大梁，攻封丘門，王瓚開門出降，嗣源入城，撫安軍民。是日，帝入自梁門，百官迎謁於馬首，拜伏請罪，帝慰勞之，使各復其位。李嗣源迎賀，帝喜不自勝，手引嗣源衣，以頭觸之曰：「吾有天下，卿父子之功也，天下與爾共之。」帝命訪求梁主，頃之，或以其首獻。；核对说明：已对照所保存电子文本；尚待人工复核，不视为纸本校勘结论。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：戊寅，或告唐軍已過曹州，塵埃漲天，趙巖謂從者曰：「吾待溫許州厚，必不負我。」遂奔許州。梁主謂皇甫麟曰：「李氏吾世仇，理難降首，不可俟彼刀鋸。吾不能自裁，卿可斷吾首。」麟泣曰：「臣為陛下揮劍死唐軍則可矣，不敢奉此詔。」梁主曰：「卿欲賣我邪？」麟欲自剄，梁主持之曰：「與卿俱死！」麟遂弒梁主，因自殺。梁主為人溫恭儉約，無荒淫之失；但寵信趙、張，使擅威福，疏棄敬、李舊臣，不用其言，以至於亡。\n己卯旦，李嗣源軍至大梁，攻封丘門，王瓚開門出降，嗣源入城，撫安軍民。是日，帝入自梁門，百官迎謁於馬首，拜伏請罪，帝慰勞之，使各復其位。李嗣源迎賀，帝喜不自勝，手引嗣源衣，以頭觸之曰：「吾有天下，卿父子之功也，天下與爾共之。」帝命訪求梁主，頃之，或以其首獻。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 5876d05b-3efd-5981-b69f-a48f19e2bf0a'; END IF; END $$;
