DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='599857f7-16cf-5c40-8a8d-c412cb15b2e2' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p027", "claim_text": "后梁加授王镕、罗绍威、王处直官衔。用户TXT中“王镕宁太师”有疑字，王镕具体官衔暂不订正。", "note": "原文：加武顺军节度使赵王王镕宁太师，天雄节度使鄴王罗绍威守太傅，义武节度使王处直兼侍中。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第27段", "claim_text": "后梁加授王镕、罗绍威、王处直官衔。所据文本“王镕宁太师”有疑字，具体官衔待考。", "note": "原文：加武顺军节度使赵王王镕宁太师，天雄节度使鄴王罗绍威守太傅，义武节度使王处直兼侍中。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 599857f7-16cf-5c40-8a8d-c412cb15b2e2'; END IF; END $$;
