DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='59cdf288-b031-5595-a509-a9a268243a04' AND (to_jsonb(t) @> '{"note": "原文：丁亥，周德威與別將史建瑭、李嗣源將精騎三千壓梁壘門而詬之，王景仁、韓勍怒，悉眾而出。德威等轉戰而北至高邑南；李存璋以步兵陳於野河之上，梁軍橫亙數里，競前奪橋，鎮、定步兵御之，勢不能支。晉王謂匡衛都指揮使李建及曰：「賊過橋則不可複製矣。」建及選卒二百，援槍大噪，力戰卻之。建及，許州人，姓王，李罕之之假子也。晉王登高丘以望曰：「梁兵爭進而囂，我兵整而靜，我必勝。」戰自巳至午，勝負未決。晉王謂周德威曰：「兩軍已合，勢不可離，我之興亡，在此一舉。我為公先登，公可繼之。」德威叩馬而諫曰：「觀梁兵之勢，可以勞逸制之，未易以力勝也。彼去營三十餘里，雖挾糗糧，亦不暇食，日昳之後，飢渴內迫，矢刃外交，士卒勞倦，必有退志。當是時，我以精騎乘之，必大捷。於今未可也。」王乃止。；核对说明：已对照所保存电子文本；尚待人工复核，不视为纸本校勘结论。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：丁亥，周德威與別將史建瑭、李嗣源將精騎三千壓梁壘門而詬之，王景仁、韓勍怒，悉眾而出。德威等轉戰而北至高邑南；李存璋以步兵陳於野河之上，梁軍橫亙數里，競前奪橋，鎮、定步兵御之，勢不能支。晉王謂匡衛都指揮使李建及曰：「賊過橋則不可複製矣。」建及選卒二百，援槍大噪，力戰卻之。建及，許州人，姓王，李罕之之假子也。晉王登高丘以望曰：「梁兵爭進而囂，我兵整而靜，我必勝。」戰自巳至午，勝負未決。晉王謂周德威曰：「兩軍已合，勢不可離，我之興亡，在此一舉。我為公先登，公可繼之。」德威叩馬而諫曰：「觀梁兵之勢，可以勞逸制之，未易以力勝也。彼去營三十餘里，雖挾糗糧，亦不暇食，日昳之後，飢渴內迫，矢刃外交，士卒勞倦，必有退志。當是時，我以精騎乘之，必大捷。於今未可也。」王乃止。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 59cdf288-b031-5595-a509-a9a268243a04'; END IF; END $$;
UPDATE public.fact_claim SET note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"note": "原文：丁亥，周德威與別將史建瑭、李嗣源將精騎三千壓梁壘門而詬之，王景仁、韓勍怒，悉眾而出。德威等轉戰而北至高邑南；李存璋以步兵陳於野河之上，梁軍橫亙數里，競前奪橋，鎮、定步兵御之，勢不能支。晉王謂匡衛都指揮使李建及曰：「賊過橋則不可複製矣。」建及選卒二百，援槍大噪，力戰卻之。建及，許州人，姓王，李罕之之假子也。晉王登高丘以望曰：「梁兵爭進而囂，我兵整而靜，我必勝。」戰自巳至午，勝負未決。晉王謂周德威曰：「兩軍已合，勢不可離，我之興亡，在此一舉。我為公先登，公可繼之。」德威叩馬而諫曰：「觀梁兵之勢，可以勞逸制之，未易以力勝也。彼去營三十餘里，雖挾糗糧，亦不暇食，日昳之後，飢渴內迫，矢刃外交，士卒勞倦，必有退志。當是時，我以精騎乘之，必大捷。於今未可也。」王乃止。；核对说明："}'::jsonb) v WHERE fact_claim.id='59cdf288-b031-5595-a509-a9a268243a04';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='59dc0d89-85aa-5d30-b4e4-6ae3d29bf636' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p013", "note": "原文：仁恭有爱妾罗氏，其子守光通焉。仁恭杖守光而斥之，不以为子数。李思安引兵入其境，所过焚荡无馀。夏，四月，己酉，直抵幽州城下。仁恭犹在大安山。城中无备，几至不守。守光自外引兵入，登城拒守；又出兵与思安战，思安败退。守光遂自称节度使，命部将李小喜、元行钦将兵攻大安山。仁恭遣兵拒战，为小喜所败。虏仁恭以归，囚于别室。仁恭将佐及左右，凡守光素所恶者皆杀之。银胡录都指挥使王思同帅部兵三千，山后八安巡检使李承约帅部兵二千奔河东，守光弟守奇奔契丹，未几，亦奔河东，河东节度使晋王克用以承约为匡霸指挥使，思同为飞腾指挥使。思同母，仁恭之女也。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第13段", "note": "原文：仁恭有爱妾罗氏，其子守光通焉。仁恭杖守光而斥之，不以为子数。李思安引兵入其境，所过焚荡无馀。夏，四月，己酉，直抵幽州城下。仁恭犹在大安山。城中无备，几至不守。守光自外引兵入，登城拒守；又出兵与思安战，思安败退。守光遂自称节度使，命部将李小喜、元行钦将兵攻大安山。仁恭遣兵拒战，为小喜所败。虏仁恭以归，囚于别室。仁恭将佐及左右，凡守光素所恶者皆杀之。银胡录都指挥使王思同帅部兵三千，山后八安巡检使李承约帅部兵二千奔河东，守光弟守奇奔契丹，未几，亦奔河东，河东节度使晋王克用以承约为匡霸指挥使，思同为飞腾指挥使。思同母，仁恭之女也。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 59dc0d89-85aa-5d30-b4e4-6ae3d29bf636'; END IF; END $$;
