DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='5d6b0fd6-ed23-54cc-a94f-b3b630284dc7' AND (to_jsonb(t) @> '{"note": "原文：旧五代史 \n74/1667 \n张祎盛称帝功德，宜应天顺人。宋州\n刺史王皋进两岐麦，陈州袁象先进白\n兔一，付史馆编录，兼示百官。诏在\n京司及诸军州县印一例铸换，其篆文\n则各如旧。辛未，武安军节度使马殷\n进封楚王。以太府卿敬翔知崇政院，\n翔与帷幄之谋，故首擢焉。追尊四代\n庙号：高祖妫州府君上谥曰宣元皇\n帝，庙号肃祖，太庙第一室，陵号兴\n极陵，祖妣高平县君范氏追谥宣僖皇\n后；皇曾祖宣惠王上谥曰光献皇帝，\n庙号敬祖，第二室，陵号永安，祖妣\n秦国夫人杨氏追谥光孝皇后；皇祖武\n元王上谥曰昭武皇帝，庙号宪祖，第\n三室，陵号光天，祖妣吴国夫人刘氏；核对说明：本项目核读电子文本；文字层不是原刻影印，未作纸本校勘。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：旧五代史 \n74/1667 \n张祎盛称帝功德，宜应天顺人。宋州\n刺史王皋进两岐麦，陈州袁象先进白\n兔一，付史馆编录，兼示百官。诏在\n京司及诸军州县印一例铸换，其篆文\n则各如旧。辛未，武安军节度使马殷\n进封楚王。以太府卿敬翔知崇政院，\n翔与帷幄之谋，故首擢焉。追尊四代\n庙号：高祖妫州府君上谥曰宣元皇\n帝，庙号肃祖，太庙第一室，陵号兴\n极陵，祖妣高平县君范氏追谥宣僖皇\n后；皇曾祖宣惠王上谥曰光献皇帝，\n庙号敬祖，第二室，陵号永安，祖妣\n秦国夫人杨氏追谥光孝皇后；皇祖武\n元王上谥曰昭武皇帝，庙号宪祖，第\n三室，陵号光天，祖妣吴国夫人刘氏；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 5d6b0fd6-ed23-54cc-a94f-b3b630284dc7'; END IF; END $$;
UPDATE public.fact_claim SET note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"note": "原文：旧五代史 \n74/1667 \n张祎盛称帝功德，宜应天顺人。宋州\n刺史王皋进两岐麦，陈州袁象先进白\n兔一，付史馆编录，兼示百官。诏在\n京司及诸军州县印一例铸换，其篆文\n则各如旧。辛未，武安军节度使马殷\n进封楚王。以太府卿敬翔知崇政院，\n翔与帷幄之谋，故首擢焉。追尊四代\n庙号：高祖妫州府君上谥曰宣元皇\n帝，庙号肃祖，太庙第一室，陵号兴\n极陵，祖妣高平县君范氏追谥宣僖皇\n后；皇曾祖宣惠王上谥曰光献皇帝，\n庙号敬祖，第二室，陵号永安，祖妣\n秦国夫人杨氏追谥光孝皇后；皇祖武\n元王上谥曰昭武皇帝，庙号宪祖，第\n三室，陵号光天，祖妣吴国夫人刘氏；核对说明："}'::jsonb) v WHERE fact_claim.id='5d6b0fd6-ed23-54cc-a94f-b3b630284dc7';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='5dc05483-363f-51b4-92a5-7191dafc8045' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p051", "claim_text": "《资治通鉴》907年条所记人物。在“王建称帝，建立前蜀”中为献议者。本批仅整理相关史事，生卒与完整履历待补。", "note": "原文：蜀王会将佐议称帝，皆曰：“大王虽忠于唐，唐已亡矣，此所谓‘天与不取’者也。”冯涓独献议，请，以蜀王称制，曰：“朝兴则未爽称臣，贼在则不同为恶。”王不从，涓杜门不出。王用安抚副使、掌书记韦庄之谋，帅吏民哭三日；己亥，即皇帝位，国号大蜀。辛丑，以前东川节度使兼侍中王宗佶为中书令，韦庄为左散骑常侍、判中书门下事，阆州防御使唐道袭为内枢密使。庄，见素之孙也。蜀主虽目不知书，好与书生谈论，粗晓其理。是时唐衣冠之族多避乱在蜀，蜀主礼而用之，使修举故事，故其典章文物有唐之遗风。蜀主长子校书郎宗仁幼以疾废，立其次子秘书少监宗懿为遂王。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第51段", "claim_text": "据《资治通鉴》，907年在“王建称帝，建立前蜀”中为献议者。", "note": "原文：蜀王会将佐议称帝，皆曰：“大王虽忠于唐，唐已亡矣，此所谓‘天与不取’者也。”冯涓独献议，请，以蜀王称制，曰：“朝兴则未爽称臣，贼在则不同为恶。”王不从，涓杜门不出。王用安抚副使、掌书记韦庄之谋，帅吏民哭三日；己亥，即皇帝位，国号大蜀。辛丑，以前东川节度使兼侍中王宗佶为中书令，韦庄为左散骑常侍、判中书门下事，阆州防御使唐道袭为内枢密使。庄，见素之孙也。蜀主虽目不知书，好与书生谈论，粗晓其理。是时唐衣冠之族多避乱在蜀，蜀主礼而用之，使修举故事，故其典章文物有唐之遗风。蜀主长子校书郎宗仁幼以疾废，立其次子秘书少监宗懿为遂王。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 5dc05483-363f-51b4-92a5-7191dafc8045'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,claim_text=v.claim_text,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第51段", "claim_text": "据《资治通鉴》，907年在“王建称帝，建立前蜀”中为献议者。", "note": "原文：蜀王会将佐议称帝，皆曰：“大王虽忠于唐，唐已亡矣，此所谓‘天与不取’者也。”冯涓独献议，请，以蜀王称制，曰：“朝兴则未爽称臣，贼在则不同为恶。”王不从，涓杜门不出。王用安抚副使、掌书记韦庄之谋，帅吏民哭三日；己亥，即皇帝位，国号大蜀。辛丑，以前东川节度使兼侍中王宗佶为中书令，韦庄为左散骑常侍、判中书门下事，阆州防御使唐道袭为内枢密使。庄，见素之孙也。蜀主虽目不知书，好与书生谈论，粗晓其理。是时唐衣冠之族多避乱在蜀，蜀主礼而用之，使修举故事，故其典章文物有唐之遗风。蜀主长子校书郎宗仁幼以疾废，立其次子秘书少监宗懿为遂王。；核对说明："}'::jsonb) v WHERE fact_claim.id='5dc05483-363f-51b4-92a5-7191dafc8045';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='5dd3abce-8cdd-5e3c-947d-d44f4203dfd4' AND (to_jsonb(t) @> '{"claim_text": "《旧五代史》记西京大内放出两宫内人及前朝宫人，任其所适；不推算人数，也不扩写后续生活。", "note": "原文：旧五代史 \n83/1667 \n树，并图形以献。是月，隰州奏，大\n宁县至固镇上下二百里，今月八日，\n黄河清，至十月如故。   \n九月辛丑，西京大内放出两宫内\n人及前朝宫人，任其所适。敕以近年\n文武官诸道奉使，皆于所在分外停\n住，逾年涉岁，未闻归阙。非惟劳费\n州郡，抑且侮慢国经。臣节既亏，宪\n章安在。自今后两浙、福建、广州、\n安南、邕、容等道使到发许住一月；\n湖南、洪、鄂、黔、桂许住二十日；\n荆、襄、同、雍、镇、定、青、沧许\n住十日；其余侧近不过三五日。凡往\n来道路，据远近里数，日行两驿。如\n遇疾患及江河阻隔，委所在长吏具事；核对说明：本项目核读电子文本；文字层不是原刻影印，未作纸本校勘。"}'::jsonb OR to_jsonb(t) @> '{"claim_text": "《旧五代史》记西京大内放出两宫内人及前朝宫人，任其所适；人数及此后去向未详。", "note": "原文：旧五代史 \n83/1667 \n树，并图形以献。是月，隰州奏，大\n宁县至固镇上下二百里，今月八日，\n黄河清，至十月如故。   \n九月辛丑，西京大内放出两宫内\n人及前朝宫人，任其所适。敕以近年\n文武官诸道奉使，皆于所在分外停\n住，逾年涉岁，未闻归阙。非惟劳费\n州郡，抑且侮慢国经。臣节既亏，宪\n章安在。自今后两浙、福建、广州、\n安南、邕、容等道使到发许住一月；\n湖南、洪、鄂、黔、桂许住二十日；\n荆、襄、同、雍、镇、定、青、沧许\n住十日；其余侧近不过三五日。凡往\n来道路，据远近里数，日行两驿。如\n遇疾患及江河阻隔，委所在长吏具事；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 5dd3abce-8cdd-5e3c-947d-d44f4203dfd4'; END IF; END $$;
