DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='5dee663c-9d5c-5552-bb53-e4c92775974c' AND (to_jsonb(t) @> '{"note": "原文：友珪，小字遙喜，母失其姓，本亳州營妓也。唐光啟中，帝徇地亳州，召而侍寢。月餘，將舍之而去，以娠告。是時，元貞皇后賢而有寵，帝素憚之，由是不果攜歸大梁，因留亳州，以別宅貯之。及期，妓以生男來告，帝喜，故字之曰遙喜。後迎歸汴。受禪後封郢王。；核对说明：已对照所保存电子文本；尚待人工复核，不视为纸本校勘结论。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：友珪，小字遙喜，母失其姓，本亳州營妓也。唐光啟中，帝徇地亳州，召而侍寢。月餘，將舍之而去，以娠告。是時，元貞皇后賢而有寵，帝素憚之，由是不果攜歸大梁，因留亳州，以別宅貯之。及期，妓以生男來告，帝喜，故字之曰遙喜。後迎歸汴。受禪後封郢王。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 5dee663c-9d5c-5552-bb53-e4c92775974c'; END IF; END $$;
