DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='663ecff9-1bb5-5c36-8fc6-930e83bf6efd' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p008", "note": "原文：三月，癸未，王以亳州刺史李思安为北路行军都统，将兵击幽州。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第8段", "note": "原文：三月，癸未，王以亳州刺史李思安为北路行军都统，将兵击幽州。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 663ecff9-1bb5-5c36-8fc6-930e83bf6efd'; END IF; END $$;
