DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='66e01be3-3396-5d87-91d4-780442ccbc03' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p015", "claim_text": "《资治通鉴》907年条所记人物。在“钱氏军队攻取温州，卢佶被杀”中为温州制置使。本批仅整理相关史事，生卒与完整履历待补。", "note": "原文：卢佶闻钱传镣等将至，将水军拒之于青澳。钱传瓘曰：“佶之精兵尽在于此，不可与战。”乃自安固舍舟，间道袭温州。戊午，温州溃，擒佶斩之。吴王镠以都监使吴璋为温州制置使，命传瓘等移兵讨卢约于处州。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第15段", "claim_text": "据《资治通鉴》，907年在“钱氏军队攻取温州，卢佶被杀”中为温州制置使。", "note": "原文：卢佶闻钱传镣等将至，将水军拒之于青澳。钱传瓘曰：“佶之精兵尽在于此，不可与战。”乃自安固舍舟，间道袭温州。戊午，温州溃，擒佶斩之。吴王镠以都监使吴璋为温州制置使，命传瓘等移兵讨卢约于处州。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 66e01be3-3396-5d87-91d4-780442ccbc03'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,claim_text=v.claim_text,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第15段", "claim_text": "据《资治通鉴》，907年在“钱氏军队攻取温州，卢佶被杀”中为温州制置使。", "note": "原文：卢佶闻钱传镣等将至，将水军拒之于青澳。钱传瓘曰：“佶之精兵尽在于此，不可与战。”乃自安固舍舟，间道袭温州。戊午，温州溃，擒佶斩之。吴王镠以都监使吴璋为温州制置使，命传瓘等移兵讨卢约于处州。；核对说明："}'::jsonb) v WHERE fact_claim.id='66e01be3-3396-5d87-91d4-780442ccbc03';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='6717f873-eb93-5754-86e1-344ffb53ad45' AND (to_jsonb(t) @> '{"note": "原文：五月，辛未朔，晉王伏兵三垂岡下，詰旦大霧，進兵直抵夾寨。梁軍無斥候，不意晉兵之至，將士尚未起，軍中驚擾。晉王命周德威、李嗣源分兵為二道，德威攻西北隅，嗣源攻東北隅，填塹燒寨，鼓噪而入。梁兵大潰，南走，招討使符道昭馬倒，為晉人所殺。失亡將校士卒以萬計，委棄資糧、器械山積。周德威等至城下，呼李嗣昭曰：「先王已薨，今王自來，破賊夾寨。賊已去矣，可開門！」嗣昭不信，曰：「此必為賊所得，使來誑我耳。」欲射之。左右止之，嗣昭曰：「王果來，可見乎？」王自往呼之。嗣昭見王白服，大慟幾絕，城中皆哭，遂開門。；核对说明：已对照所保存电子文本；尚待人工复核，不视为纸本校勘结论。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：五月，辛未朔，晉王伏兵三垂岡下，詰旦大霧，進兵直抵夾寨。梁軍無斥候，不意晉兵之至，將士尚未起，軍中驚擾。晉王命周德威、李嗣源分兵為二道，德威攻西北隅，嗣源攻東北隅，填塹燒寨，鼓噪而入。梁兵大潰，南走，招討使符道昭馬倒，為晉人所殺。失亡將校士卒以萬計，委棄資糧、器械山積。周德威等至城下，呼李嗣昭曰：「先王已薨，今王自來，破賊夾寨。賊已去矣，可開門！」嗣昭不信，曰：「此必為賊所得，使來誑我耳。」欲射之。左右止之，嗣昭曰：「王果來，可見乎？」王自往呼之。嗣昭見王白服，大慟幾絕，城中皆哭，遂開門。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 6717f873-eb93-5754-86e1-344ffb53ad45'; END IF; END $$;
