DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='682de84c-f714-521e-881c-5953c2aa29bf' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p031", "note": "原文：乙酉，立皇兄全昱为广王，子友文为博王，友珪为郢王，友璋为福王，友贞为均王，友雍为贺王，友徽为建王。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第31段", "note": "原文：乙酉，立皇兄全昱为广王，子友文为博王，友珪为郢王，友璋为福王，友贞为均王，友雍为贺王，友徽为建王。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 682de84c-f714-521e-881c-5953c2aa29bf'; END IF; END $$;
