UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第48段", "note": "原文：晋周德威壁于高河，康怀贞遣亲骑都头秦武将兵击之，武败。；核对说明："}'::jsonb) v WHERE fact_claim.id='6c29160f-29d3-5172-9194-f362d206ed55';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='6c3828c8-ef01-50be-99eb-9937af81b028' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p017", "note": "原文：甲子，张文蔚、杨涉乘辂自上源驿从册宝，诸司各备仪卫卤簿前导，百官从其后，至金祥殿前陈之。王被兗冕，即皇帝位。张文蔚、苏循奉册升殿进读，杨涉、张策、薛贻矩、赵光逢以次奉宝升殿，读已，降，帅百官舞蹈称贺。帝遂与文蔚等宴于玄德殿。帝举酒曰：“朕辅政未久，此皆诸公推戴之力。”文蔚等皆惭惧，俯伏不能对，独苏循、薛贻矩及刑部尚书张祎盛称帝功德宜应天顺人。帝复与宗戚饮博于宫中，酒酣，硃全昱忽以投琼击盆中迸散，睨帝曰：“硃三，汝本砀山一民也，从黄巢为盗，天子用汝为四镇节度使，富贵极矣！奈何一旦灭唐家三百年社稷，自称帝王！行当族灭，奚以博为！”帝不怿而罢。乙丑，命有司告天地、宗庙、社稷。丁卯，遣使宣谕州、镇。戊辰，大赦，改元，国号大梁。奉唐昭宣帝为济阴王，皆如前代故事，唐中外旧臣官爵并如故。以汴州为开封府，命曰东都；以故东都为西都；废故西京，以京兆府为大安府，置佑国军于大安府，更名魏博曰天雄军。迁济阴王于曹州，栫之以棘，使甲士守之。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第17段", "note": "原文：甲子，张文蔚、杨涉乘辂自上源驿从册宝，诸司各备仪卫卤簿前导，百官从其后，至金祥殿前陈之。王被兗冕，即皇帝位。张文蔚、苏循奉册升殿进读，杨涉、张策、薛贻矩、赵光逢以次奉宝升殿，读已，降，帅百官舞蹈称贺。帝遂与文蔚等宴于玄德殿。帝举酒曰：“朕辅政未久，此皆诸公推戴之力。”文蔚等皆惭惧，俯伏不能对，独苏循、薛贻矩及刑部尚书张祎盛称帝功德宜应天顺人。帝复与宗戚饮博于宫中，酒酣，硃全昱忽以投琼击盆中迸散，睨帝曰：“硃三，汝本砀山一民也，从黄巢为盗，天子用汝为四镇节度使，富贵极矣！奈何一旦灭唐家三百年社稷，自称帝王！行当族灭，奚以博为！”帝不怿而罢。乙丑，命有司告天地、宗庙、社稷。丁卯，遣使宣谕州、镇。戊辰，大赦，改元，国号大梁。奉唐昭宣帝为济阴王，皆如前代故事，唐中外旧臣官爵并如故。以汴州为开封府，命曰东都；以故东都为西都；废故西京，以京兆府为大安府，置佑国军于大安府，更名魏博曰天雄军。迁济阴王于曹州，栫之以棘，使甲士守之。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 6c3828c8-ef01-50be-99eb-9937af81b028'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第17段", "note": "原文：甲子，张文蔚、杨涉乘辂自上源驿从册宝，诸司各备仪卫卤簿前导，百官从其后，至金祥殿前陈之。王被兗冕，即皇帝位。张文蔚、苏循奉册升殿进读，杨涉、张策、薛贻矩、赵光逢以次奉宝升殿，读已，降，帅百官舞蹈称贺。帝遂与文蔚等宴于玄德殿。帝举酒曰：“朕辅政未久，此皆诸公推戴之力。”文蔚等皆惭惧，俯伏不能对，独苏循、薛贻矩及刑部尚书张祎盛称帝功德宜应天顺人。帝复与宗戚饮博于宫中，酒酣，硃全昱忽以投琼击盆中迸散，睨帝曰：“硃三，汝本砀山一民也，从黄巢为盗，天子用汝为四镇节度使，富贵极矣！奈何一旦灭唐家三百年社稷，自称帝王！行当族灭，奚以博为！”帝不怿而罢。乙丑，命有司告天地、宗庙、社稷。丁卯，遣使宣谕州、镇。戊辰，大赦，改元，国号大梁。奉唐昭宣帝为济阴王，皆如前代故事，唐中外旧臣官爵并如故。以汴州为开封府，命曰东都；以故东都为西都；废故西京，以京兆府为大安府，置佑国军于大安府，更名魏博曰天雄军。迁济阴王于曹州，栫之以棘，使甲士守之。；核对说明："}'::jsonb) v WHERE fact_claim.id='6c3828c8-ef01-50be-99eb-9937af81b028';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='6cb20014-47ba-527a-96b7-b2236ebe373e' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p037", "note": "原文：弘农王以鄂岳观察使刘存为西南面都招讨使，岳州刺史陈知新为岳州团练使，庐州观察使刘威为应援使，别将许玄应为监军，将水军三万以击楚。楚王马殷甚惧，静江军使杨定真贺曰：“我军胜矣！”殷问其故，定真曰：“夫战惧则胜，骄则败。今淮南兵直趋吾城，是骄而轻敌也；而王有惧色，吾是以知其必胜也。”殷命在城都指挥使秦彦晖将水军三万浮江而下，水军副指挥使黄璠帅战舰三百屯浏阳口。六月，存等遇大雨，引兵还至越堤北，彦晖追之。存数战不利，乃遗殷书诈降。彦晖使谓殷曰：“此必诈也，勿受！”存与彦晖夹水而阵，存遥呼曰：“杀降不祥，公独不为子孙计耶！”彦晖曰：“贼入吾境而不击，奚顾子孙！”鼓噪而进。存等走，黄璠自浏阳引兵绝江，与彦晖合击，大破之，执存及知新，裨将死者百馀人，士卒死者以万数，获战舰八百艘。威以馀众遁归，彦晖遂拔岳州。殷释存、知新之缚，慰谕之。二人皆骂曰：“丈夫以死报主，肯事贼乎！”遂斩之。许玄应，弘农王之腹心也，常预政事，张颢、徐温因其败，收斩之。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第37段", "note": "原文：弘农王以鄂岳观察使刘存为西南面都招讨使，岳州刺史陈知新为岳州团练使，庐州观察使刘威为应援使，别将许玄应为监军，将水军三万以击楚。楚王马殷甚惧，静江军使杨定真贺曰：“我军胜矣！”殷问其故，定真曰：“夫战惧则胜，骄则败。今淮南兵直趋吾城，是骄而轻敌也；而王有惧色，吾是以知其必胜也。”殷命在城都指挥使秦彦晖将水军三万浮江而下，水军副指挥使黄璠帅战舰三百屯浏阳口。六月，存等遇大雨，引兵还至越堤北，彦晖追之。存数战不利，乃遗殷书诈降。彦晖使谓殷曰：“此必诈也，勿受！”存与彦晖夹水而阵，存遥呼曰：“杀降不祥，公独不为子孙计耶！”彦晖曰：“贼入吾境而不击，奚顾子孙！”鼓噪而进。存等走，黄璠自浏阳引兵绝江，与彦晖合击，大破之，执存及知新，裨将死者百馀人，士卒死者以万数，获战舰八百艘。威以馀众遁归，彦晖遂拔岳州。殷释存、知新之缚，慰谕之。二人皆骂曰：“丈夫以死报主，肯事贼乎！”遂斩之。许玄应，弘农王之腹心也，常预政事，张颢、徐温因其败，收斩之。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 6cb20014-47ba-527a-96b7-b2236ebe373e'; END IF; END $$;
