DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='6df4eb89-da65-599c-8b0a-860de1cbdfb1' AND (to_jsonb(t) @> '{"note": "原文：旧五代史 \n80/1667 \n甚厚。宿州刺史王儒进白兔一，濮州\n刺史图嘉禾瑞麦以进。广州进奇宝名\n药，品类甚多。河南尹张全义进开平\n元年已前羡余钱十万贯、绸六千匹、\n绵三十万两，仍请每年上供定额每岁\n贡绢三万匹，以为常式。荆南高季昌\n进瑞橘数十颗，质状百味，倍胜常\n贡。且橘当冬熟，今方仲夏，时人咸\n异其事，因称为瑞。   \n六月，幸乾元院，宴召宰臣、学\n士及诸道入贡陪臣。己亥，帝御崇元\n殿，内出追尊四庙上谥号玉册宝共八\n副，宰臣文武百官仪仗鼓吹导引至太\n庙行事。癸卯，司天监奏：“日辰内\n有‘戊’字，请改为‘武’。”从\n旧五代史 \n81/1667 \n之。癸亥，诏以前朝官僚，谴逐南\n荒，积年未经昭雪，其间有怀抱材器\n为时所嫉者，深负冤抑。仍令录其名\n姓，尽复官资，兼告谕诸道令津致赴\n阙。如已亡殁，并许归葬，以明恩\n荡。以西都徽安门北路逼近大内宫\n垣，兼非民便，令移自榆林直趋端门\n之南。改耀州报恩禅院为兴国寺。马\n殷奏破淮寇；静海军节度使曲裕卒。  \n七月丙申，以静海军行营司马权\n知留后曲颢起复为安南都护，充节度\n使。《五代会要》：七月，敕云：\n“建国迁都，俾新其制，况山河之\n险，表里为防。今二京俱在关东以\n内，仍以潼关隶陕州，复置河潼军；核对说明：本项目核读电子文本；文字层不是原刻影印，未作纸本校勘。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：旧五代史 \n80/1667 \n甚厚。宿州刺史王儒进白兔一，濮州\n刺史图嘉禾瑞麦以进。广州进奇宝名\n药，品类甚多。河南尹张全义进开平\n元年已前羡余钱十万贯、绸六千匹、\n绵三十万两，仍请每年上供定额每岁\n贡绢三万匹，以为常式。荆南高季昌\n进瑞橘数十颗，质状百味，倍胜常\n贡。且橘当冬熟，今方仲夏，时人咸\n异其事，因称为瑞。   \n六月，幸乾元院，宴召宰臣、学\n士及诸道入贡陪臣。己亥，帝御崇元\n殿，内出追尊四庙上谥号玉册宝共八\n副，宰臣文武百官仪仗鼓吹导引至太\n庙行事。癸卯，司天监奏：“日辰内\n有‘戊’字，请改为‘武’。”从\n旧五代史 \n81/1667 \n之。癸亥，诏以前朝官僚，谴逐南\n荒，积年未经昭雪，其间有怀抱材器\n为时所嫉者，深负冤抑。仍令录其名\n姓，尽复官资，兼告谕诸道令津致赴\n阙。如已亡殁，并许归葬，以明恩\n荡。以西都徽安门北路逼近大内宫\n垣，兼非民便，令移自榆林直趋端门\n之南。改耀州报恩禅院为兴国寺。马\n殷奏破淮寇；静海军节度使曲裕卒。  \n七月丙申，以静海军行营司马权\n知留后曲颢起复为安南都护，充节度\n使。《五代会要》：七月，敕云：\n“建国迁都，俾新其制，况山河之\n险，表里为防。今二京俱在关东以\n内，仍以潼关隶陕州，复置河潼军；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 6df4eb89-da65-599c-8b0a-860de1cbdfb1'; END IF; END $$;
