DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='6e044e3a-5a11-5eee-868d-13d1e8165f0c' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p007", "note": "原文：二月，唐大臣共奏请昭宣帝逊位。壬子，诏宰相帅百官笺诣元帅府劝进，王遣使却之。于是朝臣、籓镇，乃至湖南、岭南上笺劝进者相继。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第7段", "note": "原文：二月，唐大臣共奏请昭宣帝逊位。壬子，诏宰相帅百官笺诣元帅府劝进，王遣使却之。于是朝臣、籓镇，乃至湖南、岭南上笺劝进者相继。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 6e044e3a-5a11-5eee-868d-13d1e8165f0c'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第7段", "note": "原文：二月，唐大臣共奏请昭宣帝逊位。壬子，诏宰相帅百官笺诣元帅府劝进，王遣使却之。于是朝臣、籓镇，乃至湖南、岭南上笺劝进者相继。；核对说明："}'::jsonb) v WHERE fact_claim.id='6e044e3a-5a11-5eee-868d-13d1e8165f0c';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='6e0d0af1-3455-5ea6-96db-8c60acc62235' AND (to_jsonb(t) @> '{"note": "原文：五月，辛未朔，晉王伏兵三垂岡下，詰旦大霧，進兵直抵夾寨。梁軍無斥候，不意晉兵之至，將士尚未起，軍中驚擾。晉王命周德威、李嗣源分兵為二道，德威攻西北隅，嗣源攻東北隅，填塹燒寨，鼓噪而入。梁兵大潰，南走，招討使符道昭馬倒，為晉人所殺。失亡將校士卒以萬計，委棄資糧、器械山積。周德威等至城下，呼李嗣昭曰：「先王已薨，今王自來，破賊夾寨。賊已去矣，可開門！」嗣昭不信，曰：「此必為賊所得，使來誑我耳。」欲射之。左右止之，嗣昭曰：「王果來，可見乎？」王自往呼之。嗣昭見王白服，大慟幾絕，城中皆哭，遂開門。；核对说明：已对照所保存电子文本；尚待人工复核，不视为纸本校勘结论。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：五月，辛未朔，晉王伏兵三垂岡下，詰旦大霧，進兵直抵夾寨。梁軍無斥候，不意晉兵之至，將士尚未起，軍中驚擾。晉王命周德威、李嗣源分兵為二道，德威攻西北隅，嗣源攻東北隅，填塹燒寨，鼓噪而入。梁兵大潰，南走，招討使符道昭馬倒，為晉人所殺。失亡將校士卒以萬計，委棄資糧、器械山積。周德威等至城下，呼李嗣昭曰：「先王已薨，今王自來，破賊夾寨。賊已去矣，可開門！」嗣昭不信，曰：「此必為賊所得，使來誑我耳。」欲射之。左右止之，嗣昭曰：「王果來，可見乎？」王自往呼之。嗣昭見王白服，大慟幾絕，城中皆哭，遂開門。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 6e0d0af1-3455-5ea6-96db-8c60acc62235'; END IF; END $$;
UPDATE public.fact_claim SET note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"note": "原文：五月，辛未朔，晉王伏兵三垂岡下，詰旦大霧，進兵直抵夾寨。梁軍無斥候，不意晉兵之至，將士尚未起，軍中驚擾。晉王命周德威、李嗣源分兵為二道，德威攻西北隅，嗣源攻東北隅，填塹燒寨，鼓噪而入。梁兵大潰，南走，招討使符道昭馬倒，為晉人所殺。失亡將校士卒以萬計，委棄資糧、器械山積。周德威等至城下，呼李嗣昭曰：「先王已薨，今王自來，破賊夾寨。賊已去矣，可開門！」嗣昭不信，曰：「此必為賊所得，使來誑我耳。」欲射之。左右止之，嗣昭曰：「王果來，可見乎？」王自往呼之。嗣昭見王白服，大慟幾絕，城中皆哭，遂開門。；核对说明："}'::jsonb) v WHERE fact_claim.id='6e0d0af1-3455-5ea6-96db-8c60acc62235';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='6e201342-7256-5d93-8f91-8e1ca6cce745' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p037", "claim_text": "《资治通鉴》907年条所记人物。在“楚军击败刘存等淮南水军，攻取岳州”中为楚方统帅。本批仅整理相关史事，生卒与完整履历待补。", "note": "原文：弘农王以鄂岳观察使刘存为西南面都招讨使，岳州刺史陈知新为岳州团练使，庐州观察使刘威为应援使，别将许玄应为监军，将水军三万以击楚。楚王马殷甚惧，静江军使杨定真贺曰：“我军胜矣！”殷问其故，定真曰：“夫战惧则胜，骄则败。今淮南兵直趋吾城，是骄而轻敌也；而王有惧色，吾是以知其必胜也。”殷命在城都指挥使秦彦晖将水军三万浮江而下，水军副指挥使黄璠帅战舰三百屯浏阳口。六月，存等遇大雨，引兵还至越堤北，彦晖追之。存数战不利，乃遗殷书诈降。彦晖使谓殷曰：“此必诈也，勿受！”存与彦晖夹水而阵，存遥呼曰：“杀降不祥，公独不为子孙计耶！”彦晖曰：“贼入吾境而不击，奚顾子孙！”鼓噪而进。存等走，黄璠自浏阳引兵绝江，与彦晖合击，大破之，执存及知新，裨将死者百馀人，士卒死者以万数，获战舰八百艘。威以馀众遁归，彦晖遂拔岳州。殷释存、知新之缚，慰谕之。二人皆骂曰：“丈夫以死报主，肯事贼乎！”遂斩之。许玄应，弘农王之腹心也，常预政事，张颢、徐温因其败，收斩之。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第37段", "claim_text": "据《资治通鉴》，907年在“楚军击败刘存等淮南水军，攻取岳州”中为楚方统帅。", "note": "原文：弘农王以鄂岳观察使刘存为西南面都招讨使，岳州刺史陈知新为岳州团练使，庐州观察使刘威为应援使，别将许玄应为监军，将水军三万以击楚。楚王马殷甚惧，静江军使杨定真贺曰：“我军胜矣！”殷问其故，定真曰：“夫战惧则胜，骄则败。今淮南兵直趋吾城，是骄而轻敌也；而王有惧色，吾是以知其必胜也。”殷命在城都指挥使秦彦晖将水军三万浮江而下，水军副指挥使黄璠帅战舰三百屯浏阳口。六月，存等遇大雨，引兵还至越堤北，彦晖追之。存数战不利，乃遗殷书诈降。彦晖使谓殷曰：“此必诈也，勿受！”存与彦晖夹水而阵，存遥呼曰：“杀降不祥，公独不为子孙计耶！”彦晖曰：“贼入吾境而不击，奚顾子孙！”鼓噪而进。存等走，黄璠自浏阳引兵绝江，与彦晖合击，大破之，执存及知新，裨将死者百馀人，士卒死者以万数，获战舰八百艘。威以馀众遁归，彦晖遂拔岳州。殷释存、知新之缚，慰谕之。二人皆骂曰：“丈夫以死报主，肯事贼乎！”遂斩之。许玄应，弘农王之腹心也，常预政事，张颢、徐温因其败，收斩之。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 6e201342-7256-5d93-8f91-8e1ca6cce745'; END IF; END $$;
