DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='6e61ea75-1445-5529-b7b2-33d07f04ec02' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p014", "note": "原文：庚戌，梁王始御金祥殿，受百官称臣，下书称教令，自称曰寡人。辛亥，令诸笺、表、簿、籍皆去唐年号，但称月、日。丙辰，张文蔚等至大梁。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第14段", "note": "原文：庚戌，梁王始御金祥殿，受百官称臣，下书称教令，自称曰寡人。辛亥，令诸笺、表、簿、籍皆去唐年号，但称月、日。丙辰，张文蔚等至大梁。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 6e61ea75-1445-5529-b7b2-33d07f04ec02'; END IF; END $$;
