DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='701f04e4-72bd-561f-8341-123ff8ba566b' AND (to_jsonb(t) @> '{"note": "原文：旧五代史 \n75/1667 \n追谥昭懿皇后；皇考文明王上谥曰文\n穆皇帝，庙号烈祖，第四室，陵号咸\n宁，皇妣晋国太夫人王氏追谥文惠皇\n后。以宣武节度副使皇子友文为开封\n尹，判建昌院事。友文，本康氏子\n也，帝养以为子。   \n是月，制宫殿门及都门名额：正\n殿为崇元殿，东殿为元德殿，内殿为\n金祥殿，万岁堂为万岁殿，门如殿\n名。帝自谓以金德王，又以福建上献\n鹦鹉，诸州相继上白乌、白兔洎白莲\n之合蒂者，以为金行应运之兆，故名\n殿曰金祥。以大内正门为元化门，皇\n墙南门为建国门，滴漏门为启运门，\n下马门为升龙门，元德殿前门为崇明；核对说明：本项目核读电子文本；文字层不是原刻影印，未作纸本校勘。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：旧五代史 \n75/1667 \n追谥昭懿皇后；皇考文明王上谥曰文\n穆皇帝，庙号烈祖，第四室，陵号咸\n宁，皇妣晋国太夫人王氏追谥文惠皇\n后。以宣武节度副使皇子友文为开封\n尹，判建昌院事。友文，本康氏子\n也，帝养以为子。   \n是月，制宫殿门及都门名额：正\n殿为崇元殿，东殿为元德殿，内殿为\n金祥殿，万岁堂为万岁殿，门如殿\n名。帝自谓以金德王，又以福建上献\n鹦鹉，诸州相继上白乌、白兔洎白莲\n之合蒂者，以为金行应运之兆，故名\n殿曰金祥。以大内正门为元化门，皇\n墙南门为建国门，滴漏门为启运门，\n下马门为升龙门，元德殿前门为崇明；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 701f04e4-72bd-561f-8341-123ff8ba566b'; END IF; END $$;
UPDATE public.fact_claim SET note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"note": "原文：旧五代史 \n75/1667 \n追谥昭懿皇后；皇考文明王上谥曰文\n穆皇帝，庙号烈祖，第四室，陵号咸\n宁，皇妣晋国太夫人王氏追谥文惠皇\n后。以宣武节度副使皇子友文为开封\n尹，判建昌院事。友文，本康氏子\n也，帝养以为子。   \n是月，制宫殿门及都门名额：正\n殿为崇元殿，东殿为元德殿，内殿为\n金祥殿，万岁堂为万岁殿，门如殿\n名。帝自谓以金德王，又以福建上献\n鹦鹉，诸州相继上白乌、白兔洎白莲\n之合蒂者，以为金行应运之兆，故名\n殿曰金祥。以大内正门为元化门，皇\n墙南门为建国门，滴漏门为启运门，\n下马门为升龙门，元德殿前门为崇明；核对说明："}'::jsonb) v WHERE fact_claim.id='701f04e4-72bd-561f-8341-123ff8ba566b';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='70364d22-69b2-54e5-a613-f17a5779529e' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p035", "note": "原文：礼部尚书苏循及其子起居郎楷自谓有功于梁，当不次擢用；循朝夕望为相，帝薄其为人，敬翔及殿中监李振亦鄙之。翔言于帝曰：“苏循，唐之鸱枭，卖国求利，不可以立于惟新之朝。”戊戍，诏循及刑部尚书张祎等十五人并勒致仕，楷斥归田里。循父子乃之河中依硃友谦。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第35段", "note": "原文：礼部尚书苏循及其子起居郎楷自谓有功于梁，当不次擢用；循朝夕望为相，帝薄其为人，敬翔及殿中监李振亦鄙之。翔言于帝曰：“苏循，唐之鸱枭，卖国求利，不可以立于惟新之朝。”戊戍，诏循及刑部尚书张祎等十五人并勒致仕，楷斥归田里。循父子乃之河中依硃友谦。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 70364d22-69b2-54e5-a613-f17a5779529e'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第35段", "note": "原文：礼部尚书苏循及其子起居郎楷自谓有功于梁，当不次擢用；循朝夕望为相，帝薄其为人，敬翔及殿中监李振亦鄙之。翔言于帝曰：“苏循，唐之鸱枭，卖国求利，不可以立于惟新之朝。”戊戍，诏循及刑部尚书张祎等十五人并勒致仕，楷斥归田里。循父子乃之河中依硃友谦。；核对说明："}'::jsonb) v WHERE fact_claim.id='70364d22-69b2-54e5-a613-f17a5779529e';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='7056d1d8-fcda-59db-88e5-09dbeec9d76c' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p013", "note": "原文：仁恭有爱妾罗氏，其子守光通焉。仁恭杖守光而斥之，不以为子数。李思安引兵入其境，所过焚荡无馀。夏，四月，己酉，直抵幽州城下。仁恭犹在大安山。城中无备，几至不守。守光自外引兵入，登城拒守；又出兵与思安战，思安败退。守光遂自称节度使，命部将李小喜、元行钦将兵攻大安山。仁恭遣兵拒战，为小喜所败。虏仁恭以归，囚于别室。仁恭将佐及左右，凡守光素所恶者皆杀之。银胡录都指挥使王思同帅部兵三千，山后八安巡检使李承约帅部兵二千奔河东，守光弟守奇奔契丹，未几，亦奔河东，河东节度使晋王克用以承约为匡霸指挥使，思同为飞腾指挥使。思同母，仁恭之女也。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第13段", "note": "原文：仁恭有爱妾罗氏，其子守光通焉。仁恭杖守光而斥之，不以为子数。李思安引兵入其境，所过焚荡无馀。夏，四月，己酉，直抵幽州城下。仁恭犹在大安山。城中无备，几至不守。守光自外引兵入，登城拒守；又出兵与思安战，思安败退。守光遂自称节度使，命部将李小喜、元行钦将兵攻大安山。仁恭遣兵拒战，为小喜所败。虏仁恭以归，囚于别室。仁恭将佐及左右，凡守光素所恶者皆杀之。银胡录都指挥使王思同帅部兵三千，山后八安巡检使李承约帅部兵二千奔河东，守光弟守奇奔契丹，未几，亦奔河东，河东节度使晋王克用以承约为匡霸指挥使，思同为飞腾指挥使。思同母，仁恭之女也。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 7056d1d8-fcda-59db-88e5-09dbeec9d76c'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第13段", "note": "原文：仁恭有爱妾罗氏，其子守光通焉。仁恭杖守光而斥之，不以为子数。李思安引兵入其境，所过焚荡无馀。夏，四月，己酉，直抵幽州城下。仁恭犹在大安山。城中无备，几至不守。守光自外引兵入，登城拒守；又出兵与思安战，思安败退。守光遂自称节度使，命部将李小喜、元行钦将兵攻大安山。仁恭遣兵拒战，为小喜所败。虏仁恭以归，囚于别室。仁恭将佐及左右，凡守光素所恶者皆杀之。银胡录都指挥使王思同帅部兵三千，山后八安巡检使李承约帅部兵二千奔河东，守光弟守奇奔契丹，未几，亦奔河东，河东节度使晋王克用以承约为匡霸指挥使，思同为飞腾指挥使。思同母，仁恭之女也。；核对说明："}'::jsonb) v WHERE fact_claim.id='7056d1d8-fcda-59db-88e5-09dbeec9d76c';
