DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='72360c37-6b19-5178-89e0-d78bd610bae9' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p048", "claim_text": "《资治通鉴》907年条所记人物。在“周德威在高河击败秦武”中为梁方将领。本批仅整理相关史事，生卒与完整履历待补。", "note": "原文：晋周德威壁于高河，康怀贞遣亲骑都头秦武将兵击之，武败。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第48段", "claim_text": "据《资治通鉴》，907年在“周德威在高河击败秦武”中为梁方将领。", "note": "原文：晋周德威壁于高河，康怀贞遣亲骑都头秦武将兵击之，武败。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 72360c37-6b19-5178-89e0-d78bd610bae9'; END IF; END $$;
