DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='74058a2b-a0e1-5239-bcab-1ae96d70b581' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p013", "note": "原文：仁恭有爱妾罗氏，其子守光通焉。仁恭杖守光而斥之，不以为子数。李思安引兵入其境，所过焚荡无馀。夏，四月，己酉，直抵幽州城下。仁恭犹在大安山。城中无备，几至不守。守光自外引兵入，登城拒守；又出兵与思安战，思安败退。守光遂自称节度使，命部将李小喜、元行钦将兵攻大安山。仁恭遣兵拒战，为小喜所败。虏仁恭以归，囚于别室。仁恭将佐及左右，凡守光素所恶者皆杀之。银胡录都指挥使王思同帅部兵三千，山后八安巡检使李承约帅部兵二千奔河东，守光弟守奇奔契丹，未几，亦奔河东，河东节度使晋王克用以承约为匡霸指挥使，思同为飞腾指挥使。思同母，仁恭之女也。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第13段", "note": "原文：仁恭有爱妾罗氏，其子守光通焉。仁恭杖守光而斥之，不以为子数。李思安引兵入其境，所过焚荡无馀。夏，四月，己酉，直抵幽州城下。仁恭犹在大安山。城中无备，几至不守。守光自外引兵入，登城拒守；又出兵与思安战，思安败退。守光遂自称节度使，命部将李小喜、元行钦将兵攻大安山。仁恭遣兵拒战，为小喜所败。虏仁恭以归，囚于别室。仁恭将佐及左右，凡守光素所恶者皆杀之。银胡录都指挥使王思同帅部兵三千，山后八安巡检使李承约帅部兵二千奔河东，守光弟守奇奔契丹，未几，亦奔河东，河东节度使晋王克用以承约为匡霸指挥使，思同为飞腾指挥使。思同母，仁恭之女也。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 74058a2b-a0e1-5239-bcab-1ae96d70b581'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第13段", "note": "原文：仁恭有爱妾罗氏，其子守光通焉。仁恭杖守光而斥之，不以为子数。李思安引兵入其境，所过焚荡无馀。夏，四月，己酉，直抵幽州城下。仁恭犹在大安山。城中无备，几至不守。守光自外引兵入，登城拒守；又出兵与思安战，思安败退。守光遂自称节度使，命部将李小喜、元行钦将兵攻大安山。仁恭遣兵拒战，为小喜所败。虏仁恭以归，囚于别室。仁恭将佐及左右，凡守光素所恶者皆杀之。银胡录都指挥使王思同帅部兵三千，山后八安巡检使李承约帅部兵二千奔河东，守光弟守奇奔契丹，未几，亦奔河东，河东节度使晋王克用以承约为匡霸指挥使，思同为飞腾指挥使。思同母，仁恭之女也。；核对说明："}'::jsonb) v WHERE fact_claim.id='74058a2b-a0e1-5239-bcab-1ae96d70b581';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='74581319-52b1-5252-aec5-3e4ec952abee' AND (to_jsonb(t) @> '{"note": "原文：壬戌，至胡柳陂。癸亥旦，候者言梁兵自後至矣。周德威曰：「賊倍道而來，未有所捨，我營柵已固，守備有餘，既深入敵境，動須萬全，不可輕發。此去大梁至近，梁兵各念其家，內懷憤激，不以方略制之，恐難得志。王宜按兵勿戰，德威請以騎兵擾之，使彼不得休息，至暮營壘未立，樵爨未具，乘其疲乏，可一舉滅也。」王曰：「前在河上恨不見賊，今賊至不擊，尚復何待，公何怯也！」顧李存審曰：「敕輜重先發，吾為爾殿後，破賊而去！」即以親軍先出。德威不得已，引幽州兵從之，謂其子曰：「吾無死所矣。」賀瑰結陳而至，橫亙數十里。王帥銀槍都陷其陳，沖蕩擊斬，往返十餘里。行營左廂馬軍都指揮使、鄭州防禦使王彥章軍先敗，西走趣濮陽。晉輜重在陳西，望見梁旗幟，驚潰，入幽州陳，幽州兵亦擾亂，自相蹈藉；周德威不能制，父子皆戰死。；核对说明：已对照所保存电子文本；尚待人工复核，不视为纸本校勘结论。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：壬戌，至胡柳陂。癸亥旦，候者言梁兵自後至矣。周德威曰：「賊倍道而來，未有所捨，我營柵已固，守備有餘，既深入敵境，動須萬全，不可輕發。此去大梁至近，梁兵各念其家，內懷憤激，不以方略制之，恐難得志。王宜按兵勿戰，德威請以騎兵擾之，使彼不得休息，至暮營壘未立，樵爨未具，乘其疲乏，可一舉滅也。」王曰：「前在河上恨不見賊，今賊至不擊，尚復何待，公何怯也！」顧李存審曰：「敕輜重先發，吾為爾殿後，破賊而去！」即以親軍先出。德威不得已，引幽州兵從之，謂其子曰：「吾無死所矣。」賀瑰結陳而至，橫亙數十里。王帥銀槍都陷其陳，沖蕩擊斬，往返十餘里。行營左廂馬軍都指揮使、鄭州防禦使王彥章軍先敗，西走趣濮陽。晉輜重在陳西，望見梁旗幟，驚潰，入幽州陳，幽州兵亦擾亂，自相蹈藉；周德威不能制，父子皆戰死。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 74581319-52b1-5252-aec5-3e4ec952abee'; END IF; END $$;
UPDATE public.fact_claim SET note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"note": "原文：壬戌，至胡柳陂。癸亥旦，候者言梁兵自後至矣。周德威曰：「賊倍道而來，未有所捨，我營柵已固，守備有餘，既深入敵境，動須萬全，不可輕發。此去大梁至近，梁兵各念其家，內懷憤激，不以方略制之，恐難得志。王宜按兵勿戰，德威請以騎兵擾之，使彼不得休息，至暮營壘未立，樵爨未具，乘其疲乏，可一舉滅也。」王曰：「前在河上恨不見賊，今賊至不擊，尚復何待，公何怯也！」顧李存審曰：「敕輜重先發，吾為爾殿後，破賊而去！」即以親軍先出。德威不得已，引幽州兵從之，謂其子曰：「吾無死所矣。」賀瑰結陳而至，橫亙數十里。王帥銀槍都陷其陳，沖蕩擊斬，往返十餘里。行營左廂馬軍都指揮使、鄭州防禦使王彥章軍先敗，西走趣濮陽。晉輜重在陳西，望見梁旗幟，驚潰，入幽州陳，幽州兵亦擾亂，自相蹈藉；周德威不能制，父子皆戰死。；核对说明："}'::jsonb) v WHERE fact_claim.id='74581319-52b1-5252-aec5-3e4ec952abee';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='748f827a-4c7b-595d-9f68-49603bbfc88a' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p005", "note": "原文：初，梁王以河北诸镇皆服，唯幽、沧未下，故大举伐之，欲以坚诸镇之心，既而潞州内叛，王烧营而还，威望大沮。恐中外因此离心，欲速受禅以镇之。丁亥，王入馆于魏，有疾，卧府中，魏博节度使罗绍威恐王袭之，入见王曰：“今四方称兵为王患者，皆以翼戴唐室为名，王不如早灭唐以绝人望。”王虽不许而心德之，乃亟归。壬寅，至大梁。甲辰，唐昭宣帝遣御史大夫薛贻矩至大梁劳王，贻矩请以臣礼见，王揖之升阶，贻矩曰：“殿下功德在人，三灵改卜，皇帝方行舜、禹之事，臣安敢违！”乃北面拜舞于庭。王侧身避之。贻矩还，言于帝曰：“元帅有受禅之意矣！”帝乃下诏，以二月禅位于梁，又遣宰相以书谕王；王辞。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第5段", "note": "原文：初，梁王以河北诸镇皆服，唯幽、沧未下，故大举伐之，欲以坚诸镇之心，既而潞州内叛，王烧营而还，威望大沮。恐中外因此离心，欲速受禅以镇之。丁亥，王入馆于魏，有疾，卧府中，魏博节度使罗绍威恐王袭之，入见王曰：“今四方称兵为王患者，皆以翼戴唐室为名，王不如早灭唐以绝人望。”王虽不许而心德之，乃亟归。壬寅，至大梁。甲辰，唐昭宣帝遣御史大夫薛贻矩至大梁劳王，贻矩请以臣礼见，王揖之升阶，贻矩曰：“殿下功德在人，三灵改卜，皇帝方行舜、禹之事，臣安敢违！”乃北面拜舞于庭。王侧身避之。贻矩还，言于帝曰：“元帅有受禅之意矣！”帝乃下诏，以二月禅位于梁，又遣宰相以书谕王；王辞。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 748f827a-4c7b-595d-9f68-49603bbfc88a'; END IF; END $$;
