DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='76a53013-20fa-5337-9488-06700b5f8300' AND (to_jsonb(t) @> '{"note": "原文：旧五代史 \n83/1667 \n树，并图形以献。是月，隰州奏，大\n宁县至固镇上下二百里，今月八日，\n黄河清，至十月如故。   \n九月辛丑，西京大内放出两宫内\n人及前朝宫人，任其所适。敕以近年\n文武官诸道奉使，皆于所在分外停\n住，逾年涉岁，未闻归阙。非惟劳费\n州郡，抑且侮慢国经。臣节既亏，宪\n章安在。自今后两浙、福建、广州、\n安南、邕、容等道使到发许住一月；\n湖南、洪、鄂、黔、桂许住二十日；\n荆、襄、同、雍、镇、定、青、沧许\n住十日；其余侧近不过三五日。凡往\n来道路，据远近里数，日行两驿。如\n遇疾患及江河阻隔，委所在长吏具事；核对说明：本项目核读电子文本；文字层不是原刻影印，未作纸本校勘。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：旧五代史 \n83/1667 \n树，并图形以献。是月，隰州奏，大\n宁县至固镇上下二百里，今月八日，\n黄河清，至十月如故。   \n九月辛丑，西京大内放出两宫内\n人及前朝宫人，任其所适。敕以近年\n文武官诸道奉使，皆于所在分外停\n住，逾年涉岁，未闻归阙。非惟劳费\n州郡，抑且侮慢国经。臣节既亏，宪\n章安在。自今后两浙、福建、广州、\n安南、邕、容等道使到发许住一月；\n湖南、洪、鄂、黔、桂许住二十日；\n荆、襄、同、雍、镇、定、青、沧许\n住十日；其余侧近不过三五日。凡往\n来道路，据远近里数，日行两驿。如\n遇疾患及江河阻隔，委所在长吏具事；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 76a53013-20fa-5337-9488-06700b5f8300'; END IF; END $$;
