DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='780d1d85-d6a8-56eb-927a-cf8fad41d44b' AND (to_jsonb(t) @> '{"note": "原文：庚寅旦，袁象先等帥禁兵數千人突入宮中。友珪聞變，與妻張氏及馮廷諤趨北垣樓下，將逾城，自度不免，令廷諤先殺妻，次殺己，廷諤亦自剄。諸軍十餘萬大掠都市，百司逃散，中書侍郎、同平章事杜曉、侍講學士李珽皆為亂兵所殺，門下侍郎、同平章事於兢、宣政使李振被傷。至晡乃定。\n像先、巖繼傳國寶詣大梁迎均王，王曰：「大梁國家創業之地，何必洛陽！」乃即帝位於大梁，復稱乾化三年，追廢友珪為庶人，復博王友文官爵。；核对说明：已对照所保存电子文本；尚待人工复核，不视为纸本校勘结论。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：庚寅旦，袁象先等帥禁兵數千人突入宮中。友珪聞變，與妻張氏及馮廷諤趨北垣樓下，將逾城，自度不免，令廷諤先殺妻，次殺己，廷諤亦自剄。諸軍十餘萬大掠都市，百司逃散，中書侍郎、同平章事杜曉、侍講學士李珽皆為亂兵所殺，門下侍郎、同平章事於兢、宣政使李振被傷。至晡乃定。\n像先、巖繼傳國寶詣大梁迎均王，王曰：「大梁國家創業之地，何必洛陽！」乃即帝位於大梁，復稱乾化三年，追廢友珪為庶人，復博王友文官爵。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 780d1d85-d6a8-56eb-927a-cf8fad41d44b'; END IF; END $$;
UPDATE public.fact_claim SET note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"note": "原文：庚寅旦，袁象先等帥禁兵數千人突入宮中。友珪聞變，與妻張氏及馮廷諤趨北垣樓下，將逾城，自度不免，令廷諤先殺妻，次殺己，廷諤亦自剄。諸軍十餘萬大掠都市，百司逃散，中書侍郎、同平章事杜曉、侍講學士李珽皆為亂兵所殺，門下侍郎、同平章事於兢、宣政使李振被傷。至晡乃定。\n像先、巖繼傳國寶詣大梁迎均王，王曰：「大梁國家創業之地，何必洛陽！」乃即帝位於大梁，復稱乾化三年，追廢友珪為庶人，復博王友文官爵。；核对说明："}'::jsonb) v WHERE fact_claim.id='780d1d85-d6a8-56eb-927a-cf8fad41d44b';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='784ed495-08d5-563d-87ba-5d0572bc1188' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p024", "claim_text": "《资治通鉴》907年条所记人物。在“岐王在唐亡后开府置百官”中为开府者。本批仅整理相关史事，生卒与完整履历待补。", "note": "原文：岐王治军甚宽，待士卒简易。有告部将苻昭反者，岐王直诣其家，悉去左右，熟寝经宿而还；由是众心悦服。然御军无纪律。及闻唐亡，以兵羸地蹙，不敢称帝，但开岐王府，置百官，名其所居为宫殿，妻称皇后，将吏上书称笺表，鞭、扇、号令多拟帝者。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第24段", "claim_text": "据《资治通鉴》，907年在“岐王在唐亡后开府置百官”中为开府者。", "note": "原文：岐王治军甚宽，待士卒简易。有告部将苻昭反者，岐王直诣其家，悉去左右，熟寝经宿而还；由是众心悦服。然御军无纪律。及闻唐亡，以兵羸地蹙，不敢称帝，但开岐王府，置百官，名其所居为宫殿，妻称皇后，将吏上书称笺表，鞭、扇、号令多拟帝者。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 784ed495-08d5-563d-87ba-5d0572bc1188'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,claim_text=v.claim_text,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第24段", "claim_text": "据《资治通鉴》，907年在“岐王在唐亡后开府置百官”中为开府者。", "note": "原文：岐王治军甚宽，待士卒简易。有告部将苻昭反者，岐王直诣其家，悉去左右，熟寝经宿而还；由是众心悦服。然御军无纪律。及闻唐亡，以兵羸地蹙，不敢称帝，但开岐王府，置百官，名其所居为宫殿，妻称皇后，将吏上书称笺表，鞭、扇、号令多拟帝者。；核对说明："}'::jsonb) v WHERE fact_claim.id='784ed495-08d5-563d-87ba-5d0572bc1188';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='792316a7-3864-57cf-92de-8fa36eacd6b2' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p052", "note": "原文：冬，十月，高季昌遣其将倪可福会楚将秦彦晖攻朗州，雷彦恭遣使乞降于淮南，且告急。弘农王遣将泠业将水军屯平江，李饶将步骑屯浏阳以救之，楚王殷遣岳州刺史许德勋将兵拒之。泠业进屯朗口，德勋使善游者五十人，以木枝叶覆其首，持长刀浮江而下，夜犯其营，且举火，业军中惊扰。德以大军进击，大破之，追至鹿角镇，擒业；又破浏阳寨，擒李饶；掠上高、唐年而归。斩业、饶于长沙市。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第52段", "note": "原文：冬，十月，高季昌遣其将倪可福会楚将秦彦晖攻朗州，雷彦恭遣使乞降于淮南，且告急。弘农王遣将泠业将水军屯平江，李饶将步骑屯浏阳以救之，楚王殷遣岳州刺史许德勋将兵拒之。泠业进屯朗口，德勋使善游者五十人，以木枝叶覆其首，持长刀浮江而下，夜犯其营，且举火，业军中惊扰。德以大军进击，大破之，追至鹿角镇，擒业；又破浏阳寨，擒李饶；掠上高、唐年而归。斩业、饶于长沙市。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 792316a7-3864-57cf-92de-8fa36eacd6b2'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第52段", "note": "原文：冬，十月，高季昌遣其将倪可福会楚将秦彦晖攻朗州，雷彦恭遣使乞降于淮南，且告急。弘农王遣将泠业将水军屯平江，李饶将步骑屯浏阳以救之，楚王殷遣岳州刺史许德勋将兵拒之。泠业进屯朗口，德勋使善游者五十人，以木枝叶覆其首，持长刀浮江而下，夜犯其营，且举火，业军中惊扰。德以大军进击，大破之，追至鹿角镇，擒业；又破浏阳寨，擒李饶；掠上高、唐年而归。斩业、饶于长沙市。；核对说明："}'::jsonb) v WHERE fact_claim.id='792316a7-3864-57cf-92de-8fa36eacd6b2';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='7935ad4e-4227-5d6a-8a9f-24db4a5ae54a' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p004", "note": "原文：渥居丧，昼夜酣饮作乐，然十围之烛以击球，一烛费钱数万。或单骑出游，从者奔走道路，不知所之。左、右牙指挥使张颢、徐温泣谏，渥怒曰：“汝谓我不才，何不杀我自为之！”二人惧。渥选壮士，号“东院马军”，广署亲信为将吏；所署者恃势骄横，陵蔑勋旧。颢、温潜谋作乱。渥父行密之世，有亲军数千，营于牙城之内，渥迁出于外，以其地为射场，颢、温由是无所惮。渥之镇宣州也，命指挥使硃思勍、范思从、陈璠将亲兵三千；及嗣位，召归广陵。颢、温使三将从秦裴击江西，因戍洪州，诬以谋叛，命别将陈祐往诛之。祐间道兼行，六日至洪州，微服怀短兵径入秦裴帐中，裴大惊，祐告之故，乃召思勍等饮酒，祐数思勍等罪，执而斩之。渥闻三将死，益忌颢、温，欲诛之。丙戍，渥晨视事，颢、温帅牙兵二百，露刃直入庭中，渥曰：“尔思欲杀我邪？”对曰，“非敢然也，欲诛王左右乱政者耳！”因数渥所亲信十馀人之罪，曳下，以铁楇击杀之，谓之“兵谏”。诸将不与之同者，颢、温稍以法诛之，于是军政悉归二人，渥不能制。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第4段", "note": "原文：渥居丧，昼夜酣饮作乐，然十围之烛以击球，一烛费钱数万。或单骑出游，从者奔走道路，不知所之。左、右牙指挥使张颢、徐温泣谏，渥怒曰：“汝谓我不才，何不杀我自为之！”二人惧。渥选壮士，号“东院马军”，广署亲信为将吏；所署者恃势骄横，陵蔑勋旧。颢、温潜谋作乱。渥父行密之世，有亲军数千，营于牙城之内，渥迁出于外，以其地为射场，颢、温由是无所惮。渥之镇宣州也，命指挥使硃思勍、范思从、陈璠将亲兵三千；及嗣位，召归广陵。颢、温使三将从秦裴击江西，因戍洪州，诬以谋叛，命别将陈祐往诛之。祐间道兼行，六日至洪州，微服怀短兵径入秦裴帐中，裴大惊，祐告之故，乃召思勍等饮酒，祐数思勍等罪，执而斩之。渥闻三将死，益忌颢、温，欲诛之。丙戍，渥晨视事，颢、温帅牙兵二百，露刃直入庭中，渥曰：“尔思欲杀我邪？”对曰，“非敢然也，欲诛王左右乱政者耳！”因数渥所亲信十馀人之罪，曳下，以铁楇击杀之，谓之“兵谏”。诸将不与之同者，颢、温稍以法诛之，于是军政悉归二人，渥不能制。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 7935ad4e-4227-5d6a-8a9f-24db4a5ae54a'; END IF; END $$;
