DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='7c3a567b-1c2c-54c7-a068-3002e08c3875' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p025", "note": "原文：镇海节度判官罗隐说吴王镠兴兵讨梁，曰：“纵无成功，犹可退保杭、越，自为东帝；奈何交臂事贼，为终古之羞乎！”镠始以隐为不遇于唐，必有怨心，及闻其言，虽不能用，心甚义之。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第25段", "note": "原文：镇海节度判官罗隐说吴王镠兴兵讨梁，曰：“纵无成功，犹可退保杭、越，自为东帝；奈何交臂事贼，为终古之羞乎！”镠始以隐为不遇于唐，必有怨心，及闻其言，虽不能用，心甚义之。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 7c3a567b-1c2c-54c7-a068-3002e08c3875'; END IF; END $$;
