DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='7c951bcd-8836-5503-b22a-497be5be2683' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p015", "note": "原文：卢佶闻钱传镣等将至，将水军拒之于青澳。钱传瓘曰：“佶之精兵尽在于此，不可与战。”乃自安固舍舟，间道袭温州。戊午，温州溃，擒佶斩之。吴王镠以都监使吴璋为温州制置使，命传瓘等移兵讨卢约于处州。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第15段", "note": "原文：卢佶闻钱传镣等将至，将水军拒之于青澳。钱传瓘曰：“佶之精兵尽在于此，不可与战。”乃自安固舍舟，间道袭温州。戊午，温州溃，擒佶斩之。吴王镠以都监使吴璋为温州制置使，命传瓘等移兵讨卢约于处州。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 7c951bcd-8836-5503-b22a-497be5be2683'; END IF; END $$;
