DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='7cdf4711-634b-5795-96d8-06845f7c2d69' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p022", "note": "原文：乙亥，下制削夺李克用官爵。是时，惟河东、凤翔、淮南称“天祐”，西川称“天复”年号。馀皆禀梁正朔，称臣奉贡。蜀王与弘农王移檄诸道，云欲与岐王、晋王会兵兴复唐室，卒无应者。蜀王乃谋称帝，下教谕统内吏民；又遗晋王书云：“请各帝一方，俟硃温既平，乃访唐宗室立之，退归籓服。”晋王复书不许，曰：“誓于此生靡敢失节。”；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第22段", "note": "原文：乙亥，下制削夺李克用官爵。是时，惟河东、凤翔、淮南称“天祐”，西川称“天复”年号。馀皆禀梁正朔，称臣奉贡。蜀王与弘农王移檄诸道，云欲与岐王、晋王会兵兴复唐室，卒无应者。蜀王乃谋称帝，下教谕统内吏民；又遗晋王书云：“请各帝一方，俟硃温既平，乃访唐宗室立之，退归籓服。”晋王复书不许，曰：“誓于此生靡敢失节。”；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 7cdf4711-634b-5795-96d8-06845f7c2d69'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第22段", "note": "原文：乙亥，下制削夺李克用官爵。是时，惟河东、凤翔、淮南称“天祐”，西川称“天复”年号。馀皆禀梁正朔，称臣奉贡。蜀王与弘农王移檄诸道，云欲与岐王、晋王会兵兴复唐室，卒无应者。蜀王乃谋称帝，下教谕统内吏民；又遗晋王书云：“请各帝一方，俟硃温既平，乃访唐宗室立之，退归籓服。”晋王复书不许，曰：“誓于此生靡敢失节。”；核对说明："}'::jsonb) v WHERE fact_claim.id='7cdf4711-634b-5795-96d8-06845f7c2d69';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='7d21f121-4e5b-53b4-8e48-fd1e6187331f' AND (to_jsonb(t) @> '{"note": "原文：壬寅，遣嗣源將所部精兵五千自德勝趣鄆州。比及楊劉，日已暮，陰雨道黑，將士皆不欲進，高行周曰：「此天讚我也，彼必無備。」夜，渡河至城下，鄆人不知，李從珂先登，殺守卒，啟關納外兵，進攻牙城，城中大擾。癸卯旦，嗣源兵盡入，遂拔牙城，劉遂嚴、燕顒奔大梁。嗣源禁焚掠，撫吏民，執知州事節度副使崔簹、判官趙鳳送興唐。帝大喜曰：「總管真奇才，吾事集矣。」即以嗣源為天平節度使。；核对说明：已对照所保存电子文本；尚待人工复核，不视为纸本校勘结论。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：壬寅，遣嗣源將所部精兵五千自德勝趣鄆州。比及楊劉，日已暮，陰雨道黑，將士皆不欲進，高行周曰：「此天讚我也，彼必無備。」夜，渡河至城下，鄆人不知，李從珂先登，殺守卒，啟關納外兵，進攻牙城，城中大擾。癸卯旦，嗣源兵盡入，遂拔牙城，劉遂嚴、燕顒奔大梁。嗣源禁焚掠，撫吏民，執知州事節度副使崔簹、判官趙鳳送興唐。帝大喜曰：「總管真奇才，吾事集矣。」即以嗣源為天平節度使。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 7d21f121-4e5b-53b4-8e48-fd1e6187331f'; END IF; END $$;
UPDATE public.fact_claim SET note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"note": "原文：壬寅，遣嗣源將所部精兵五千自德勝趣鄆州。比及楊劉，日已暮，陰雨道黑，將士皆不欲進，高行周曰：「此天讚我也，彼必無備。」夜，渡河至城下，鄆人不知，李從珂先登，殺守卒，啟關納外兵，進攻牙城，城中大擾。癸卯旦，嗣源兵盡入，遂拔牙城，劉遂嚴、燕顒奔大梁。嗣源禁焚掠，撫吏民，執知州事節度副使崔簹、判官趙鳳送興唐。帝大喜曰：「總管真奇才，吾事集矣。」即以嗣源為天平節度使。；核对说明："}'::jsonb) v WHERE fact_claim.id='7d21f121-4e5b-53b4-8e48-fd1e6187331f';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='7d3d6cb3-ffbc-56e0-a707-92d60c0fa195' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p005", "claim_text": "《资治通鉴》907年条所记人物。在“罗绍威劝梁王灭唐，薛贻矩往返传达禅位意向”中为遣使者。本批仅整理相关史事，生卒与完整履历待补。", "note": "原文：初，梁王以河北诸镇皆服，唯幽、沧未下，故大举伐之，欲以坚诸镇之心，既而潞州内叛，王烧营而还，威望大沮。恐中外因此离心，欲速受禅以镇之。丁亥，王入馆于魏，有疾，卧府中，魏博节度使罗绍威恐王袭之，入见王曰：“今四方称兵为王患者，皆以翼戴唐室为名，王不如早灭唐以绝人望。”王虽不许而心德之，乃亟归。壬寅，至大梁。甲辰，唐昭宣帝遣御史大夫薛贻矩至大梁劳王，贻矩请以臣礼见，王揖之升阶，贻矩曰：“殿下功德在人，三灵改卜，皇帝方行舜、禹之事，臣安敢违！”乃北面拜舞于庭。王侧身避之。贻矩还，言于帝曰：“元帅有受禅之意矣！”帝乃下诏，以二月禅位于梁，又遣宰相以书谕王；王辞。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第5段", "claim_text": "据《资治通鉴》，907年在“罗绍威劝梁王灭唐，薛贻矩往返传达禅位意向”中为遣使者。", "note": "原文：初，梁王以河北诸镇皆服，唯幽、沧未下，故大举伐之，欲以坚诸镇之心，既而潞州内叛，王烧营而还，威望大沮。恐中外因此离心，欲速受禅以镇之。丁亥，王入馆于魏，有疾，卧府中，魏博节度使罗绍威恐王袭之，入见王曰：“今四方称兵为王患者，皆以翼戴唐室为名，王不如早灭唐以绝人望。”王虽不许而心德之，乃亟归。壬寅，至大梁。甲辰，唐昭宣帝遣御史大夫薛贻矩至大梁劳王，贻矩请以臣礼见，王揖之升阶，贻矩曰：“殿下功德在人，三灵改卜，皇帝方行舜、禹之事，臣安敢违！”乃北面拜舞于庭。王侧身避之。贻矩还，言于帝曰：“元帅有受禅之意矣！”帝乃下诏，以二月禅位于梁，又遣宰相以书谕王；王辞。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 7d3d6cb3-ffbc-56e0-a707-92d60c0fa195'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,claim_text=v.claim_text,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第5段", "claim_text": "据《资治通鉴》，907年在“罗绍威劝梁王灭唐，薛贻矩往返传达禅位意向”中为遣使者。", "note": "原文：初，梁王以河北诸镇皆服，唯幽、沧未下，故大举伐之，欲以坚诸镇之心，既而潞州内叛，王烧营而还，威望大沮。恐中外因此离心，欲速受禅以镇之。丁亥，王入馆于魏，有疾，卧府中，魏博节度使罗绍威恐王袭之，入见王曰：“今四方称兵为王患者，皆以翼戴唐室为名，王不如早灭唐以绝人望。”王虽不许而心德之，乃亟归。壬寅，至大梁。甲辰，唐昭宣帝遣御史大夫薛贻矩至大梁劳王，贻矩请以臣礼见，王揖之升阶，贻矩曰：“殿下功德在人，三灵改卜，皇帝方行舜、禹之事，臣安敢违！”乃北面拜舞于庭。王侧身避之。贻矩还，言于帝曰：“元帅有受禅之意矣！”帝乃下诏，以二月禅位于梁，又遣宰相以书谕王；王辞。；核对说明："}'::jsonb) v WHERE fact_claim.id='7d3d6cb3-ffbc-56e0-a707-92d60c0fa195';
