UPDATE public.fact_claim SET citation=v.citation,claim_text=v.claim_text,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第31段", "claim_text": "据《资治通鉴》，907年在“后梁封朱全昱及诸子为王”中为受封者。", "note": "原文：乙酉，立皇兄全昱为广王，子友文为博王，友珪为郢王，友璋为福王，友贞为均王，友雍为贺王，友徽为建王。；核对说明："}'::jsonb) v WHERE fact_claim.id='7f22906e-6bbc-5fab-b325-0eb8bdc21bce';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='7f22be08-4a09-512a-9338-d435300d3610' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p013", "note": "原文：仁恭有爱妾罗氏，其子守光通焉。仁恭杖守光而斥之，不以为子数。李思安引兵入其境，所过焚荡无馀。夏，四月，己酉，直抵幽州城下。仁恭犹在大安山。城中无备，几至不守。守光自外引兵入，登城拒守；又出兵与思安战，思安败退。守光遂自称节度使，命部将李小喜、元行钦将兵攻大安山。仁恭遣兵拒战，为小喜所败。虏仁恭以归，囚于别室。仁恭将佐及左右，凡守光素所恶者皆杀之。银胡录都指挥使王思同帅部兵三千，山后八安巡检使李承约帅部兵二千奔河东，守光弟守奇奔契丹，未几，亦奔河东，河东节度使晋王克用以承约为匡霸指挥使，思同为飞腾指挥使。思同母，仁恭之女也。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第13段", "note": "原文：仁恭有爱妾罗氏，其子守光通焉。仁恭杖守光而斥之，不以为子数。李思安引兵入其境，所过焚荡无馀。夏，四月，己酉，直抵幽州城下。仁恭犹在大安山。城中无备，几至不守。守光自外引兵入，登城拒守；又出兵与思安战，思安败退。守光遂自称节度使，命部将李小喜、元行钦将兵攻大安山。仁恭遣兵拒战，为小喜所败。虏仁恭以归，囚于别室。仁恭将佐及左右，凡守光素所恶者皆杀之。银胡录都指挥使王思同帅部兵三千，山后八安巡检使李承约帅部兵二千奔河东，守光弟守奇奔契丹，未几，亦奔河东，河东节度使晋王克用以承约为匡霸指挥使，思同为飞腾指挥使。思同母，仁恭之女也。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 7f22be08-4a09-512a-9338-d435300d3610'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第13段", "note": "原文：仁恭有爱妾罗氏，其子守光通焉。仁恭杖守光而斥之，不以为子数。李思安引兵入其境，所过焚荡无馀。夏，四月，己酉，直抵幽州城下。仁恭犹在大安山。城中无备，几至不守。守光自外引兵入，登城拒守；又出兵与思安战，思安败退。守光遂自称节度使，命部将李小喜、元行钦将兵攻大安山。仁恭遣兵拒战，为小喜所败。虏仁恭以归，囚于别室。仁恭将佐及左右，凡守光素所恶者皆杀之。银胡录都指挥使王思同帅部兵三千，山后八安巡检使李承约帅部兵二千奔河东，守光弟守奇奔契丹，未几，亦奔河东，河东节度使晋王克用以承约为匡霸指挥使，思同为飞腾指挥使。思同母，仁恭之女也。；核对说明："}'::jsonb) v WHERE fact_claim.id='7f22be08-4a09-512a-9338-d435300d3610';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='7f31aefa-ac7d-588d-9f11-ee626eb5ba64' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p028", "note": "原文：契丹遣其臣袍笏梅老来通好，帝遣太府少卿高颀报之。初，契丹有八部，部各有大人，相与约，推一人为王，建旗鼓以号令诸部，每三年则以次相代。咸通末，有习尔者为王，土宇始大。其后钦德为王，乘中原多故，时入盗边。及阿保机为王，尤雄勇，五姓奚及七姓室韦、达靼咸役属之。阿保机姓邪律氏，恃其强，不肯受代。久之，阿保机击黄头室韦还，七部劫之于境上，求如约。阿保机不得已，传旗鼓，且曰：“我为王九年，得汉人多，请帅种落居古汉城，与汉人守之，别自为一部。”七部许之。汉城者，故后魏滑盐县也。地宜五谷，有盐池之利。其后阿保机稍以兵击灭七部，复并为一国。又北侵室韦、女真，西取突阙故地，击奚，灭之，复立奚王而使契丹监其兵，东北诸夷皆畏服之。是岁，阿保机帅众三十万寇云州，晋王与之连和，面会东城，约为兄弟，延之帐中，纵酒，握手尽欢，约以今冬共击梁。或劝晋王：“因其来，可擒也，”王曰：“仇敌未灭而失信夷狄，自亡之道也。”阿保机留旬日乃去，晋王赠以金缯数万。阿保机留马三千匹，杂畜万计以酬之。阿保机既归而背盟，更附于梁，晋王由是而恨之。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第28段", "note": "原文：契丹遣其臣袍笏梅老来通好，帝遣太府少卿高颀报之。初，契丹有八部，部各有大人，相与约，推一人为王，建旗鼓以号令诸部，每三年则以次相代。咸通末，有习尔者为王，土宇始大。其后钦德为王，乘中原多故，时入盗边。及阿保机为王，尤雄勇，五姓奚及七姓室韦、达靼咸役属之。阿保机姓邪律氏，恃其强，不肯受代。久之，阿保机击黄头室韦还，七部劫之于境上，求如约。阿保机不得已，传旗鼓，且曰：“我为王九年，得汉人多，请帅种落居古汉城，与汉人守之，别自为一部。”七部许之。汉城者，故后魏滑盐县也。地宜五谷，有盐池之利。其后阿保机稍以兵击灭七部，复并为一国。又北侵室韦、女真，西取突阙故地，击奚，灭之，复立奚王而使契丹监其兵，东北诸夷皆畏服之。是岁，阿保机帅众三十万寇云州，晋王与之连和，面会东城，约为兄弟，延之帐中，纵酒，握手尽欢，约以今冬共击梁。或劝晋王：“因其来，可擒也，”王曰：“仇敌未灭而失信夷狄，自亡之道也。”阿保机留旬日乃去，晋王赠以金缯数万。阿保机留马三千匹，杂畜万计以酬之。阿保机既归而背盟，更附于梁，晋王由是而恨之。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 7f31aefa-ac7d-588d-9f11-ee626eb5ba64'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第28段", "note": "原文：契丹遣其臣袍笏梅老来通好，帝遣太府少卿高颀报之。初，契丹有八部，部各有大人，相与约，推一人为王，建旗鼓以号令诸部，每三年则以次相代。咸通末，有习尔者为王，土宇始大。其后钦德为王，乘中原多故，时入盗边。及阿保机为王，尤雄勇，五姓奚及七姓室韦、达靼咸役属之。阿保机姓邪律氏，恃其强，不肯受代。久之，阿保机击黄头室韦还，七部劫之于境上，求如约。阿保机不得已，传旗鼓，且曰：“我为王九年，得汉人多，请帅种落居古汉城，与汉人守之，别自为一部。”七部许之。汉城者，故后魏滑盐县也。地宜五谷，有盐池之利。其后阿保机稍以兵击灭七部，复并为一国。又北侵室韦、女真，西取突阙故地，击奚，灭之，复立奚王而使契丹监其兵，东北诸夷皆畏服之。是岁，阿保机帅众三十万寇云州，晋王与之连和，面会东城，约为兄弟，延之帐中，纵酒，握手尽欢，约以今冬共击梁。或劝晋王：“因其来，可擒也，”王曰：“仇敌未灭而失信夷狄，自亡之道也。”阿保机留旬日乃去，晋王赠以金缯数万。阿保机留马三千匹，杂畜万计以酬之。阿保机既归而背盟，更附于梁，晋王由是而恨之。；核对说明："}'::jsonb) v WHERE fact_claim.id='7f31aefa-ac7d-588d-9f11-ee626eb5ba64';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='7f9f22b3-a552-5f58-b8fe-a384c55afb30' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p049", "note": "原文：丁已，帝以亳州刺史李思安代怀贞为潞州行营都统，黜怀贞为行营都虞候。思安将河北兵西上，至潞州城下，更筑重城，内以防奔突，外以拒援兵，谓之夹寨。调山东民馈军粮，德威日以轻骑抄之，思安乃自东南山口筑甬道，属于夹寨。德威与诸将互往攻之，排墙填堑，一昼夜间数十发，梁兵疲于奔命。夹寨中出刍牧者，德威辄抄之，于是梁兵闭壁不出。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第49段", "note": "原文：丁已，帝以亳州刺史李思安代怀贞为潞州行营都统，黜怀贞为行营都虞候。思安将河北兵西上，至潞州城下，更筑重城，内以防奔突，外以拒援兵，谓之夹寨。调山东民馈军粮，德威日以轻骑抄之，思安乃自东南山口筑甬道，属于夹寨。德威与诸将互往攻之，排墙填堑，一昼夜间数十发，梁兵疲于奔命。夹寨中出刍牧者，德威辄抄之，于是梁兵闭壁不出。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 7f9f22b3-a552-5f58-b8fe-a384c55afb30'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第49段", "note": "原文：丁已，帝以亳州刺史李思安代怀贞为潞州行营都统，黜怀贞为行营都虞候。思安将河北兵西上，至潞州城下，更筑重城，内以防奔突，外以拒援兵，谓之夹寨。调山东民馈军粮，德威日以轻骑抄之，思安乃自东南山口筑甬道，属于夹寨。德威与诸将互往攻之，排墙填堑，一昼夜间数十发，梁兵疲于奔命。夹寨中出刍牧者，德威辄抄之，于是梁兵闭壁不出。；核对说明："}'::jsonb) v WHERE fact_claim.id='7f9f22b3-a552-5f58-b8fe-a384c55afb30';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='806c6609-e023-5ea4-ba50-14dd9ea8117d' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p052", "claim_text": "《资治通鉴》907年条所记人物。在“荆南、楚军攻朗州，许德勋击败淮南援军”中为淮南援将。本批仅整理相关史事，生卒与完整履历待补。", "note": "原文：冬，十月，高季昌遣其将倪可福会楚将秦彦晖攻朗州，雷彦恭遣使乞降于淮南，且告急。弘农王遣将泠业将水军屯平江，李饶将步骑屯浏阳以救之，楚王殷遣岳州刺史许德勋将兵拒之。泠业进屯朗口，德勋使善游者五十人，以木枝叶覆其首，持长刀浮江而下，夜犯其营，且举火，业军中惊扰。德以大军进击，大破之，追至鹿角镇，擒业；又破浏阳寨，擒李饶；掠上高、唐年而归。斩业、饶于长沙市。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第52段", "claim_text": "据《资治通鉴》，907年在“荆南、楚军攻朗州，许德勋击败淮南援军”中为淮南援将。", "note": "原文：冬，十月，高季昌遣其将倪可福会楚将秦彦晖攻朗州，雷彦恭遣使乞降于淮南，且告急。弘农王遣将泠业将水军屯平江，李饶将步骑屯浏阳以救之，楚王殷遣岳州刺史许德勋将兵拒之。泠业进屯朗口，德勋使善游者五十人，以木枝叶覆其首，持长刀浮江而下，夜犯其营，且举火，业军中惊扰。德以大军进击，大破之，追至鹿角镇，擒业；又破浏阳寨，擒李饶；掠上高、唐年而归。斩业、饶于长沙市。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 806c6609-e023-5ea4-ba50-14dd9ea8117d'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,claim_text=v.claim_text,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第52段", "claim_text": "据《资治通鉴》，907年在“荆南、楚军攻朗州，许德勋击败淮南援军”中为淮南援将。", "note": "原文：冬，十月，高季昌遣其将倪可福会楚将秦彦晖攻朗州，雷彦恭遣使乞降于淮南，且告急。弘农王遣将泠业将水军屯平江，李饶将步骑屯浏阳以救之，楚王殷遣岳州刺史许德勋将兵拒之。泠业进屯朗口，德勋使善游者五十人，以木枝叶覆其首，持长刀浮江而下，夜犯其营，且举火，业军中惊扰。德以大军进击，大破之，追至鹿角镇，擒业；又破浏阳寨，擒李饶；掠上高、唐年而归。斩业、饶于长沙市。；核对说明："}'::jsonb) v WHERE fact_claim.id='806c6609-e023-5ea4-ba50-14dd9ea8117d';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='81481efb-75a9-57ff-98e9-98e112cfa540' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p011", "claim_text": "《资治通鉴》907年条所记人物。在“唐廷与各镇相继向梁王劝进”中为册礼使。本批仅整理相关史事，生卒与完整履历待补。", "note": "原文：甲辰，唐昭宣帝降御札禅位于梁。以摄中书令张文蔚为册礼使，礼部尚书苏循副之；摄侍中杨涉为押传国宝使，翰林学士张策副之；御史大夫薛贻矩为押金宝使，尚书左丞赵光逢副之；帅百官备法驾诣大梁。杨涉子直史馆凝式言于涉曰：“大人为唐宰相，而国家至此，不可谓之无过。况手持天子玺绶与人，虽保富贵，奈千载何！盍辞之！”涉大骇曰：“汝灭吾族！”神色为之不宁者数日。策，敦煌人。光逢，隐之子也。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第11段", "claim_text": "据《资治通鉴》，907年在“唐廷与各镇相继向梁王劝进”中为册礼使。", "note": "原文：甲辰，唐昭宣帝降御札禅位于梁。以摄中书令张文蔚为册礼使，礼部尚书苏循副之；摄侍中杨涉为押传国宝使，翰林学士张策副之；御史大夫薛贻矩为押金宝使，尚书左丞赵光逢副之；帅百官备法驾诣大梁。杨涉子直史馆凝式言于涉曰：“大人为唐宰相，而国家至此，不可谓之无过。况手持天子玺绶与人，虽保富贵，奈千载何！盍辞之！”涉大骇曰：“汝灭吾族！”神色为之不宁者数日。策，敦煌人。光逢，隐之子也。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 81481efb-75a9-57ff-98e9-98e112cfa540'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,claim_text=v.claim_text,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第11段", "claim_text": "据《资治通鉴》，907年在“唐廷与各镇相继向梁王劝进”中为册礼使。", "note": "原文：甲辰，唐昭宣帝降御札禅位于梁。以摄中书令张文蔚为册礼使，礼部尚书苏循副之；摄侍中杨涉为押传国宝使，翰林学士张策副之；御史大夫薛贻矩为押金宝使，尚书左丞赵光逢副之；帅百官备法驾诣大梁。杨涉子直史馆凝式言于涉曰：“大人为唐宰相，而国家至此，不可谓之无过。况手持天子玺绶与人，虽保富贵，奈千载何！盍辞之！”涉大骇曰：“汝灭吾族！”神色为之不宁者数日。策，敦煌人。光逢，隐之子也。；核对说明："}'::jsonb) v WHERE fact_claim.id='81481efb-75a9-57ff-98e9-98e112cfa540';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='81b70977-2076-5c43-a97e-7311ac57ada7' AND (to_jsonb(t) @> '{"note": "原文：新五代史 \n23/1627 \n \n \n梁本纪第二  \n \n开平元年春正月壬寅，天子使御\n史大夫薛贻矩来劳军。宰相张文蔚率\n百官来劝进。夏四月壬戌，更名晃。\n甲子，皇帝即位。戊辰，大赦  ，改\n元，国号梁。封唐主为济阴王。升汴\n州为开封府，建为东都，以唐东都为\n西都。废京兆府为雍州。赐东都酺一\n日。契丹阿保机使袍笏梅老来。  \n五月丁丑朔，以唐相张文蔚杨涉；核对说明：本项目核读电子文本；文字层不是原刻影印，未作纸本校勘。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：新五代史 \n23/1627 \n \n \n梁本纪第二  \n \n开平元年春正月壬寅，天子使御\n史大夫薛贻矩来劳军。宰相张文蔚率\n百官来劝进。夏四月壬戌，更名晃。\n甲子，皇帝即位。戊辰，大赦  ，改\n元，国号梁。封唐主为济阴王。升汴\n州为开封府，建为东都，以唐东都为\n西都。废京兆府为雍州。赐东都酺一\n日。契丹阿保机使袍笏梅老来。  \n五月丁丑朔，以唐相张文蔚杨涉；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 81b70977-2076-5c43-a97e-7311ac57ada7'; END IF; END $$;
UPDATE public.fact_claim SET note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"note": "原文：新五代史 \n23/1627 \n \n \n梁本纪第二  \n \n开平元年春正月壬寅，天子使御\n史大夫薛贻矩来劳军。宰相张文蔚率\n百官来劝进。夏四月壬戌，更名晃。\n甲子，皇帝即位。戊辰，大赦  ，改\n元，国号梁。封唐主为济阴王。升汴\n州为开封府，建为东都，以唐东都为\n西都。废京兆府为雍州。赐东都酺一\n日。契丹阿保机使袍笏梅老来。  \n五月丁丑朔，以唐相张文蔚杨涉；核对说明："}'::jsonb) v WHERE fact_claim.id='81b70977-2076-5c43-a97e-7311ac57ada7';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='81e85247-c7ef-5806-b2bf-8dcb3fbbde4e' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p028", "claim_text": "《资治通鉴》907年条所记人物。在“契丹与后梁互遣使者通好”中为后梁使者。本批仅整理相关史事，生卒与完整履历待补。", "note": "原文：契丹遣其臣袍笏梅老来通好，帝遣太府少卿高颀报之。初，契丹有八部，部各有大人，相与约，推一人为王，建旗鼓以号令诸部，每三年则以次相代。咸通末，有习尔者为王，土宇始大。其后钦德为王，乘中原多故，时入盗边。及阿保机为王，尤雄勇，五姓奚及七姓室韦、达靼咸役属之。阿保机姓邪律氏，恃其强，不肯受代。久之，阿保机击黄头室韦还，七部劫之于境上，求如约。阿保机不得已，传旗鼓，且曰：“我为王九年，得汉人多，请帅种落居古汉城，与汉人守之，别自为一部。”七部许之。汉城者，故后魏滑盐县也。地宜五谷，有盐池之利。其后阿保机稍以兵击灭七部，复并为一国。又北侵室韦、女真，西取突阙故地，击奚，灭之，复立奚王而使契丹监其兵，东北诸夷皆畏服之。是岁，阿保机帅众三十万寇云州，晋王与之连和，面会东城，约为兄弟，延之帐中，纵酒，握手尽欢，约以今冬共击梁。或劝晋王：“因其来，可擒也，”王曰：“仇敌未灭而失信夷狄，自亡之道也。”阿保机留旬日乃去，晋王赠以金缯数万。阿保机留马三千匹，杂畜万计以酬之。阿保机既归而背盟，更附于梁，晋王由是而恨之。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第28段", "claim_text": "据《资治通鉴》，907年在“契丹与后梁互遣使者通好”中为后梁使者。", "note": "原文：契丹遣其臣袍笏梅老来通好，帝遣太府少卿高颀报之。初，契丹有八部，部各有大人，相与约，推一人为王，建旗鼓以号令诸部，每三年则以次相代。咸通末，有习尔者为王，土宇始大。其后钦德为王，乘中原多故，时入盗边。及阿保机为王，尤雄勇，五姓奚及七姓室韦、达靼咸役属之。阿保机姓邪律氏，恃其强，不肯受代。久之，阿保机击黄头室韦还，七部劫之于境上，求如约。阿保机不得已，传旗鼓，且曰：“我为王九年，得汉人多，请帅种落居古汉城，与汉人守之，别自为一部。”七部许之。汉城者，故后魏滑盐县也。地宜五谷，有盐池之利。其后阿保机稍以兵击灭七部，复并为一国。又北侵室韦、女真，西取突阙故地，击奚，灭之，复立奚王而使契丹监其兵，东北诸夷皆畏服之。是岁，阿保机帅众三十万寇云州，晋王与之连和，面会东城，约为兄弟，延之帐中，纵酒，握手尽欢，约以今冬共击梁。或劝晋王：“因其来，可擒也，”王曰：“仇敌未灭而失信夷狄，自亡之道也。”阿保机留旬日乃去，晋王赠以金缯数万。阿保机留马三千匹，杂畜万计以酬之。阿保机既归而背盟，更附于梁，晋王由是而恨之。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 81e85247-c7ef-5806-b2bf-8dcb3fbbde4e'; END IF; END $$;
