DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='85f33d0b-7a8b-594e-a78d-2721c364fa34' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p022", "claim_text": "蜀王致书晋王，提出各帝一方、平梁后再立唐宗室；李克用回书不许。本事件只记录书信提议，不据此建立已成形的军事同盟。", "note": "原文：乙亥，下制削夺李克用官爵。是时，惟河东、凤翔、淮南称“天祐”，西川称“天复”年号。馀皆禀梁正朔，称臣奉贡。蜀王与弘农王移檄诸道，云欲与岐王、晋王会兵兴复唐室，卒无应者。蜀王乃谋称帝，下教谕统内吏民；又遗晋王书云：“请各帝一方，俟硃温既平，乃访唐宗室立之，退归籓服。”晋王复书不许，曰：“誓于此生靡敢失节。”；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第22段", "claim_text": "蜀王致书晋王，提出各帝一方、平梁后再立唐宗室；李克用回书不许。此为书信提议，不能据此认定双方已结成军事同盟。", "note": "原文：乙亥，下制削夺李克用官爵。是时，惟河东、凤翔、淮南称“天祐”，西川称“天复”年号。馀皆禀梁正朔，称臣奉贡。蜀王与弘农王移檄诸道，云欲与岐王、晋王会兵兴复唐室，卒无应者。蜀王乃谋称帝，下教谕统内吏民；又遗晋王书云：“请各帝一方，俟硃温既平，乃访唐宗室立之，退归籓服。”晋王复书不许，曰：“誓于此生靡敢失节。”；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 85f33d0b-7a8b-594e-a78d-2721c364fa34'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,claim_text=v.claim_text,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第22段", "claim_text": "蜀王致书晋王，提出各帝一方、平梁后再立唐宗室；李克用回书不许。此为书信提议，不能据此认定双方已结成军事同盟。", "note": "原文：乙亥，下制削夺李克用官爵。是时，惟河东、凤翔、淮南称“天祐”，西川称“天复”年号。馀皆禀梁正朔，称臣奉贡。蜀王与弘农王移檄诸道，云欲与岐王、晋王会兵兴复唐室，卒无应者。蜀王乃谋称帝，下教谕统内吏民；又遗晋王书云：“请各帝一方，俟硃温既平，乃访唐宗室立之，退归籓服。”晋王复书不许，曰：“誓于此生靡敢失节。”；核对说明："}'::jsonb) v WHERE fact_claim.id='85f33d0b-7a8b-594e-a78d-2721c364fa34';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='8602165f-c185-5c4a-a2a1-904a258e839b' AND (to_jsonb(t) @> '{"note": "原文：新五代史 \n1353/1627 \n洛阳，改元天祐，建与唐隔绝而不\n知，故仍称天复。六年，又取归州，\n于是并有三峡。  \n七年，梁灭唐，遣使者谕建，建\n拒而不纳。建因驰檄四方，会兵讨\n梁，四方知其非诚实，皆不应。  \n是岁正月，巨人见青城山。六\n月，凤凰见万岁县，黄龙见嘉阳江，\n而诸州皆言甘露、白鹿、白雀、龟、\n龙之瑞。秋九月己亥，建乃即皇帝\n位。封其诸子为王，以王宗佶为中书\n令，韦庄为左散骑常侍判中书门下\n事，唐袭为枢密使，郑骞为御史中\n丞，张格、王锴皆为翰林学士，周博\n雅为成都尹。蜀恃险而富，当唐之；核对说明：按PDF文字层提取核对；版式断行保留，未作纸本校勘。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：新五代史 \n1353/1627 \n洛阳，改元天祐，建与唐隔绝而不\n知，故仍称天复。六年，又取归州，\n于是并有三峡。  \n七年，梁灭唐，遣使者谕建，建\n拒而不纳。建因驰檄四方，会兵讨\n梁，四方知其非诚实，皆不应。  \n是岁正月，巨人见青城山。六\n月，凤凰见万岁县，黄龙见嘉阳江，\n而诸州皆言甘露、白鹿、白雀、龟、\n龙之瑞。秋九月己亥，建乃即皇帝\n位。封其诸子为王，以王宗佶为中书\n令，韦庄为左散骑常侍判中书门下\n事，唐袭为枢密使，郑骞为御史中\n丞，张格、王锴皆为翰林学士，周博\n雅为成都尹。蜀恃险而富，当唐之；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 8602165f-c185-5c4a-a2a1-904a258e839b'; END IF; END $$;
UPDATE public.fact_claim SET note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"note": "原文：新五代史 \n1353/1627 \n洛阳，改元天祐，建与唐隔绝而不\n知，故仍称天复。六年，又取归州，\n于是并有三峡。  \n七年，梁灭唐，遣使者谕建，建\n拒而不纳。建因驰檄四方，会兵讨\n梁，四方知其非诚实，皆不应。  \n是岁正月，巨人见青城山。六\n月，凤凰见万岁县，黄龙见嘉阳江，\n而诸州皆言甘露、白鹿、白雀、龟、\n龙之瑞。秋九月己亥，建乃即皇帝\n位。封其诸子为王，以王宗佶为中书\n令，韦庄为左散骑常侍判中书门下\n事，唐袭为枢密使，郑骞为御史中\n丞，张格、王锴皆为翰林学士，周博\n雅为成都尹。蜀恃险而富，当唐之；核对说明："}'::jsonb) v WHERE fact_claim.id='8602165f-c185-5c4a-a2a1-904a258e839b';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='8679644d-1056-5137-a5bd-605d54e81acd' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p013", "note": "原文：仁恭有爱妾罗氏，其子守光通焉。仁恭杖守光而斥之，不以为子数。李思安引兵入其境，所过焚荡无馀。夏，四月，己酉，直抵幽州城下。仁恭犹在大安山。城中无备，几至不守。守光自外引兵入，登城拒守；又出兵与思安战，思安败退。守光遂自称节度使，命部将李小喜、元行钦将兵攻大安山。仁恭遣兵拒战，为小喜所败。虏仁恭以归，囚于别室。仁恭将佐及左右，凡守光素所恶者皆杀之。银胡录都指挥使王思同帅部兵三千，山后八安巡检使李承约帅部兵二千奔河东，守光弟守奇奔契丹，未几，亦奔河东，河东节度使晋王克用以承约为匡霸指挥使，思同为飞腾指挥使。思同母，仁恭之女也。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第13段", "note": "原文：仁恭有爱妾罗氏，其子守光通焉。仁恭杖守光而斥之，不以为子数。李思安引兵入其境，所过焚荡无馀。夏，四月，己酉，直抵幽州城下。仁恭犹在大安山。城中无备，几至不守。守光自外引兵入，登城拒守；又出兵与思安战，思安败退。守光遂自称节度使，命部将李小喜、元行钦将兵攻大安山。仁恭遣兵拒战，为小喜所败。虏仁恭以归，囚于别室。仁恭将佐及左右，凡守光素所恶者皆杀之。银胡录都指挥使王思同帅部兵三千，山后八安巡检使李承约帅部兵二千奔河东，守光弟守奇奔契丹，未几，亦奔河东，河东节度使晋王克用以承约为匡霸指挥使，思同为飞腾指挥使。思同母，仁恭之女也。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 8679644d-1056-5137-a5bd-605d54e81acd'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第13段", "note": "原文：仁恭有爱妾罗氏，其子守光通焉。仁恭杖守光而斥之，不以为子数。李思安引兵入其境，所过焚荡无馀。夏，四月，己酉，直抵幽州城下。仁恭犹在大安山。城中无备，几至不守。守光自外引兵入，登城拒守；又出兵与思安战，思安败退。守光遂自称节度使，命部将李小喜、元行钦将兵攻大安山。仁恭遣兵拒战，为小喜所败。虏仁恭以归，囚于别室。仁恭将佐及左右，凡守光素所恶者皆杀之。银胡录都指挥使王思同帅部兵三千，山后八安巡检使李承约帅部兵二千奔河东，守光弟守奇奔契丹，未几，亦奔河东，河东节度使晋王克用以承约为匡霸指挥使，思同为飞腾指挥使。思同母，仁恭之女也。；核对说明："}'::jsonb) v WHERE fact_claim.id='8679644d-1056-5137-a5bd-605d54e81acd';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='86d464e9-2ef9-5a73-a0ea-4adbc0dd41c9' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p008", "note": "原文：三月，癸未，王以亳州刺史李思安为北路行军都统，将兵击幽州。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第8段", "note": "原文：三月，癸未，王以亳州刺史李思安为北路行军都统，将兵击幽州。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 86d464e9-2ef9-5a73-a0ea-4adbc0dd41c9'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第8段", "note": "原文：三月，癸未，王以亳州刺史李思安为北路行军都统，将兵击幽州。；核对说明："}'::jsonb) v WHERE fact_claim.id='86d464e9-2ef9-5a73-a0ea-4adbc0dd41c9';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='8783d666-a6da-5cf7-8728-ae6224702d09' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p037", "note": "原文：弘农王以鄂岳观察使刘存为西南面都招讨使，岳州刺史陈知新为岳州团练使，庐州观察使刘威为应援使，别将许玄应为监军，将水军三万以击楚。楚王马殷甚惧，静江军使杨定真贺曰：“我军胜矣！”殷问其故，定真曰：“夫战惧则胜，骄则败。今淮南兵直趋吾城，是骄而轻敌也；而王有惧色，吾是以知其必胜也。”殷命在城都指挥使秦彦晖将水军三万浮江而下，水军副指挥使黄璠帅战舰三百屯浏阳口。六月，存等遇大雨，引兵还至越堤北，彦晖追之。存数战不利，乃遗殷书诈降。彦晖使谓殷曰：“此必诈也，勿受！”存与彦晖夹水而阵，存遥呼曰：“杀降不祥，公独不为子孙计耶！”彦晖曰：“贼入吾境而不击，奚顾子孙！”鼓噪而进。存等走，黄璠自浏阳引兵绝江，与彦晖合击，大破之，执存及知新，裨将死者百馀人，士卒死者以万数，获战舰八百艘。威以馀众遁归，彦晖遂拔岳州。殷释存、知新之缚，慰谕之。二人皆骂曰：“丈夫以死报主，肯事贼乎！”遂斩之。许玄应，弘农王之腹心也，常预政事，张颢、徐温因其败，收斩之。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第37段", "note": "原文：弘农王以鄂岳观察使刘存为西南面都招讨使，岳州刺史陈知新为岳州团练使，庐州观察使刘威为应援使，别将许玄应为监军，将水军三万以击楚。楚王马殷甚惧，静江军使杨定真贺曰：“我军胜矣！”殷问其故，定真曰：“夫战惧则胜，骄则败。今淮南兵直趋吾城，是骄而轻敌也；而王有惧色，吾是以知其必胜也。”殷命在城都指挥使秦彦晖将水军三万浮江而下，水军副指挥使黄璠帅战舰三百屯浏阳口。六月，存等遇大雨，引兵还至越堤北，彦晖追之。存数战不利，乃遗殷书诈降。彦晖使谓殷曰：“此必诈也，勿受！”存与彦晖夹水而阵，存遥呼曰：“杀降不祥，公独不为子孙计耶！”彦晖曰：“贼入吾境而不击，奚顾子孙！”鼓噪而进。存等走，黄璠自浏阳引兵绝江，与彦晖合击，大破之，执存及知新，裨将死者百馀人，士卒死者以万数，获战舰八百艘。威以馀众遁归，彦晖遂拔岳州。殷释存、知新之缚，慰谕之。二人皆骂曰：“丈夫以死报主，肯事贼乎！”遂斩之。许玄应，弘农王之腹心也，常预政事，张颢、徐温因其败，收斩之。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 8783d666-a6da-5cf7-8728-ae6224702d09'; END IF; END $$;
