DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='87880234-135f-5192-bdda-721c48fb077f' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p017", "note": "原文：甲子，张文蔚、杨涉乘辂自上源驿从册宝，诸司各备仪卫卤簿前导，百官从其后，至金祥殿前陈之。王被兗冕，即皇帝位。张文蔚、苏循奉册升殿进读，杨涉、张策、薛贻矩、赵光逢以次奉宝升殿，读已，降，帅百官舞蹈称贺。帝遂与文蔚等宴于玄德殿。帝举酒曰：“朕辅政未久，此皆诸公推戴之力。”文蔚等皆惭惧，俯伏不能对，独苏循、薛贻矩及刑部尚书张祎盛称帝功德宜应天顺人。帝复与宗戚饮博于宫中，酒酣，硃全昱忽以投琼击盆中迸散，睨帝曰：“硃三，汝本砀山一民也，从黄巢为盗，天子用汝为四镇节度使，富贵极矣！奈何一旦灭唐家三百年社稷，自称帝王！行当族灭，奚以博为！”帝不怿而罢。乙丑，命有司告天地、宗庙、社稷。丁卯，遣使宣谕州、镇。戊辰，大赦，改元，国号大梁。奉唐昭宣帝为济阴王，皆如前代故事，唐中外旧臣官爵并如故。以汴州为开封府，命曰东都；以故东都为西都；废故西京，以京兆府为大安府，置佑国军于大安府，更名魏博曰天雄军。迁济阴王于曹州，栫之以棘，使甲士守之。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第17段", "note": "原文：甲子，张文蔚、杨涉乘辂自上源驿从册宝，诸司各备仪卫卤簿前导，百官从其后，至金祥殿前陈之。王被兗冕，即皇帝位。张文蔚、苏循奉册升殿进读，杨涉、张策、薛贻矩、赵光逢以次奉宝升殿，读已，降，帅百官舞蹈称贺。帝遂与文蔚等宴于玄德殿。帝举酒曰：“朕辅政未久，此皆诸公推戴之力。”文蔚等皆惭惧，俯伏不能对，独苏循、薛贻矩及刑部尚书张祎盛称帝功德宜应天顺人。帝复与宗戚饮博于宫中，酒酣，硃全昱忽以投琼击盆中迸散，睨帝曰：“硃三，汝本砀山一民也，从黄巢为盗，天子用汝为四镇节度使，富贵极矣！奈何一旦灭唐家三百年社稷，自称帝王！行当族灭，奚以博为！”帝不怿而罢。乙丑，命有司告天地、宗庙、社稷。丁卯，遣使宣谕州、镇。戊辰，大赦，改元，国号大梁。奉唐昭宣帝为济阴王，皆如前代故事，唐中外旧臣官爵并如故。以汴州为开封府，命曰东都；以故东都为西都；废故西京，以京兆府为大安府，置佑国军于大安府，更名魏博曰天雄军。迁济阴王于曹州，栫之以棘，使甲士守之。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 87880234-135f-5192-bdda-721c48fb077f'; END IF; END $$;
