DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='8c286553-c4e7-5ce0-a65e-51a35bf06e8e' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p049", "note": "原文：丁已，帝以亳州刺史李思安代怀贞为潞州行营都统，黜怀贞为行营都虞候。思安将河北兵西上，至潞州城下，更筑重城，内以防奔突，外以拒援兵，谓之夹寨。调山东民馈军粮，德威日以轻骑抄之，思安乃自东南山口筑甬道，属于夹寨。德威与诸将互往攻之，排墙填堑，一昼夜间数十发，梁兵疲于奔命。夹寨中出刍牧者，德威辄抄之，于是梁兵闭壁不出。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第49段", "note": "原文：丁已，帝以亳州刺史李思安代怀贞为潞州行营都统，黜怀贞为行营都虞候。思安将河北兵西上，至潞州城下，更筑重城，内以防奔突，外以拒援兵，谓之夹寨。调山东民馈军粮，德威日以轻骑抄之，思安乃自东南山口筑甬道，属于夹寨。德威与诸将互往攻之，排墙填堑，一昼夜间数十发，梁兵疲于奔命。夹寨中出刍牧者，德威辄抄之，于是梁兵闭壁不出。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 8c286553-c4e7-5ce0-a65e-51a35bf06e8e'; END IF; END $$;
