DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='8d53abab-1029-5197-83c5-c0779ee8a798' AND (to_jsonb(t) @> '{"note": "原文：壬申，帝以大軍自楊劉濟河，癸酉，至鄆州，中夜，進軍逾汶，以李嗣源為前鋒，甲戌旦，遇梁兵，一戰敗之，追至中都，圍其城。城無守備，少頃，梁兵潰圍出，追擊，破之。王彥章以數十騎走，龍武大將軍李紹奇單騎追之，識其聲，曰：「王鐵槍也！」拔槊刺之，彥章重傷，馬躓，遂擒之，並擒都監張漢傑；核对说明：已对照所保存电子文本；尚待人工复核，不视为纸本校勘结论。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：壬申，帝以大軍自楊劉濟河，癸酉，至鄆州，中夜，進軍逾汶，以李嗣源為前鋒，甲戌旦，遇梁兵，一戰敗之，追至中都，圍其城。城無守備，少頃，梁兵潰圍出，追擊，破之。王彥章以數十騎走，龍武大將軍李紹奇單騎追之，識其聲，曰：「王鐵槍也！」拔槊刺之，彥章重傷，馬躓，遂擒之，並擒都監張漢傑；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 8d53abab-1029-5197-83c5-c0779ee8a798'; END IF; END $$;
