DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='93377aca-dc70-5f8d-b848-dbc104ba5ebc' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p013", "note": "原文：仁恭有爱妾罗氏，其子守光通焉。仁恭杖守光而斥之，不以为子数。李思安引兵入其境，所过焚荡无馀。夏，四月，己酉，直抵幽州城下。仁恭犹在大安山。城中无备，几至不守。守光自外引兵入，登城拒守；又出兵与思安战，思安败退。守光遂自称节度使，命部将李小喜、元行钦将兵攻大安山。仁恭遣兵拒战，为小喜所败。虏仁恭以归，囚于别室。仁恭将佐及左右，凡守光素所恶者皆杀之。银胡录都指挥使王思同帅部兵三千，山后八安巡检使李承约帅部兵二千奔河东，守光弟守奇奔契丹，未几，亦奔河东，河东节度使晋王克用以承约为匡霸指挥使，思同为飞腾指挥使。思同母，仁恭之女也。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第13段", "note": "原文：仁恭有爱妾罗氏，其子守光通焉。仁恭杖守光而斥之，不以为子数。李思安引兵入其境，所过焚荡无馀。夏，四月，己酉，直抵幽州城下。仁恭犹在大安山。城中无备，几至不守。守光自外引兵入，登城拒守；又出兵与思安战，思安败退。守光遂自称节度使，命部将李小喜、元行钦将兵攻大安山。仁恭遣兵拒战，为小喜所败。虏仁恭以归，囚于别室。仁恭将佐及左右，凡守光素所恶者皆杀之。银胡录都指挥使王思同帅部兵三千，山后八安巡检使李承约帅部兵二千奔河东，守光弟守奇奔契丹，未几，亦奔河东，河东节度使晋王克用以承约为匡霸指挥使，思同为飞腾指挥使。思同母，仁恭之女也。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 93377aca-dc70-5f8d-b848-dbc104ba5ebc'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第13段", "note": "原文：仁恭有爱妾罗氏，其子守光通焉。仁恭杖守光而斥之，不以为子数。李思安引兵入其境，所过焚荡无馀。夏，四月，己酉，直抵幽州城下。仁恭犹在大安山。城中无备，几至不守。守光自外引兵入，登城拒守；又出兵与思安战，思安败退。守光遂自称节度使，命部将李小喜、元行钦将兵攻大安山。仁恭遣兵拒战，为小喜所败。虏仁恭以归，囚于别室。仁恭将佐及左右，凡守光素所恶者皆杀之。银胡录都指挥使王思同帅部兵三千，山后八安巡检使李承约帅部兵二千奔河东，守光弟守奇奔契丹，未几，亦奔河东，河东节度使晋王克用以承约为匡霸指挥使，思同为飞腾指挥使。思同母，仁恭之女也。；核对说明："}'::jsonb) v WHERE fact_claim.id='93377aca-dc70-5f8d-b848-dbc104ba5ebc';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='934294cf-6a67-50eb-8d4e-20b03301dc3f' AND (to_jsonb(t) @> '{"note": "原文：旧五代史 \n83/1667 \n树，并图形以献。是月，隰州奏，大\n宁县至固镇上下二百里，今月八日，\n黄河清，至十月如故。   \n九月辛丑，西京大内放出两宫内\n人及前朝宫人，任其所适。敕以近年\n文武官诸道奉使，皆于所在分外停\n住，逾年涉岁，未闻归阙。非惟劳费\n州郡，抑且侮慢国经。臣节既亏，宪\n章安在。自今后两浙、福建、广州、\n安南、邕、容等道使到发许住一月；\n湖南、洪、鄂、黔、桂许住二十日；\n荆、襄、同、雍、镇、定、青、沧许\n住十日；其余侧近不过三五日。凡往\n来道路，据远近里数，日行两驿。如\n遇疾患及江河阻隔，委所在长吏具事\n旧五代史 \n84/1667 \n由奏闻。如或有违，当行朝典，命御\n史点检纠察，以亻敬慢官。魏博罗绍\n威二男廷望、廷矩，年在幼稚，皆有\n材器，帝以其籓屏勋臣之胄，宜受非\n次之用，皆擢为郎。恩命既行之后，\n二子亦就班列。绍威乃上章，以齿幼\n未任公事，乞免主印、宿直。从之。\n封镇东军神祠为崇福侯。浙西奏，道\n门威仪郑章、道士夏隐言，焚修精\n志，妙达希夷，推诸辈流实有道业。\n郑章宜赐号贞一大师，仍名元章，隐\n言赐紫衣。《五代会要》：九月，置\n左右天兴、左右广胜军，仍以亲王为\n军使。   \n十月，帝以用军，未暇西幸，文；核对说明：本项目核读电子文本；文字层不是原刻影印，未作纸本校勘。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：旧五代史 \n83/1667 \n树，并图形以献。是月，隰州奏，大\n宁县至固镇上下二百里，今月八日，\n黄河清，至十月如故。   \n九月辛丑，西京大内放出两宫内\n人及前朝宫人，任其所适。敕以近年\n文武官诸道奉使，皆于所在分外停\n住，逾年涉岁，未闻归阙。非惟劳费\n州郡，抑且侮慢国经。臣节既亏，宪\n章安在。自今后两浙、福建、广州、\n安南、邕、容等道使到发许住一月；\n湖南、洪、鄂、黔、桂许住二十日；\n荆、襄、同、雍、镇、定、青、沧许\n住十日；其余侧近不过三五日。凡往\n来道路，据远近里数，日行两驿。如\n遇疾患及江河阻隔，委所在长吏具事\n旧五代史 \n84/1667 \n由奏闻。如或有违，当行朝典，命御\n史点检纠察，以亻敬慢官。魏博罗绍\n威二男廷望、廷矩，年在幼稚，皆有\n材器，帝以其籓屏勋臣之胄，宜受非\n次之用，皆擢为郎。恩命既行之后，\n二子亦就班列。绍威乃上章，以齿幼\n未任公事，乞免主印、宿直。从之。\n封镇东军神祠为崇福侯。浙西奏，道\n门威仪郑章、道士夏隐言，焚修精\n志，妙达希夷，推诸辈流实有道业。\n郑章宜赐号贞一大师，仍名元章，隐\n言赐紫衣。《五代会要》：九月，置\n左右天兴、左右广胜军，仍以亲王为\n军使。   \n十月，帝以用军，未暇西幸，文；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 934294cf-6a67-50eb-8d4e-20b03301dc3f'; END IF; END $$;
