DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='9c65542c-d13f-5279-917c-7d5cb3b4f20e' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p054", "note": "原文：义昌节度使刘守文闻其弟守光幽其父，集将吏大哭曰：“不意吾家生此枭獍！吾生不如死，誓与诸君讨之！”乃发兵击守光，互有胜负。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第54段", "note": "原文：义昌节度使刘守文闻其弟守光幽其父，集将吏大哭曰：“不意吾家生此枭獍！吾生不如死，誓与诸君讨之！”乃发兵击守光，互有胜负。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 9c65542c-d13f-5279-917c-7d5cb3b4f20e'; END IF; END $$;
