DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='9d3a4671-7a9b-5e2c-b4b5-102d89fc5952' AND (to_jsonb(t) @> '{"note": "原文：<pb:KR2i0019_SBCK_002-2a>¶\n亂兵所殺賊衆尚優我師提頵首以示之賊衆遁散頵母¶\n遂奉王歸我師衛而歸焉二年春正月制授王檢校右僕¶\n射八月䖏州刺史盧約弟佶㓂永嘉開平元年正月武肅¶\n王命王伐永嘉四月斬盧佶而還¶\n　時盧佶列巨舟四十艘于清澳海門以&KR0829;我師王謂諸¶\n　将曰賊之銳卒盡在此矣宜勿與戦當有他道徑襲賊¶\n　壘出其不意必成&KR2587;也于是由安固江登陸而襲之佶¶\n　由是就執¶\n師還承制改王衙内都指揮使檢校尚書右僕射冬十月¶\n授王金𬗋光祿大夫檢校司空五年秋七月賜號王賛正¶\n；核对说明：本项目核读电子文本；文字层不是原刻影印，未作纸本校勘。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：<pb:KR2i0019_SBCK_002-2a>¶\n亂兵所殺賊衆尚優我師提頵首以示之賊衆遁散頵母¶\n遂奉王歸我師衛而歸焉二年春正月制授王檢校右僕¶\n射八月䖏州刺史盧約弟佶㓂永嘉開平元年正月武肅¶\n王命王伐永嘉四月斬盧佶而還¶\n　時盧佶列巨舟四十艘于清澳海門以&KR0829;我師王謂諸¶\n　将曰賊之銳卒盡在此矣宜勿與戦當有他道徑襲賊¶\n　壘出其不意必成&KR2587;也于是由安固江登陸而襲之佶¶\n　由是就執¶\n師還承制改王衙内都指揮使檢校尚書右僕射冬十月¶\n授王金𬗋光祿大夫檢校司空五年秋七月賜號王賛正¶\n；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 9d3a4671-7a9b-5e2c-b4b5-102d89fc5952'; END IF; END $$;
UPDATE public.fact_claim SET note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"note": "原文：<pb:KR2i0019_SBCK_002-2a>¶\n亂兵所殺賊衆尚優我師提頵首以示之賊衆遁散頵母¶\n遂奉王歸我師衛而歸焉二年春正月制授王檢校右僕¶\n射八月䖏州刺史盧約弟佶㓂永嘉開平元年正月武肅¶\n王命王伐永嘉四月斬盧佶而還¶\n　時盧佶列巨舟四十艘于清澳海門以&KR0829;我師王謂諸¶\n　将曰賊之銳卒盡在此矣宜勿與戦當有他道徑襲賊¶\n　壘出其不意必成&KR2587;也于是由安固江登陸而襲之佶¶\n　由是就執¶\n師還承制改王衙内都指揮使檢校尚書右僕射冬十月¶\n授王金𬗋光祿大夫檢校司空五年秋七月賜號王賛正¶\n；核对说明："}'::jsonb) v WHERE fact_claim.id='9d3a4671-7a9b-5e2c-b4b5-102d89fc5952';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='9e771bd7-b18c-52d9-a892-e45031e763d2' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p004", "claim_text": "《资治通鉴》907年条所记人物。在“张颢、徐温发动兵谏，控制淮南军政”中为事变组织者。本批仅整理相关史事，生卒与完整履历待补。", "note": "原文：渥居丧，昼夜酣饮作乐，然十围之烛以击球，一烛费钱数万。或单骑出游，从者奔走道路，不知所之。左、右牙指挥使张颢、徐温泣谏，渥怒曰：“汝谓我不才，何不杀我自为之！”二人惧。渥选壮士，号“东院马军”，广署亲信为将吏；所署者恃势骄横，陵蔑勋旧。颢、温潜谋作乱。渥父行密之世，有亲军数千，营于牙城之内，渥迁出于外，以其地为射场，颢、温由是无所惮。渥之镇宣州也，命指挥使硃思勍、范思从、陈璠将亲兵三千；及嗣位，召归广陵。颢、温使三将从秦裴击江西，因戍洪州，诬以谋叛，命别将陈祐往诛之。祐间道兼行，六日至洪州，微服怀短兵径入秦裴帐中，裴大惊，祐告之故，乃召思勍等饮酒，祐数思勍等罪，执而斩之。渥闻三将死，益忌颢、温，欲诛之。丙戍，渥晨视事，颢、温帅牙兵二百，露刃直入庭中，渥曰：“尔思欲杀我邪？”对曰，“非敢然也，欲诛王左右乱政者耳！”因数渥所亲信十馀人之罪，曳下，以铁楇击杀之，谓之“兵谏”。诸将不与之同者，颢、温稍以法诛之，于是军政悉归二人，渥不能制。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第4段", "claim_text": "据《资治通鉴》，907年在“张颢、徐温发动兵谏，控制淮南军政”中为事变组织者。", "note": "原文：渥居丧，昼夜酣饮作乐，然十围之烛以击球，一烛费钱数万。或单骑出游，从者奔走道路，不知所之。左、右牙指挥使张颢、徐温泣谏，渥怒曰：“汝谓我不才，何不杀我自为之！”二人惧。渥选壮士，号“东院马军”，广署亲信为将吏；所署者恃势骄横，陵蔑勋旧。颢、温潜谋作乱。渥父行密之世，有亲军数千，营于牙城之内，渥迁出于外，以其地为射场，颢、温由是无所惮。渥之镇宣州也，命指挥使硃思勍、范思从、陈璠将亲兵三千；及嗣位，召归广陵。颢、温使三将从秦裴击江西，因戍洪州，诬以谋叛，命别将陈祐往诛之。祐间道兼行，六日至洪州，微服怀短兵径入秦裴帐中，裴大惊，祐告之故，乃召思勍等饮酒，祐数思勍等罪，执而斩之。渥闻三将死，益忌颢、温，欲诛之。丙戍，渥晨视事，颢、温帅牙兵二百，露刃直入庭中，渥曰：“尔思欲杀我邪？”对曰，“非敢然也，欲诛王左右乱政者耳！”因数渥所亲信十馀人之罪，曳下，以铁楇击杀之，谓之“兵谏”。诸将不与之同者，颢、温稍以法诛之，于是军政悉归二人，渥不能制。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 9e771bd7-b18c-52d9-a892-e45031e763d2'; END IF; END $$;
