DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='9e8a163f-dac4-5aee-bc42-b33402b056e3' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p031", "claim_text": "《资治通鉴》907年条所记人物。在“后梁封朱全昱及诸子为王”中为受封者。本批仅整理相关史事，生卒与完整履历待补。", "note": "原文：乙酉，立皇兄全昱为广王，子友文为博王，友珪为郢王，友璋为福王，友贞为均王，友雍为贺王，友徽为建王。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第31段", "claim_text": "据《资治通鉴》，907年在“后梁封朱全昱及诸子为王”中为受封者。", "note": "原文：乙酉，立皇兄全昱为广王，子友文为博王，友珪为郢王，友璋为福王，友贞为均王，友雍为贺王，友徽为建王。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 9e8a163f-dac4-5aee-bc42-b33402b056e3'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,claim_text=v.claim_text,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第31段", "claim_text": "据《资治通鉴》，907年在“后梁封朱全昱及诸子为王”中为受封者。", "note": "原文：乙酉，立皇兄全昱为广王，子友文为博王，友珪为郢王，友璋为福王，友贞为均王，友雍为贺王，友徽为建王。；核对说明："}'::jsonb) v WHERE fact_claim.id='9e8a163f-dac4-5aee-bc42-b33402b056e3';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='9e9eb319-bfb4-501b-af38-c82d282d9d3f' AND (to_jsonb(t) @> '{"note": "原文：旧五代史 \n77/1667 \n五月，以唐朝宰臣张文蔚、杨涉\n并为门下侍郎、平章事；以御史大夫\n薛贻矩为中书侍郎、平章事。帝初受\n禅，求理尤切，委宰臣搜访贤良。或\n有在下位抱负器业久不得伸者，特加\n擢用；有明政理得失之道规救时病\n者，可陈章疏，当亲鉴择利害施行，\n然后赏以爵秩；有晦迹丘园不求闻达\n者，令彼长吏备礼邀致，冀无遗逸之\n恨。进封河南尹兼河阳节度使张全义\n为魏王，两浙节度使钱镠进封吴越\n王。辛巳，有司奏，以降诞之日为大\n明节，休假前后各一日。壬午，保义\n军节度使朱友谦进百官衣二百副。乙\n酉，立皇兄全昱为广王，皇子友文为；核对说明：本项目核读电子文本；文字层不是原刻影印，未作纸本校勘。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：旧五代史 \n77/1667 \n五月，以唐朝宰臣张文蔚、杨涉\n并为门下侍郎、平章事；以御史大夫\n薛贻矩为中书侍郎、平章事。帝初受\n禅，求理尤切，委宰臣搜访贤良。或\n有在下位抱负器业久不得伸者，特加\n擢用；有明政理得失之道规救时病\n者，可陈章疏，当亲鉴择利害施行，\n然后赏以爵秩；有晦迹丘园不求闻达\n者，令彼长吏备礼邀致，冀无遗逸之\n恨。进封河南尹兼河阳节度使张全义\n为魏王，两浙节度使钱镠进封吴越\n王。辛巳，有司奏，以降诞之日为大\n明节，休假前后各一日。壬午，保义\n军节度使朱友谦进百官衣二百副。乙\n酉，立皇兄全昱为广王，皇子友文为；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 9e9eb319-bfb4-501b-af38-c82d282d9d3f'; END IF; END $$;
