DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='9f3cbd70-497c-5e4e-b002-b48cd94905a9' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p023", "note": "原文：唐末之诛宦官也，诏书至河东，晋王匿监军张承业于斛律寺，斩罪人以应诏。至是，复以为监军，待之加厚，承业亦为之竭力。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第23段", "note": "原文：唐末之诛宦官也，诏书至河东，晋王匿监军张承业于斛律寺，斩罪人以应诏。至是，复以为监军，待之加厚，承业亦为之竭力。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: 9f3cbd70-497c-5e4e-b002-b48cd94905a9'; END IF; END $$;
