DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='a04c1c64-f9b9-5c8e-b166-9961b7308a9a' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p035", "claim_text": "《资治通鉴》907年条所记人物。在“后梁勒令苏循、张祎等致仕”中为议论者。本批仅整理相关史事，生卒与完整履历待补。", "note": "原文：礼部尚书苏循及其子起居郎楷自谓有功于梁，当不次擢用；循朝夕望为相，帝薄其为人，敬翔及殿中监李振亦鄙之。翔言于帝曰：“苏循，唐之鸱枭，卖国求利，不可以立于惟新之朝。”戊戍，诏循及刑部尚书张祎等十五人并勒致仕，楷斥归田里。循父子乃之河中依硃友谦。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第35段", "claim_text": "据《资治通鉴》，907年在“后梁勒令苏循、张祎等致仕”中为议论者。", "note": "原文：礼部尚书苏循及其子起居郎楷自谓有功于梁，当不次擢用；循朝夕望为相，帝薄其为人，敬翔及殿中监李振亦鄙之。翔言于帝曰：“苏循，唐之鸱枭，卖国求利，不可以立于惟新之朝。”戊戍，诏循及刑部尚书张祎等十五人并勒致仕，楷斥归田里。循父子乃之河中依硃友谦。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: a04c1c64-f9b9-5c8e-b166-9961b7308a9a'; END IF; END $$;
