DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='a34fc3da-ad1c-51de-a7d0-daa17210b3fb' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p029", "claim_text": "《资治通鉴》907年条所记人物。在“后梁加封钱镠、张全义、刘隐等”中为受授者。本批仅整理相关史事，生卒与完整履历待补。", "note": "原文：己卯，以河南尹兼河阳节度使张全义为魏王；镇海、镇东节度使吴王钱镠为吴越王；加清海节度使刘隐、威武节度使王审知兼侍中，乃以隐为大彭王。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第29段", "claim_text": "据《资治通鉴》，907年在“后梁加封钱镠、张全义、刘隐等”中为受授者。", "note": "原文：己卯，以河南尹兼河阳节度使张全义为魏王；镇海、镇东节度使吴王钱镠为吴越王；加清海节度使刘隐、威武节度使王审知兼侍中，乃以隐为大彭王。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: a34fc3da-ad1c-51de-a7d0-daa17210b3fb'; END IF; END $$;
