DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='a4300bd6-669a-5feb-8c84-bf696f1ea294' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p007", "note": "原文：二月，唐大臣共奏请昭宣帝逊位。壬子，诏宰相帅百官笺诣元帅府劝进，王遣使却之。于是朝臣、籓镇，乃至湖南、岭南上笺劝进者相继。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第7段", "note": "原文：二月，唐大臣共奏请昭宣帝逊位。壬子，诏宰相帅百官笺诣元帅府劝进，王遣使却之。于是朝臣、籓镇，乃至湖南、岭南上笺劝进者相继。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: a4300bd6-669a-5feb-8c84-bf696f1ea294'; END IF; END $$;
