DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='a6b3ee92-af7b-50b9-9b56-a6333cda2a62' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p029", "note": "原文：己卯，以河南尹兼河阳节度使张全义为魏王；镇海、镇东节度使吴王钱镠为吴越王；加清海节度使刘隐、威武节度使王审知兼侍中，乃以隐为大彭王。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第29段", "note": "原文：己卯，以河南尹兼河阳节度使张全义为魏王；镇海、镇东节度使吴王钱镠为吴越王；加清海节度使刘隐、威武节度使王审知兼侍中，乃以隐为大彭王。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: a6b3ee92-af7b-50b9-9b56-a6333cda2a62'; END IF; END $$;
