DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='a821b7df-d3aa-55af-b2ba-0591fe98c394' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p017", "note": "原文：甲子，张文蔚、杨涉乘辂自上源驿从册宝，诸司各备仪卫卤簿前导，百官从其后，至金祥殿前陈之。王被兗冕，即皇帝位。张文蔚、苏循奉册升殿进读，杨涉、张策、薛贻矩、赵光逢以次奉宝升殿，读已，降，帅百官舞蹈称贺。帝遂与文蔚等宴于玄德殿。帝举酒曰：“朕辅政未久，此皆诸公推戴之力。”文蔚等皆惭惧，俯伏不能对，独苏循、薛贻矩及刑部尚书张祎盛称帝功德宜应天顺人。帝复与宗戚饮博于宫中，酒酣，硃全昱忽以投琼击盆中迸散，睨帝曰：“硃三，汝本砀山一民也，从黄巢为盗，天子用汝为四镇节度使，富贵极矣！奈何一旦灭唐家三百年社稷，自称帝王！行当族灭，奚以博为！”帝不怿而罢。乙丑，命有司告天地、宗庙、社稷。丁卯，遣使宣谕州、镇。戊辰，大赦，改元，国号大梁。奉唐昭宣帝为济阴王，皆如前代故事，唐中外旧臣官爵并如故。以汴州为开封府，命曰东都；以故东都为西都；废故西京，以京兆府为大安府，置佑国军于大安府，更名魏博曰天雄军。迁济阴王于曹州，栫之以棘，使甲士守之。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第17段", "note": "原文：甲子，张文蔚、杨涉乘辂自上源驿从册宝，诸司各备仪卫卤簿前导，百官从其后，至金祥殿前陈之。王被兗冕，即皇帝位。张文蔚、苏循奉册升殿进读，杨涉、张策、薛贻矩、赵光逢以次奉宝升殿，读已，降，帅百官舞蹈称贺。帝遂与文蔚等宴于玄德殿。帝举酒曰：“朕辅政未久，此皆诸公推戴之力。”文蔚等皆惭惧，俯伏不能对，独苏循、薛贻矩及刑部尚书张祎盛称帝功德宜应天顺人。帝复与宗戚饮博于宫中，酒酣，硃全昱忽以投琼击盆中迸散，睨帝曰：“硃三，汝本砀山一民也，从黄巢为盗，天子用汝为四镇节度使，富贵极矣！奈何一旦灭唐家三百年社稷，自称帝王！行当族灭，奚以博为！”帝不怿而罢。乙丑，命有司告天地、宗庙、社稷。丁卯，遣使宣谕州、镇。戊辰，大赦，改元，国号大梁。奉唐昭宣帝为济阴王，皆如前代故事，唐中外旧臣官爵并如故。以汴州为开封府，命曰东都；以故东都为西都；废故西京，以京兆府为大安府，置佑国军于大安府，更名魏博曰天雄军。迁济阴王于曹州，栫之以棘，使甲士守之。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: a821b7df-d3aa-55af-b2ba-0591fe98c394'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第17段", "note": "原文：甲子，张文蔚、杨涉乘辂自上源驿从册宝，诸司各备仪卫卤簿前导，百官从其后，至金祥殿前陈之。王被兗冕，即皇帝位。张文蔚、苏循奉册升殿进读，杨涉、张策、薛贻矩、赵光逢以次奉宝升殿，读已，降，帅百官舞蹈称贺。帝遂与文蔚等宴于玄德殿。帝举酒曰：“朕辅政未久，此皆诸公推戴之力。”文蔚等皆惭惧，俯伏不能对，独苏循、薛贻矩及刑部尚书张祎盛称帝功德宜应天顺人。帝复与宗戚饮博于宫中，酒酣，硃全昱忽以投琼击盆中迸散，睨帝曰：“硃三，汝本砀山一民也，从黄巢为盗，天子用汝为四镇节度使，富贵极矣！奈何一旦灭唐家三百年社稷，自称帝王！行当族灭，奚以博为！”帝不怿而罢。乙丑，命有司告天地、宗庙、社稷。丁卯，遣使宣谕州、镇。戊辰，大赦，改元，国号大梁。奉唐昭宣帝为济阴王，皆如前代故事，唐中外旧臣官爵并如故。以汴州为开封府，命曰东都；以故东都为西都；废故西京，以京兆府为大安府，置佑国军于大安府，更名魏博曰天雄军。迁济阴王于曹州，栫之以棘，使甲士守之。；核对说明："}'::jsonb) v WHERE fact_claim.id='a821b7df-d3aa-55af-b2ba-0591fe98c394';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='a97efd4c-b590-5d7b-be5d-cde93208aa21' AND (to_jsonb(t) @> '{"claim_text": "后梁下诏登记唐朝被贬南方官员姓名，恢复官资并送赴京师；已死者准许归葬。这里记录诏令，不断言各地全部执行。", "note": "原文：旧五代史 \n80/1667 \n甚厚。宿州刺史王儒进白兔一，濮州\n刺史图嘉禾瑞麦以进。广州进奇宝名\n药，品类甚多。河南尹张全义进开平\n元年已前羡余钱十万贯、绸六千匹、\n绵三十万两，仍请每年上供定额每岁\n贡绢三万匹，以为常式。荆南高季昌\n进瑞橘数十颗，质状百味，倍胜常\n贡。且橘当冬熟，今方仲夏，时人咸\n异其事，因称为瑞。   \n六月，幸乾元院，宴召宰臣、学\n士及诸道入贡陪臣。己亥，帝御崇元\n殿，内出追尊四庙上谥号玉册宝共八\n副，宰臣文武百官仪仗鼓吹导引至太\n庙行事。癸卯，司天监奏：“日辰内\n有‘戊’字，请改为‘武’。”从\n旧五代史 \n81/1667 \n之。癸亥，诏以前朝官僚，谴逐南\n荒，积年未经昭雪，其间有怀抱材器\n为时所嫉者，深负冤抑。仍令录其名\n姓，尽复官资，兼告谕诸道令津致赴\n阙。如已亡殁，并许归葬，以明恩\n荡。以西都徽安门北路逼近大内宫\n垣，兼非民便，令移自榆林直趋端门\n之南。改耀州报恩禅院为兴国寺。马\n殷奏破淮寇；静海军节度使曲裕卒。  \n七月丙申，以静海军行营司马权\n知留后曲颢起复为安南都护，充节度\n使。《五代会要》：七月，敕云：\n“建国迁都，俾新其制，况山河之\n险，表里为防。今二京俱在关东以\n内，仍以潼关隶陕州，复置河潼军；核对说明：本项目核读电子文本；文字层不是原刻影印，未作纸本校勘。"}'::jsonb OR to_jsonb(t) @> '{"claim_text": "后梁下诏登记唐朝被贬南方官员姓名，恢复官资并送赴京师；已死者准许归葬。诏令在各地的实际执行情况未详。", "note": "原文：旧五代史 \n80/1667 \n甚厚。宿州刺史王儒进白兔一，濮州\n刺史图嘉禾瑞麦以进。广州进奇宝名\n药，品类甚多。河南尹张全义进开平\n元年已前羡余钱十万贯、绸六千匹、\n绵三十万两，仍请每年上供定额每岁\n贡绢三万匹，以为常式。荆南高季昌\n进瑞橘数十颗，质状百味，倍胜常\n贡。且橘当冬熟，今方仲夏，时人咸\n异其事，因称为瑞。   \n六月，幸乾元院，宴召宰臣、学\n士及诸道入贡陪臣。己亥，帝御崇元\n殿，内出追尊四庙上谥号玉册宝共八\n副，宰臣文武百官仪仗鼓吹导引至太\n庙行事。癸卯，司天监奏：“日辰内\n有‘戊’字，请改为‘武’。”从\n旧五代史 \n81/1667 \n之。癸亥，诏以前朝官僚，谴逐南\n荒，积年未经昭雪，其间有怀抱材器\n为时所嫉者，深负冤抑。仍令录其名\n姓，尽复官资，兼告谕诸道令津致赴\n阙。如已亡殁，并许归葬，以明恩\n荡。以西都徽安门北路逼近大内宫\n垣，兼非民便，令移自榆林直趋端门\n之南。改耀州报恩禅院为兴国寺。马\n殷奏破淮寇；静海军节度使曲裕卒。  \n七月丙申，以静海军行营司马权\n知留后曲颢起复为安南都护，充节度\n使。《五代会要》：七月，敕云：\n“建国迁都，俾新其制，况山河之\n险，表里为防。今二京俱在关东以\n内，仍以潼关隶陕州，复置河潼军；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: a97efd4c-b590-5d7b-be5d-cde93208aa21'; END IF; END $$;
UPDATE public.fact_claim SET claim_text=v.claim_text,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"claim_text": "后梁下诏登记唐朝被贬南方官员姓名，恢复官资并送赴京师；已死者准许归葬。诏令在各地的实际执行情况未详。", "note": "原文：旧五代史 \n80/1667 \n甚厚。宿州刺史王儒进白兔一，濮州\n刺史图嘉禾瑞麦以进。广州进奇宝名\n药，品类甚多。河南尹张全义进开平\n元年已前羡余钱十万贯、绸六千匹、\n绵三十万两，仍请每年上供定额每岁\n贡绢三万匹，以为常式。荆南高季昌\n进瑞橘数十颗，质状百味，倍胜常\n贡。且橘当冬熟，今方仲夏，时人咸\n异其事，因称为瑞。   \n六月，幸乾元院，宴召宰臣、学\n士及诸道入贡陪臣。己亥，帝御崇元\n殿，内出追尊四庙上谥号玉册宝共八\n副，宰臣文武百官仪仗鼓吹导引至太\n庙行事。癸卯，司天监奏：“日辰内\n有‘戊’字，请改为‘武’。”从\n旧五代史 \n81/1667 \n之。癸亥，诏以前朝官僚，谴逐南\n荒，积年未经昭雪，其间有怀抱材器\n为时所嫉者，深负冤抑。仍令录其名\n姓，尽复官资，兼告谕诸道令津致赴\n阙。如已亡殁，并许归葬，以明恩\n荡。以西都徽安门北路逼近大内宫\n垣，兼非民便，令移自榆林直趋端门\n之南。改耀州报恩禅院为兴国寺。马\n殷奏破淮寇；静海军节度使曲裕卒。  \n七月丙申，以静海军行营司马权\n知留后曲颢起复为安南都护，充节度\n使。《五代会要》：七月，敕云：\n“建国迁都，俾新其制，况山河之\n险，表里为防。今二京俱在关东以\n内，仍以潼关隶陕州，复置河潼军；核对说明："}'::jsonb) v WHERE fact_claim.id='a97efd4c-b590-5d7b-be5d-cde93208aa21';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='aa0a6f0b-aa89-51ff-b4a7-e37e2ef81963' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p051", "note": "原文：蜀王会将佐议称帝，皆曰：“大王虽忠于唐，唐已亡矣，此所谓‘天与不取’者也。”冯涓独献议，请，以蜀王称制，曰：“朝兴则未爽称臣，贼在则不同为恶。”王不从，涓杜门不出。王用安抚副使、掌书记韦庄之谋，帅吏民哭三日；己亥，即皇帝位，国号大蜀。辛丑，以前东川节度使兼侍中王宗佶为中书令，韦庄为左散骑常侍、判中书门下事，阆州防御使唐道袭为内枢密使。庄，见素之孙也。蜀主虽目不知书，好与书生谈论，粗晓其理。是时唐衣冠之族多避乱在蜀，蜀主礼而用之，使修举故事，故其典章文物有唐之遗风。蜀主长子校书郎宗仁幼以疾废，立其次子秘书少监宗懿为遂王。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第51段", "note": "原文：蜀王会将佐议称帝，皆曰：“大王虽忠于唐，唐已亡矣，此所谓‘天与不取’者也。”冯涓独献议，请，以蜀王称制，曰：“朝兴则未爽称臣，贼在则不同为恶。”王不从，涓杜门不出。王用安抚副使、掌书记韦庄之谋，帅吏民哭三日；己亥，即皇帝位，国号大蜀。辛丑，以前东川节度使兼侍中王宗佶为中书令，韦庄为左散骑常侍、判中书门下事，阆州防御使唐道袭为内枢密使。庄，见素之孙也。蜀主虽目不知书，好与书生谈论，粗晓其理。是时唐衣冠之族多避乱在蜀，蜀主礼而用之，使修举故事，故其典章文物有唐之遗风。蜀主长子校书郎宗仁幼以疾废，立其次子秘书少监宗懿为遂王。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: aa0a6f0b-aa89-51ff-b4a7-e37e2ef81963'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第51段", "note": "原文：蜀王会将佐议称帝，皆曰：“大王虽忠于唐，唐已亡矣，此所谓‘天与不取’者也。”冯涓独献议，请，以蜀王称制，曰：“朝兴则未爽称臣，贼在则不同为恶。”王不从，涓杜门不出。王用安抚副使、掌书记韦庄之谋，帅吏民哭三日；己亥，即皇帝位，国号大蜀。辛丑，以前东川节度使兼侍中王宗佶为中书令，韦庄为左散骑常侍、判中书门下事，阆州防御使唐道袭为内枢密使。庄，见素之孙也。蜀主虽目不知书，好与书生谈论，粗晓其理。是时唐衣冠之族多避乱在蜀，蜀主礼而用之，使修举故事，故其典章文物有唐之遗风。蜀主长子校书郎宗仁幼以疾废，立其次子秘书少监宗懿为遂王。；核对说明："}'::jsonb) v WHERE fact_claim.id='aa0a6f0b-aa89-51ff-b4a7-e37e2ef81963';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='aaefe120-e685-587d-954e-6793ee1b5cea' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p037", "note": "原文：弘农王以鄂岳观察使刘存为西南面都招讨使，岳州刺史陈知新为岳州团练使，庐州观察使刘威为应援使，别将许玄应为监军，将水军三万以击楚。楚王马殷甚惧，静江军使杨定真贺曰：“我军胜矣！”殷问其故，定真曰：“夫战惧则胜，骄则败。今淮南兵直趋吾城，是骄而轻敌也；而王有惧色，吾是以知其必胜也。”殷命在城都指挥使秦彦晖将水军三万浮江而下，水军副指挥使黄璠帅战舰三百屯浏阳口。六月，存等遇大雨，引兵还至越堤北，彦晖追之。存数战不利，乃遗殷书诈降。彦晖使谓殷曰：“此必诈也，勿受！”存与彦晖夹水而阵，存遥呼曰：“杀降不祥，公独不为子孙计耶！”彦晖曰：“贼入吾境而不击，奚顾子孙！”鼓噪而进。存等走，黄璠自浏阳引兵绝江，与彦晖合击，大破之，执存及知新，裨将死者百馀人，士卒死者以万数，获战舰八百艘。威以馀众遁归，彦晖遂拔岳州。殷释存、知新之缚，慰谕之。二人皆骂曰：“丈夫以死报主，肯事贼乎！”遂斩之。许玄应，弘农王之腹心也，常预政事，张颢、徐温因其败，收斩之。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第37段", "note": "原文：弘农王以鄂岳观察使刘存为西南面都招讨使，岳州刺史陈知新为岳州团练使，庐州观察使刘威为应援使，别将许玄应为监军，将水军三万以击楚。楚王马殷甚惧，静江军使杨定真贺曰：“我军胜矣！”殷问其故，定真曰：“夫战惧则胜，骄则败。今淮南兵直趋吾城，是骄而轻敌也；而王有惧色，吾是以知其必胜也。”殷命在城都指挥使秦彦晖将水军三万浮江而下，水军副指挥使黄璠帅战舰三百屯浏阳口。六月，存等遇大雨，引兵还至越堤北，彦晖追之。存数战不利，乃遗殷书诈降。彦晖使谓殷曰：“此必诈也，勿受！”存与彦晖夹水而阵，存遥呼曰：“杀降不祥，公独不为子孙计耶！”彦晖曰：“贼入吾境而不击，奚顾子孙！”鼓噪而进。存等走，黄璠自浏阳引兵绝江，与彦晖合击，大破之，执存及知新，裨将死者百馀人，士卒死者以万数，获战舰八百艘。威以馀众遁归，彦晖遂拔岳州。殷释存、知新之缚，慰谕之。二人皆骂曰：“丈夫以死报主，肯事贼乎！”遂斩之。许玄应，弘农王之腹心也，常预政事，张颢、徐温因其败，收斩之。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: aaefe120-e685-587d-954e-6793ee1b5cea'; END IF; END $$;
