DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='aeb6b77f-b6d5-5a12-be44-7976d015ab6a' AND (to_jsonb(t) @> '{"note": "原文：五月辛未朔，晨霧晦暝，帝率親軍伏三垂崗下。詰旦，天復昏霧，進軍直抵夾城。時李嗣源總帳下親軍攻東北隅；李存璋、王霸率丁夫燒寨，劚夾城為二道；周德威、李存審各分道進攻，軍士鼓噪，三道齊進。李嗣源壞夾城東北隅，率先掩擊，梁軍大恐，南向而奔；核对说明：已对照所保存电子文本；尚待人工复核，不视为纸本校勘结论。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：五月辛未朔，晨霧晦暝，帝率親軍伏三垂崗下。詰旦，天復昏霧，進軍直抵夾城。時李嗣源總帳下親軍攻東北隅；李存璋、王霸率丁夫燒寨，劚夾城為二道；周德威、李存審各分道進攻，軍士鼓噪，三道齊進。李嗣源壞夾城東北隅，率先掩擊，梁軍大恐，南向而奔；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: aeb6b77f-b6d5-5a12-be44-7976d015ab6a'; END IF; END $$;
UPDATE public.fact_claim SET note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"note": "原文：五月辛未朔，晨霧晦暝，帝率親軍伏三垂崗下。詰旦，天復昏霧，進軍直抵夾城。時李嗣源總帳下親軍攻東北隅；李存璋、王霸率丁夫燒寨，劚夾城為二道；周德威、李存審各分道進攻，軍士鼓噪，三道齊進。李嗣源壞夾城東北隅，率先掩擊，梁軍大恐，南向而奔；核对说明："}'::jsonb) v WHERE fact_claim.id='aeb6b77f-b6d5-5a12-be44-7976d015ab6a';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='aeeac164-5e3a-52f6-aba6-5eb527ff16ad' AND (to_jsonb(t) @> '{"note": "原文：旧五代史 \n77/1667 \n五月，以唐朝宰臣张文蔚、杨涉\n并为门下侍郎、平章事；以御史大夫\n薛贻矩为中书侍郎、平章事。帝初受\n禅，求理尤切，委宰臣搜访贤良。或\n有在下位抱负器业久不得伸者，特加\n擢用；有明政理得失之道规救时病\n者，可陈章疏，当亲鉴择利害施行，\n然后赏以爵秩；有晦迹丘园不求闻达\n者，令彼长吏备礼邀致，冀无遗逸之\n恨。进封河南尹兼河阳节度使张全义\n为魏王，两浙节度使钱镠进封吴越\n王。辛巳，有司奏，以降诞之日为大\n明节，休假前后各一日。壬午，保义\n军节度使朱友谦进百官衣二百副。乙\n酉，立皇兄全昱为广王，皇子友文为；核对说明：本项目核读电子文本；文字层不是原刻影印，未作纸本校勘。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：旧五代史 \n77/1667 \n五月，以唐朝宰臣张文蔚、杨涉\n并为门下侍郎、平章事；以御史大夫\n薛贻矩为中书侍郎、平章事。帝初受\n禅，求理尤切，委宰臣搜访贤良。或\n有在下位抱负器业久不得伸者，特加\n擢用；有明政理得失之道规救时病\n者，可陈章疏，当亲鉴择利害施行，\n然后赏以爵秩；有晦迹丘园不求闻达\n者，令彼长吏备礼邀致，冀无遗逸之\n恨。进封河南尹兼河阳节度使张全义\n为魏王，两浙节度使钱镠进封吴越\n王。辛巳，有司奏，以降诞之日为大\n明节，休假前后各一日。壬午，保义\n军节度使朱友谦进百官衣二百副。乙\n酉，立皇兄全昱为广王，皇子友文为；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: aeeac164-5e3a-52f6-aba6-5eb527ff16ad'; END IF; END $$;
