DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='afa6ebfc-a8a0-5165-b3b7-fa92500cc5d8' AND (to_jsonb(t) @> '{"note": "原文：新五代史 \n24/1627 \n为门下侍郎，御史大夫薛贻矩为中书\n侍郎；同中书门下平章事。戊寅，渤\n海、契丹遣使者来。乙酉，封兄全昱\n为广王，子友文博王，友珪郢王，友\n璋福王，友贞均王，友徽建王，侄友\n谅衡王，友能惠王，友诲邵王。甲\n午，改枢密院为崇政院，太府卿敬翔\n为使。是月，潞州行营都指挥使李思\n安及晋人战，败绩。六月甲寅，平卢\n军节度使韩建守司徒，同中书门下平\n章事。秋七月己亥，追尊祖考为皇\n帝，妣为皇后；皇高祖黯谥曰宣元，\n庙号肃祖，祖妣范氏谥曰宣僖；曾祖\n茂琳谥曰光献，庙号敬祖，祖妣杨氏\n谥曰光孝；祖信谥曰昭武，庙号宪；核对说明：本项目核读电子文本；文字层不是原刻影印，未作纸本校勘。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：新五代史 \n24/1627 \n为门下侍郎，御史大夫薛贻矩为中书\n侍郎；同中书门下平章事。戊寅，渤\n海、契丹遣使者来。乙酉，封兄全昱\n为广王，子友文博王，友珪郢王，友\n璋福王，友贞均王，友徽建王，侄友\n谅衡王，友能惠王，友诲邵王。甲\n午，改枢密院为崇政院，太府卿敬翔\n为使。是月，潞州行营都指挥使李思\n安及晋人战，败绩。六月甲寅，平卢\n军节度使韩建守司徒，同中书门下平\n章事。秋七月己亥，追尊祖考为皇\n帝，妣为皇后；皇高祖黯谥曰宣元，\n庙号肃祖，祖妣范氏谥曰宣僖；曾祖\n茂琳谥曰光献，庙号敬祖，祖妣杨氏\n谥曰光孝；祖信谥曰昭武，庙号宪；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: afa6ebfc-a8a0-5165-b3b7-fa92500cc5d8'; END IF; END $$;
