DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='b1e88320-6574-580b-ba12-c2c4f75c5999' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p024", "note": "原文：岐王治军甚宽，待士卒简易。有告部将苻昭反者，岐王直诣其家，悉去左右，熟寝经宿而还；由是众心悦服。然御军无纪律。及闻唐亡，以兵羸地蹙，不敢称帝，但开岐王府，置百官，名其所居为宫殿，妻称皇后，将吏上书称笺表，鞭、扇、号令多拟帝者。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第24段", "note": "原文：岐王治军甚宽，待士卒简易。有告部将苻昭反者，岐王直诣其家，悉去左右，熟寝经宿而还；由是众心悦服。然御军无纪律。及闻唐亡，以兵羸地蹙，不敢称帝，但开岐王府，置百官，名其所居为宫殿，妻称皇后，将吏上书称笺表，鞭、扇、号令多拟帝者。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: b1e88320-6574-580b-ba12-c2c4f75c5999'; END IF; END $$;
