DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='b2fe6238-a869-5dee-940e-6392c6a13e39' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p051", "note": "原文：蜀王会将佐议称帝，皆曰：“大王虽忠于唐，唐已亡矣，此所谓‘天与不取’者也。”冯涓独献议，请，以蜀王称制，曰：“朝兴则未爽称臣，贼在则不同为恶。”王不从，涓杜门不出。王用安抚副使、掌书记韦庄之谋，帅吏民哭三日；己亥，即皇帝位，国号大蜀。辛丑，以前东川节度使兼侍中王宗佶为中书令，韦庄为左散骑常侍、判中书门下事，阆州防御使唐道袭为内枢密使。庄，见素之孙也。蜀主虽目不知书，好与书生谈论，粗晓其理。是时唐衣冠之族多避乱在蜀，蜀主礼而用之，使修举故事，故其典章文物有唐之遗风。蜀主长子校书郎宗仁幼以疾废，立其次子秘书少监宗懿为遂王。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第51段", "note": "原文：蜀王会将佐议称帝，皆曰：“大王虽忠于唐，唐已亡矣，此所谓‘天与不取’者也。”冯涓独献议，请，以蜀王称制，曰：“朝兴则未爽称臣，贼在则不同为恶。”王不从，涓杜门不出。王用安抚副使、掌书记韦庄之谋，帅吏民哭三日；己亥，即皇帝位，国号大蜀。辛丑，以前东川节度使兼侍中王宗佶为中书令，韦庄为左散骑常侍、判中书门下事，阆州防御使唐道袭为内枢密使。庄，见素之孙也。蜀主虽目不知书，好与书生谈论，粗晓其理。是时唐衣冠之族多避乱在蜀，蜀主礼而用之，使修举故事，故其典章文物有唐之遗风。蜀主长子校书郎宗仁幼以疾废，立其次子秘书少监宗懿为遂王。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: b2fe6238-a869-5dee-940e-6392c6a13e39'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第51段", "note": "原文：蜀王会将佐议称帝，皆曰：“大王虽忠于唐，唐已亡矣，此所谓‘天与不取’者也。”冯涓独献议，请，以蜀王称制，曰：“朝兴则未爽称臣，贼在则不同为恶。”王不从，涓杜门不出。王用安抚副使、掌书记韦庄之谋，帅吏民哭三日；己亥，即皇帝位，国号大蜀。辛丑，以前东川节度使兼侍中王宗佶为中书令，韦庄为左散骑常侍、判中书门下事，阆州防御使唐道袭为内枢密使。庄，见素之孙也。蜀主虽目不知书，好与书生谈论，粗晓其理。是时唐衣冠之族多避乱在蜀，蜀主礼而用之，使修举故事，故其典章文物有唐之遗风。蜀主长子校书郎宗仁幼以疾废，立其次子秘书少监宗懿为遂王。；核对说明："}'::jsonb) v WHERE fact_claim.id='b2fe6238-a869-5dee-940e-6392c6a13e39';
