UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第44段", "note": "原文：静海节度使曲裕卒，丙申，以其子权知留后颢为节度使。；核对说明："}'::jsonb) v WHERE fact_claim.id='b350e625-2181-5e7b-bf52-24359502c882';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='b37b85bd-208c-5fcf-a655-17511300af29' AND (to_jsonb(t) @> '{"note": "原文：甲子，張文蔚、楊涉乘輅自上源驛從冊寶，諸司各備儀衛鹵簿前導，百官從其後，至金祥殿前陳之。王被兗冕，即皇帝位。張文蔚、蘇循奉冊升殿進讀，楊涉、張策、薛貽矩、趙光逢以次奉寶升殿，讀已，降，帥百官舞蹈稱賀。帝遂與文蔚等宴於玄德殿。帝舉酒曰：「朕輔政未久，此皆諸公推戴之力。」文蔚等皆慚懼，俯伏不能對，獨蘇循、薛貽矩及刑部尚書張禕盛稱帝功德宜應天順人。帝復與宗戚飲博於宮中，酒酣，朱全昱忽以投瓊擊盆中迸散，睨帝曰：「朱三，汝本碭山一民也，從黃巢為盜，天子用汝為四鎮節度使，富貴極矣！奈何一旦滅唐家三百年社稷，自稱帝王！行當族滅，奚以博為！」帝不懌而罷。乙丑，命有司告天地、宗廟、社稷。丁卯，遣使宣諭州、鎮。戊辰，大赦，改元，國號大梁。奉唐昭宣帝為濟陰王，皆如前代故事，唐中外舊臣官爵並如故。以汴州為開封府，命曰東都；以故東都為西都；廢故西京，以京兆府為大安府，置佑國軍於大安府，更名魏博曰天雄軍。遷濟陰王於曹州，栫之以棘，使甲士守之。；核对说明：已对照所保存电子文本；尚待人工复核，不视为纸本校勘结论。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：甲子，張文蔚、楊涉乘輅自上源驛從冊寶，諸司各備儀衛鹵簿前導，百官從其後，至金祥殿前陳之。王被兗冕，即皇帝位。張文蔚、蘇循奉冊升殿進讀，楊涉、張策、薛貽矩、趙光逢以次奉寶升殿，讀已，降，帥百官舞蹈稱賀。帝遂與文蔚等宴於玄德殿。帝舉酒曰：「朕輔政未久，此皆諸公推戴之力。」文蔚等皆慚懼，俯伏不能對，獨蘇循、薛貽矩及刑部尚書張禕盛稱帝功德宜應天順人。帝復與宗戚飲博於宮中，酒酣，朱全昱忽以投瓊擊盆中迸散，睨帝曰：「朱三，汝本碭山一民也，從黃巢為盜，天子用汝為四鎮節度使，富貴極矣！奈何一旦滅唐家三百年社稷，自稱帝王！行當族滅，奚以博為！」帝不懌而罷。乙丑，命有司告天地、宗廟、社稷。丁卯，遣使宣諭州、鎮。戊辰，大赦，改元，國號大梁。奉唐昭宣帝為濟陰王，皆如前代故事，唐中外舊臣官爵並如故。以汴州為開封府，命曰東都；以故東都為西都；廢故西京，以京兆府為大安府，置佑國軍於大安府，更名魏博曰天雄軍。遷濟陰王於曹州，栫之以棘，使甲士守之。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: b37b85bd-208c-5fcf-a655-17511300af29'; END IF; END $$;
