DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='b41b0942-7058-5f15-b5f7-dfb6f3de1023' AND (to_jsonb(t) @> '{"note": "原文：戊寅，友珪易服微行入左龍虎軍。見統軍韓珪，以情告之。勍亦見功臣宿將多以小過被誅，懼不自保，遂相與合謀。勍以牙兵五百人從友珪雜控鶴士入，伏於禁中，中夜斬關入，至寢殿，侍疾者皆散走。帝驚起，問：「反者為誰？」友珪曰：「非他人也！」帝曰：「我固疑此賊，恨不早殺之。汝悖逆如此，天地豈容汝乎！」友珪曰：「老賊萬段！」友珪僕夫馮廷諤刺帝腹，刃出於背。友珪自以敗氈裹之，瘞於寢殿，秘不發喪。遣供奉官丁昭溥馳詣東都，命均王友貞殺友文。\n己卯，矯詔稱：「博王友文謀逆，遣兵突入殿中，賴郢王友珪忠孝，將兵誅之，保全朕躬。然疾因震驚，彌致危殆，宜令友珪權主軍國之務。」韓勍為友珪謀，多出府庫金帛賜諸軍及百官以取悅。\n辛巳，丁昭溥還，聞友文已死，乃發喪，宣遺制，友珪即皇帝位。；核对说明：已对照所保存电子文本；尚待人工复核，不视为纸本校勘结论。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：戊寅，友珪易服微行入左龍虎軍。見統軍韓珪，以情告之。勍亦見功臣宿將多以小過被誅，懼不自保，遂相與合謀。勍以牙兵五百人從友珪雜控鶴士入，伏於禁中，中夜斬關入，至寢殿，侍疾者皆散走。帝驚起，問：「反者為誰？」友珪曰：「非他人也！」帝曰：「我固疑此賊，恨不早殺之。汝悖逆如此，天地豈容汝乎！」友珪曰：「老賊萬段！」友珪僕夫馮廷諤刺帝腹，刃出於背。友珪自以敗氈裹之，瘞於寢殿，秘不發喪。遣供奉官丁昭溥馳詣東都，命均王友貞殺友文。\n己卯，矯詔稱：「博王友文謀逆，遣兵突入殿中，賴郢王友珪忠孝，將兵誅之，保全朕躬。然疾因震驚，彌致危殆，宜令友珪權主軍國之務。」韓勍為友珪謀，多出府庫金帛賜諸軍及百官以取悅。\n辛巳，丁昭溥還，聞友文已死，乃發喪，宣遺制，友珪即皇帝位。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: b41b0942-7058-5f15-b5f7-dfb6f3de1023'; END IF; END $$;
UPDATE public.fact_claim SET note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"note": "原文：戊寅，友珪易服微行入左龍虎軍。見統軍韓珪，以情告之。勍亦見功臣宿將多以小過被誅，懼不自保，遂相與合謀。勍以牙兵五百人從友珪雜控鶴士入，伏於禁中，中夜斬關入，至寢殿，侍疾者皆散走。帝驚起，問：「反者為誰？」友珪曰：「非他人也！」帝曰：「我固疑此賊，恨不早殺之。汝悖逆如此，天地豈容汝乎！」友珪曰：「老賊萬段！」友珪僕夫馮廷諤刺帝腹，刃出於背。友珪自以敗氈裹之，瘞於寢殿，秘不發喪。遣供奉官丁昭溥馳詣東都，命均王友貞殺友文。\n己卯，矯詔稱：「博王友文謀逆，遣兵突入殿中，賴郢王友珪忠孝，將兵誅之，保全朕躬。然疾因震驚，彌致危殆，宜令友珪權主軍國之務。」韓勍為友珪謀，多出府庫金帛賜諸軍及百官以取悅。\n辛巳，丁昭溥還，聞友文已死，乃發喪，宣遺制，友珪即皇帝位。；核对说明："}'::jsonb) v WHERE fact_claim.id='b41b0942-7058-5f15-b5f7-dfb6f3de1023';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='b4b29736-b243-5a6d-8bba-46645a7c6780' AND (to_jsonb(t) @> '{"note": "原文：旧五代史 \n82/1667 \n使，命虢州刺史兼领之。”其月，敕\n改虎牢关为军，仍置虎牢关军使。己\n亥，追尊皇妣为皇太后。   \n八月，以潞州军前屯师旅，壁垒\n未收，乃别议戎帅，于是以亳州刺史\n李思安充潞州行营都统。敕：“朝廷\n之仪，封册为重，用报勋烈，以隆恩\n荣，固合亲临，式光典礼。旧章久\n缺，自我复行。今后每封册大臣，宜\n令有司备临轩之礼。”《五代会\n要》：八月，敕云：“诸道所有军事\n申奏，令直至右银台门，委客省使画\n时引进，寻常公事依前四方馆收\n接。”甲子平明前，老人星见于南\n极。壬申，密州进嘉禾，又有合欢榆；核对说明：本项目核读电子文本；文字层不是原刻影印，未作纸本校勘。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：旧五代史 \n82/1667 \n使，命虢州刺史兼领之。”其月，敕\n改虎牢关为军，仍置虎牢关军使。己\n亥，追尊皇妣为皇太后。   \n八月，以潞州军前屯师旅，壁垒\n未收，乃别议戎帅，于是以亳州刺史\n李思安充潞州行营都统。敕：“朝廷\n之仪，封册为重，用报勋烈，以隆恩\n荣，固合亲临，式光典礼。旧章久\n缺，自我复行。今后每封册大臣，宜\n令有司备临轩之礼。”《五代会\n要》：八月，敕云：“诸道所有军事\n申奏，令直至右银台门，委客省使画\n时引进，寻常公事依前四方馆收\n接。”甲子平明前，老人星见于南\n极。壬申，密州进嘉禾，又有合欢榆；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: b4b29736-b243-5a6d-8bba-46645a7c6780'; END IF; END $$;
