DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='b6539daa-bd79-52f9-a878-860339131b21' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p004", "claim_text": "张颢、徐温率牙兵进入杨渥治事之所，杀其亲信，并逐步控制军政。段首所述诛杀三将等前事另列待核，不全部断为当日。", "note": "原文：渥居丧，昼夜酣饮作乐，然十围之烛以击球，一烛费钱数万。或单骑出游，从者奔走道路，不知所之。左、右牙指挥使张颢、徐温泣谏，渥怒曰：“汝谓我不才，何不杀我自为之！”二人惧。渥选壮士，号“东院马军”，广署亲信为将吏；所署者恃势骄横，陵蔑勋旧。颢、温潜谋作乱。渥父行密之世，有亲军数千，营于牙城之内，渥迁出于外，以其地为射场，颢、温由是无所惮。渥之镇宣州也，命指挥使硃思勍、范思从、陈璠将亲兵三千；及嗣位，召归广陵。颢、温使三将从秦裴击江西，因戍洪州，诬以谋叛，命别将陈祐往诛之。祐间道兼行，六日至洪州，微服怀短兵径入秦裴帐中，裴大惊，祐告之故，乃召思勍等饮酒，祐数思勍等罪，执而斩之。渥闻三将死，益忌颢、温，欲诛之。丙戍，渥晨视事，颢、温帅牙兵二百，露刃直入庭中，渥曰：“尔思欲杀我邪？”对曰，“非敢然也，欲诛王左右乱政者耳！”因数渥所亲信十馀人之罪，曳下，以铁楇击杀之，谓之“兵谏”。诸将不与之同者，颢、温稍以法诛之，于是军政悉归二人，渥不能制。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第4段", "claim_text": "张颢、徐温率牙兵进入杨渥治事之所，杀其亲信，并逐步控制军政。诛杀三将等前事的具体日期未详。", "note": "原文：渥居丧，昼夜酣饮作乐，然十围之烛以击球，一烛费钱数万。或单骑出游，从者奔走道路，不知所之。左、右牙指挥使张颢、徐温泣谏，渥怒曰：“汝谓我不才，何不杀我自为之！”二人惧。渥选壮士，号“东院马军”，广署亲信为将吏；所署者恃势骄横，陵蔑勋旧。颢、温潜谋作乱。渥父行密之世，有亲军数千，营于牙城之内，渥迁出于外，以其地为射场，颢、温由是无所惮。渥之镇宣州也，命指挥使硃思勍、范思从、陈璠将亲兵三千；及嗣位，召归广陵。颢、温使三将从秦裴击江西，因戍洪州，诬以谋叛，命别将陈祐往诛之。祐间道兼行，六日至洪州，微服怀短兵径入秦裴帐中，裴大惊，祐告之故，乃召思勍等饮酒，祐数思勍等罪，执而斩之。渥闻三将死，益忌颢、温，欲诛之。丙戍，渥晨视事，颢、温帅牙兵二百，露刃直入庭中，渥曰：“尔思欲杀我邪？”对曰，“非敢然也，欲诛王左右乱政者耳！”因数渥所亲信十馀人之罪，曳下，以铁楇击杀之，谓之“兵谏”。诸将不与之同者，颢、温稍以法诛之，于是军政悉归二人，渥不能制。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: b6539daa-bd79-52f9-a878-860339131b21'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,claim_text=v.claim_text,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第4段", "claim_text": "张颢、徐温率牙兵进入杨渥治事之所，杀其亲信，并逐步控制军政。诛杀三将等前事的具体日期未详。", "note": "原文：渥居丧，昼夜酣饮作乐，然十围之烛以击球，一烛费钱数万。或单骑出游，从者奔走道路，不知所之。左、右牙指挥使张颢、徐温泣谏，渥怒曰：“汝谓我不才，何不杀我自为之！”二人惧。渥选壮士，号“东院马军”，广署亲信为将吏；所署者恃势骄横，陵蔑勋旧。颢、温潜谋作乱。渥父行密之世，有亲军数千，营于牙城之内，渥迁出于外，以其地为射场，颢、温由是无所惮。渥之镇宣州也，命指挥使硃思勍、范思从、陈璠将亲兵三千；及嗣位，召归广陵。颢、温使三将从秦裴击江西，因戍洪州，诬以谋叛，命别将陈祐往诛之。祐间道兼行，六日至洪州，微服怀短兵径入秦裴帐中，裴大惊，祐告之故，乃召思勍等饮酒，祐数思勍等罪，执而斩之。渥闻三将死，益忌颢、温，欲诛之。丙戍，渥晨视事，颢、温帅牙兵二百，露刃直入庭中，渥曰：“尔思欲杀我邪？”对曰，“非敢然也，欲诛王左右乱政者耳！”因数渥所亲信十馀人之罪，曳下，以铁楇击杀之，谓之“兵谏”。诸将不与之同者，颢、温稍以法诛之，于是军政悉归二人，渥不能制。；核对说明："}'::jsonb) v WHERE fact_claim.id='b6539daa-bd79-52f9-a878-860339131b21';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='b758e861-ba3d-5b7b-88fe-a05ab123ff45' AND (to_jsonb(t) @> '{"note": "原文：時魏、滑之兵陳於東、宋、汴之兵陳於西。至晡，梁軍未食，士無鬥志，景仁等引兵稍卻，周德威疾呼曰：「梁兵走矣！」晉兵大噪爭進，魏、滑兵先退，李嗣源帥眾噪於西陳之前曰：「東陳已走，爾何久留！」梁兵互相驚怖，遂大潰。李存璋引步兵乘之，呼曰：「梁人亦吾人也，父兄子弟餉軍者勿殺。」於是戰士悉解甲投兵而棄之，囂聲動天地。趙人以深、冀之憾，不顧剽掠，但奮白刃追之，梁之龍驤、神捷精兵殆盡，自野河至柏鄉，殭屍蔽地。王景仁、韓勍、李思安以數十騎走。晉兵夜至柏鄉，梁軍已去，棄糧食、資財、器械不可勝計。凡斬首二萬級。李嗣源等追奔至邢州，河朔大震。保義節度使王檀嚴備，然後開城納敗卒，給以資糧，散遣歸本道。晉王收兵屯趙州。；核对说明：已对照所保存电子文本；尚待人工复核，不视为纸本校勘结论。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：時魏、滑之兵陳於東、宋、汴之兵陳於西。至晡，梁軍未食，士無鬥志，景仁等引兵稍卻，周德威疾呼曰：「梁兵走矣！」晉兵大噪爭進，魏、滑兵先退，李嗣源帥眾噪於西陳之前曰：「東陳已走，爾何久留！」梁兵互相驚怖，遂大潰。李存璋引步兵乘之，呼曰：「梁人亦吾人也，父兄子弟餉軍者勿殺。」於是戰士悉解甲投兵而棄之，囂聲動天地。趙人以深、冀之憾，不顧剽掠，但奮白刃追之，梁之龍驤、神捷精兵殆盡，自野河至柏鄉，殭屍蔽地。王景仁、韓勍、李思安以數十騎走。晉兵夜至柏鄉，梁軍已去，棄糧食、資財、器械不可勝計。凡斬首二萬級。李嗣源等追奔至邢州，河朔大震。保義節度使王檀嚴備，然後開城納敗卒，給以資糧，散遣歸本道。晉王收兵屯趙州。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: b758e861-ba3d-5b7b-88fe-a05ab123ff45'; END IF; END $$;
