DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='b76c8267-3495-571d-b6fa-254f28b31ba2' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p030", "note": "原文：癸未，以权知荆南留后高季昌为节度使。荆南旧统八州，乾符以来，寇乱相继，诸州皆为邻道所据，独馀江陵。季昌到官，城邑残毁，户口雕耗。季昌安集流散，民皆复业。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第30段", "note": "原文：癸未，以权知荆南留后高季昌为节度使。荆南旧统八州，乾符以来，寇乱相继，诸州皆为邻道所据，独馀江陵。季昌到官，城邑残毁，户口雕耗。季昌安集流散，民皆复业。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: b76c8267-3495-571d-b6fa-254f28b31ba2'; END IF; END $$;
