DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='b87ff0cd-00f2-58b0-9018-814e336b873c' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p035", "note": "原文：礼部尚书苏循及其子起居郎楷自谓有功于梁，当不次擢用；循朝夕望为相，帝薄其为人，敬翔及殿中监李振亦鄙之。翔言于帝曰：“苏循，唐之鸱枭，卖国求利，不可以立于惟新之朝。”戊戍，诏循及刑部尚书张祎等十五人并勒致仕，楷斥归田里。循父子乃之河中依硃友谦。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第35段", "note": "原文：礼部尚书苏循及其子起居郎楷自谓有功于梁，当不次擢用；循朝夕望为相，帝薄其为人，敬翔及殿中监李振亦鄙之。翔言于帝曰：“苏循，唐之鸱枭，卖国求利，不可以立于惟新之朝。”戊戍，诏循及刑部尚书张祎等十五人并勒致仕，楷斥归田里。循父子乃之河中依硃友谦。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: b87ff0cd-00f2-58b0-9018-814e336b873c'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第35段", "note": "原文：礼部尚书苏循及其子起居郎楷自谓有功于梁，当不次擢用；循朝夕望为相，帝薄其为人，敬翔及殿中监李振亦鄙之。翔言于帝曰：“苏循，唐之鸱枭，卖国求利，不可以立于惟新之朝。”戊戍，诏循及刑部尚书张祎等十五人并勒致仕，楷斥归田里。循父子乃之河中依硃友谦。；核对说明："}'::jsonb) v WHERE fact_claim.id='b87ff0cd-00f2-58b0-9018-814e336b873c';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='b8bb8e3a-d33e-5727-bc50-a33efe0107d6' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p005", "claim_text": "《资治通鉴》907年条所记人物。在“罗绍威劝梁王灭唐，薛贻矩往返传达禅位意向”中为使者。本批仅整理相关史事，生卒与完整履历待补。", "note": "原文：初，梁王以河北诸镇皆服，唯幽、沧未下，故大举伐之，欲以坚诸镇之心，既而潞州内叛，王烧营而还，威望大沮。恐中外因此离心，欲速受禅以镇之。丁亥，王入馆于魏，有疾，卧府中，魏博节度使罗绍威恐王袭之，入见王曰：“今四方称兵为王患者，皆以翼戴唐室为名，王不如早灭唐以绝人望。”王虽不许而心德之，乃亟归。壬寅，至大梁。甲辰，唐昭宣帝遣御史大夫薛贻矩至大梁劳王，贻矩请以臣礼见，王揖之升阶，贻矩曰：“殿下功德在人，三灵改卜，皇帝方行舜、禹之事，臣安敢违！”乃北面拜舞于庭。王侧身避之。贻矩还，言于帝曰：“元帅有受禅之意矣！”帝乃下诏，以二月禅位于梁，又遣宰相以书谕王；王辞。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第5段", "claim_text": "据《资治通鉴》，907年在“罗绍威劝梁王灭唐，薛贻矩往返传达禅位意向”中为使者。", "note": "原文：初，梁王以河北诸镇皆服，唯幽、沧未下，故大举伐之，欲以坚诸镇之心，既而潞州内叛，王烧营而还，威望大沮。恐中外因此离心，欲速受禅以镇之。丁亥，王入馆于魏，有疾，卧府中，魏博节度使罗绍威恐王袭之，入见王曰：“今四方称兵为王患者，皆以翼戴唐室为名，王不如早灭唐以绝人望。”王虽不许而心德之，乃亟归。壬寅，至大梁。甲辰，唐昭宣帝遣御史大夫薛贻矩至大梁劳王，贻矩请以臣礼见，王揖之升阶，贻矩曰：“殿下功德在人，三灵改卜，皇帝方行舜、禹之事，臣安敢违！”乃北面拜舞于庭。王侧身避之。贻矩还，言于帝曰：“元帅有受禅之意矣！”帝乃下诏，以二月禅位于梁，又遣宰相以书谕王；王辞。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: b8bb8e3a-d33e-5727-bc50-a33efe0107d6'; END IF; END $$;
