DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='bb3e8500-a9b8-58c1-bff5-26c402ed856c' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p048", "note": "原文：晋周德威壁于高河，康怀贞遣亲骑都头秦武将兵击之，武败。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第48段", "note": "原文：晋周德威壁于高河，康怀贞遣亲骑都头秦武将兵击之，武败。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: bb3e8500-a9b8-58c1-bff5-26c402ed856c'; END IF; END $$;
