DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='bc47e59c-16b0-5146-a8e3-634423e9ad9c' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p022", "note": "原文：乙亥，下制削夺李克用官爵。是时，惟河东、凤翔、淮南称“天祐”，西川称“天复”年号。馀皆禀梁正朔，称臣奉贡。蜀王与弘农王移檄诸道，云欲与岐王、晋王会兵兴复唐室，卒无应者。蜀王乃谋称帝，下教谕统内吏民；又遗晋王书云：“请各帝一方，俟硃温既平，乃访唐宗室立之，退归籓服。”晋王复书不许，曰：“誓于此生靡敢失节。”；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第22段", "note": "原文：乙亥，下制削夺李克用官爵。是时，惟河东、凤翔、淮南称“天祐”，西川称“天复”年号。馀皆禀梁正朔，称臣奉贡。蜀王与弘农王移檄诸道，云欲与岐王、晋王会兵兴复唐室，卒无应者。蜀王乃谋称帝，下教谕统内吏民；又遗晋王书云：“请各帝一方，俟硃温既平，乃访唐宗室立之，退归籓服。”晋王复书不许，曰：“誓于此生靡敢失节。”；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: bc47e59c-16b0-5146-a8e3-634423e9ad9c'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第22段", "note": "原文：乙亥，下制削夺李克用官爵。是时，惟河东、凤翔、淮南称“天祐”，西川称“天复”年号。馀皆禀梁正朔，称臣奉贡。蜀王与弘农王移檄诸道，云欲与岐王、晋王会兵兴复唐室，卒无应者。蜀王乃谋称帝，下教谕统内吏民；又遗晋王书云：“请各帝一方，俟硃温既平，乃访唐宗室立之，退归籓服。”晋王复书不许，曰：“誓于此生靡敢失节。”；核对说明："}'::jsonb) v WHERE fact_claim.id='bc47e59c-16b0-5146-a8e3-634423e9ad9c';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='bd37023e-574c-5d49-b7ad-ce598f272bb3' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p025", "claim_text": "《资治通鉴》907年条所记人物。在“罗隐劝钱镠讨梁，钱镠未采纳”中为劝谏者。本批仅整理相关史事，生卒与完整履历待补。", "note": "原文：镇海节度判官罗隐说吴王镠兴兵讨梁，曰：“纵无成功，犹可退保杭、越，自为东帝；奈何交臂事贼，为终古之羞乎！”镠始以隐为不遇于唐，必有怨心，及闻其言，虽不能用，心甚义之。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第25段", "claim_text": "据《资治通鉴》，907年在“罗隐劝钱镠讨梁，钱镠未采纳”中为劝谏者。", "note": "原文：镇海节度判官罗隐说吴王镠兴兵讨梁，曰：“纵无成功，犹可退保杭、越，自为东帝；奈何交臂事贼，为终古之羞乎！”镠始以隐为不遇于唐，必有怨心，及闻其言，虽不能用，心甚义之。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: bd37023e-574c-5d49-b7ad-ce598f272bb3'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,claim_text=v.claim_text,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第25段", "claim_text": "据《资治通鉴》，907年在“罗隐劝钱镠讨梁，钱镠未采纳”中为劝谏者。", "note": "原文：镇海节度判官罗隐说吴王镠兴兵讨梁，曰：“纵无成功，犹可退保杭、越，自为东帝；奈何交臂事贼，为终古之羞乎！”镠始以隐为不遇于唐，必有怨心，及闻其言，虽不能用，心甚义之。；核对说明："}'::jsonb) v WHERE fact_claim.id='bd37023e-574c-5d49-b7ad-ce598f272bb3';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='bd555708-bcfe-516f-bee6-4e4b5e4836ba' AND (to_jsonb(t) @> '{"note": "原文：晉王疽發於首，病篤。周德威等退屯亂柳。晉王命其弟內外蕃漢都知兵馬使、振武節度使克寧、監軍張承業、大將李存璋、吳珙、掌書記盧質立其子晉州刺史存勖為嗣，曰：「此子志氣遠大，必能成吾事，爾曹善教導之！」辛卯，晉王謂存勖曰：「嗣昭厄於重圍，吾不及見矣。俟葬畢，汝與德威輩速竭力救之！」又謂克寧等曰：「以亞子累汝！」亞子，存勖小名也。言終而卒。克寧綱紀軍府，中外無敢喧嘩。克寧久總兵柄，有次立之勢，時上黨圍未解，軍中以存勖年少，多竊議者，人情忷忷。存勖懼，以位讓克寧。克寧曰：「汝冢嗣也，且有先王之命，誰敢違之！」將吏欲謁見存勖，存勖方哀哭未出。張承業入謂存勖曰：「大孝在不墜基業，多哭何為！」因扶存勖出，襲位為河東節度使、晉王。；核对说明：已对照所保存电子文本；尚待人工复核，不视为纸本校勘结论。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：晉王疽發於首，病篤。周德威等退屯亂柳。晉王命其弟內外蕃漢都知兵馬使、振武節度使克寧、監軍張承業、大將李存璋、吳珙、掌書記盧質立其子晉州刺史存勖為嗣，曰：「此子志氣遠大，必能成吾事，爾曹善教導之！」辛卯，晉王謂存勖曰：「嗣昭厄於重圍，吾不及見矣。俟葬畢，汝與德威輩速竭力救之！」又謂克寧等曰：「以亞子累汝！」亞子，存勖小名也。言終而卒。克寧綱紀軍府，中外無敢喧嘩。克寧久總兵柄，有次立之勢，時上黨圍未解，軍中以存勖年少，多竊議者，人情忷忷。存勖懼，以位讓克寧。克寧曰：「汝冢嗣也，且有先王之命，誰敢違之！」將吏欲謁見存勖，存勖方哀哭未出。張承業入謂存勖曰：「大孝在不墜基業，多哭何為！」因扶存勖出，襲位為河東節度使、晉王。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: bd555708-bcfe-516f-bee6-4e4b5e4836ba'; END IF; END $$;
