DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='bd7f689b-5f77-5346-9526-54f158f35d05' AND (to_jsonb(t) @> '{"note": "原文：天雄節度使兼中書令鄴王楊師厚卒。師厚晚年矜功恃眾，擅割財賦，選軍中驍勇，置銀槍效節都數千人，給賜優厚，欲以復故時牙兵之盛。帝雖外加尊禮，內實忌之，及卒，私於宮中受賀。租庸使趙巖、判官邵贊言於帝曰：「魏博為唐腹心之蠹，二百餘年不能除去者，以其地廣兵強之故也。羅紹威、楊師厚據之，朝廷皆不能制。陛下不乘此時為之計，所謂『彈疽不嚴，必將復聚，』安知來者不為師厚乎！宜分六州為兩鎮以弱其權。」帝以為然，以平盧節度使賀德倫為天雄節度使；置昭德軍於相州，割澶、衛二州隸焉，以宣徽使張筠為昭德節度使，仍分魏州將士府庫之半於相州。筠，海州人也。二人既赴鎮，朝廷恐魏人不服，遣開封尹劉鄩將兵六萬自白馬濟河，以討鎮、定為名，實張形勢以脅之。\n魏兵皆父子相承數百年，族姻磐結，不願分徙。德倫屢趣之，應行者皆嗟怨，連營聚哭。己丑，劉鄩屯南樂，先遣澶州刺史王彥章將龍驤五百騎入魏州，屯金波亭。魏兵相與謀曰：「朝廷忌吾軍府強盛，欲設策使之殘破耳。吾六州歷代籓鎮，兵未嘗遠出河門，一旦骨肉流離，生不如死。」是夕，軍亂，縱火大掠，圍金波亭，王彥章斬關而走。詰旦，亂兵入牙城，殺賀德倫之親兵五百人，劫德倫置樓上。有效節軍校張彥者，自帥其黨，拔白刃，止剽掠。夏，四月，帝遣供奉官扈異撫諭魏軍，許張彥以刺史。彥請復相、澶、衛三州如舊制。異還，言張彥易與，但遣劉鄩加兵，立當傳首。帝由是不許，但以優詔答之。使者再返，彥裂詔書抵於地，戟手南向詬朝廷，謂德倫曰：「天子愚闇，聽人穿鼻。今我兵甲雖強，苟無處援，不能獨立，宜投款於晉。」遂逼德倫以書求援於晉。；核对说明：已对照所保存电子文本；尚待人工复核，不视为纸本校勘结论。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：天雄節度使兼中書令鄴王楊師厚卒。師厚晚年矜功恃眾，擅割財賦，選軍中驍勇，置銀槍效節都數千人，給賜優厚，欲以復故時牙兵之盛。帝雖外加尊禮，內實忌之，及卒，私於宮中受賀。租庸使趙巖、判官邵贊言於帝曰：「魏博為唐腹心之蠹，二百餘年不能除去者，以其地廣兵強之故也。羅紹威、楊師厚據之，朝廷皆不能制。陛下不乘此時為之計，所謂『彈疽不嚴，必將復聚，』安知來者不為師厚乎！宜分六州為兩鎮以弱其權。」帝以為然，以平盧節度使賀德倫為天雄節度使；置昭德軍於相州，割澶、衛二州隸焉，以宣徽使張筠為昭德節度使，仍分魏州將士府庫之半於相州。筠，海州人也。二人既赴鎮，朝廷恐魏人不服，遣開封尹劉鄩將兵六萬自白馬濟河，以討鎮、定為名，實張形勢以脅之。\n魏兵皆父子相承數百年，族姻磐結，不願分徙。德倫屢趣之，應行者皆嗟怨，連營聚哭。己丑，劉鄩屯南樂，先遣澶州刺史王彥章將龍驤五百騎入魏州，屯金波亭。魏兵相與謀曰：「朝廷忌吾軍府強盛，欲設策使之殘破耳。吾六州歷代籓鎮，兵未嘗遠出河門，一旦骨肉流離，生不如死。」是夕，軍亂，縱火大掠，圍金波亭，王彥章斬關而走。詰旦，亂兵入牙城，殺賀德倫之親兵五百人，劫德倫置樓上。有效節軍校張彥者，自帥其黨，拔白刃，止剽掠。夏，四月，帝遣供奉官扈異撫諭魏軍，許張彥以刺史。彥請復相、澶、衛三州如舊制。異還，言張彥易與，但遣劉鄩加兵，立當傳首。帝由是不許，但以優詔答之。使者再返，彥裂詔書抵於地，戟手南向詬朝廷，謂德倫曰：「天子愚闇，聽人穿鼻。今我兵甲雖強，苟無處援，不能獨立，宜投款於晉。」遂逼德倫以書求援於晉。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: bd7f689b-5f77-5346-9526-54f158f35d05'; END IF; END $$;
