DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='bdb78e9b-8d85-5056-8745-d5f5c4c998b5' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p021", "note": "原文：初，帝为四镇节度使，凡仓库之籍，置建昌院以领之；至是，以养子宣武节度副使友文为开封尹、判院事，掌凡国之金谷。友文本康氏之子也。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第21段", "note": "原文：初，帝为四镇节度使，凡仓库之籍，置建昌院以领之；至是，以养子宣武节度副使友文为开封尹、判院事，掌凡国之金谷。友文本康氏之子也。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: bdb78e9b-8d85-5056-8745-d5f5c4c998b5'; END IF; END $$;
