DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='bec0bcbd-7253-526c-9371-9bdf49a123a4' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p025", "note": "原文：镇海节度判官罗隐说吴王镠兴兵讨梁，曰：“纵无成功，犹可退保杭、越，自为东帝；奈何交臂事贼，为终古之羞乎！”镠始以隐为不遇于唐，必有怨心，及闻其言，虽不能用，心甚义之。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第25段", "note": "原文：镇海节度判官罗隐说吴王镠兴兵讨梁，曰：“纵无成功，犹可退保杭、越，自为东帝；奈何交臂事贼，为终古之羞乎！”镠始以隐为不遇于唐，必有怨心，及闻其言，虽不能用，心甚义之。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: bec0bcbd-7253-526c-9371-9bdf49a123a4'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第25段", "note": "原文：镇海节度判官罗隐说吴王镠兴兵讨梁，曰：“纵无成功，犹可退保杭、越，自为东帝；奈何交臂事贼，为终古之羞乎！”镠始以隐为不遇于唐，必有怨心，及闻其言，虽不能用，心甚义之。；核对说明："}'::jsonb) v WHERE fact_claim.id='bec0bcbd-7253-526c-9371-9bdf49a123a4';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='befb5832-83e2-509a-b31f-7e78806ac45a' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p027", "claim_text": "《资治通鉴》907年条所记人物。在“后梁加授王镕、罗绍威、王处直官衔”中为受授者。本批仅整理相关史事，生卒与完整履历待补。", "note": "原文：加武顺军节度使赵王王镕宁太师，天雄节度使鄴王罗绍威守太傅，义武节度使王处直兼侍中。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第27段", "claim_text": "据《资治通鉴》，907年在“后梁加授王镕、罗绍威、王处直官衔”中为受授者。", "note": "原文：加武顺军节度使赵王王镕宁太师，天雄节度使鄴王罗绍威守太傅，义武节度使王处直兼侍中。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: befb5832-83e2-509a-b31f-7e78806ac45a'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,claim_text=v.claim_text,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第27段", "claim_text": "据《资治通鉴》，907年在“后梁加授王镕、罗绍威、王处直官衔”中为受授者。", "note": "原文：加武顺军节度使赵王王镕宁太师，天雄节度使鄴王罗绍威守太傅，义武节度使王处直兼侍中。；核对说明："}'::jsonb) v WHERE fact_claim.id='befb5832-83e2-509a-b31f-7e78806ac45a';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='bf30faa8-462b-5f52-a2d3-696e3276d83d' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p037", "claim_text": "原文明确称许玄应为弘农王腹心、常预政事；本批只记录907年前后的依附关系。", "note": "原文：弘农王以鄂岳观察使刘存为西南面都招讨使，岳州刺史陈知新为岳州团练使，庐州观察使刘威为应援使，别将许玄应为监军，将水军三万以击楚。楚王马殷甚惧，静江军使杨定真贺曰：“我军胜矣！”殷问其故，定真曰：“夫战惧则胜，骄则败。今淮南兵直趋吾城，是骄而轻敌也；而王有惧色，吾是以知其必胜也。”殷命在城都指挥使秦彦晖将水军三万浮江而下，水军副指挥使黄璠帅战舰三百屯浏阳口。六月，存等遇大雨，引兵还至越堤北，彦晖追之。存数战不利，乃遗殷书诈降。彦晖使谓殷曰：“此必诈也，勿受！”存与彦晖夹水而阵，存遥呼曰：“杀降不祥，公独不为子孙计耶！”彦晖曰：“贼入吾境而不击，奚顾子孙！”鼓噪而进。存等走，黄璠自浏阳引兵绝江，与彦晖合击，大破之，执存及知新，裨将死者百馀人，士卒死者以万数，获战舰八百艘。威以馀众遁归，彦晖遂拔岳州。殷释存、知新之缚，慰谕之。二人皆骂曰：“丈夫以死报主，肯事贼乎！”遂斩之。许玄应，弘农王之腹心也，常预政事，张颢、徐温因其败，收斩之。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第37段", "claim_text": "原文明确称许玄应为弘农王腹心、常预政事；此处为907年前后的依附关系。", "note": "原文：弘农王以鄂岳观察使刘存为西南面都招讨使，岳州刺史陈知新为岳州团练使，庐州观察使刘威为应援使，别将许玄应为监军，将水军三万以击楚。楚王马殷甚惧，静江军使杨定真贺曰：“我军胜矣！”殷问其故，定真曰：“夫战惧则胜，骄则败。今淮南兵直趋吾城，是骄而轻敌也；而王有惧色，吾是以知其必胜也。”殷命在城都指挥使秦彦晖将水军三万浮江而下，水军副指挥使黄璠帅战舰三百屯浏阳口。六月，存等遇大雨，引兵还至越堤北，彦晖追之。存数战不利，乃遗殷书诈降。彦晖使谓殷曰：“此必诈也，勿受！”存与彦晖夹水而阵，存遥呼曰：“杀降不祥，公独不为子孙计耶！”彦晖曰：“贼入吾境而不击，奚顾子孙！”鼓噪而进。存等走，黄璠自浏阳引兵绝江，与彦晖合击，大破之，执存及知新，裨将死者百馀人，士卒死者以万数，获战舰八百艘。威以馀众遁归，彦晖遂拔岳州。殷释存、知新之缚，慰谕之。二人皆骂曰：“丈夫以死报主，肯事贼乎！”遂斩之。许玄应，弘农王之腹心也，常预政事，张颢、徐温因其败，收斩之。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: bf30faa8-462b-5f52-a2d3-696e3276d83d'; END IF; END $$;
