DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='c1263718-5d6b-597d-b021-ea815349325d' AND (to_jsonb(t) @> '{"note": "原文：五月甲申朔，帝被冕旒禦朝元殿視朝，仗衛如式。制：改開平五年為乾化元年，大赦天下。；核对说明：已对照所保存电子文本；尚待人工复核，不视为纸本校勘结论。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：五月甲申朔，帝被冕旒禦朝元殿視朝，仗衛如式。制：改開平五年為乾化元年，大赦天下。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: c1263718-5d6b-597d-b021-ea815349325d'; END IF; END $$;
