DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='c2e1aeaf-6844-571b-93bf-ceeab2629755' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p030", "note": "原文：癸未，以权知荆南留后高季昌为节度使。荆南旧统八州，乾符以来，寇乱相继，诸州皆为邻道所据，独馀江陵。季昌到官，城邑残毁，户口雕耗。季昌安集流散，民皆复业。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第30段", "note": "原文：癸未，以权知荆南留后高季昌为节度使。荆南旧统八州，乾符以来，寇乱相继，诸州皆为邻道所据，独馀江陵。季昌到官，城邑残毁，户口雕耗。季昌安集流散，民皆复业。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: c2e1aeaf-6844-571b-93bf-ceeab2629755'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第30段", "note": "原文：癸未，以权知荆南留后高季昌为节度使。荆南旧统八州，乾符以来，寇乱相继，诸州皆为邻道所据，独馀江陵。季昌到官，城邑残毁，户口雕耗。季昌安集流散，民皆复业。；核对说明："}'::jsonb) v WHERE fact_claim.id='c2e1aeaf-6844-571b-93bf-ceeab2629755';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='c34535c4-b73b-5d71-a007-61e8c58c9426' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p020", "claim_text": "朱温追尊高祖以来的先人，尊父朱诚为烈祖文穆皇帝，母王氏为文惠皇后。本事件是追尊行为，不据此新增先人的在世活动。", "note": "原文：追尊皇高祖考、妣以来皆为帝、后，皇考诚为烈祖文穆皇帝。妣王氏为文惠皇后。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第20段", "claim_text": "朱温追尊高祖以来的先人，尊父朱诚为烈祖文穆皇帝，母王氏为文惠皇后。追尊发生于先人去世之后。", "note": "原文：追尊皇高祖考、妣以来皆为帝、后，皇考诚为烈祖文穆皇帝。妣王氏为文惠皇后。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: c34535c4-b73b-5d71-a007-61e8c58c9426'; END IF; END $$;
