UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第52段", "note": "原文：冬，十月，高季昌遣其将倪可福会楚将秦彦晖攻朗州，雷彦恭遣使乞降于淮南，且告急。弘农王遣将泠业将水军屯平江，李饶将步骑屯浏阳以救之，楚王殷遣岳州刺史许德勋将兵拒之。泠业进屯朗口，德勋使善游者五十人，以木枝叶覆其首，持长刀浮江而下，夜犯其营，且举火，业军中惊扰。德以大军进击，大破之，追至鹿角镇，擒业；又破浏阳寨，擒李饶；掠上高、唐年而归。斩业、饶于长沙市。；核对说明："}'::jsonb) v WHERE fact_claim.id='c47519a1-7f98-5147-8f24-db752ec2727c';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='c4f7afec-e192-5c58-8399-1540745942b4' AND (to_jsonb(t) @> '{"note": "原文：甲子，張文蔚、楊涉乘輅自上源驛從冊寶，諸司各備儀衛鹵簿前導，百官從其後，至金祥殿前陳之。王被兗冕，即皇帝位。張文蔚、蘇循奉冊升殿進讀，楊涉、張策、薛貽矩、趙光逢以次奉寶升殿，讀已，降，帥百官舞蹈稱賀。帝遂與文蔚等宴於玄德殿。帝舉酒曰：「朕輔政未久，此皆諸公推戴之力。」文蔚等皆慚懼，俯伏不能對，獨蘇循、薛貽矩及刑部尚書張禕盛稱帝功德宜應天順人。帝復與宗戚飲博於宮中，酒酣，朱全昱忽以投瓊擊盆中迸散，睨帝曰：「朱三，汝本碭山一民也，從黃巢為盜，天子用汝為四鎮節度使，富貴極矣！奈何一旦滅唐家三百年社稷，自稱帝王！行當族滅，奚以博為！」帝不懌而罷。乙丑，命有司告天地、宗廟、社稷。丁卯，遣使宣諭州、鎮。戊辰，大赦，改元，國號大梁。奉唐昭宣帝為濟陰王，皆如前代故事，唐中外舊臣官爵並如故。以汴州為開封府，命曰東都；以故東都為西都；廢故西京，以京兆府為大安府，置佑國軍於大安府，更名魏博曰天雄軍。遷濟陰王於曹州，栫之以棘，使甲士守之。；核对说明：已对照所保存电子文本；尚待人工复核，不视为纸本校勘结论。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：甲子，張文蔚、楊涉乘輅自上源驛從冊寶，諸司各備儀衛鹵簿前導，百官從其後，至金祥殿前陳之。王被兗冕，即皇帝位。張文蔚、蘇循奉冊升殿進讀，楊涉、張策、薛貽矩、趙光逢以次奉寶升殿，讀已，降，帥百官舞蹈稱賀。帝遂與文蔚等宴於玄德殿。帝舉酒曰：「朕輔政未久，此皆諸公推戴之力。」文蔚等皆慚懼，俯伏不能對，獨蘇循、薛貽矩及刑部尚書張禕盛稱帝功德宜應天順人。帝復與宗戚飲博於宮中，酒酣，朱全昱忽以投瓊擊盆中迸散，睨帝曰：「朱三，汝本碭山一民也，從黃巢為盜，天子用汝為四鎮節度使，富貴極矣！奈何一旦滅唐家三百年社稷，自稱帝王！行當族滅，奚以博為！」帝不懌而罷。乙丑，命有司告天地、宗廟、社稷。丁卯，遣使宣諭州、鎮。戊辰，大赦，改元，國號大梁。奉唐昭宣帝為濟陰王，皆如前代故事，唐中外舊臣官爵並如故。以汴州為開封府，命曰東都；以故東都為西都；廢故西京，以京兆府為大安府，置佑國軍於大安府，更名魏博曰天雄軍。遷濟陰王於曹州，栫之以棘，使甲士守之。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: c4f7afec-e192-5c58-8399-1540745942b4'; END IF; END $$;
