DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='c57e79c7-eb61-5c08-bae8-830c460e3014' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p040", "note": "原文：晋兵攻泽州，帝遣左神勇军使范居实将兵救之。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第40段", "note": "原文：晋兵攻泽州，帝遣左神勇军使范居实将兵救之。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: c57e79c7-eb61-5c08-bae8-830c460e3014'; END IF; END $$;
