DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='c5b8d586-8306-5d42-8eb5-e806e451af0a' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p000", "note": "原文：开平元年丁卯，公元九零七年；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·年次题记", "note": "原文：开平元年丁卯，公元九零七年；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: c5b8d586-8306-5d42-8eb5-e806e451af0a'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·年次题记", "note": "原文：开平元年丁卯，公元九零七年；核对说明："}'::jsonb) v WHERE fact_claim.id='c5b8d586-8306-5d42-8eb5-e806e451af0a';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='c6092376-85f1-5a01-afcd-3bba760e8de8' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p028", "claim_text": "《资治通鉴》907年条所记人物。在“契丹与后梁互遣使者通好”中为契丹使者。本批仅整理相关史事，生卒与完整履历待补。", "note": "原文：契丹遣其臣袍笏梅老来通好，帝遣太府少卿高颀报之。初，契丹有八部，部各有大人，相与约，推一人为王，建旗鼓以号令诸部，每三年则以次相代。咸通末，有习尔者为王，土宇始大。其后钦德为王，乘中原多故，时入盗边。及阿保机为王，尤雄勇，五姓奚及七姓室韦、达靼咸役属之。阿保机姓邪律氏，恃其强，不肯受代。久之，阿保机击黄头室韦还，七部劫之于境上，求如约。阿保机不得已，传旗鼓，且曰：“我为王九年，得汉人多，请帅种落居古汉城，与汉人守之，别自为一部。”七部许之。汉城者，故后魏滑盐县也。地宜五谷，有盐池之利。其后阿保机稍以兵击灭七部，复并为一国。又北侵室韦、女真，西取突阙故地，击奚，灭之，复立奚王而使契丹监其兵，东北诸夷皆畏服之。是岁，阿保机帅众三十万寇云州，晋王与之连和，面会东城，约为兄弟，延之帐中，纵酒，握手尽欢，约以今冬共击梁。或劝晋王：“因其来，可擒也，”王曰：“仇敌未灭而失信夷狄，自亡之道也。”阿保机留旬日乃去，晋王赠以金缯数万。阿保机留马三千匹，杂畜万计以酬之。阿保机既归而背盟，更附于梁，晋王由是而恨之。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第28段", "claim_text": "据《资治通鉴》，907年在“契丹与后梁互遣使者通好”中为契丹使者。", "note": "原文：契丹遣其臣袍笏梅老来通好，帝遣太府少卿高颀报之。初，契丹有八部，部各有大人，相与约，推一人为王，建旗鼓以号令诸部，每三年则以次相代。咸通末，有习尔者为王，土宇始大。其后钦德为王，乘中原多故，时入盗边。及阿保机为王，尤雄勇，五姓奚及七姓室韦、达靼咸役属之。阿保机姓邪律氏，恃其强，不肯受代。久之，阿保机击黄头室韦还，七部劫之于境上，求如约。阿保机不得已，传旗鼓，且曰：“我为王九年，得汉人多，请帅种落居古汉城，与汉人守之，别自为一部。”七部许之。汉城者，故后魏滑盐县也。地宜五谷，有盐池之利。其后阿保机稍以兵击灭七部，复并为一国。又北侵室韦、女真，西取突阙故地，击奚，灭之，复立奚王而使契丹监其兵，东北诸夷皆畏服之。是岁，阿保机帅众三十万寇云州，晋王与之连和，面会东城，约为兄弟，延之帐中，纵酒，握手尽欢，约以今冬共击梁。或劝晋王：“因其来，可擒也，”王曰：“仇敌未灭而失信夷狄，自亡之道也。”阿保机留旬日乃去，晋王赠以金缯数万。阿保机留马三千匹，杂畜万计以酬之。阿保机既归而背盟，更附于梁，晋王由是而恨之。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: c6092376-85f1-5a01-afcd-3bba760e8de8'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,claim_text=v.claim_text,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第28段", "claim_text": "据《资治通鉴》，907年在“契丹与后梁互遣使者通好”中为契丹使者。", "note": "原文：契丹遣其臣袍笏梅老来通好，帝遣太府少卿高颀报之。初，契丹有八部，部各有大人，相与约，推一人为王，建旗鼓以号令诸部，每三年则以次相代。咸通末，有习尔者为王，土宇始大。其后钦德为王，乘中原多故，时入盗边。及阿保机为王，尤雄勇，五姓奚及七姓室韦、达靼咸役属之。阿保机姓邪律氏，恃其强，不肯受代。久之，阿保机击黄头室韦还，七部劫之于境上，求如约。阿保机不得已，传旗鼓，且曰：“我为王九年，得汉人多，请帅种落居古汉城，与汉人守之，别自为一部。”七部许之。汉城者，故后魏滑盐县也。地宜五谷，有盐池之利。其后阿保机稍以兵击灭七部，复并为一国。又北侵室韦、女真，西取突阙故地，击奚，灭之，复立奚王而使契丹监其兵，东北诸夷皆畏服之。是岁，阿保机帅众三十万寇云州，晋王与之连和，面会东城，约为兄弟，延之帐中，纵酒，握手尽欢，约以今冬共击梁。或劝晋王：“因其来，可擒也，”王曰：“仇敌未灭而失信夷狄，自亡之道也。”阿保机留旬日乃去，晋王赠以金缯数万。阿保机留马三千匹，杂畜万计以酬之。阿保机既归而背盟，更附于梁，晋王由是而恨之。；核对说明："}'::jsonb) v WHERE fact_claim.id='c6092376-85f1-5a01-afcd-3bba760e8de8';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='c6eaa798-abfd-5a51-b868-8ca9c0cb94ba' AND (to_jsonb(t) @> '{"note": "原文：戊寅，或告唐軍已過曹州，塵埃漲天，趙巖謂從者曰：「吾待溫許州厚，必不負我。」遂奔許州。梁主謂皇甫麟曰：「李氏吾世仇，理難降首，不可俟彼刀鋸。吾不能自裁，卿可斷吾首。」麟泣曰：「臣為陛下揮劍死唐軍則可矣，不敢奉此詔。」梁主曰：「卿欲賣我邪？」麟欲自剄，梁主持之曰：「與卿俱死！」麟遂弒梁主，因自殺。梁主為人溫恭儉約，無荒淫之失；但寵信趙、張，使擅威福，疏棄敬、李舊臣，不用其言，以至於亡。\n己卯旦，李嗣源軍至大梁，攻封丘門，王瓚開門出降，嗣源入城，撫安軍民。是日，帝入自梁門，百官迎謁於馬首，拜伏請罪，帝慰勞之，使各復其位。李嗣源迎賀，帝喜不自勝，手引嗣源衣，以頭觸之曰：「吾有天下，卿父子之功也，天下與爾共之。」帝命訪求梁主，頃之，或以其首獻。；核对说明：已对照所保存电子文本；尚待人工复核，不视为纸本校勘结论。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：戊寅，或告唐軍已過曹州，塵埃漲天，趙巖謂從者曰：「吾待溫許州厚，必不負我。」遂奔許州。梁主謂皇甫麟曰：「李氏吾世仇，理難降首，不可俟彼刀鋸。吾不能自裁，卿可斷吾首。」麟泣曰：「臣為陛下揮劍死唐軍則可矣，不敢奉此詔。」梁主曰：「卿欲賣我邪？」麟欲自剄，梁主持之曰：「與卿俱死！」麟遂弒梁主，因自殺。梁主為人溫恭儉約，無荒淫之失；但寵信趙、張，使擅威福，疏棄敬、李舊臣，不用其言，以至於亡。\n己卯旦，李嗣源軍至大梁，攻封丘門，王瓚開門出降，嗣源入城，撫安軍民。是日，帝入自梁門，百官迎謁於馬首，拜伏請罪，帝慰勞之，使各復其位。李嗣源迎賀，帝喜不自勝，手引嗣源衣，以頭觸之曰：「吾有天下，卿父子之功也，天下與爾共之。」帝命訪求梁主，頃之，或以其首獻。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: c6eaa798-abfd-5a51-b868-8ca9c0cb94ba'; END IF; END $$;
