DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='c8154be9-8417-55a0-850c-e24ee5419d68' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p055", "note": "原文：天雄节度使鄴王绍威谓其下曰：“守光以窘急归国，守文孤立无援，沧州可不战服也。”乃遗守文书，谕以祸福。守文亦恐梁乘虚袭其后，戊子，遣使请降，以子延祐为质。帝拊手曰：“绍威折简，胜十万兵！”加守文中书令，抚纳之。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第55段", "note": "原文：天雄节度使鄴王绍威谓其下曰：“守光以窘急归国，守文孤立无援，沧州可不战服也。”乃遗守文书，谕以祸福。守文亦恐梁乘虚袭其后，戊子，遣使请降，以子延祐为质。帝拊手曰：“绍威折简，胜十万兵！”加守文中书令，抚纳之。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: c8154be9-8417-55a0-850c-e24ee5419d68'; END IF; END $$;
