DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='c86cc70b-55bb-5c0d-9bee-2c4b1d28b782' AND (to_jsonb(t) @> '{"note": "原文：庚寅旦，袁象先等帥禁兵數千人突入宮中。友珪聞變，與妻張氏及馮廷諤趨北垣樓下，將逾城，自度不免，令廷諤先殺妻，次殺己，廷諤亦自剄。諸軍十餘萬大掠都市，百司逃散，中書侍郎、同平章事杜曉、侍講學士李珽皆為亂兵所殺，門下侍郎、同平章事於兢、宣政使李振被傷。至晡乃定。\n像先、巖繼傳國寶詣大梁迎均王，王曰：「大梁國家創業之地，何必洛陽！」乃即帝位於大梁，復稱乾化三年，追廢友珪為庶人，復博王友文官爵。；核对说明：已对照所保存电子文本；尚待人工复核，不视为纸本校勘结论。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：庚寅旦，袁象先等帥禁兵數千人突入宮中。友珪聞變，與妻張氏及馮廷諤趨北垣樓下，將逾城，自度不免，令廷諤先殺妻，次殺己，廷諤亦自剄。諸軍十餘萬大掠都市，百司逃散，中書侍郎、同平章事杜曉、侍講學士李珽皆為亂兵所殺，門下侍郎、同平章事於兢、宣政使李振被傷。至晡乃定。\n像先、巖繼傳國寶詣大梁迎均王，王曰：「大梁國家創業之地，何必洛陽！」乃即帝位於大梁，復稱乾化三年，追廢友珪為庶人，復博王友文官爵。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: c86cc70b-55bb-5c0d-9bee-2c4b1d28b782'; END IF; END $$;
