DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='cb7dfab3-0f0d-5119-ac85-cd8fee026342' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p054", "claim_text": "《资治通鉴》907年条所记人物。在“刘守文起兵攻打刘守光”中为进攻者。本批仅整理相关史事，生卒与完整履历待补。", "note": "原文：义昌节度使刘守文闻其弟守光幽其父，集将吏大哭曰：“不意吾家生此枭獍！吾生不如死，誓与诸君讨之！”乃发兵击守光，互有胜负。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第54段", "claim_text": "据《资治通鉴》，907年在“刘守文起兵攻打刘守光”中为进攻者。", "note": "原文：义昌节度使刘守文闻其弟守光幽其父，集将吏大哭曰：“不意吾家生此枭獍！吾生不如死，誓与诸君讨之！”乃发兵击守光，互有胜负。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: cb7dfab3-0f0d-5119-ac85-cd8fee026342'; END IF; END $$;
