DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='cded9dbe-5b37-5aaf-8900-dc14b2299849' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p005", "claim_text": "《资治通鉴》907年条所记人物。在“罗绍威劝梁王灭唐，薛贻矩往返传达禅位意向”中为劝进者。本批仅整理相关史事，生卒与完整履历待补。", "note": "原文：初，梁王以河北诸镇皆服，唯幽、沧未下，故大举伐之，欲以坚诸镇之心，既而潞州内叛，王烧营而还，威望大沮。恐中外因此离心，欲速受禅以镇之。丁亥，王入馆于魏，有疾，卧府中，魏博节度使罗绍威恐王袭之，入见王曰：“今四方称兵为王患者，皆以翼戴唐室为名，王不如早灭唐以绝人望。”王虽不许而心德之，乃亟归。壬寅，至大梁。甲辰，唐昭宣帝遣御史大夫薛贻矩至大梁劳王，贻矩请以臣礼见，王揖之升阶，贻矩曰：“殿下功德在人，三灵改卜，皇帝方行舜、禹之事，臣安敢违！”乃北面拜舞于庭。王侧身避之。贻矩还，言于帝曰：“元帅有受禅之意矣！”帝乃下诏，以二月禅位于梁，又遣宰相以书谕王；王辞。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第5段", "claim_text": "据《资治通鉴》，907年在“罗绍威劝梁王灭唐，薛贻矩往返传达禅位意向”中为劝进者。", "note": "原文：初，梁王以河北诸镇皆服，唯幽、沧未下，故大举伐之，欲以坚诸镇之心，既而潞州内叛，王烧营而还，威望大沮。恐中外因此离心，欲速受禅以镇之。丁亥，王入馆于魏，有疾，卧府中，魏博节度使罗绍威恐王袭之，入见王曰：“今四方称兵为王患者，皆以翼戴唐室为名，王不如早灭唐以绝人望。”王虽不许而心德之，乃亟归。壬寅，至大梁。甲辰，唐昭宣帝遣御史大夫薛贻矩至大梁劳王，贻矩请以臣礼见，王揖之升阶，贻矩曰：“殿下功德在人，三灵改卜，皇帝方行舜、禹之事，臣安敢违！”乃北面拜舞于庭。王侧身避之。贻矩还，言于帝曰：“元帅有受禅之意矣！”帝乃下诏，以二月禅位于梁，又遣宰相以书谕王；王辞。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: cded9dbe-5b37-5aaf-8900-dc14b2299849'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,claim_text=v.claim_text,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第5段", "claim_text": "据《资治通鉴》，907年在“罗绍威劝梁王灭唐，薛贻矩往返传达禅位意向”中为劝进者。", "note": "原文：初，梁王以河北诸镇皆服，唯幽、沧未下，故大举伐之，欲以坚诸镇之心，既而潞州内叛，王烧营而还，威望大沮。恐中外因此离心，欲速受禅以镇之。丁亥，王入馆于魏，有疾，卧府中，魏博节度使罗绍威恐王袭之，入见王曰：“今四方称兵为王患者，皆以翼戴唐室为名，王不如早灭唐以绝人望。”王虽不许而心德之，乃亟归。壬寅，至大梁。甲辰，唐昭宣帝遣御史大夫薛贻矩至大梁劳王，贻矩请以臣礼见，王揖之升阶，贻矩曰：“殿下功德在人，三灵改卜，皇帝方行舜、禹之事，臣安敢违！”乃北面拜舞于庭。王侧身避之。贻矩还，言于帝曰：“元帅有受禅之意矣！”帝乃下诏，以二月禅位于梁，又遣宰相以书谕王；王辞。；核对说明："}'::jsonb) v WHERE fact_claim.id='cded9dbe-5b37-5aaf-8900-dc14b2299849';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='ce988158-5c57-5eb5-963c-f59bb9e827c1' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p050", "note": "原文：九月，雷彦恭攻涔阳、公安，高季昌击败之。彦恭贪残类其父，专以焚掠为事，荆、湖间常被其患；又附于淮南。丙申，诏削彦恭官爵，命季昌与楚王殷讨之。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第50段", "note": "原文：九月，雷彦恭攻涔阳、公安，高季昌击败之。彦恭贪残类其父，专以焚掠为事，荆、湖间常被其患；又附于淮南。丙申，诏削彦恭官爵，命季昌与楚王殷讨之。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: ce988158-5c57-5eb5-963c-f59bb9e827c1'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第50段", "note": "原文：九月，雷彦恭攻涔阳、公安，高季昌击败之。彦恭贪残类其父，专以焚掠为事，荆、湖间常被其患；又附于淮南。丙申，诏削彦恭官爵，命季昌与楚王殷讨之。；核对说明："}'::jsonb) v WHERE fact_claim.id='ce988158-5c57-5eb5-963c-f59bb9e827c1';
