DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='d1f4c826-f151-5718-bad2-5850f6ba180a' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p019", "claim_text": "907年敬翔受命主持崇政院，承宣旨意、顾问谋议；关系范围限于本批任职记载。", "note": "原文：以宣武掌书记、太府卿敬翔知崇政院事，以备顾问，参谋议，于禁中承上旨，宣于宰相而行之。宰相非进对时有所奏请及已受旨应复请者，皆具记事因崇政院以闻，得旨则复宣于宰相。翔为人沉深，有智略，在幕府三十馀年，军谋、民政，帝一以委之。翔尽心勤劳，昼夜不寐，自言惟马上乃得休息，帝性暴戾难近，人莫能测，惟翔能识其意趣。或有所不可，翔未尝显言，但微示持疑；帝意已悟，多为之改易。禅代之际，翔谋居多。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第19段", "claim_text": "907年敬翔受命主持崇政院，承宣旨意、顾问谋议；此处为907年的任职关系。", "note": "原文：以宣武掌书记、太府卿敬翔知崇政院事，以备顾问，参谋议，于禁中承上旨，宣于宰相而行之。宰相非进对时有所奏请及已受旨应复请者，皆具记事因崇政院以闻，得旨则复宣于宰相。翔为人沉深，有智略，在幕府三十馀年，军谋、民政，帝一以委之。翔尽心勤劳，昼夜不寐，自言惟马上乃得休息，帝性暴戾难近，人莫能测，惟翔能识其意趣。或有所不可，翔未尝显言，但微示持疑；帝意已悟，多为之改易。禅代之际，翔谋居多。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: d1f4c826-f151-5718-bad2-5850f6ba180a'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,claim_text=v.claim_text,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第19段", "claim_text": "907年敬翔受命主持崇政院，承宣旨意、顾问谋议；此处为907年的任职关系。", "note": "原文：以宣武掌书记、太府卿敬翔知崇政院事，以备顾问，参谋议，于禁中承上旨，宣于宰相而行之。宰相非进对时有所奏请及已受旨应复请者，皆具记事因崇政院以闻，得旨则复宣于宰相。翔为人沉深，有智略，在幕府三十馀年，军谋、民政，帝一以委之。翔尽心勤劳，昼夜不寐，自言惟马上乃得休息，帝性暴戾难近，人莫能测，惟翔能识其意趣。或有所不可，翔未尝显言，但微示持疑；帝意已悟，多为之改易。禅代之际，翔谋居多。；核对说明："}'::jsonb) v WHERE fact_claim.id='d1f4c826-f151-5718-bad2-5850f6ba180a';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='d1f9d61b-7ebe-55ca-824b-1ee47ff51298' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p013", "note": "原文：仁恭有爱妾罗氏，其子守光通焉。仁恭杖守光而斥之，不以为子数。李思安引兵入其境，所过焚荡无馀。夏，四月，己酉，直抵幽州城下。仁恭犹在大安山。城中无备，几至不守。守光自外引兵入，登城拒守；又出兵与思安战，思安败退。守光遂自称节度使，命部将李小喜、元行钦将兵攻大安山。仁恭遣兵拒战，为小喜所败。虏仁恭以归，囚于别室。仁恭将佐及左右，凡守光素所恶者皆杀之。银胡录都指挥使王思同帅部兵三千，山后八安巡检使李承约帅部兵二千奔河东，守光弟守奇奔契丹，未几，亦奔河东，河东节度使晋王克用以承约为匡霸指挥使，思同为飞腾指挥使。思同母，仁恭之女也。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第13段", "note": "原文：仁恭有爱妾罗氏，其子守光通焉。仁恭杖守光而斥之，不以为子数。李思安引兵入其境，所过焚荡无馀。夏，四月，己酉，直抵幽州城下。仁恭犹在大安山。城中无备，几至不守。守光自外引兵入，登城拒守；又出兵与思安战，思安败退。守光遂自称节度使，命部将李小喜、元行钦将兵攻大安山。仁恭遣兵拒战，为小喜所败。虏仁恭以归，囚于别室。仁恭将佐及左右，凡守光素所恶者皆杀之。银胡录都指挥使王思同帅部兵三千，山后八安巡检使李承约帅部兵二千奔河东，守光弟守奇奔契丹，未几，亦奔河东，河东节度使晋王克用以承约为匡霸指挥使，思同为飞腾指挥使。思同母，仁恭之女也。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: d1f9d61b-7ebe-55ca-824b-1ee47ff51298'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第13段", "note": "原文：仁恭有爱妾罗氏，其子守光通焉。仁恭杖守光而斥之，不以为子数。李思安引兵入其境，所过焚荡无馀。夏，四月，己酉，直抵幽州城下。仁恭犹在大安山。城中无备，几至不守。守光自外引兵入，登城拒守；又出兵与思安战，思安败退。守光遂自称节度使，命部将李小喜、元行钦将兵攻大安山。仁恭遣兵拒战，为小喜所败。虏仁恭以归，囚于别室。仁恭将佐及左右，凡守光素所恶者皆杀之。银胡录都指挥使王思同帅部兵三千，山后八安巡检使李承约帅部兵二千奔河东，守光弟守奇奔契丹，未几，亦奔河东，河东节度使晋王克用以承约为匡霸指挥使，思同为飞腾指挥使。思同母，仁恭之女也。；核对说明："}'::jsonb) v WHERE fact_claim.id='d1f9d61b-7ebe-55ca-824b-1ee47ff51298';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='d1fdc4d0-9fc0-5278-9230-08732c640edb' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p017", "claim_text": "《资治通鉴》907年条所记人物。在“朱温称帝，后梁建立”中为在场称贺者。本批仅整理相关史事，生卒与完整履历待补。", "note": "原文：甲子，张文蔚、杨涉乘辂自上源驿从册宝，诸司各备仪卫卤簿前导，百官从其后，至金祥殿前陈之。王被兗冕，即皇帝位。张文蔚、苏循奉册升殿进读，杨涉、张策、薛贻矩、赵光逢以次奉宝升殿，读已，降，帅百官舞蹈称贺。帝遂与文蔚等宴于玄德殿。帝举酒曰：“朕辅政未久，此皆诸公推戴之力。”文蔚等皆惭惧，俯伏不能对，独苏循、薛贻矩及刑部尚书张祎盛称帝功德宜应天顺人。帝复与宗戚饮博于宫中，酒酣，硃全昱忽以投琼击盆中迸散，睨帝曰：“硃三，汝本砀山一民也，从黄巢为盗，天子用汝为四镇节度使，富贵极矣！奈何一旦灭唐家三百年社稷，自称帝王！行当族灭，奚以博为！”帝不怿而罢。乙丑，命有司告天地、宗庙、社稷。丁卯，遣使宣谕州、镇。戊辰，大赦，改元，国号大梁。奉唐昭宣帝为济阴王，皆如前代故事，唐中外旧臣官爵并如故。以汴州为开封府，命曰东都；以故东都为西都；废故西京，以京兆府为大安府，置佑国军于大安府，更名魏博曰天雄军。迁济阴王于曹州，栫之以棘，使甲士守之。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第17段", "claim_text": "据《资治通鉴》，907年在“朱温称帝，后梁建立”中为在场称贺者。", "note": "原文：甲子，张文蔚、杨涉乘辂自上源驿从册宝，诸司各备仪卫卤簿前导，百官从其后，至金祥殿前陈之。王被兗冕，即皇帝位。张文蔚、苏循奉册升殿进读，杨涉、张策、薛贻矩、赵光逢以次奉宝升殿，读已，降，帅百官舞蹈称贺。帝遂与文蔚等宴于玄德殿。帝举酒曰：“朕辅政未久，此皆诸公推戴之力。”文蔚等皆惭惧，俯伏不能对，独苏循、薛贻矩及刑部尚书张祎盛称帝功德宜应天顺人。帝复与宗戚饮博于宫中，酒酣，硃全昱忽以投琼击盆中迸散，睨帝曰：“硃三，汝本砀山一民也，从黄巢为盗，天子用汝为四镇节度使，富贵极矣！奈何一旦灭唐家三百年社稷，自称帝王！行当族灭，奚以博为！”帝不怿而罢。乙丑，命有司告天地、宗庙、社稷。丁卯，遣使宣谕州、镇。戊辰，大赦，改元，国号大梁。奉唐昭宣帝为济阴王，皆如前代故事，唐中外旧臣官爵并如故。以汴州为开封府，命曰东都；以故东都为西都；废故西京，以京兆府为大安府，置佑国军于大安府，更名魏博曰天雄军。迁济阴王于曹州，栫之以棘，使甲士守之。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: d1fdc4d0-9fc0-5278-9230-08732c640edb'; END IF; END $$;
