DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='d481b64c-3cf4-556d-98a2-c961ed2c56e0' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p013", "note": "原文：仁恭有爱妾罗氏，其子守光通焉。仁恭杖守光而斥之，不以为子数。李思安引兵入其境，所过焚荡无馀。夏，四月，己酉，直抵幽州城下。仁恭犹在大安山。城中无备，几至不守。守光自外引兵入，登城拒守；又出兵与思安战，思安败退。守光遂自称节度使，命部将李小喜、元行钦将兵攻大安山。仁恭遣兵拒战，为小喜所败。虏仁恭以归，囚于别室。仁恭将佐及左右，凡守光素所恶者皆杀之。银胡录都指挥使王思同帅部兵三千，山后八安巡检使李承约帅部兵二千奔河东，守光弟守奇奔契丹，未几，亦奔河东，河东节度使晋王克用以承约为匡霸指挥使，思同为飞腾指挥使。思同母，仁恭之女也。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第13段", "note": "原文：仁恭有爱妾罗氏，其子守光通焉。仁恭杖守光而斥之，不以为子数。李思安引兵入其境，所过焚荡无馀。夏，四月，己酉，直抵幽州城下。仁恭犹在大安山。城中无备，几至不守。守光自外引兵入，登城拒守；又出兵与思安战，思安败退。守光遂自称节度使，命部将李小喜、元行钦将兵攻大安山。仁恭遣兵拒战，为小喜所败。虏仁恭以归，囚于别室。仁恭将佐及左右，凡守光素所恶者皆杀之。银胡录都指挥使王思同帅部兵三千，山后八安巡检使李承约帅部兵二千奔河东，守光弟守奇奔契丹，未几，亦奔河东，河东节度使晋王克用以承约为匡霸指挥使，思同为飞腾指挥使。思同母，仁恭之女也。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: d481b64c-3cf4-556d-98a2-c961ed2c56e0'; END IF; END $$;
