DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='d4bad070-9172-5e0a-96f5-4c5e0fb2e752' AND (to_jsonb(t) @> '{"claim_text": "本批“岐王”对应李茂贞；《新五代史》李茂贞传记其受封岐王。", "note": "原文：新五代史 \n726/1627 \n宗出居于石门。茂贞以兵至鄠县，斩\n继鹏自赎。晋兵已破王行瑜，还军渭\n北，请击茂贞。昭宗以谓晋远而茂贞\n近，因欲庇之以为德，而冀缓急之可\n恃也；且茂贞已杀其子自赎矣，乃诏\n罢归晋军。克用叹曰：“唐不诛茂\n贞，忧未已也！”  \n昭宗自石门还，益募安圣、捧宸\n等军万馀人，以诸王将之。茂贞谓唐\n将讨己，亦治兵请觐，京师大恐，居\n人亡入山谷。茂贞遂犯京师，昭宗遣\n覃王拒之，覃王至三桥，军溃，昭宗\n出居于华州。遣宰相孙偓以兵讨茂\n贞，韩建为茂贞请，乃已。久之，加\n拜茂贞尚书令，封岐王。其后，昭宗；核对说明：按PDF文字层提取核对；版式断行保留，未作纸本校勘。"}'::jsonb OR to_jsonb(t) @> '{"claim_text": "“岐王”指李茂贞；《新五代史》李茂贞传记其受封岐王。", "note": "原文：新五代史 \n726/1627 \n宗出居于石门。茂贞以兵至鄠县，斩\n继鹏自赎。晋兵已破王行瑜，还军渭\n北，请击茂贞。昭宗以谓晋远而茂贞\n近，因欲庇之以为德，而冀缓急之可\n恃也；且茂贞已杀其子自赎矣，乃诏\n罢归晋军。克用叹曰：“唐不诛茂\n贞，忧未已也！”  \n昭宗自石门还，益募安圣、捧宸\n等军万馀人，以诸王将之。茂贞谓唐\n将讨己，亦治兵请觐，京师大恐，居\n人亡入山谷。茂贞遂犯京师，昭宗遣\n覃王拒之，覃王至三桥，军溃，昭宗\n出居于华州。遣宰相孙偓以兵讨茂\n贞，韩建为茂贞请，乃已。久之，加\n拜茂贞尚书令，封岐王。其后，昭宗；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: d4bad070-9172-5e0a-96f5-4c5e0fb2e752'; END IF; END $$;
UPDATE public.fact_claim SET claim_text=v.claim_text,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"claim_text": "“岐王”指李茂贞；《新五代史》李茂贞传记其受封岐王。", "note": "原文：新五代史 \n726/1627 \n宗出居于石门。茂贞以兵至鄠县，斩\n继鹏自赎。晋兵已破王行瑜，还军渭\n北，请击茂贞。昭宗以谓晋远而茂贞\n近，因欲庇之以为德，而冀缓急之可\n恃也；且茂贞已杀其子自赎矣，乃诏\n罢归晋军。克用叹曰：“唐不诛茂\n贞，忧未已也！”  \n昭宗自石门还，益募安圣、捧宸\n等军万馀人，以诸王将之。茂贞谓唐\n将讨己，亦治兵请觐，京师大恐，居\n人亡入山谷。茂贞遂犯京师，昭宗遣\n覃王拒之，覃王至三桥，军溃，昭宗\n出居于华州。遣宰相孙偓以兵讨茂\n贞，韩建为茂贞请，乃已。久之，加\n拜茂贞尚书令，封岐王。其后，昭宗；核对说明："}'::jsonb) v WHERE fact_claim.id='d4bad070-9172-5e0a-96f5-4c5e0fb2e752';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='d50b7177-46e3-5448-af8c-bdce78cb825d' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p000", "note": "原文：开平元年丁卯，公元九零七年；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·年次题记", "note": "原文：开平元年丁卯，公元九零七年；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: d50b7177-46e3-5448-af8c-bdce78cb825d'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·年次题记", "note": "原文：开平元年丁卯，公元九零七年；核对说明："}'::jsonb) v WHERE fact_claim.id='d50b7177-46e3-5448-af8c-bdce78cb825d';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='d529e300-b3a6-5f1f-aacb-916921f24e8f' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p051", "note": "原文：蜀王会将佐议称帝，皆曰：“大王虽忠于唐，唐已亡矣，此所谓‘天与不取’者也。”冯涓独献议，请，以蜀王称制，曰：“朝兴则未爽称臣，贼在则不同为恶。”王不从，涓杜门不出。王用安抚副使、掌书记韦庄之谋，帅吏民哭三日；己亥，即皇帝位，国号大蜀。辛丑，以前东川节度使兼侍中王宗佶为中书令，韦庄为左散骑常侍、判中书门下事，阆州防御使唐道袭为内枢密使。庄，见素之孙也。蜀主虽目不知书，好与书生谈论，粗晓其理。是时唐衣冠之族多避乱在蜀，蜀主礼而用之，使修举故事，故其典章文物有唐之遗风。蜀主长子校书郎宗仁幼以疾废，立其次子秘书少监宗懿为遂王。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第51段", "note": "原文：蜀王会将佐议称帝，皆曰：“大王虽忠于唐，唐已亡矣，此所谓‘天与不取’者也。”冯涓独献议，请，以蜀王称制，曰：“朝兴则未爽称臣，贼在则不同为恶。”王不从，涓杜门不出。王用安抚副使、掌书记韦庄之谋，帅吏民哭三日；己亥，即皇帝位，国号大蜀。辛丑，以前东川节度使兼侍中王宗佶为中书令，韦庄为左散骑常侍、判中书门下事，阆州防御使唐道袭为内枢密使。庄，见素之孙也。蜀主虽目不知书，好与书生谈论，粗晓其理。是时唐衣冠之族多避乱在蜀，蜀主礼而用之，使修举故事，故其典章文物有唐之遗风。蜀主长子校书郎宗仁幼以疾废，立其次子秘书少监宗懿为遂王。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: d529e300-b3a6-5f1f-aacb-916921f24e8f'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第51段", "note": "原文：蜀王会将佐议称帝，皆曰：“大王虽忠于唐，唐已亡矣，此所谓‘天与不取’者也。”冯涓独献议，请，以蜀王称制，曰：“朝兴则未爽称臣，贼在则不同为恶。”王不从，涓杜门不出。王用安抚副使、掌书记韦庄之谋，帅吏民哭三日；己亥，即皇帝位，国号大蜀。辛丑，以前东川节度使兼侍中王宗佶为中书令，韦庄为左散骑常侍、判中书门下事，阆州防御使唐道袭为内枢密使。庄，见素之孙也。蜀主虽目不知书，好与书生谈论，粗晓其理。是时唐衣冠之族多避乱在蜀，蜀主礼而用之，使修举故事，故其典章文物有唐之遗风。蜀主长子校书郎宗仁幼以疾废，立其次子秘书少监宗懿为遂王。；核对说明："}'::jsonb) v WHERE fact_claim.id='d529e300-b3a6-5f1f-aacb-916921f24e8f';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='d62af07b-4554-5feb-891b-c565312c0d5c' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p054", "note": "原文：义昌节度使刘守文闻其弟守光幽其父，集将吏大哭曰：“不意吾家生此枭獍！吾生不如死，誓与诸君讨之！”乃发兵击守光，互有胜负。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第54段", "note": "原文：义昌节度使刘守文闻其弟守光幽其父，集将吏大哭曰：“不意吾家生此枭獍！吾生不如死，誓与诸君讨之！”乃发兵击守光，互有胜负。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: d62af07b-4554-5feb-891b-c565312c0d5c'; END IF; END $$;
