DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='da9aa055-d1d4-50ce-b679-a30997a93476' AND (to_jsonb(t) @> '{"note": "原文：是時，惟河東、鳳翔、淮南稱「天祐」，西川稱「天復」年號。餘皆稟梁正朔，稱臣奉貢。；核对说明：已对照所保存电子文本；尚待人工复核，不视为纸本校勘结论。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：是時，惟河東、鳳翔、淮南稱「天祐」，西川稱「天復」年號。餘皆稟梁正朔，稱臣奉貢。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: da9aa055-d1d4-50ce-b679-a30997a93476'; END IF; END $$;
