DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='daad377d-bec8-5006-af0d-fd88d23fce58' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p039", "note": "原文：康怀贞至潞州，晋昭义节度使李嗣昭、副使李嗣弼闭城拒守。怀贞昼夜攻之，半月不克，乃筑垒穿蚰蜓堑而守之，内外断绝。晋王以蕃、汉都指挥使周德威为行营都指挥使，帅马军都指挥使李嗣本、马步都虞候李存璋、先锋指挥使史建瑭、铁林都指挥使安元信、横冲指挥使李嗣源、骑将安金全救潞州。嗣弼，克修之子；嗣本，本姓张；建瑭，敬思之子；金全，代北人也。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第39段", "note": "原文：康怀贞至潞州，晋昭义节度使李嗣昭、副使李嗣弼闭城拒守。怀贞昼夜攻之，半月不克，乃筑垒穿蚰蜓堑而守之，内外断绝。晋王以蕃、汉都指挥使周德威为行营都指挥使，帅马军都指挥使李嗣本、马步都虞候李存璋、先锋指挥使史建瑭、铁林都指挥使安元信、横冲指挥使李嗣源、骑将安金全救潞州。嗣弼，克修之子；嗣本，本姓张；建瑭，敬思之子；金全，代北人也。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: daad377d-bec8-5006-af0d-fd88d23fce58'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第39段", "note": "原文：康怀贞至潞州，晋昭义节度使李嗣昭、副使李嗣弼闭城拒守。怀贞昼夜攻之，半月不克，乃筑垒穿蚰蜓堑而守之，内外断绝。晋王以蕃、汉都指挥使周德威为行营都指挥使，帅马军都指挥使李嗣本、马步都虞候李存璋、先锋指挥使史建瑭、铁林都指挥使安元信、横冲指挥使李嗣源、骑将安金全救潞州。嗣弼，克修之子；嗣本，本姓张；建瑭，敬思之子；金全，代北人也。；核对说明："}'::jsonb) v WHERE fact_claim.id='daad377d-bec8-5006-af0d-fd88d23fce58';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='dac6d10f-3e87-5f5d-8eb1-59fef2abab41' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p052", "claim_text": "《资治通鉴》907年条所记人物。在“荆南、楚军攻朗州，许德勋击败淮南援军”中为楚方统帅。本批仅整理相关史事，生卒与完整履历待补。", "note": "原文：冬，十月，高季昌遣其将倪可福会楚将秦彦晖攻朗州，雷彦恭遣使乞降于淮南，且告急。弘农王遣将泠业将水军屯平江，李饶将步骑屯浏阳以救之，楚王殷遣岳州刺史许德勋将兵拒之。泠业进屯朗口，德勋使善游者五十人，以木枝叶覆其首，持长刀浮江而下，夜犯其营，且举火，业军中惊扰。德以大军进击，大破之，追至鹿角镇，擒业；又破浏阳寨，擒李饶；掠上高、唐年而归。斩业、饶于长沙市。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第52段", "claim_text": "据《资治通鉴》，907年在“荆南、楚军攻朗州，许德勋击败淮南援军”中为楚方统帅。", "note": "原文：冬，十月，高季昌遣其将倪可福会楚将秦彦晖攻朗州，雷彦恭遣使乞降于淮南，且告急。弘农王遣将泠业将水军屯平江，李饶将步骑屯浏阳以救之，楚王殷遣岳州刺史许德勋将兵拒之。泠业进屯朗口，德勋使善游者五十人，以木枝叶覆其首，持长刀浮江而下，夜犯其营，且举火，业军中惊扰。德以大军进击，大破之，追至鹿角镇，擒业；又破浏阳寨，擒李饶；掠上高、唐年而归。斩业、饶于长沙市。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: dac6d10f-3e87-5f5d-8eb1-59fef2abab41'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,claim_text=v.claim_text,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第52段", "claim_text": "据《资治通鉴》，907年在“荆南、楚军攻朗州，许德勋击败淮南援军”中为楚方统帅。", "note": "原文：冬，十月，高季昌遣其将倪可福会楚将秦彦晖攻朗州，雷彦恭遣使乞降于淮南，且告急。弘农王遣将泠业将水军屯平江，李饶将步骑屯浏阳以救之，楚王殷遣岳州刺史许德勋将兵拒之。泠业进屯朗口，德勋使善游者五十人，以木枝叶覆其首，持长刀浮江而下，夜犯其营，且举火，业军中惊扰。德以大军进击，大破之，追至鹿角镇，擒业；又破浏阳寨，擒李饶；掠上高、唐年而归。斩业、饶于长沙市。；核对说明："}'::jsonb) v WHERE fact_claim.id='dac6d10f-3e87-5f5d-8eb1-59fef2abab41';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='db44aba3-d6c1-5114-b1a1-8ae10ec068c9' AND (to_jsonb(t) @> '{"note": "原文：晉王疽發於首，病篤。周德威等退屯亂柳。晉王命其弟內外蕃漢都知兵馬使、振武節度使克寧、監軍張承業、大將李存璋、吳珙、掌書記盧質立其子晉州刺史存勖為嗣，曰：「此子志氣遠大，必能成吾事，爾曹善教導之！」辛卯，晉王謂存勖曰：「嗣昭厄於重圍，吾不及見矣。俟葬畢，汝與德威輩速竭力救之！」又謂克寧等曰：「以亞子累汝！」亞子，存勖小名也。言終而卒。克寧綱紀軍府，中外無敢喧嘩。克寧久總兵柄，有次立之勢，時上黨圍未解，軍中以存勖年少，多竊議者，人情忷忷。存勖懼，以位讓克寧。克寧曰：「汝冢嗣也，且有先王之命，誰敢違之！」將吏欲謁見存勖，存勖方哀哭未出。張承業入謂存勖曰：「大孝在不墜基業，多哭何為！」因扶存勖出，襲位為河東節度使、晉王。；核对说明：已对照所保存电子文本；尚待人工复核，不视为纸本校勘结论。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：晉王疽發於首，病篤。周德威等退屯亂柳。晉王命其弟內外蕃漢都知兵馬使、振武節度使克寧、監軍張承業、大將李存璋、吳珙、掌書記盧質立其子晉州刺史存勖為嗣，曰：「此子志氣遠大，必能成吾事，爾曹善教導之！」辛卯，晉王謂存勖曰：「嗣昭厄於重圍，吾不及見矣。俟葬畢，汝與德威輩速竭力救之！」又謂克寧等曰：「以亞子累汝！」亞子，存勖小名也。言終而卒。克寧綱紀軍府，中外無敢喧嘩。克寧久總兵柄，有次立之勢，時上黨圍未解，軍中以存勖年少，多竊議者，人情忷忷。存勖懼，以位讓克寧。克寧曰：「汝冢嗣也，且有先王之命，誰敢違之！」將吏欲謁見存勖，存勖方哀哭未出。張承業入謂存勖曰：「大孝在不墜基業，多哭何為！」因扶存勖出，襲位為河東節度使、晉王。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: db44aba3-d6c1-5114-b1a1-8ae10ec068c9'; END IF; END $$;
