DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='de22f4c3-a24f-5494-80ef-4abf438ac889' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p056", "claim_text": "后梁赦免逃亡军士，允许有军号刺字者还乡。此前跋队斩和刺字制度为段首追叙，不作为本年新设制度；盗贼减少比例不结构化。", "note": "原文：初，帝在籓镇，用法严，将校有战没者，所部兵悉斩之，谓之跋队斩。士卒失主将者，多亡逸不敢归。帝乃命凡军士皆文其面以记军号。军士或思乡里逃去，关津辄执之送所属，无不死者，其乡里亦不敢容。由是亡者皆聚山泽为盗，大为州县之患。壬寅，诏赦其罪，自今虽文面亦听还乡里。盗减什七八。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第56段", "claim_text": "后梁赦免逃亡军士，允许有军号刺字者还乡。此前跋队斩和刺字制度为段首追叙，不作为本年新设制度。", "note": "原文：初，帝在籓镇，用法严，将校有战没者，所部兵悉斩之，谓之跋队斩。士卒失主将者，多亡逸不敢归。帝乃命凡军士皆文其面以记军号。军士或思乡里逃去，关津辄执之送所属，无不死者，其乡里亦不敢容。由是亡者皆聚山泽为盗，大为州县之患。壬寅，诏赦其罪，自今虽文面亦听还乡里。盗减什七八。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: de22f4c3-a24f-5494-80ef-4abf438ac889'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,claim_text=v.claim_text,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第56段", "claim_text": "后梁赦免逃亡军士，允许有军号刺字者还乡。此前跋队斩和刺字制度为段首追叙，不作为本年新设制度。", "note": "原文：初，帝在籓镇，用法严，将校有战没者，所部兵悉斩之，谓之跋队斩。士卒失主将者，多亡逸不敢归。帝乃命凡军士皆文其面以记军号。军士或思乡里逃去，关津辄执之送所属，无不死者，其乡里亦不敢容。由是亡者皆聚山泽为盗，大为州县之患。壬寅，诏赦其罪，自今虽文面亦听还乡里。盗减什七八。；核对说明："}'::jsonb) v WHERE fact_claim.id='de22f4c3-a24f-5494-80ef-4abf438ac889';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='de3a780a-fff8-559c-a07a-018a4ef9eed8' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p036", "claim_text": "《资治通鉴》907年条所记人物。在“卢约以处州归降吴越”中为归降者。本批仅整理相关史事，生卒与完整履历待补。", "note": "原文：卢约以处州降吴越。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第36段", "claim_text": "据《资治通鉴》，907年在“卢约以处州归降吴越”中为归降者。", "note": "原文：卢约以处州降吴越。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: de3a780a-fff8-559c-a07a-018a4ef9eed8'; END IF; END $$;
