DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='e14584d4-4215-5cd1-8f41-0de59a074ecf' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p050", "note": "原文：九月，雷彦恭攻涔阳、公安，高季昌击败之。彦恭贪残类其父，专以焚掠为事，荆、湖间常被其患；又附于淮南。丙申，诏削彦恭官爵，命季昌与楚王殷讨之。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第50段", "note": "原文：九月，雷彦恭攻涔阳、公安，高季昌击败之。彦恭贪残类其父，专以焚掠为事，荆、湖间常被其患；又附于淮南。丙申，诏削彦恭官爵，命季昌与楚王殷讨之。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: e14584d4-4215-5cd1-8f41-0de59a074ecf'; END IF; END $$;
