DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='e26a564a-0cfa-5635-ae11-7fcbb5add48c' AND (to_jsonb(t) @> '{"note": "原文：壬戌，至胡柳陂。癸亥旦，候者言梁兵自後至矣。周德威曰：「賊倍道而來，未有所捨，我營柵已固，守備有餘，既深入敵境，動須萬全，不可輕發。此去大梁至近，梁兵各念其家，內懷憤激，不以方略制之，恐難得志。王宜按兵勿戰，德威請以騎兵擾之，使彼不得休息，至暮營壘未立，樵爨未具，乘其疲乏，可一舉滅也。」王曰：「前在河上恨不見賊，今賊至不擊，尚復何待，公何怯也！」顧李存審曰：「敕輜重先發，吾為爾殿後，破賊而去！」即以親軍先出。德威不得已，引幽州兵從之，謂其子曰：「吾無死所矣。」賀瑰結陳而至，橫亙數十里。王帥銀槍都陷其陳，沖蕩擊斬，往返十餘里。行營左廂馬軍都指揮使、鄭州防禦使王彥章軍先敗，西走趣濮陽。晉輜重在陳西，望見梁旗幟，驚潰，入幽州陳，幽州兵亦擾亂，自相蹈藉；周德威不能制，父子皆戰死。；核对说明：已对照所保存电子文本；尚待人工复核，不视为纸本校勘结论。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：壬戌，至胡柳陂。癸亥旦，候者言梁兵自後至矣。周德威曰：「賊倍道而來，未有所捨，我營柵已固，守備有餘，既深入敵境，動須萬全，不可輕發。此去大梁至近，梁兵各念其家，內懷憤激，不以方略制之，恐難得志。王宜按兵勿戰，德威請以騎兵擾之，使彼不得休息，至暮營壘未立，樵爨未具，乘其疲乏，可一舉滅也。」王曰：「前在河上恨不見賊，今賊至不擊，尚復何待，公何怯也！」顧李存審曰：「敕輜重先發，吾為爾殿後，破賊而去！」即以親軍先出。德威不得已，引幽州兵從之，謂其子曰：「吾無死所矣。」賀瑰結陳而至，橫亙數十里。王帥銀槍都陷其陳，沖蕩擊斬，往返十餘里。行營左廂馬軍都指揮使、鄭州防禦使王彥章軍先敗，西走趣濮陽。晉輜重在陳西，望見梁旗幟，驚潰，入幽州陳，幽州兵亦擾亂，自相蹈藉；周德威不能制，父子皆戰死。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: e26a564a-0cfa-5635-ae11-7fcbb5add48c'; END IF; END $$;
UPDATE public.fact_claim SET note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"note": "原文：壬戌，至胡柳陂。癸亥旦，候者言梁兵自後至矣。周德威曰：「賊倍道而來，未有所捨，我營柵已固，守備有餘，既深入敵境，動須萬全，不可輕發。此去大梁至近，梁兵各念其家，內懷憤激，不以方略制之，恐難得志。王宜按兵勿戰，德威請以騎兵擾之，使彼不得休息，至暮營壘未立，樵爨未具，乘其疲乏，可一舉滅也。」王曰：「前在河上恨不見賊，今賊至不擊，尚復何待，公何怯也！」顧李存審曰：「敕輜重先發，吾為爾殿後，破賊而去！」即以親軍先出。德威不得已，引幽州兵從之，謂其子曰：「吾無死所矣。」賀瑰結陳而至，橫亙數十里。王帥銀槍都陷其陳，沖蕩擊斬，往返十餘里。行營左廂馬軍都指揮使、鄭州防禦使王彥章軍先敗，西走趣濮陽。晉輜重在陳西，望見梁旗幟，驚潰，入幽州陳，幽州兵亦擾亂，自相蹈藉；周德威不能制，父子皆戰死。；核对说明："}'::jsonb) v WHERE fact_claim.id='e26a564a-0cfa-5635-ae11-7fcbb5add48c';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='e32adca0-b4d2-5955-96e5-8fe1e8e1f1dd' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p013", "note": "原文：仁恭有爱妾罗氏，其子守光通焉。仁恭杖守光而斥之，不以为子数。李思安引兵入其境，所过焚荡无馀。夏，四月，己酉，直抵幽州城下。仁恭犹在大安山。城中无备，几至不守。守光自外引兵入，登城拒守；又出兵与思安战，思安败退。守光遂自称节度使，命部将李小喜、元行钦将兵攻大安山。仁恭遣兵拒战，为小喜所败。虏仁恭以归，囚于别室。仁恭将佐及左右，凡守光素所恶者皆杀之。银胡录都指挥使王思同帅部兵三千，山后八安巡检使李承约帅部兵二千奔河东，守光弟守奇奔契丹，未几，亦奔河东，河东节度使晋王克用以承约为匡霸指挥使，思同为飞腾指挥使。思同母，仁恭之女也。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第13段", "note": "原文：仁恭有爱妾罗氏，其子守光通焉。仁恭杖守光而斥之，不以为子数。李思安引兵入其境，所过焚荡无馀。夏，四月，己酉，直抵幽州城下。仁恭犹在大安山。城中无备，几至不守。守光自外引兵入，登城拒守；又出兵与思安战，思安败退。守光遂自称节度使，命部将李小喜、元行钦将兵攻大安山。仁恭遣兵拒战，为小喜所败。虏仁恭以归，囚于别室。仁恭将佐及左右，凡守光素所恶者皆杀之。银胡录都指挥使王思同帅部兵三千，山后八安巡检使李承约帅部兵二千奔河东，守光弟守奇奔契丹，未几，亦奔河东，河东节度使晋王克用以承约为匡霸指挥使，思同为飞腾指挥使。思同母，仁恭之女也。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: e32adca0-b4d2-5955-96e5-8fe1e8e1f1dd'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第13段", "note": "原文：仁恭有爱妾罗氏，其子守光通焉。仁恭杖守光而斥之，不以为子数。李思安引兵入其境，所过焚荡无馀。夏，四月，己酉，直抵幽州城下。仁恭犹在大安山。城中无备，几至不守。守光自外引兵入，登城拒守；又出兵与思安战，思安败退。守光遂自称节度使，命部将李小喜、元行钦将兵攻大安山。仁恭遣兵拒战，为小喜所败。虏仁恭以归，囚于别室。仁恭将佐及左右，凡守光素所恶者皆杀之。银胡录都指挥使王思同帅部兵三千，山后八安巡检使李承约帅部兵二千奔河东，守光弟守奇奔契丹，未几，亦奔河东，河东节度使晋王克用以承约为匡霸指挥使，思同为飞腾指挥使。思同母，仁恭之女也。；核对说明："}'::jsonb) v WHERE fact_claim.id='e32adca0-b4d2-5955-96e5-8fe1e8e1f1dd';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='e34e32ec-82c0-529f-ae9d-ee59b08cc8a8' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p047", "note": "原文：辛亥，以吴越王镠兼淮南节度使，楚王殷兼武昌节度使，各充本道招讨制置使。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第47段", "note": "原文：辛亥，以吴越王镠兼淮南节度使，楚王殷兼武昌节度使，各充本道招讨制置使。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: e34e32ec-82c0-529f-ae9d-ee59b08cc8a8'; END IF; END $$;
