DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='e584356c-d1e2-5399-9172-b45d4a499ea5' AND (to_jsonb(t) @> '{"note": "原文：旧五代史 \n74/1667 \n张祎盛称帝功德，宜应天顺人。宋州\n刺史王皋进两岐麦，陈州袁象先进白\n兔一，付史馆编录，兼示百官。诏在\n京司及诸军州县印一例铸换，其篆文\n则各如旧。辛未，武安军节度使马殷\n进封楚王。以太府卿敬翔知崇政院，\n翔与帷幄之谋，故首擢焉。追尊四代\n庙号：高祖妫州府君上谥曰宣元皇\n帝，庙号肃祖，太庙第一室，陵号兴\n极陵，祖妣高平县君范氏追谥宣僖皇\n后；皇曾祖宣惠王上谥曰光献皇帝，\n庙号敬祖，第二室，陵号永安，祖妣\n秦国夫人杨氏追谥光孝皇后；皇祖武\n元王上谥曰昭武皇帝，庙号宪祖，第\n三室，陵号光天，祖妣吴国夫人刘氏；核对说明：本项目核读电子文本；文字层不是原刻影印，未作纸本校勘。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：旧五代史 \n74/1667 \n张祎盛称帝功德，宜应天顺人。宋州\n刺史王皋进两岐麦，陈州袁象先进白\n兔一，付史馆编录，兼示百官。诏在\n京司及诸军州县印一例铸换，其篆文\n则各如旧。辛未，武安军节度使马殷\n进封楚王。以太府卿敬翔知崇政院，\n翔与帷幄之谋，故首擢焉。追尊四代\n庙号：高祖妫州府君上谥曰宣元皇\n帝，庙号肃祖，太庙第一室，陵号兴\n极陵，祖妣高平县君范氏追谥宣僖皇\n后；皇曾祖宣惠王上谥曰光献皇帝，\n庙号敬祖，第二室，陵号永安，祖妣\n秦国夫人杨氏追谥光孝皇后；皇祖武\n元王上谥曰昭武皇帝，庙号宪祖，第\n三室，陵号光天，祖妣吴国夫人刘氏；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: e584356c-d1e2-5399-9172-b45d4a499ea5'; END IF; END $$;
