DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='e629031f-6ba0-5a4f-a6aa-c96487f0103f' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p006", "claim_text": "《资治通鉴》907年条所记人物。在“康怀贞奉命屯晋州防备河东军”中为领兵者。本批仅整理相关史事，生卒与完整履历待补。", "note": "原文：河东兵犹屯长孑，欲窥泽州。王命保平节度使康怀贞悉发京兆，同华之兵屯晋州以备之。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第6段", "claim_text": "据《资治通鉴》，907年在“康怀贞奉命屯晋州防备河东军”中为领兵者。", "note": "原文：河东兵犹屯长孑，欲窥泽州。王命保平节度使康怀贞悉发京兆，同华之兵屯晋州以备之。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: e629031f-6ba0-5a4f-a6aa-c96487f0103f'; END IF; END $$;
