DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='ec275c24-1613-53c9-9c10-bd2a09c85c05' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p035", "note": "原文：礼部尚书苏循及其子起居郎楷自谓有功于梁，当不次擢用；循朝夕望为相，帝薄其为人，敬翔及殿中监李振亦鄙之。翔言于帝曰：“苏循，唐之鸱枭，卖国求利，不可以立于惟新之朝。”戊戍，诏循及刑部尚书张祎等十五人并勒致仕，楷斥归田里。循父子乃之河中依硃友谦。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第35段", "note": "原文：礼部尚书苏循及其子起居郎楷自谓有功于梁，当不次擢用；循朝夕望为相，帝薄其为人，敬翔及殿中监李振亦鄙之。翔言于帝曰：“苏循，唐之鸱枭，卖国求利，不可以立于惟新之朝。”戊戍，诏循及刑部尚书张祎等十五人并勒致仕，楷斥归田里。循父子乃之河中依硃友谦。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: ec275c24-1613-53c9-9c10-bd2a09c85c05'; END IF; END $$;
UPDATE public.fact_claim SET citation=v.citation,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"citation": "卷266·开平元年·第35段", "note": "原文：礼部尚书苏循及其子起居郎楷自谓有功于梁，当不次擢用；循朝夕望为相，帝薄其为人，敬翔及殿中监李振亦鄙之。翔言于帝曰：“苏循，唐之鸱枭，卖国求利，不可以立于惟新之朝。”戊戍，诏循及刑部尚书张祎等十五人并勒致仕，楷斥归田里。循父子乃之河中依硃友谦。；核对说明："}'::jsonb) v WHERE fact_claim.id='ec275c24-1613-53c9-9c10-bd2a09c85c05';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='ec2b724e-2915-5522-84a1-d7e7076b9c05' AND (to_jsonb(t) @> '{"note": "原文：丁亥，周德威與別將史建瑭、李嗣源將精騎三千壓梁壘門而詬之，王景仁、韓勍怒，悉眾而出。德威等轉戰而北至高邑南；李存璋以步兵陳於野河之上，梁軍橫亙數里，競前奪橋，鎮、定步兵御之，勢不能支。晉王謂匡衛都指揮使李建及曰：「賊過橋則不可複製矣。」建及選卒二百，援槍大噪，力戰卻之。建及，許州人，姓王，李罕之之假子也。晉王登高丘以望曰：「梁兵爭進而囂，我兵整而靜，我必勝。」戰自巳至午，勝負未決。晉王謂周德威曰：「兩軍已合，勢不可離，我之興亡，在此一舉。我為公先登，公可繼之。」德威叩馬而諫曰：「觀梁兵之勢，可以勞逸制之，未易以力勝也。彼去營三十餘里，雖挾糗糧，亦不暇食，日昳之後，飢渴內迫，矢刃外交，士卒勞倦，必有退志。當是時，我以精騎乘之，必大捷。於今未可也。」王乃止。；核对说明：已对照所保存电子文本；尚待人工复核，不视为纸本校勘结论。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：丁亥，周德威與別將史建瑭、李嗣源將精騎三千壓梁壘門而詬之，王景仁、韓勍怒，悉眾而出。德威等轉戰而北至高邑南；李存璋以步兵陳於野河之上，梁軍橫亙數里，競前奪橋，鎮、定步兵御之，勢不能支。晉王謂匡衛都指揮使李建及曰：「賊過橋則不可複製矣。」建及選卒二百，援槍大噪，力戰卻之。建及，許州人，姓王，李罕之之假子也。晉王登高丘以望曰：「梁兵爭進而囂，我兵整而靜，我必勝。」戰自巳至午，勝負未決。晉王謂周德威曰：「兩軍已合，勢不可離，我之興亡，在此一舉。我為公先登，公可繼之。」德威叩馬而諫曰：「觀梁兵之勢，可以勞逸制之，未易以力勝也。彼去營三十餘里，雖挾糗糧，亦不暇食，日昳之後，飢渴內迫，矢刃外交，士卒勞倦，必有退志。當是時，我以精騎乘之，必大捷。於今未可也。」王乃止。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: ec2b724e-2915-5522-84a1-d7e7076b9c05'; END IF; END $$;
