DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='f1cf55d0-87d7-506a-a7cd-69e0245f9ddd' AND (to_jsonb(t) @> '{"note": "原文：壬戌，至胡柳陂。癸亥旦，候者言梁兵自後至矣。周德威曰：「賊倍道而來，未有所捨，我營柵已固，守備有餘，既深入敵境，動須萬全，不可輕發。此去大梁至近，梁兵各念其家，內懷憤激，不以方略制之，恐難得志。王宜按兵勿戰，德威請以騎兵擾之，使彼不得休息，至暮營壘未立，樵爨未具，乘其疲乏，可一舉滅也。」王曰：「前在河上恨不見賊，今賊至不擊，尚復何待，公何怯也！」顧李存審曰：「敕輜重先發，吾為爾殿後，破賊而去！」即以親軍先出。德威不得已，引幽州兵從之，謂其子曰：「吾無死所矣。」賀瑰結陳而至，橫亙數十里。王帥銀槍都陷其陳，沖蕩擊斬，往返十餘里。行營左廂馬軍都指揮使、鄭州防禦使王彥章軍先敗，西走趣濮陽。晉輜重在陳西，望見梁旗幟，驚潰，入幽州陳，幽州兵亦擾亂，自相蹈藉；周德威不能制，父子皆戰死。；核对说明：已对照所保存电子文本；尚待人工复核，不视为纸本校勘结论。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：壬戌，至胡柳陂。癸亥旦，候者言梁兵自後至矣。周德威曰：「賊倍道而來，未有所捨，我營柵已固，守備有餘，既深入敵境，動須萬全，不可輕發。此去大梁至近，梁兵各念其家，內懷憤激，不以方略制之，恐難得志。王宜按兵勿戰，德威請以騎兵擾之，使彼不得休息，至暮營壘未立，樵爨未具，乘其疲乏，可一舉滅也。」王曰：「前在河上恨不見賊，今賊至不擊，尚復何待，公何怯也！」顧李存審曰：「敕輜重先發，吾為爾殿後，破賊而去！」即以親軍先出。德威不得已，引幽州兵從之，謂其子曰：「吾無死所矣。」賀瑰結陳而至，橫亙數十里。王帥銀槍都陷其陳，沖蕩擊斬，往返十餘里。行營左廂馬軍都指揮使、鄭州防禦使王彥章軍先敗，西走趣濮陽。晉輜重在陳西，望見梁旗幟，驚潰，入幽州陳，幽州兵亦擾亂，自相蹈藉；周德威不能制，父子皆戰死。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: f1cf55d0-87d7-506a-a7cd-69e0245f9ddd'; END IF; END $$;
