DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='f294d13c-52db-54a3-8dff-6670995c78c5' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p004", "note": "原文：渥居丧，昼夜酣饮作乐，然十围之烛以击球，一烛费钱数万。或单骑出游，从者奔走道路，不知所之。左、右牙指挥使张颢、徐温泣谏，渥怒曰：“汝谓我不才，何不杀我自为之！”二人惧。渥选壮士，号“东院马军”，广署亲信为将吏；所署者恃势骄横，陵蔑勋旧。颢、温潜谋作乱。渥父行密之世，有亲军数千，营于牙城之内，渥迁出于外，以其地为射场，颢、温由是无所惮。渥之镇宣州也，命指挥使硃思勍、范思从、陈璠将亲兵三千；及嗣位，召归广陵。颢、温使三将从秦裴击江西，因戍洪州，诬以谋叛，命别将陈祐往诛之。祐间道兼行，六日至洪州，微服怀短兵径入秦裴帐中，裴大惊，祐告之故，乃召思勍等饮酒，祐数思勍等罪，执而斩之。渥闻三将死，益忌颢、温，欲诛之。丙戍，渥晨视事，颢、温帅牙兵二百，露刃直入庭中，渥曰：“尔思欲杀我邪？”对曰，“非敢然也，欲诛王左右乱政者耳！”因数渥所亲信十馀人之罪，曳下，以铁楇击杀之，谓之“兵谏”。诸将不与之同者，颢、温稍以法诛之，于是军政悉归二人，渥不能制。；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第4段", "note": "原文：渥居丧，昼夜酣饮作乐，然十围之烛以击球，一烛费钱数万。或单骑出游，从者奔走道路，不知所之。左、右牙指挥使张颢、徐温泣谏，渥怒曰：“汝谓我不才，何不杀我自为之！”二人惧。渥选壮士，号“东院马军”，广署亲信为将吏；所署者恃势骄横，陵蔑勋旧。颢、温潜谋作乱。渥父行密之世，有亲军数千，营于牙城之内，渥迁出于外，以其地为射场，颢、温由是无所惮。渥之镇宣州也，命指挥使硃思勍、范思从、陈璠将亲兵三千；及嗣位，召归广陵。颢、温使三将从秦裴击江西，因戍洪州，诬以谋叛，命别将陈祐往诛之。祐间道兼行，六日至洪州，微服怀短兵径入秦裴帐中，裴大惊，祐告之故，乃召思勍等饮酒，祐数思勍等罪，执而斩之。渥闻三将死，益忌颢、温，欲诛之。丙戍，渥晨视事，颢、温帅牙兵二百，露刃直入庭中，渥曰：“尔思欲杀我邪？”对曰，“非敢然也，欲诛王左右乱政者耳！”因数渥所亲信十馀人之罪，曳下，以铁楇击杀之，谓之“兵谏”。诸将不与之同者，颢、温稍以法诛之，于是军政悉归二人，渥不能制。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: f294d13c-52db-54a3-8dff-6670995c78c5'; END IF; END $$;
