DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='f7b5a53a-98e3-5968-84aa-d2534e77c3e3' AND (to_jsonb(t) @> '{"claim_text": "方向为李存勖对李嗣源；本批记录908年作战指挥及923年后唐君臣关系，不延伸为永久阵营。", "note": "原文：帝密召李嗣源於帳中謀之曰：「梁人志在吞澤潞，不備東方，若得東平，則潰其心腹。東平果可取乎？」嗣源自胡柳有渡河之慚，常欲立奇功以補過，對曰：「今用兵歲久，生民疲弊，苟非出奇取勝，大功何由可成！臣願獨當此役，必有以報。」帝悅。壬寅，遣嗣源將所部精兵五千自德勝趣鄆州。比及楊劉，日已暮，陰雨道黑，將士皆不欲進，高行周曰：「此天讚我也，彼必無備。」夜，渡河至城下，鄆人不知，李從珂先登，殺守卒，啟關納外兵，進攻牙城，城中大擾。癸卯旦，嗣源兵盡入，遂拔牙城，劉遂嚴、燕顒奔大梁。嗣源禁焚掠，撫吏民，執知州事節度副使崔簹、判官趙鳳送興唐。帝大喜曰：「總管真奇才，吾事集矣。」即以嗣源為天平節度使。；核对说明：已对照所保存电子文本；尚待人工复核，不视为纸本校勘结论。"}'::jsonb OR to_jsonb(t) @> '{"claim_text": "方向为李存勖对李嗣源；记载涉及908年作战指挥及923年后唐君臣关系，不延伸为永久阵营。", "note": "原文：帝密召李嗣源於帳中謀之曰：「梁人志在吞澤潞，不備東方，若得東平，則潰其心腹。東平果可取乎？」嗣源自胡柳有渡河之慚，常欲立奇功以補過，對曰：「今用兵歲久，生民疲弊，苟非出奇取勝，大功何由可成！臣願獨當此役，必有以報。」帝悅。壬寅，遣嗣源將所部精兵五千自德勝趣鄆州。比及楊劉，日已暮，陰雨道黑，將士皆不欲進，高行周曰：「此天讚我也，彼必無備。」夜，渡河至城下，鄆人不知，李從珂先登，殺守卒，啟關納外兵，進攻牙城，城中大擾。癸卯旦，嗣源兵盡入，遂拔牙城，劉遂嚴、燕顒奔大梁。嗣源禁焚掠，撫吏民，執知州事節度副使崔簹、判官趙鳳送興唐。帝大喜曰：「總管真奇才，吾事集矣。」即以嗣源為天平節度使。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: f7b5a53a-98e3-5968-84aa-d2534e77c3e3'; END IF; END $$;
UPDATE public.fact_claim SET claim_text=v.claim_text,note=v.note FROM jsonb_populate_record(NULL::public.fact_claim, '{"claim_text": "方向为李存勖对李嗣源；记载涉及908年作战指挥及923年后唐君臣关系，不延伸为永久阵营。", "note": "原文：帝密召李嗣源於帳中謀之曰：「梁人志在吞澤潞，不備東方，若得東平，則潰其心腹。東平果可取乎？」嗣源自胡柳有渡河之慚，常欲立奇功以補過，對曰：「今用兵歲久，生民疲弊，苟非出奇取勝，大功何由可成！臣願獨當此役，必有以報。」帝悅。壬寅，遣嗣源將所部精兵五千自德勝趣鄆州。比及楊劉，日已暮，陰雨道黑，將士皆不欲進，高行周曰：「此天讚我也，彼必無備。」夜，渡河至城下，鄆人不知，李從珂先登，殺守卒，啟關納外兵，進攻牙城，城中大擾。癸卯旦，嗣源兵盡入，遂拔牙城，劉遂嚴、燕顒奔大梁。嗣源禁焚掠，撫吏民，執知州事節度副使崔簹、判官趙鳳送興唐。帝大喜曰：「總管真奇才，吾事集矣。」即以嗣源為天平節度使。；核对说明："}'::jsonb) v WHERE fact_claim.id='f7b5a53a-98e3-5968-84aa-d2534e77c3e3';
