DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='fadcd1e0-83e6-55c8-8035-d8947b490e00' AND (to_jsonb(t) @> '{"note": "原文：戊寅，或告唐軍已過曹州，塵埃漲天，趙巖謂從者曰：「吾待溫許州厚，必不負我。」遂奔許州。梁主謂皇甫麟曰：「李氏吾世仇，理難降首，不可俟彼刀鋸。吾不能自裁，卿可斷吾首。」麟泣曰：「臣為陛下揮劍死唐軍則可矣，不敢奉此詔。」梁主曰：「卿欲賣我邪？」麟欲自剄，梁主持之曰：「與卿俱死！」麟遂弒梁主，因自殺。梁主為人溫恭儉約，無荒淫之失；但寵信趙、張，使擅威福，疏棄敬、李舊臣，不用其言，以至於亡。\n己卯旦，李嗣源軍至大梁，攻封丘門，王瓚開門出降，嗣源入城，撫安軍民。是日，帝入自梁門，百官迎謁於馬首，拜伏請罪，帝慰勞之，使各復其位。李嗣源迎賀，帝喜不自勝，手引嗣源衣，以頭觸之曰：「吾有天下，卿父子之功也，天下與爾共之。」帝命訪求梁主，頃之，或以其首獻。；核对说明：已对照所保存电子文本；尚待人工复核，不视为纸本校勘结论。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：戊寅，或告唐軍已過曹州，塵埃漲天，趙巖謂從者曰：「吾待溫許州厚，必不負我。」遂奔許州。梁主謂皇甫麟曰：「李氏吾世仇，理難降首，不可俟彼刀鋸。吾不能自裁，卿可斷吾首。」麟泣曰：「臣為陛下揮劍死唐軍則可矣，不敢奉此詔。」梁主曰：「卿欲賣我邪？」麟欲自剄，梁主持之曰：「與卿俱死！」麟遂弒梁主，因自殺。梁主為人溫恭儉約，無荒淫之失；但寵信趙、張，使擅威福，疏棄敬、李舊臣，不用其言，以至於亡。\n己卯旦，李嗣源軍至大梁，攻封丘門，王瓚開門出降，嗣源入城，撫安軍民。是日，帝入自梁門，百官迎謁於馬首，拜伏請罪，帝慰勞之，使各復其位。李嗣源迎賀，帝喜不自勝，手引嗣源衣，以頭觸之曰：「吾有天下，卿父子之功也，天下與爾共之。」帝命訪求梁主，頃之，或以其首獻。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: fadcd1e0-83e6-55c8-8035-d8947b490e00'; END IF; END $$;
