DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='fd016212-a482-5bbd-ab58-a819b3393ec3' AND (to_jsonb(t) @> '{"note": "原文：旧五代史 \n77/1667 \n五月，以唐朝宰臣张文蔚、杨涉\n并为门下侍郎、平章事；以御史大夫\n薛贻矩为中书侍郎、平章事。帝初受\n禅，求理尤切，委宰臣搜访贤良。或\n有在下位抱负器业久不得伸者，特加\n擢用；有明政理得失之道规救时病\n者，可陈章疏，当亲鉴择利害施行，\n然后赏以爵秩；有晦迹丘园不求闻达\n者，令彼长吏备礼邀致，冀无遗逸之\n恨。进封河南尹兼河阳节度使张全义\n为魏王，两浙节度使钱镠进封吴越\n王。辛巳，有司奏，以降诞之日为大\n明节，休假前后各一日。壬午，保义\n军节度使朱友谦进百官衣二百副。乙\n酉，立皇兄全昱为广王，皇子友文为；核对说明：本项目核读电子文本；文字层不是原刻影印，未作纸本校勘。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：旧五代史 \n77/1667 \n五月，以唐朝宰臣张文蔚、杨涉\n并为门下侍郎、平章事；以御史大夫\n薛贻矩为中书侍郎、平章事。帝初受\n禅，求理尤切，委宰臣搜访贤良。或\n有在下位抱负器业久不得伸者，特加\n擢用；有明政理得失之道规救时病\n者，可陈章疏，当亲鉴择利害施行，\n然后赏以爵秩；有晦迹丘园不求闻达\n者，令彼长吏备礼邀致，冀无遗逸之\n恨。进封河南尹兼河阳节度使张全义\n为魏王，两浙节度使钱镠进封吴越\n王。辛巳，有司奏，以降诞之日为大\n明节，休假前后各一日。壬午，保义\n军节度使朱友谦进百官衣二百副。乙\n酉，立皇兄全昱为广王，皇子友文为；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: fd016212-a482-5bbd-ab58-a819b3393ec3'; END IF; END $$;
