DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='fd334405-d1b8-5b76-84f9-78febb881a96' AND (to_jsonb(t) @> '{"note": "原文：丁亥，周德威與別將史建瑭、李嗣源將精騎三千壓梁壘門而詬之，王景仁、韓勍怒，悉眾而出。德威等轉戰而北至高邑南；李存璋以步兵陳於野河之上，梁軍橫亙數里，競前奪橋，鎮、定步兵御之，勢不能支。晉王謂匡衛都指揮使李建及曰：「賊過橋則不可複製矣。」建及選卒二百，援槍大噪，力戰卻之。建及，許州人，姓王，李罕之之假子也。晉王登高丘以望曰：「梁兵爭進而囂，我兵整而靜，我必勝。」戰自巳至午，勝負未決。晉王謂周德威曰：「兩軍已合，勢不可離，我之興亡，在此一舉。我為公先登，公可繼之。」德威叩馬而諫曰：「觀梁兵之勢，可以勞逸制之，未易以力勝也。彼去營三十餘里，雖挾糗糧，亦不暇食，日昳之後，飢渴內迫，矢刃外交，士卒勞倦，必有退志。當是時，我以精騎乘之，必大捷。於今未可也。」王乃止。；核对说明：已对照所保存电子文本；尚待人工复核，不视为纸本校勘结论。"}'::jsonb OR to_jsonb(t) @> '{"note": "原文：丁亥，周德威與別將史建瑭、李嗣源將精騎三千壓梁壘門而詬之，王景仁、韓勍怒，悉眾而出。德威等轉戰而北至高邑南；李存璋以步兵陳於野河之上，梁軍橫亙數里，競前奪橋，鎮、定步兵御之，勢不能支。晉王謂匡衛都指揮使李建及曰：「賊過橋則不可複製矣。」建及選卒二百，援槍大噪，力戰卻之。建及，許州人，姓王，李罕之之假子也。晉王登高丘以望曰：「梁兵爭進而囂，我兵整而靜，我必勝。」戰自巳至午，勝負未決。晉王謂周德威曰：「兩軍已合，勢不可離，我之興亡，在此一舉。我為公先登，公可繼之。」德威叩馬而諫曰：「觀梁兵之勢，可以勞逸制之，未易以力勝也。彼去營三十餘里，雖挾糗糧，亦不暇食，日昳之後，飢渴內迫，矢刃外交，士卒勞倦，必有退志。當是時，我以精騎乘之，必大捷。於今未可也。」王乃止。；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: fd334405-d1b8-5b76-84f9-78febb881a96'; END IF; END $$;
