DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_claim t WHERE id='fe8b7187-1b84-51f6-9ae8-bc45bdae9d68' AND (to_jsonb(t) @> '{"citation": "卷266·开平元年条·tj266-907-p016", "note": "原文：壬戌，梁王更名晃。王兄全昱闻王将即帝位，谓王曰：“硃三，尔可作天子乎！”；核对说明：按指定电子文本逐段整理；907年条中的前事与泛论不据此强行断年；2026-09-29由项目助手核读；单源内容按书中记载发布，不视为独立证实。"}'::jsonb OR to_jsonb(t) @> '{"citation": "卷266·开平元年·第16段", "note": "原文：壬戌，梁王更名晃。王兄全昱闻王将即帝位，谓王曰：“硃三，尔可作天子乎！”；核对说明："}'::jsonb)) THEN RAISE EXCEPTION 'Copy edit conflict: fe8b7187-1b84-51f6-9ae8-bc45bdae9d68'; END IF; END $$;
